import type { BankQuestion } from "@/lib/bank";

/** Chemistry Basics (General Science): 375 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"sci-chemistry-1","question":"What is the pH of pure water?","options":["0","5","7","14"],"answer":2,"explanation":"Pure water ionises equally into H⁺ and OH⁻ (each 10⁻⁷ mol/L at 25 °C), so it is neutral with pH 7. At higher temperatures the neutral pH falls slightly below 7, but water stays neutral.","difficulty":"easy","questionHi":"शुद्ध जल का pH कितना होता है?","optionsHi":["0","5","7","14"],"explanationHi":"शुद्ध जल समान रूप से H⁺ और OH⁻ में आयनित होता है (25 °C पर प्रत्येक 10⁻⁷ mol/L), इसलिए वह उदासीन है और उसका pH 7 है। उच्च तापमान पर उदासीन pH 7 से थोड़ा कम हो जाता है, परंतु जल उदासीन ही रहता है।"},
  {"id":"sci-chemistry-2","question":"Which gas is most abundant in the Earth’s atmosphere?","options":["Oxygen","Carbon dioxide","Nitrogen","Argon"],"answer":2,"explanation":"Dry air is about 78% nitrogen, 21% oxygen and 0.9% argon; carbon dioxide is only about 0.04%. Oxygen is the tempting answer because it is the gas we need, but it is second.","difficulty":"easy","questionHi":"पृथ्वी के वायुमंडल में कौन-सी गैस सबसे अधिक मात्रा में है?","optionsHi":["ऑक्सीजन","कार्बन डाइऑक्साइड","नाइट्रोजन","आर्गन"],"explanationHi":"शुष्क वायु में लगभग 78% नाइट्रोजन, 21% ऑक्सीजन और 0.9% आर्गन होती है; कार्बन डाइऑक्साइड केवल लगभग 0.04% है। ऑक्सीजन भ्रम का उत्तर है क्योंकि वह हमारे लिए आवश्यक गैस है, परंतु वह दूसरे स्थान पर है।"},
  {"id":"sci-chemistry-3","question":"The chemical formula of common salt is:","options":["NaCl","KCl","NaOH","CaCO₃"],"answer":0,"explanation":"Common salt is sodium chloride, NaCl, an ionic compound of Na⁺ and Cl⁻. KCl (potassium chloride) is used as a salt substitute, and NaOH is caustic soda.","difficulty":"easy","questionHi":"सामान्य नमक का रासायनिक सूत्र क्या है?","optionsHi":["NaCl","KCl","NaOH","CaCO₃"],"explanationHi":"सामान्य नमक सोडियम क्लोराइड, NaCl, है, जो Na⁺ और Cl⁻ का आयनिक यौगिक है। KCl (पोटैशियम क्लोराइड) नमक के विकल्प के रूप में उपयोग होता है, और NaOH कॉस्टिक सोडा है।"},
  {"id":"sci-chemistry-4","question":"What is the chemical name of baking soda?","options":["Sodium carbonate","Sodium bicarbonate","Calcium carbonate","Ammonium carbonate"],"answer":1,"explanation":"Baking soda is sodium bicarbonate (sodium hydrogencarbonate), NaHCO₃. Sodium carbonate is washing soda, and ammonium carbonate is a different leavening agent (baker's ammonia).","difficulty":"moderate","questionHi":"बेकिंग सोडा का रासायनिक नाम क्या है?","optionsHi":["सोडियम कार्बोनेट","सोडियम बाइकार्बोनेट","कैल्शियम कार्बोनेट","अमोनियम कार्बोनेट"],"explanationHi":"बेकिंग सोडा सोडियम बाइकार्बोनेट (सोडियम हाइड्रोजनकार्बोनेट), NaHCO₃, है। सोडियम कार्बोनेट धावन सोडा है, और अमोनियम कार्बोनेट एक भिन्न खमीर उठाने वाला पदार्थ (बेकर्स अमोनिया) है।"},
  {"id":"sci-chemistry-5","question":"“Laughing gas” is the common name of:","options":["Nitric oxide","Nitrous oxide","Nitrogen dioxide","Ammonia"],"answer":1,"explanation":"Nitrous oxide, N₂O, is laughing gas and is used as a mild anaesthetic. Nitric oxide is NO, and nitrogen dioxide (NO₂) is a brown, toxic gas, so the near-identical names are the trap.","difficulty":"moderate","questionHi":"“लाफिंग गैस (हँसाने वाली गैस)” किसका प्रचलित नाम है?","optionsHi":["नाइट्रिक ऑक्साइड","नाइट्रस ऑक्साइड","नाइट्रोजन डाइऑक्साइड","अमोनिया"],"explanationHi":"नाइट्रस ऑक्साइड, N₂O, लाफिंग गैस है और इसका उपयोग हल्के निश्चेतक के रूप में होता है। नाइट्रिक ऑक्साइड NO है, और नाइट्रोजन डाइऑक्साइड (NO₂) भूरी, विषैली गैस है, इसलिए लगभग एक-से नाम ही भ्रम का कारण हैं।"},
  {"id":"sci-chemistry-6","question":"A solution with pH 3 is:","options":["Neutral","Acidic","Basic","Saline"],"answer":1,"explanation":"pH below 7 is acidic; the lower the pH, the stronger the acid.","difficulty":"moderate","questionHi":"pH 3 वाला विलयन होता है:","optionsHi":["उदासीन","अम्लीय","क्षारीय","लवणीय"],"explanationHi":"7 से कम pH अम्लीय होता है; pH जितना कम, अम्ल उतना प्रबल।"},
  {"id":"sci-chemistry-7","question":"Which gas is commonly used in fire extinguishers?","options":["Oxygen","Carbon dioxide","Nitrogen","Carbon monoxide"],"answer":1,"explanation":"CO₂ is heavier than air and does not support combustion, so it smothers the fire.","difficulty":"hard","questionHi":"अग्निशामक यंत्रों में सामान्यतः किस गैस का उपयोग किया जाता है?","optionsHi":["ऑक्सीजन","कार्बन डाइऑक्साइड","नाइट्रोजन","कार्बन मोनोऑक्साइड"],"explanationHi":"CO₂ वायु से भारी होती है और दहन में सहायक नहीं होती, इसलिए वह आग को ढककर बुझा देती है।"},
  {"id":"sci-chemistry-8","question":"The chemical name of quicklime is:","options":["Calcium carbonate","Calcium oxide","Calcium hydroxide","Calcium sulphate"],"answer":1,"explanation":"Quicklime is calcium oxide (CaO); slaked lime is calcium hydroxide.","difficulty":"hard","questionHi":"बिना बुझे चूने (क्विकलाइम) का रासायनिक नाम क्या है?","optionsHi":["कैल्शियम कार्बोनेट","कैल्शियम ऑक्साइड","कैल्शियम हाइड्रॉक्साइड","कैल्शियम सल्फेट"],"explanationHi":"बिना बुझा चूना कैल्शियम ऑक्साइड (CaO) है; बुझा हुआ चूना कैल्शियम हाइड्रॉक्साइड है।"},
  {"id":"sci-chemistry-9","question":"Washing soda is chemically:","options":["Na₂CO₃·10H₂O","NaHCO₃","Na₂SO₄·10H₂O","CaCO₃"],"answer":0,"explanation":"Washing soda is sodium carbonate decahydrate, Na₂CO₃·10H₂O. NaHCO₃ is baking soda, and Na₂SO₄·10H₂O, which looks similar, is Glauber's salt (a sulphate, not a carbonate).","difficulty":"hard","questionHi":"धावन सोडा (वाशिंग सोडा) रासायनिक रूप से क्या है?","optionsHi":["Na₂CO₃·10H₂O","NaHCO₃","Na₂SO₄·10H₂O","CaCO₃"],"explanationHi":"धावन सोडा सोडियम कार्बोनेट डेकाहाइड्रेट, Na₂CO₃·10H₂O, है। NaHCO₃ बेकिंग सोडा है, और Na₂SO₄·10H₂O, जो देखने में समान लगता है, ग्लॉबर लवण है (सल्फेट, कार्बोनेट नहीं)।"},
  {"id":"sci-chemistry-10","question":"Plaster of Paris is chemically:","options":["CaSO₄·2H₂O","CaSO₄·½H₂O","CaCO₃","Ca(OH)₂"],"answer":1,"explanation":"Plaster of Paris is calcium sulphate hemihydrate; gypsum is the dihydrate.","difficulty":"very-hard","questionHi":"प्लास्टर ऑफ पेरिस रासायनिक रूप से क्या है?","optionsHi":["CaSO₄·2H₂O","CaSO₄·½H₂O","CaCO₃","Ca(OH)₂"],"explanationHi":"प्लास्टर ऑफ पेरिस कैल्शियम सल्फेट हेमीहाइड्रेट है; जिप्सम डाइहाइड्रेट है।"},
  {"id":"sci-chemistry-11","question":"The pH of normal human blood is approximately:","options":["6.0","7.0","7.4","8.1"],"answer":2,"explanation":"Blood is slightly alkaline, pH about 7.35–7.45, held there by the bicarbonate buffer. 7.0 is the trap of assuming body fluids are neutral; 6.0 is typical of urine and 8.1 of sea water.","difficulty":"very-hard","questionHi":"सामान्य मानव रक्त का pH लगभग कितना होता है?","optionsHi":["6.0","7.0","7.4","8.1"],"explanationHi":"रक्त थोड़ा क्षारीय होता है, pH लगभग 7.35–7.45, जिसे बाइकार्बोनेट बफर बनाए रखता है। 7.0 इस भ्रम का विकल्प है कि शरीर के तरल उदासीन होते हैं; 6.0 मूत्र का और 8.1 समुद्री जल का सामान्य मान है।"},
  {"id":"sci-chemistry-12","question":"Bleaching powder is chemically:","options":["CaOCl₂","CaCl₂","Ca(OH)₂","CaCO₃"],"answer":0,"explanation":"Bleaching powder is calcium oxychloride, CaOCl₂, made by passing chlorine over slaked lime.","difficulty":"very-hard","questionHi":"विरंजक चूर्ण (ब्लीचिंग पाउडर) रासायनिक रूप से क्या है?","optionsHi":["CaOCl₂","CaCl₂","Ca(OH)₂","CaCO₃"],"explanationHi":"विरंजक चूर्ण कैल्शियम ऑक्सीक्लोराइड, CaOCl₂, है, जो बुझे हुए चूने पर क्लोरीन प्रवाहित करके बनाया जाता है।"},
  {"id":"sci-chemistry-13","question":"The chemical formula of washing soda is:","options":["NaHCO₃","Na₂CO₃·10H₂O","Na₂B₄O₇·10H₂O","CaOCl₂"],"answer":1,"explanation":"Washing soda is hydrated sodium carbonate; NaHCO₃ is baking soda.","difficulty":"easy","source":"SSC CGL · RRB Group D","questionHi":"धावन सोडा (वाशिंग सोडा) का रासायनिक सूत्र क्या है?","optionsHi":["NaHCO₃","Na₂CO₃·10H₂O","Na₂B₄O₇·10H₂O","CaOCl₂"],"explanationHi":"धावन सोडा जलयोजित सोडियम कार्बोनेट है; NaHCO₃ बेकिंग सोडा है।"},
  {"id":"sci-chemistry-14","question":"The gas used in fire extinguishers is:","options":["Oxygen","Nitrogen","Carbon dioxide","Carbon monoxide"],"answer":2,"explanation":"CO₂ is heavier than air and does not support combustion, so it blankets the fire and cuts off oxygen. Carbon monoxide is itself flammable and poisonous, so it would feed the fire.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"अग्निशामक यंत्रों में प्रयुक्त गैस कौन-सी है?","optionsHi":["ऑक्सीजन","नाइट्रोजन","कार्बन डाइऑक्साइड","कार्बन मोनोऑक्साइड"],"explanationHi":"CO₂ वायु से भारी होती है और दहन में सहायक नहीं होती, इसलिए वह आग को ढककर ऑक्सीजन की आपूर्ति काट देती है। कार्बन मोनोऑक्साइड स्वयं ज्वलनशील और विषैली है, इसलिए वह आग को और भड़काती।"},
  {"id":"sci-chemistry-15","question":"Which metal is liquid at room temperature?","options":["Sodium","Mercury","Gallium","Lead"],"answer":1,"explanation":"Mercury is the only metal that is liquid at ordinary room temperature.","difficulty":"moderate","source":"SSC CGL · RRB Group D","questionHi":"कौन-सी धातु कमरे के तापमान पर द्रव अवस्था में होती है?","optionsHi":["सोडियम","पारा (मर्करी)","गैलियम","सीसा (लेड)"],"explanationHi":"पारा एकमात्र धातु है जो सामान्य कमरे के तापमान पर द्रव होती है।"},
  {"id":"sci-chemistry-16","question":"The pH of pure water at 25 °C is:","options":["0","7","10","14"],"answer":1,"explanation":"Pure water is neutral; below 7 is acidic and above 7 is basic.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"25 °C पर शुद्ध जल का pH कितना होता है?","optionsHi":["0","7","10","14"],"explanationHi":"शुद्ध जल उदासीन होता है; 7 से कम अम्लीय और 7 से अधिक क्षारीय होता है।"},
  {"id":"sci-chemistry-17","question":"Which element has the highest electronegativity?","options":["Oxygen","Chlorine","Fluorine","Nitrogen"],"answer":2,"explanation":"Fluorine, top right of the periodic table, is the most electronegative element.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"किस तत्व की विद्युत ऋणात्मकता सबसे अधिक है?","optionsHi":["ऑक्सीजन","क्लोरीन","फ्लोरीन","नाइट्रोजन"],"explanationHi":"आवर्त सारणी के ऊपरी दाएँ भाग में स्थित फ्लोरीन सबसे अधिक विद्युत ऋणात्मक तत्व है।"},
  {"id":"sci-chemistry-18","question":"Brass is an alloy of:","options":["Copper and tin","Copper and zinc","Iron and carbon","Lead and tin"],"answer":1,"explanation":"Brass is copper + zinc (yellow, used in fittings and utensils), while bronze is copper + tin. Mixing up these two copper alloys is the classic trap; iron + carbon is steel and lead + tin is solder.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"पीतल (ब्रास) किसकी मिश्रधातु है?","optionsHi":["ताँबा और टिन","ताँबा और जस्ता","लोहा और कार्बन","सीसा और टिन"],"explanationHi":"पीतल ताँबा + जस्ता है (पीला, फिटिंग और बर्तनों में प्रयुक्त), जबकि काँसा ताँबा + टिन है। इन दो ताँबे की मिश्रधातुओं को आपस में मिला देना सामान्य भूल है; लोहा + कार्बन इस्पात है और सीसा + टिन सोल्डर है।"},
  {"id":"sci-chemistry-19","question":"Which of these are chemical changes? 1. Rusting of iron 2. Melting of wax 3. Curdling of milk 4. Sublimation of camphor","options":["1 and 3 only","2 and 4 only","1, 2 and 3","All four"],"answer":0,"explanation":"Rusting and curdling form new substances; melting and sublimation only change state.","difficulty":"hard","questionHi":"इनमें से कौन-से रासायनिक परिवर्तन हैं? 1. लोहे में जंग लगना 2. मोम का पिघलना 3. दूध का फटना 4. कपूर का उर्ध्वपातन","optionsHi":["केवल 1 और 3","केवल 2 और 4","1, 2 और 3","सभी चार"],"explanationHi":"जंग लगने और दूध फटने से नए पदार्थ बनते हैं; पिघलने और उर्ध्वपातन में केवल अवस्था बदलती है।"},
  {"id":"sci-chemistry-20","question":"How many moles are there in 22 g of carbon dioxide?","options":["0.5","1.0","2.0","22"],"answer":0,"explanation":"Molar mass of CO₂ = 12 + 2 × 16 = 44 g/mol, so 22 ÷ 44 = 0.5 mol. 2.0 comes from dividing the wrong way (44 ÷ 22), and 1.0 from treating 22 g as one mole.","difficulty":"hard","questionHi":"22 g कार्बन डाइऑक्साइड में कितने मोल होते हैं?","optionsHi":["0.5","1.0","2.0","22"],"explanationHi":"CO₂ का मोलर द्रव्यमान = 12 + 2 × 16 = 44 g/mol, इसलिए 22 ÷ 44 = 0.5 mol। 2.0 उल्टा भाग देने (44 ÷ 22) से आता है, और 1.0 22 g को एक मोल मान लेने से।"},
  {"id":"sci-chemistry-21","question":"Which of these has the highest pH?","options":["Lemon juice","Pure distilled water","Milk of magnesia","Vinegar"],"answer":2,"explanation":"Milk of magnesia (Mg(OH)₂) is basic, pH about 10.5; the others are acidic or neutral.","difficulty":"very-hard","questionHi":"इनमें से किसका pH सबसे अधिक है?","optionsHi":["नींबू का रस","शुद्ध आसुत जल","मिल्क ऑफ मैग्नीशिया","सिरका"],"explanationHi":"मिल्क ऑफ मैग्नीशिया (Mg(OH)₂) क्षारीय है, pH लगभग 10.5; अन्य अम्लीय या उदासीन हैं।"},
  {"id":"sci-chemistry-22","question":"What volume of oxygen at STP is needed to burn 1 mole of methane completely?","options":["11.2 L","22.4 L","44.8 L","67.2 L"],"answer":2,"explanation":"Balance first: CH₄ + 2O₂ → CO₂ + 2H₂O, so 1 mol methane needs 2 mol O₂ = 2 × 22.4 L = 44.8 L at STP. 22.4 L is the trap of using the unbalanced 1 : 1 ratio.","difficulty":"very-hard","questionHi":"1 मोल मेथेन के पूर्ण दहन के लिए STP पर कितने आयतन ऑक्सीजन की आवश्यकता होती है?","optionsHi":["11.2 L","22.4 L","44.8 L","67.2 L"],"explanationHi":"पहले समीकरण संतुलित कीजिए: CH₄ + 2O₂ → CO₂ + 2H₂O, इसलिए 1 mol मेथेन को 2 mol O₂ = 2 × 22.4 L = 44.8 L STP पर चाहिए। 22.4 L असंतुलित 1 : 1 अनुपात लेने का भ्रम है।"},
  {"id":"sci-chemistry-23","question":"How many of these statements are correct? I. Diamond and graphite are allotropes of carbon. II. Graphite conducts electricity. III. Diamond conducts electricity well. IV. Fullerene (C₆₀) is an allotrope of carbon.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Diamond has no free electrons and does not conduct.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. हीरा और ग्रेफाइट कार्बन के अपररूप हैं। II. ग्रेफाइट विद्युत का चालन करता है। III. हीरा विद्युत का अच्छा चालन करता है। IV. फुलरीन (C₆₀) कार्बन का एक अपररूप है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। हीरे में मुक्त इलेक्ट्रॉन नहीं होते और वह विद्युत का चालन नहीं करता।"},
  {"id":"sci-chemistry-24","question":"How many of these statements are correct? I. Noble gases have completely filled outer shells. II. Helium has eight electrons in its outer shell. III. Argon is the most abundant noble gas in the atmosphere.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and III. Helium has just two electrons, which fill its only shell.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. उत्कृष्ट गैसों के बाह्यतम कोश पूर्णतः भरे होते हैं। II. हीलियम के बाह्यतम कोश में आठ इलेक्ट्रॉन होते हैं। III. आर्गन वायुमंडल में सबसे प्रचुर उत्कृष्ट गैस है।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"केवल I और III। हीलियम में केवल दो इलेक्ट्रॉन होते हैं, जो उसके एकमात्र कोश को भर देते हैं।"},
  {"id":"sci-chemistry-25","question":"What is the pH of a 0.001 M solution of HCl?","options":["1","3","11","0.001"],"answer":1,"explanation":"HCl ionises fully, so [H⁺] = 10⁻³ M and pH = −log(10⁻³) = 3.","difficulty":"very-hard","questionHi":"0.001 M HCl विलयन का pH कितना है?","optionsHi":["1","3","11","0.001"],"explanationHi":"HCl पूर्णतः आयनित होता है, इसलिए [H⁺] = 10⁻³ M और pH = −log(10⁻³) = 3।"},
  {"id":"sci-chemistry-26","question":"How many of these statements are correct? I. Isotopes have the same atomic number. II. Isobars have the same mass number. III. Isotopes have identical physical properties.","options":["Only one","Only two","All three","None"],"answer":1,"explanation":"Only I and II. Isotopes share chemical properties but differ in physical ones such as mass and density.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. समस्थानिकों का परमाणु क्रमांक समान होता है। II. समभारिकों की द्रव्यमान संख्या समान होती है। III. समस्थानिकों के भौतिक गुण समान होते हैं।","optionsHi":["केवल एक","केवल दो","सभी तीन","कोई नहीं"],"explanationHi":"केवल I और II। समस्थानिकों के रासायनिक गुण समान होते हैं, परंतु द्रव्यमान और घनत्व जैसे भौतिक गुण भिन्न होते हैं।"},
  {"id":"sci-chemistry-27","question":"How many molecules are there in 36 g of water?","options":["3.011 × 10²³","6.022 × 10²³","1.204 × 10²⁴","1.505 × 10²³"],"answer":2,"explanation":"The molar mass of H₂O is 18 g/mol, so 36 g is 2 mol, i.e. 2 × 6.022 × 10²³ = 1.204 × 10²⁴ molecules.","difficulty":"very-hard","questionHi":"36 g जल में कितने अणु होते हैं?","optionsHi":["3.011 × 10²³","6.022 × 10²³","1.204 × 10²⁴","1.505 × 10²³"],"explanationHi":"H₂O का मोलर द्रव्यमान 18 g/mol है, इसलिए 36 g = 2 mol, अर्थात 2 × 6.022 × 10²³ = 1.204 × 10²⁴ अणु।"},
  {"id":"sci-chemistry-28","question":"How many grams of calcium carbonate must be heated to obtain 11.2 L of carbon dioxide at STP? (Ca = 40, C = 12, O = 16)","options":["50 g","100 g","25 g","56 g"],"answer":0,"explanation":"CaCO₃ → CaO + CO₂. 11.2 L at STP is 0.5 mol of CO₂, so 0.5 mol of CaCO₃ (molar mass 100 g/mol) = 50 g is needed.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"STP पर 11.2 L कार्बन डाइऑक्साइड प्राप्त करने के लिए कितने ग्राम कैल्शियम कार्बोनेट को गर्म करना होगा? (Ca = 40, C = 12, O = 16)","optionsHi":["50 g","100 g","25 g","56 g"],"explanationHi":"CaCO₃ → CaO + CO₂। STP पर 11.2 L = 0.5 mol CO₂ है, इसलिए 0.5 mol CaCO₃ (मोलर द्रव्यमान 100 g/mol) = 50 g चाहिए।"},
  {"id":"sci-chemistry-29","question":"How many of these statements are correct? I. In the electrolysis of water, hydrogen collects at the anode. II. The volume of oxygen produced is twice that of hydrogen. III. Rusting of iron needs both oxygen and water. IV. Galvanisation coats iron with a layer of tin.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only III is correct. Hydrogen collects at the cathode (negative electrode), and its volume is twice that of oxygen since water is H₂O. Galvanisation coats iron with zinc, not tin.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. जल के विद्युत अपघटन में हाइड्रोजन एनोड पर एकत्र होती है। II. उत्पन्न ऑक्सीजन का आयतन हाइड्रोजन के आयतन का दोगुना होता है। III. लोहे में जंग लगने के लिए ऑक्सीजन और जल दोनों की आवश्यकता होती है। IV. यशदलेपन (गैल्वनीकरण) में लोहे पर टिन की परत चढ़ाई जाती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल III सही है। हाइड्रोजन कैथोड (ऋणात्मक इलेक्ट्रोड) पर एकत्र होती है, और उसका आयतन ऑक्सीजन का दोगुना होता है क्योंकि जल H₂O है। यशदलेपन में लोहे पर जस्ते की परत चढ़ाई जाती है, टिन की नहीं।"},
  {"id":"sci-chemistry-30","question":"The chemical symbol of sodium is:","options":["S","So","Na","Sn"],"answer":2,"explanation":"Na comes from the Latin name natrium; S is sulphur and Sn is tin (stannum).","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"सोडियम का रासायनिक प्रतीक क्या है?","optionsHi":["S","So","Na","Sn"],"explanationHi":"Na लैटिन नाम नैट्रियम से आया है; S सल्फर और Sn टिन (स्टैनम) है।"},
  {"id":"sci-chemistry-31","question":"The gas evolved when zinc reacts with dilute hydrochloric acid is:","options":["Oxygen","Hydrogen","Chlorine","Carbon dioxide"],"answer":1,"explanation":"Zn + 2HCl → ZnCl₂ + H₂; a metal above hydrogen in the reactivity series displaces hydrogen from a dilute acid.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"जिंक की तनु हाइड्रोक्लोरिक अम्ल से अभिक्रिया पर कौन-सी गैस निकलती है?","optionsHi":["ऑक्सीजन","हाइड्रोजन","क्लोरीन","कार्बन डाइऑक्साइड"],"explanationHi":"Zn + 2HCl → ZnCl₂ + H₂; क्रियाशीलता श्रेणी में हाइड्रोजन से ऊपर की धातु तनु अम्ल से हाइड्रोजन को विस्थापित कर देती है।"},
  {"id":"sci-chemistry-32","question":"The atomic number of an element is equal to the number of:","options":["Neutrons","Protons","Nucleons","Isotopes"],"answer":1,"explanation":"Atomic number Z = number of protons (= electrons in a neutral atom); the mass number counts protons plus neutrons.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"किसी तत्व का परमाणु क्रमांक किसकी संख्या के बराबर होता है?","optionsHi":["न्यूट्रॉनों","प्रोटॉनों","न्यूक्लिऑनों","समस्थानिकों"],"explanationHi":"परमाणु क्रमांक Z = प्रोटॉनों की संख्या (उदासीन परमाणु में इलेक्ट्रॉनों के बराबर); द्रव्यमान संख्या प्रोटॉन और न्यूट्रॉन का योग गिनती है।"},
  {"id":"sci-chemistry-33","question":"Which of the following is a noble gas?","options":["Nitrogen","Neon","Hydrogen","Oxygen"],"answer":1,"explanation":"Neon belongs to group 18 (He, Ne, Ar, Kr, Xe, Rn), whose completely filled outer shells make them almost unreactive.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"निम्नलिखित में से कौन-सी उत्कृष्ट गैस है?","optionsHi":["नाइट्रोजन","नियॉन","हाइड्रोजन","ऑक्सीजन"],"explanationHi":"नियॉन समूह 18 (He, Ne, Ar, Kr, Xe, Rn) का सदस्य है, जिनके पूर्णतः भरे बाह्यतम कोश उन्हें लगभग अक्रिय बना देते हैं।"},
  {"id":"sci-chemistry-34","question":"The chemical formula of ozone is:","options":["O","O₂","O₃","O₄"],"answer":2,"explanation":"Ozone is a triatomic allotrope of oxygen, O₃, found in the stratosphere where it absorbs ultraviolet light.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"ओज़ोन का रासायनिक सूत्र क्या है?","optionsHi":["O","O₂","O₃","O₄"],"explanationHi":"ओज़ोन ऑक्सीजन का त्रिपरमाण्विक अपररूप, O₃, है, जो समताप मंडल में पाई जाती है जहाँ वह पराबैंगनी प्रकाश को अवशोषित करती है।"},
  {"id":"sci-chemistry-35","question":"Vinegar is a dilute solution of:","options":["Citric acid","Lactic acid","Acetic acid","Formic acid"],"answer":2,"explanation":"Vinegar contains about 5–8% acetic (ethanoic) acid, CH₃COOH, in water.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"सिरका किसका तनु विलयन होता है?","optionsHi":["साइट्रिक अम्ल","लैक्टिक अम्ल","एसीटिक अम्ल","फॉर्मिक अम्ल"],"explanationHi":"सिरके में जल में लगभग 5–8% एसीटिक (एथेनॉइक) अम्ल, CH₃COOH, होता है।"},
  {"id":"sci-chemistry-36","question":"Aluminium is extracted mainly from which ore?","options":["Haematite","Bauxite","Galena","Cinnabar"],"answer":1,"explanation":"Bauxite (hydrated aluminium oxide) is purified to alumina and then electrolysed; haematite gives iron, galena lead and cinnabar mercury.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"ऐलुमिनियम का निष्कर्षण मुख्यतः किस अयस्क से किया जाता है?","optionsHi":["हेमेटाइट","बॉक्साइट","गैलेना","सिनेबार"],"explanationHi":"बॉक्साइट (जलयोजित ऐलुमिनियम ऑक्साइड) को शुद्ध करके ऐलुमिना बनाया जाता है और फिर विद्युत अपघटित किया जाता है; हेमेटाइट से लोहा, गैलेना से सीसा और सिनेबार से पारा मिलता है।"},
  {"id":"sci-chemistry-37","question":"The element present in all acids is:","options":["Oxygen","Chlorine","Hydrogen","Sulphur"],"answer":2,"explanation":"An acid releases H⁺ ions in water; HCl, for example, contains no oxygen, so oxygen is not essential to acids.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"सभी अम्लों में उपस्थित तत्व कौन-सा है?","optionsHi":["ऑक्सीजन","क्लोरीन","हाइड्रोजन","सल्फर"],"explanationHi":"अम्ल जल में H⁺ आयन मुक्त करता है; उदाहरण के लिए HCl में ऑक्सीजन नहीं होती, इसलिए अम्लों में ऑक्सीजन अनिवार्य नहीं है।"},
  {"id":"sci-chemistry-38","question":"Dry ice, used to keep food and medicines cold in transit, is:","options":["Frozen water without air","Solid carbon dioxide","Solid ammonia","Frozen nitrogen"],"answer":1,"explanation":"Dry ice is solid CO₂, which sublimes directly to gas at −78.5 °C and so leaves no liquid behind.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"शुष्क बर्फ (ड्राई आइस), जिसका उपयोग परिवहन के दौरान भोजन और दवाओं को ठंडा रखने में होता है, क्या है?","optionsHi":["हवा रहित जमा हुआ पानी","ठोस कार्बन डाइऑक्साइड","ठोस अमोनिया","जमी हुई नाइट्रोजन"],"explanationHi":"शुष्क बर्फ ठोस CO₂ है, जो −78.5 °C पर सीधे गैस में ऊर्ध्वपातित हो जाती है और इसलिए कोई द्रव नहीं छोड़ती।"},
  {"id":"sci-chemistry-39","question":"The number of neutrons in an atom of ²³Na (atomic number 11) is:","options":["11","12","23","34"],"answer":1,"explanation":"Neutrons = mass number − atomic number = 23 − 11 = 12. 11 is the proton (and electron) count, and 23 is the total number of nucleons, not neutrons.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"²³Na (परमाणु क्रमांक 11) के परमाणु में न्यूट्रॉनों की संख्या कितनी है?","optionsHi":["11","12","23","34"],"explanationHi":"न्यूट्रॉन = द्रव्यमान संख्या − परमाणु क्रमांक = 23 − 11 = 12। 11 प्रोटॉन (और इलेक्ट्रॉन) की संख्या है, और 23 न्यूक्लिऑनों की कुल संख्या है, न्यूट्रॉनों की नहीं।"},
  {"id":"sci-chemistry-40","question":"Which of the following is an endothermic change?","options":["Burning of coal","Respiration","Photosynthesis","Neutralisation of an acid by a base"],"answer":2,"explanation":"Photosynthesis absorbs light energy to make glucose; combustion, respiration and neutralisation all release heat.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"निम्नलिखित में से कौन-सा ऊष्माशोषी परिवर्तन है?","optionsHi":["कोयले का जलना","श्वसन","प्रकाश संश्लेषण","अम्ल का क्षार द्वारा उदासीनीकरण"],"explanationHi":"प्रकाश संश्लेषण ग्लूकोज बनाने के लिए प्रकाश ऊर्जा का अवशोषण करता है; दहन, श्वसन और उदासीनीकरण तीनों में ऊष्मा निकलती है।"},
  {"id":"sci-chemistry-41","question":"The gas released when baking soda is heated is:","options":["Hydrogen","Oxygen","Carbon dioxide","Carbon monoxide"],"answer":2,"explanation":"On heating, 2NaHCO₃ → Na₂CO₃ + H₂O + CO₂, and the carbon dioxide makes cakes rise. Carbon monoxide is not formed, because the carbon in the hydrogencarbonate is already fully oxidised.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"बेकिंग सोडा को गर्म करने पर कौन-सी गैस निकलती है?","optionsHi":["हाइड्रोजन","ऑक्सीजन","कार्बन डाइऑक्साइड","कार्बन मोनोऑक्साइड"],"explanationHi":"गर्म करने पर 2NaHCO₃ → Na₂CO₃ + H₂O + CO₂ होता है, और कार्बन डाइऑक्साइड केक को फुला देती है। कार्बन मोनोऑक्साइड नहीं बनती, क्योंकि हाइड्रोजनकार्बोनेट में कार्बन पहले से पूर्णतः ऑक्सीकृत है।"},
  {"id":"sci-chemistry-42","question":"In the electrolytic refining of copper, the cathode is made of:","options":["A thick block of impure copper","A thin strip of pure copper","A graphite rod","An inert platinum plate"],"answer":1,"explanation":"The impure copper block is the anode, a pure copper strip is the cathode, and copper sulphate solution is the electrolyte; pure copper deposits on the cathode.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"ताँबे के विद्युत अपघटनी परिष्करण में कैथोड किससे बना होता है?","optionsHi":["अशुद्ध ताँबे का मोटा ब्लॉक","शुद्ध ताँबे की पतली पट्टी","ग्रेफाइट की छड़","अक्रिय प्लैटिनम की प्लेट"],"explanationHi":"अशुद्ध ताँबे का ब्लॉक ऐनोड होता है, शुद्ध ताँबे की पट्टी कैथोड होती है, और कॉपर सल्फेट विलयन विद्युत अपघट्य होता है; शुद्ध ताँबा कैथोड पर जमा होता है।"},
  {"id":"sci-chemistry-43","question":"The oxidation number of manganese in KMnO₄ is:","options":["+2","+4","+6","+7"],"answer":3,"explanation":"K is +1 and each O is −2, so +1 + x + 4(−2) = 0 and x = +7, the highest state of Mn. +6 is the trap from K₂MnO₄ (manganate), where two K atoms change the sum.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"KMnO₄ में मैंगनीज की ऑक्सीकरण संख्या कितनी है?","optionsHi":["+2","+4","+6","+7"],"explanationHi":"K का +1 और प्रत्येक O का −2 है, इसलिए +1 + x + 4(−2) = 0 और x = +7, जो Mn की उच्चतम अवस्था है। +6 K₂MnO₄ (मैंगनेट) से आने वाला भ्रम है, जिसमें दो K परमाणु योग को बदल देते हैं।"},
  {"id":"sci-chemistry-44","question":"Phenolphthalein turns which colour in a basic solution?","options":["Red","Pink","Blue","Colourless"],"answer":1,"explanation":"Phenolphthalein is colourless in acid and turns pink in base; litmus is the indicator that turns blue in base.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"फिनॉल्फ्थेलिन क्षारीय विलयन में कौन-सा रंग देता है?","optionsHi":["लाल","गुलाबी","नीला","रंगहीन"],"explanationHi":"फिनॉल्फ्थेलिन अम्ल में रंगहीन रहता है और क्षार में गुलाबी हो जाता है; लिटमस वह सूचक है जो क्षार में नीला होता है।"},
  {"id":"sci-chemistry-45","question":"Sulphuric acid, the “king of chemicals”, is manufactured industrially by the:","options":["Haber process","Contact process","Ostwald process","Solvay process"],"answer":1,"explanation":"The contact process oxidises SO₂ to SO₃ over a V₂O₅ catalyst; Haber makes ammonia, Ostwald nitric acid and Solvay sodium carbonate.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"सल्फ्यूरिक अम्ल, जिसे “रसायनों का राजा” कहा जाता है, का औद्योगिक निर्माण किस विधि से होता है?","optionsHi":["हैबर प्रक्रम","संपर्क प्रक्रम","ओस्टवाल्ड प्रक्रम","सॉल्वे प्रक्रम"],"explanationHi":"संपर्क प्रक्रम में V₂O₅ उत्प्रेरक पर SO₂ का SO₃ में ऑक्सीकरण किया जाता है; हैबर प्रक्रम से अमोनिया, ओस्टवाल्ड प्रक्रम से नाइट्रिक अम्ल और सॉल्वे प्रक्रम से सोडियम कार्बोनेट बनता है।"},
  {"id":"sci-chemistry-46","question":"The mass of NaOH required to prepare 500 mL of a 0.2 M solution is (Na = 23, O = 16, H = 1):","options":["2 g","4 g","8 g","40 g"],"answer":1,"explanation":"Moles = molarity × volume in litres = 0.2 × 0.5 = 0.1 mol, and mass = 0.1 × 40 = 4 g. 8 g forgets to convert 500 mL to 0.5 L, and 40 g is the mass of one whole mole.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"0.2 M विलयन के 500 mL बनाने के लिए आवश्यक NaOH का द्रव्यमान कितना है (Na = 23, O = 16, H = 1)?","optionsHi":["2 g","4 g","8 g","40 g"],"explanationHi":"मोल = मोलरता × आयतन (लीटर में) = 0.2 × 0.5 = 0.1 mol, और द्रव्यमान = 0.1 × 40 = 4 g। 8 g तब आता है जब 500 mL को 0.5 L में बदलना भूल जाएँ, और 40 g एक पूरे मोल का द्रव्यमान है।"},
  {"id":"sci-chemistry-47","question":"Temporary hardness of water is caused by the presence of:","options":["Chlorides of calcium and magnesium","Sulphates of calcium and magnesium","Bicarbonates of calcium and magnesium","Dissolved sodium chloride (common salt)"],"answer":2,"explanation":"Bicarbonates decompose on boiling and precipitate as carbonates, so this hardness is “temporary”; chlorides and sulphates cause permanent hardness.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"जल की अस्थायी कठोरता किसकी उपस्थिति के कारण होती है?","optionsHi":["कैल्शियम और मैग्नीशियम के क्लोराइड","कैल्शियम और मैग्नीशियम के सल्फेट","कैल्शियम और मैग्नीशियम के बाइकार्बोनेट","घुला हुआ सोडियम क्लोराइड (सामान्य नमक)"],"explanationHi":"बाइकार्बोनेट उबालने पर विघटित होकर कार्बोनेट के रूप में अवक्षेपित हो जाते हैं, इसलिए यह कठोरता “अस्थायी” है; क्लोराइड और सल्फेट स्थायी कठोरता उत्पन्न करते हैं।"},
  {"id":"sci-chemistry-48","question":"How many of these statements are correct? I. At 25 °C, pH + pOH = 14. II. A solution of pH 2 is ten times more acidic than one of pH 3. III. Milk of magnesia is an acidic suspension. IV. The pH of lemon juice is about 2 to 3.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct (the pH scale is logarithmic). III is wrong: milk of magnesia, Mg(OH)₂, is basic and is used as an antacid.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. 25 °C पर pH + pOH = 14। II. pH 2 वाला विलयन pH 3 वाले विलयन से दस गुना अधिक अम्लीय होता है। III. मिल्क ऑफ मैग्नीशिया अम्लीय निलंबन है। IV. नींबू के रस का pH लगभग 2 से 3 होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं (pH पैमाना लघुगणकीय है)। III गलत है: मिल्क ऑफ मैग्नीशिया, Mg(OH)₂, क्षारीय है और प्रति-अम्ल (एंटैसिड) के रूप में प्रयुक्त होता है।"},
  {"id":"sci-chemistry-49","question":"Assertion (A): Aluminium utensils do not corrode easily in air. Reason (R): A thin, tough layer of aluminium oxide forms on the surface and protects the metal underneath.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Although aluminium is a reactive metal, the Al₂O₃ film formed instantly in air is impermeable and self-healing, so corrosion stops at the surface.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"अभिकथन (A): ऐलुमिनियम के बर्तन वायु में आसानी से संक्षारित नहीं होते। कारण (R): सतह पर ऐलुमिनियम ऑक्साइड की पतली, मजबूत परत बन जाती है जो नीचे की धातु की रक्षा करती है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"यद्यपि ऐलुमिनियम एक क्रियाशील धातु है, वायु में तुरंत बनने वाली Al₂O₃ की परत अपारगम्य और स्वतः-मरम्मत करने वाली होती है, इसलिए संक्षारण सतह पर ही रुक जाता है।"},
  {"id":"sci-chemistry-50","question":"Match the common name with the compound: 1. Gypsum 2. Blue vitriol 3. Epsom salt 4. Caustic soda; a. MgSO₄·7H₂O b. NaOH c. CaSO₄·2H₂O d. CuSO₄·5H₂O","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-a, 2-d, 3-c, 4-b"],"answer":0,"explanation":"Gypsum is CaSO₄·2H₂O, blue vitriol CuSO₄·5H₂O, Epsom salt MgSO₄·7H₂O and caustic soda NaOH.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"प्रचलित नाम का यौगिक से मिलान कीजिए: 1. जिप्सम 2. नीला थोथा (ब्लू विट्रियॉल) 3. एप्सम लवण 4. कॉस्टिक सोडा; a. MgSO₄·7H₂O b. NaOH c. CaSO₄·2H₂O d. CuSO₄·5H₂O","optionsHi":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-a, 4-b","1-c, 2-a, 3-d, 4-b","1-a, 2-d, 3-c, 4-b"],"explanationHi":"जिप्सम CaSO₄·2H₂O है, नीला थोथा CuSO₄·5H₂O, एप्सम लवण MgSO₄·7H₂O और कॉस्टिक सोडा NaOH है।"},
  {"id":"sci-chemistry-51","question":"4 g of hydrogen is burnt with 32 g of oxygen (H = 1, O = 16). The mass of water formed is:","options":["18 g","32 g","36 g","72 g"],"answer":2,"explanation":"2H₂ + O₂ → 2H₂O: 4 g H₂ = 2 mol needs exactly 1 mol (32 g) O₂, giving 2 mol of water = 36 g, consistent with conservation of mass.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"4 g हाइड्रोजन को 32 g ऑक्सीजन के साथ जलाया जाता है (H = 1, O = 16)। बने जल का द्रव्यमान कितना है?","optionsHi":["18 g","32 g","36 g","72 g"],"explanationHi":"2H₂ + O₂ → 2H₂O: 4 g H₂ = 2 mol को ठीक 1 mol (32 g) O₂ चाहिए, जिससे 2 mol जल = 36 g बनता है, जो द्रव्यमान संरक्षण के अनुरूप है।"},
  {"id":"sci-chemistry-52","question":"Which of the following alloys does NOT contain copper?","options":["Brass","Bronze","German silver","Solder"],"answer":3,"explanation":"Solder is an alloy of lead and tin. Brass is Cu + Zn, bronze Cu + Sn and German silver Cu + Zn + Ni.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"निम्नलिखित में से किस मिश्रधातु में ताँबा नहीं होता?","optionsHi":["पीतल (ब्रास)","काँसा (ब्रॉन्ज़)","जर्मन सिल्वर","सोल्डर"],"explanationHi":"सोल्डर सीसा और टिन की मिश्रधातु है। पीतल Cu + Zn है, काँसा Cu + Sn और जर्मन सिल्वर Cu + Zn + Ni है।"},
  {"id":"sci-chemistry-53","question":"How many of these statements are correct? I. Rutherford discovered the nucleus through the alpha-particle scattering experiment. II. Chadwick discovered the neutron in 1932. III. The electron was discovered by Goldstein. IV. The K shell can hold a maximum of eight electrons.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"I and II are correct. III is wrong: J. J. Thomson discovered the electron; Goldstein discovered canal rays. IV is wrong: the K shell holds at most 2 electrons (2n² with n = 1); eight is the L shell's maximum.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. रदरफोर्ड ने ऐल्फा-कण प्रकीर्णन प्रयोग द्वारा नाभिक की खोज की। II. चैडविक ने 1932 में न्यूट्रॉन की खोज की। III. इलेक्ट्रॉन की खोज गोल्डस्टीन ने की। IV. K कोश में अधिकतम आठ इलेक्ट्रॉन आ सकते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I और II सही हैं। III गलत है: इलेक्ट्रॉन की खोज जे. जे. थॉमसन ने की; गोल्डस्टीन ने केनाल किरणें खोजीं। IV गलत है: K कोश में अधिकतम 2 इलेक्ट्रॉन आते हैं (2n², जहाँ n = 1); आठ L कोश की अधिकतम संख्या है।"},
  {"id":"sci-chemistry-54","question":"Arrange in chronological order: 1. Mendeleev’s periodic table 2. Dobereiner’s triads 3. Moseley’s modern periodic law 4. Newlands’ law of octaves","options":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1"],"answer":0,"explanation":"Dobereiner’s triads (1829) → Newlands’ octaves (1866) → Mendeleev’s table (1869) → Moseley’s law based on atomic number (1913).","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. मेंडेलीव की आवर्त सारणी 2. डोबेराइनर की त्रयी 3. मोसले का आधुनिक आवर्त नियम 4. न्यूलैंड्स का अष्टक नियम","optionsHi":["2, 4, 1, 3","2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1"],"explanationHi":"डोबेराइनर की त्रयी (1829) → न्यूलैंड्स का अष्टक (1866) → मेंडेलीव की सारणी (1869) → परमाणु क्रमांक पर आधारित मोसले का नियम (1913)।"},
  {"id":"sci-chemistry-55","question":"Assertion (A): Noble gases are chemically inert. Reason (R): Noble gases have completely filled outermost shells.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"A stable, filled valence shell (2 for He, 8 for the rest) means there is no tendency to gain, lose or share electrons, which is exactly why they are inert.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"अभिकथन (A): उत्कृष्ट गैसें रासायनिक रूप से अक्रिय होती हैं। कारण (R): उत्कृष्ट गैसों के बाह्यतम कोश पूर्णतः भरे होते हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"स्थिर, भरा हुआ संयोजकता कोश (He के लिए 2, शेष के लिए 8) होने का अर्थ है कि इलेक्ट्रॉन ग्रहण करने, त्यागने या साझा करने की कोई प्रवृत्ति नहीं रहती, और इसीलिए वे अक्रिय हैं।"},
  {"id":"sci-chemistry-56","question":"The number of oxygen atoms in 8 g of oxygen gas is (O = 16, Avogadro’s number = 6.022 × 10²³):","options":["1.505 × 10²³","3.011 × 10²³","6.022 × 10²³","1.204 × 10²⁴"],"answer":1,"explanation":"8 g of O₂ = 8/32 = 0.25 mol of molecules = 0.5 mol of atoms = 0.5 × 6.022 × 10²³ = 3.011 × 10²³ atoms; counting molecules instead gives 1.505 × 10²³.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"8 g ऑक्सीजन गैस में ऑक्सीजन परमाणुओं की संख्या कितनी है (O = 16, आवोगाद्रो संख्या = 6.022 × 10²³)?","optionsHi":["1.505 × 10²³","3.011 × 10²³","6.022 × 10²³","1.204 × 10²⁴"],"explanationHi":"8 g O₂ = 8/32 = 0.25 mol अणु = 0.5 mol परमाणु = 0.5 × 6.022 × 10²³ = 3.011 × 10²³ परमाणु; इसके बजाय अणु गिनने पर 1.505 × 10²³ आता है।"},
  {"id":"sci-chemistry-57","question":"How many of these statements about metals are correct? I. Sodium is stored under kerosene. II. Gold is the most malleable metal. III. Silver is the best conductor of electricity. IV. Tungsten has the lowest melting point among metals.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: tungsten has the highest melting point of all metals (about 3,400 °C), which is why it is used for bulb filaments.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"धातुओं से संबंधित इनमें से कितने कथन सही हैं? I. सोडियम को मिट्टी के तेल में रखा जाता है। II. सोना सबसे आघातवर्ध्य धातु है। III. चाँदी विद्युत की सर्वश्रेष्ठ चालक है। IV. धातुओं में टंगस्टन का गलनांक सबसे कम होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: टंगस्टन का गलनांक सभी धातुओं में सबसे अधिक (लगभग 3,400 °C) होता है, इसीलिए उसे बल्ब के तंतु में प्रयोग किया जाता है।"},
  {"id":"sci-chemistry-58","question":"Match the acid with its natural source: 1. Citric acid 2. Lactic acid 3. Oxalic acid 4. Formic acid; a. Ant sting b. Curd c. Lemon d. Tomato","options":["1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-c, 2-b, 3-a, 4-d"],"answer":0,"explanation":"Lemon → citric acid, curd → lactic acid, tomato (and spinach) → oxalic acid, ant sting → formic acid.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"अम्ल का उसके प्राकृतिक स्रोत से मिलान कीजिए: 1. साइट्रिक अम्ल 2. लैक्टिक अम्ल 3. ऑक्सैलिक अम्ल 4. फॉर्मिक अम्ल; a. चींटी का डंक b. दही c. नींबू d. टमाटर","optionsHi":["1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-c, 2-b, 3-a, 4-d"],"explanationHi":"नींबू → साइट्रिक अम्ल, दही → लैक्टिक अम्ल, टमाटर (और पालक) → ऑक्सैलिक अम्ल, चींटी का डंक → फॉर्मिक अम्ल।"},
  {"id":"sci-chemistry-59","question":"Which of the following reactions is both a displacement and a redox reaction?","options":["NaOH + HCl → NaCl + H₂O","CaCO₃ → CaO + CO₂","Zn + CuSO₄ → ZnSO₄ + Cu","AgNO₃ + NaCl → AgCl + NaNO₃"],"answer":2,"explanation":"Zinc displaces copper and is oxidised (Zn → Zn²⁺) while Cu²⁺ is reduced. Neutralisation and double displacement involve no change in oxidation state, and the decomposition of CaCO₃ is not redox either.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"निम्नलिखित में से कौन-सी अभिक्रिया विस्थापन और रेडॉक्स दोनों है?","optionsHi":["NaOH + HCl → NaCl + H₂O","CaCO₃ → CaO + CO₂","Zn + CuSO₄ → ZnSO₄ + Cu","AgNO₃ + NaCl → AgCl + NaNO₃"],"explanationHi":"जिंक ताँबे को विस्थापित करता है और ऑक्सीकृत होता है (Zn → Zn²⁺) जबकि Cu²⁺ अपचयित होता है। उदासीनीकरण और द्विविस्थापन में ऑक्सीकरण अवस्था में कोई परिवर्तन नहीं होता, और CaCO₃ का अपघटन भी रेडॉक्स नहीं है।"},
  {"id":"sci-chemistry-60","question":"The chemical symbol of iron is:","options":["Ir","Fe","In","I"],"answer":1,"explanation":"Fe comes from the Latin name ferrum. Ir is iridium, In is indium and I is iodine.","difficulty":"easy","source":"SSC GD · RRB Group D","questionHi":"लोहे का रासायनिक प्रतीक क्या है?","optionsHi":["Ir","Fe","In","I"],"explanationHi":"Fe लैटिन नाम फेरम से आया है। Ir इरिडियम है, In इंडियम है और I आयोडीन है।"},
  {"id":"sci-chemistry-61","question":"The chemical name of common table sugar is:","options":["Glucose","Fructose","Sucrose","Lactose"],"answer":2,"explanation":"Table sugar is sucrose (C₁₂H₂₂O₁₁), a disaccharide of glucose and fructose. Lactose is milk sugar.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"सामान्य खाने की चीनी का रासायनिक नाम क्या है?","optionsHi":["ग्लूकोज","फ्रक्टोज","सुक्रोज","लैक्टोज"],"explanationHi":"खाने की चीनी सुक्रोज (C₁₂H₂₂O₁₁) है, जो ग्लूकोज और फ्रक्टोज का एक डाइसैकेराइड है। लैक्टोज दूध की शर्करा है।"},
  {"id":"sci-chemistry-62","question":"Which gas burns with a “pop” sound when a burning splinter is brought near it?","options":["Oxygen","Carbon dioxide","Nitrogen","Hydrogen"],"answer":3,"explanation":"Hydrogen burns explosively with a pop. Oxygen relights a glowing splinter, and carbon dioxide puts a flame out.","difficulty":"moderate","source":"RRB Group D · SSC CHSL","questionHi":"किस गैस के पास जलती हुई तीली ले जाने पर वह “पॉप” की ध्वनि के साथ जलती है?","optionsHi":["ऑक्सीजन","कार्बन डाइऑक्साइड","नाइट्रोजन","हाइड्रोजन"],"explanationHi":"हाइड्रोजन “पॉप” की ध्वनि के साथ विस्फोटक रूप से जलती है। ऑक्सीजन सुलगती हुई तीली को फिर जला देती है, और कार्बन डाइऑक्साइड लौ को बुझा देती है।"},
  {"id":"sci-chemistry-63","question":"Which gas is known as “marsh gas”?","options":["Methane","Ethane","Butane","Hydrogen"],"answer":0,"explanation":"Methane (CH₄) is produced when plant matter decays without air in marshes and paddy fields, hence the name.","difficulty":"moderate","source":"RRB Group D · SSC CHSL","questionHi":"किस गैस को “मार्श गैस (दलदली गैस)” कहा जाता है?","optionsHi":["मेथेन","एथेन","ब्यूटेन","हाइड्रोजन"],"explanationHi":"दलदलों और धान के खेतों में वायु के अभाव में पादप पदार्थ के सड़ने से मेथेन (CH₄) बनती है, इसीलिए यह नाम पड़ा।"},
  {"id":"sci-chemistry-64","question":"Which acid is secreted in the human stomach?","options":["Sulphuric acid","Hydrofluoric acid","Hydrochloric acid","Acetic acid"],"answer":2,"explanation":"Gastric glands secrete dilute hydrochloric acid, which activates pepsin and kills germs in food.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"मानव आमाशय में कौन-सा अम्ल स्रावित होता है?","optionsHi":["सल्फ्यूरिक अम्ल","हाइड्रोफ्लोरिक अम्ल","हाइड्रोक्लोरिक अम्ल","एसीटिक अम्ल"],"explanationHi":"जठर ग्रंथियाँ तनु हाइड्रोक्लोरिक अम्ल का स्राव करती हैं, जो पेप्सिन को सक्रिय करता है और भोजन के रोगाणुओं को मारता है।"},
  {"id":"sci-chemistry-65","question":"Liquefied petroleum gas (LPG) used for cooking consists mainly of:","options":["Methane and ethane","Butane and propane","Hydrogen and carbon monoxide","Ethylene and acetylene"],"answer":1,"explanation":"LPG is mostly butane and propane; ethyl mercaptan is added to give it a smell for detecting leaks. CNG is mainly methane.","difficulty":"moderate","source":"RRB Group D · SSC CHSL","questionHi":"खाना पकाने में प्रयुक्त द्रवित पेट्रोलियम गैस (LPG) मुख्यतः किससे बनी होती है?","optionsHi":["मेथेन और एथेन","ब्यूटेन और प्रोपेन","हाइड्रोजन और कार्बन मोनोऑक्साइड","एथिलीन और ऐसीटिलीन"],"explanationHi":"LPG मुख्यतः ब्यूटेन और प्रोपेन है; रिसाव का पता लगाने के लिए उसमें गंध देने हेतु एथिल मर्कैप्टन मिलाया जाता है। CNG मुख्यतः मेथेन है।"},
  {"id":"sci-chemistry-66","question":"The depletion of the stratospheric ozone layer is caused mainly by:","options":["Carbon dioxide","Methane","Sulphur hexafluoride","Chlorofluorocarbons"],"answer":3,"explanation":"CFCs release chlorine atoms in the stratosphere, and each chlorine atom can destroy thousands of ozone molecules; the Montreal Protocol phases them out. Sulphur hexafluoride is a powerful greenhouse gas but contains no chlorine and does not deplete ozone.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"समताप मंडलीय ओज़ोन परत का क्षरण मुख्यतः किसके कारण होता है?","optionsHi":["कार्बन डाइऑक्साइड","मेथेन","सल्फर हेक्साफ्लोराइड","क्लोरोफ्लोरोकार्बन"],"explanationHi":"CFC समताप मंडल में क्लोरीन परमाणु मुक्त करते हैं, और प्रत्येक क्लोरीन परमाणु हजारों ओज़ोन अणुओं को नष्ट कर सकता है; मॉन्ट्रियल प्रोटोकॉल इन्हें चरणबद्ध रूप से समाप्त करता है। सल्फर हेक्साफ्लोराइड एक प्रबल ग्रीनहाउस गैस है, परंतु उसमें क्लोरीन नहीं होती और वह ओज़ोन का क्षरण नहीं करती।"},
  {"id":"sci-chemistry-67","question":"The lightest metal is:","options":["Sodium","Lithium","Aluminium","Magnesium"],"answer":1,"explanation":"Lithium has a density of about 0.53 g/cm³, the lowest of all metals; it even floats on oil.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"सबसे हल्की धातु कौन-सी है?","optionsHi":["सोडियम","लिथियम","ऐलुमिनियम","मैग्नीशियम"],"explanationHi":"लिथियम का घनत्व लगभग 0.53 g/cm³ है, जो सभी धातुओं में सबसे कम है; वह तेल पर भी तैरती है।"},
  {"id":"sci-chemistry-68","question":"An element has atomic number 17. Its electronic configuration and valency are:","options":["2, 8, 7 and 1","2, 8, 7 and 7","2, 7, 8 and 1","2, 8, 6 and 2"],"answer":0,"explanation":"17 electrons fill as 2, 8, 7. Needing one more electron to complete its octet, the element (chlorine) has valency 1.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"किसी तत्व का परमाणु क्रमांक 17 है। उसका इलेक्ट्रॉनिक विन्यास और संयोजकता क्या है?","optionsHi":["2, 8, 7 और 1","2, 8, 7 और 7","2, 7, 8 और 1","2, 8, 6 और 2"],"explanationHi":"17 इलेक्ट्रॉन 2, 8, 7 के रूप में भरते हैं। अष्टक पूरा करने के लिए एक और इलेक्ट्रॉन की आवश्यकता होने से इस तत्व (क्लोरीन) की संयोजकता 1 है।"},
  {"id":"sci-chemistry-69","question":"Which gas is produced when water is added to calcium carbide?","options":["Phosphine","Ethylene","Acetylene","Ethane"],"answer":2,"explanation":"CaC₂ + 2H₂O → Ca(OH)₂ + C₂H₂. Acetylene (ethyne) is used in welding and to ripen fruit artificially. Phosphine comes from calcium phosphide and water, a reaction often confused with this one.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"कैल्शियम कार्बाइड में जल मिलाने पर कौन-सी गैस बनती है?","optionsHi":["फॉस्फीन","एथिलीन","ऐसीटिलीन","एथेन"],"explanationHi":"CaC₂ + 2H₂O → Ca(OH)₂ + C₂H₂। ऐसीटिलीन (एथाइन) का उपयोग वेल्डिंग में और फलों को कृत्रिम रूप से पकाने में होता है। फॉस्फीन कैल्शियम फॉस्फाइड और जल से बनती है, यह अभिक्रिया प्रायः इससे भ्रमित हो जाती है।"},
  {"id":"sci-chemistry-70","question":"What percentage of gold does 18-carat gold contain?","options":["18%","82%","75%","90%"],"answer":2,"explanation":"Pure gold is 24 carat, so 18-carat gold = 18/24 = 3/4 = 75% gold; the rest is usually copper or silver.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"18 कैरेट सोने में सोने का कितना प्रतिशत होता है?","optionsHi":["18%","82%","75%","90%"],"explanationHi":"शुद्ध सोना 24 कैरेट का होता है, इसलिए 18 कैरेट सोना = 18/24 = 3/4 = 75% सोना है; शेष प्रायः ताँबा या चाँदी होती है।"},
  {"id":"sci-chemistry-71","question":"The radioisotope commonly used to diagnose and treat disorders of the thyroid gland is:","options":["Cobalt-60","Iodine-131","Carbon-14","Uranium-235"],"answer":1,"explanation":"The thyroid takes up iodine, so radioactive iodine-131 collects there. Cobalt-60 is used in radiotherapy of other cancers and carbon-14 in dating.","difficulty":"hard","source":"UPSC Prelims · SSC CGL","questionHi":"थायरॉइड ग्रंथि के विकारों के निदान और उपचार में सामान्यतः प्रयुक्त रेडियोसमस्थानिक कौन-सा है?","optionsHi":["कोबाल्ट-60","आयोडीन-131","कार्बन-14","यूरेनियम-235"],"explanationHi":"थायरॉइड आयोडीन ग्रहण करती है, इसलिए रेडियोधर्मी आयोडीन-131 वहीं एकत्र होता है। कोबाल्ट-60 अन्य कैंसरों की विकिरण चिकित्सा में और कार्बन-14 काल निर्धारण में प्रयुक्त होता है।"},
  {"id":"sci-chemistry-72","question":"A chlorine atom has atomic number 17 and mass number 35. How many electrons does a chloride ion (Cl⁻) have?","options":["17","35","16","18"],"answer":3,"explanation":"The neutral atom has 17 electrons; gaining one gives Cl⁻ 18 electrons. 35 is the number of nucleons, and the 18 neutrons are a separate count.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"क्लोरीन परमाणु का परमाणु क्रमांक 17 और द्रव्यमान संख्या 35 है। क्लोराइड आयन (Cl⁻) में कितने इलेक्ट्रॉन होते हैं?","optionsHi":["17","35","16","18"],"explanationHi":"उदासीन परमाणु में 17 इलेक्ट्रॉन होते हैं; एक ग्रहण करने पर Cl⁻ में 18 इलेक्ट्रॉन हो जाते हैं। 35 न्यूक्लिऑनों की संख्या है, और 18 न्यूट्रॉन एक अलग गणना है।"},
  {"id":"sci-chemistry-73","question":"Which of the following is NOT a greenhouse gas?","options":["Carbon dioxide","Methane","Nitrous oxide","Nitrogen"],"answer":3,"explanation":"N₂ does not absorb infrared radiation, so it is not a greenhouse gas even though it makes up 78% of the air. CO₂, CH₄ and N₂O all trap heat.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"निम्नलिखित में से कौन-सी ग्रीनहाउस गैस नहीं है?","optionsHi":["कार्बन डाइऑक्साइड","मेथेन","नाइट्रस ऑक्साइड","नाइट्रोजन"],"explanationHi":"N₂ अवरक्त विकिरण को अवशोषित नहीं करती, इसलिए वह ग्रीनहाउस गैस नहीं है, यद्यपि वह वायु का 78% है। CO₂, CH₄ और N₂O तीनों ऊष्मा को रोकती हैं।"},
  {"id":"sci-chemistry-74","question":"What is the percentage of nitrogen by mass in urea, CO(NH₂)₂? (C = 12, N = 14, O = 16, H = 1)","options":["23.3%","46.7%","28.0%","60.0%"],"answer":1,"explanation":"Molar mass = 12 + 16 + 2 × (14 + 2) = 60. Nitrogen = 28. Percentage = 28/60 × 100 ≈ 46.7%, which is why urea is a rich nitrogen fertiliser.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"यूरिया, CO(NH₂)₂, में नाइट्रोजन का द्रव्यमान प्रतिशत कितना है? (C = 12, N = 14, O = 16, H = 1)","optionsHi":["23.3%","46.7%","28.0%","60.0%"],"explanationHi":"मोलर द्रव्यमान = 12 + 16 + 2 × (14 + 2) = 60। नाइट्रोजन = 28। प्रतिशत = 28/60 × 100 ≈ 46.7%, इसीलिए यूरिया नाइट्रोजन से भरपूर उर्वरक है।"},
  {"id":"sci-chemistry-75","question":"What is the pH of a 0.01 M solution of sodium hydroxide at 25 °C?","options":["2","10","13","12"],"answer":3,"explanation":"NaOH ionises fully, so [OH⁻] = 10⁻² M and pOH = 2. pH = 14 − 2 = 12. The value 2 is the trap of treating the base like an acid.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"25 °C पर 0.01 M सोडियम हाइड्रॉक्साइड विलयन का pH कितना है?","optionsHi":["2","10","13","12"],"explanationHi":"NaOH पूर्णतः आयनित होता है, इसलिए [OH⁻] = 10⁻² M और pOH = 2। pH = 14 − 2 = 12। मान 2 क्षार को अम्ल की तरह मान लेने का भ्रम है।"},
  {"id":"sci-chemistry-76","question":"A compound contains 40% carbon, 6.67% hydrogen and 53.33% oxygen by mass, and its molar mass is 180 g/mol. Its molecular formula is:","options":["CH₂O","C₂H₄O₂","C₆H₁₂O₆","C₃H₆O₃"],"answer":2,"explanation":"Mole ratio C : H : O = 40/12 : 6.67/1 : 53.33/16 = 3.33 : 6.67 : 3.33 = 1 : 2 : 1, so the empirical formula is CH₂O (mass 30). 180 ÷ 30 = 6, giving C₆H₁₂O₆.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"किसी यौगिक में द्रव्यमान के अनुसार 40% कार्बन, 6.67% हाइड्रोजन और 53.33% ऑक्सीजन है, और उसका मोलर द्रव्यमान 180 g/mol है। उसका अणुसूत्र क्या है?","optionsHi":["CH₂O","C₂H₄O₂","C₆H₁₂O₆","C₃H₆O₃"],"explanationHi":"मोल अनुपात C : H : O = 40/12 : 6.67/1 : 53.33/16 = 3.33 : 6.67 : 3.33 = 1 : 2 : 1, इसलिए मूलानुपाती सूत्र CH₂O है (द्रव्यमान 30)। 180 ÷ 30 = 6, जिससे C₆H₁₂O₆ मिलता है।"},
  {"id":"sci-chemistry-77","question":"How many of these statements about periodic trends are correct? I. Atomic radius decreases from left to right across a period. II. Ionisation energy generally decreases across a period. III. Metallic character decreases down a group. IV. Electronegativity increases down a group.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only I is correct. Across a period the rising nuclear charge increases ionisation energy (II wrong); down a group atoms grow larger and lose electrons more easily, so metallic character increases (III wrong) and electronegativity decreases (IV wrong).","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"आवर्ती प्रवृत्तियों से संबंधित इनमें से कितने कथन सही हैं? I. आवर्त में बाएँ से दाएँ जाने पर परमाणु त्रिज्या घटती है। II. आवर्त में आयनन ऊर्जा सामान्यतः घटती है। III. समूह में नीचे जाने पर धात्विक गुण घटता है। IV. समूह में नीचे जाने पर विद्युत ऋणात्मकता बढ़ती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I सही है। आवर्त में बढ़ता नाभिकीय आवेश आयनन ऊर्जा बढ़ाता है (II गलत); समूह में नीचे जाने पर परमाणु बड़े होते हैं और इलेक्ट्रॉन अधिक आसानी से त्यागते हैं, इसलिए धात्विक गुण बढ़ता है (III गलत) और विद्युत ऋणात्मकता घटती है (IV गलत)।"},
  {"id":"sci-chemistry-78","question":"Assertion (A): Hydrogen gas is usually not evolved when a metal reacts with nitric acid. Reason (R): Nitric acid is a strong oxidising agent that oxidises the hydrogen produced to water.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"HNO₃ oxidises the H₂ and is itself reduced to oxides of nitrogen. Only magnesium and manganese give hydrogen with very dilute nitric acid. R explains A.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"अभिकथन (A): किसी धातु की नाइट्रिक अम्ल से अभिक्रिया पर सामान्यतः हाइड्रोजन गैस नहीं निकलती। कारण (R): नाइट्रिक अम्ल प्रबल ऑक्सीकारक है जो बनी हुई हाइड्रोजन को जल में ऑक्सीकृत कर देता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"HNO₃ H₂ का ऑक्सीकरण कर देता है और स्वयं नाइट्रोजन के ऑक्साइडों में अपचयित हो जाता है। केवल मैग्नीशियम और मैंगनीज अत्यंत तनु नाइट्रिक अम्ल से हाइड्रोजन देते हैं। R, A की व्याख्या करता है।"},
  {"id":"sci-chemistry-79","question":"Assertion (A): Ionic compounds have high melting points. Reason (R): Ionic compounds are formed by the sharing of electrons between atoms.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true: strong electrostatic attraction between ions needs much energy to overcome. R is false: ionic bonds form by transfer of electrons; sharing forms covalent bonds.","difficulty":"very-hard","source":"RRB Group D · SSC CHSL","questionHi":"अभिकथन (A): आयनिक यौगिकों के गलनांक उच्च होते हैं। कारण (R): आयनिक यौगिक परमाणुओं के बीच इलेक्ट्रॉनों की साझेदारी से बनते हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"A सही है: आयनों के बीच प्रबल स्थिरवैद्युत आकर्षण को दूर करने में बहुत ऊर्जा लगती है। R गलत है: आयनिक बंध इलेक्ट्रॉनों के स्थानांतरण से बनते हैं; साझेदारी से सहसंयोजक बंध बनते हैं।"},
  {"id":"sci-chemistry-80","question":"Match the element with its use: 1. Tungsten 2. Chlorine 3. Helium 4. Silicon; a. Solar cells b. Filling weather balloons c. Filaments of electric bulbs d. Disinfecting drinking water","options":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a"],"answer":3,"explanation":"Tungsten’s very high melting point suits bulb filaments, chlorine kills germs in water, light and non-flammable helium fills balloons, and silicon is the semiconductor in solar cells.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"तत्व का उसके उपयोग से मिलान कीजिए: 1. टंगस्टन 2. क्लोरीन 3. हीलियम 4. सिलिकॉन; a. सौर सेल b. मौसम संबंधी गुब्बारे भरना c. बिजली के बल्बों के तंतु d. पेयजल को रोगाणुमुक्त करना","optionsHi":["1-c, 2-d, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-c, 2-b, 3-d, 4-a","1-c, 2-d, 3-b, 4-a"],"explanationHi":"टंगस्टन का अत्यंत उच्च गलनांक बल्ब के तंतुओं के लिए उपयुक्त है, क्लोरीन जल के रोगाणुओं को मारती है, हल्की और अज्वलनशील हीलियम गुब्बारे भरने में काम आती है, और सिलिकॉन सौर सेलों में अर्धचालक है।"},
  {"id":"sci-chemistry-81","question":"Which of the following is NOT an allotrope of carbon?","options":["Fullerene","Lonsdaleite","Diamond","Carborundum"],"answer":3,"explanation":"Carborundum is silicon carbide (SiC), a compound used as an abrasive. Diamond, graphite, graphene, fullerenes and lonsdaleite (hexagonal diamond) are all forms of pure carbon.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"निम्नलिखित में से कौन-सा कार्बन का अपररूप नहीं है?","optionsHi":["फुलरीन","लॉन्सडेलाइट","हीरा","कार्बोरंडम"],"explanationHi":"कार्बोरंडम सिलिकन कार्बाइड (SiC) है, जो अपघर्षक के रूप में प्रयुक्त एक यौगिक है। हीरा, ग्रेफाइट, ग्रैफीन, फुलरीन और लॉन्सडेलाइट (षट्कोणीय हीरा) शुद्ध कार्बन के रूप हैं।"},
  {"id":"sci-chemistry-82","question":"How many of these statements are correct? I. Oxidation is the loss of electrons. II. In 2Mg + O₂ → 2MgO, magnesium is oxidised. III. A reducing agent is itself reduced in a reaction. IV. In CuO + H₂ → Cu + H₂O, copper oxide is oxidised.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and II are correct. A reducing agent is itself oxidised, and in the last reaction CuO loses oxygen, so it is reduced while hydrogen is oxidised.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. ऑक्सीकरण इलेक्ट्रॉनों की हानि है। II. 2Mg + O₂ → 2MgO में मैग्नीशियम ऑक्सीकृत होता है। III. अपचायक स्वयं अभिक्रिया में अपचयित होता है। IV. CuO + H₂ → Cu + H₂O में कॉपर ऑक्साइड ऑक्सीकृत होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और II सही हैं। अपचायक स्वयं ऑक्सीकृत होता है, और अंतिम अभिक्रिया में CuO ऑक्सीजन खोता है, इसलिए वह अपचयित होता है जबकि हाइड्रोजन ऑक्सीकृत होती है।"},
  {"id":"sci-chemistry-83","question":"What volume of carbon dioxide at STP is produced when 3 g of carbon burns completely in oxygen? (C = 12)","options":["22.4 L","11.2 L","5.6 L","2.8 L"],"answer":2,"explanation":"C + O₂ → CO₂. 3 g of carbon = 3/12 = 0.25 mol, which gives 0.25 mol of CO₂ = 0.25 × 22.4 = 5.6 L.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"ऑक्सीजन में 3 g कार्बन के पूर्ण दहन पर STP पर कितना कार्बन डाइऑक्साइड उत्पन्न होता है? (C = 12)","optionsHi":["22.4 L","11.2 L","5.6 L","2.8 L"],"explanationHi":"C + O₂ → CO₂। 3 g कार्बन = 3/12 = 0.25 mol, जिससे 0.25 mol CO₂ = 0.25 × 22.4 = 5.6 L बनती है।"},
  {"id":"sci-chemistry-84","question":"How many of these statements are correct? I. Alkanes are saturated hydrocarbons with the general formula CₙH₂ₙ₊₂. II. Ethene has a carbon–carbon double bond. III. The molecular formula of benzene is C₆H₆. IV. Ethanol is the alcohol present in alcoholic drinks.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. Alkenes such as ethene (C₂H₄) have a C=C double bond, alkynes a triple bond, and methanol, not ethanol, is the poisonous alcohol.","difficulty":"very-hard","source":"RRB Group D · SSC CHSL","questionHi":"इनमें से कितने कथन सही हैं? I. ऐल्केन संतृप्त हाइड्रोकार्बन हैं जिनका सामान्य सूत्र CₙH₂ₙ₊₂ है। II. एथीन में कार्बन–कार्बन द्विबंध होता है। III. बेंज़ीन का अणुसूत्र C₆H₆ है। IV. एथेनॉल वह ऐल्कोहॉल है जो मादक पेयों में होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। एथीन (C₂H₄) जैसे ऐल्कीनों में C=C द्विबंध होता है, ऐल्काइनों में त्रिबंध, और विषैला ऐल्कोहॉल मेथेनॉल है, एथेनॉल नहीं।"},
  {"id":"sci-chemistry-85","question":"Teflon, used to coat non-stick cookware, is chemically:","options":["Polymethyl methacrylate","Polystyrene","Polytetrafluoroethylene","Polyvinyl chloride"],"answer":2,"explanation":"Teflon is PTFE, a polymer of tetrafluoroethylene (CF₂=CF₂); strong C–F bonds make it slippery, heat-resistant and unreactive. Polymethyl methacrylate is Perspex.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"नॉन-स्टिक बर्तनों पर परत चढ़ाने में प्रयुक्त टेफ्लॉन रासायनिक रूप से क्या है?","optionsHi":["पॉलिमेथिल मेथैक्रिलेट","पॉलिस्टाइरीन","पॉलिटेट्राफ्लुओरोएथिलीन","पॉलिविनाइल क्लोराइड"],"explanationHi":"टेफ्लॉन PTFE है, जो टेट्राफ्लुओरोएथिलीन (CF₂=CF₂) का बहुलक है; प्रबल C–F बंध इसे फिसलन भरा, ऊष्मा-सहनशील और अक्रिय बनाते हैं। पॉलिमेथिल मेथैक्रिलेट परस्पेक्स है।"},
  {"id":"sci-chemistry-86","question":"The different coloured dyes present in a drop of black ink are best separated by:","options":["Sublimation","Filtration","Chromatography","Fractional distillation"],"answer":2,"explanation":"In paper chromatography each dye moves up the paper at its own speed, so the colours separate into bands. Filtration only removes insoluble solids.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"काली स्याही की एक बूँद में उपस्थित विभिन्न रंगीन रंजकों को सबसे अच्छी तरह किससे पृथक किया जाता है?","optionsHi":["उर्ध्वपातन","निस्पंदन (छानना)","वर्णलेखन (क्रोमैटोग्राफी)","प्रभाजी आसवन"],"explanationHi":"पेपर क्रोमैटोग्राफी में प्रत्येक रंजक कागज पर अपनी गति से ऊपर चढ़ता है, इसलिए रंग पट्टियों के रूप में अलग हो जाते हैं। निस्पंदन केवल अघुलनशील ठोसों को हटाता है।"},
  {"id":"sci-chemistry-87","question":"For iron to rust, it must be exposed to:","options":["Oxygen only","Both oxygen and water","Carbon dioxide and moisture","Water only"],"answer":1,"explanation":"Rust is hydrated iron(III) oxide, Fe₂O₃·xH₂O, and forms only when both air (oxygen) and moisture are present; iron kept in dry air or in boiled, oil-covered water does not rust.","difficulty":"easy","source":"SSC CGL · SSC CHSL · RRB NTPC","questionHi":"लोहे में जंग लगने के लिए उसका किसके संपर्क में आना आवश्यक है?","optionsHi":["केवल ऑक्सीजन","ऑक्सीजन और जल दोनों","कार्बन डाइऑक्साइड और नमी","केवल जल"],"explanationHi":"जंग जलयोजित आयरन(III) ऑक्साइड, Fe₂O₃·xH₂O, है, जो तभी बनती है जब वायु (ऑक्सीजन) और नमी दोनों उपस्थित हों; शुष्क वायु में या उबले हुए, तेल से ढके जल में रखे लोहे में जंग नहीं लगती।"},
  {"id":"sci-chemistry-88","question":"In the Haber process for making ammonia from nitrogen and hydrogen, the catalyst used is:","options":["Vanadium pentoxide","Nickel","Platinum","Iron"],"answer":3,"explanation":"Finely divided iron (with molybdenum or oxide promoters) is used at about 450 °C and 200 atm. Nickel is used to hydrogenate oils and V₂O₅ in the contact process.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"नाइट्रोजन और हाइड्रोजन से अमोनिया बनाने की हैबर प्रक्रिया में प्रयुक्त उत्प्रेरक कौन-सा है?","optionsHi":["वैनेडियम पेंटाऑक्साइड","निकल","प्लैटिनम","लोहा"],"explanationHi":"लगभग 450 °C और 200 atm पर महीन चूर्ण के रूप में लोहे (मॉलिब्डेनम या ऑक्साइड प्रवर्तकों के साथ) का उपयोग होता है। निकल तेलों के हाइड्रोजनीकरण में और V₂O₅ संपर्क प्रक्रम में प्रयुक्त होता है।"},
  {"id":"sci-chemistry-89","question":"The chief ore from which iron is extracted is:","options":["Cinnabar","Chalcopyrite","Bauxite","Haematite"],"answer":3,"explanation":"Haematite (Fe₂O₃) is the main iron ore and is reduced in a blast furnace. Bauxite is the ore of aluminium, chalcopyrite (copper iron sulphide) is mined for copper, and cinnabar is the ore of mercury.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"लोहे के निष्कर्षण का प्रमुख अयस्क कौन-सा है?","optionsHi":["सिनेबार","कैल्कोपाइराइट","बॉक्साइट","हेमेटाइट"],"explanationHi":"हेमेटाइट (Fe₂O₃) लोहे का मुख्य अयस्क है, जिसे वात्या भट्ठी में अपचयित किया जाता है। बॉक्साइट ऐलुमिनियम का अयस्क है, कैल्कोपाइराइट (कॉपर आयरन सल्फाइड) से ताँबा निकाला जाता है, और सिनेबार पारे का अयस्क है।"},
  {"id":"sci-chemistry-90","question":"The process of making soap by heating fats or oils with sodium hydroxide is called:","options":["Fermentation","Saponification","Hydrogenation","Esterification"],"answer":1,"explanation":"Saponification breaks the fat (an ester) into glycerol and the sodium salts of fatty acids, which are soap. Hydrogenation turns oils into vanaspati ghee.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"वसा या तेलों को सोडियम हाइड्रॉक्साइड के साथ गर्म करके साबुन बनाने की प्रक्रिया को क्या कहते हैं?","optionsHi":["किण्वन","साबुनीकरण","हाइड्रोजनीकरण","एस्टरीकरण"],"explanationHi":"साबुनीकरण में वसा (एक एस्टर) टूटकर ग्लिसरॉल और वसा अम्लों के सोडियम लवण बनाती है, जो साबुन है। हाइड्रोजनीकरण तेलों को वनस्पति घी में बदलता है।"},
  {"id":"sci-chemistry-91","question":"Soap does not lather well in hard water because:","options":["Soap dissolves too quickly in hard water to form lather","Hard water is acidic and destroys the soap molecules","Ca²⁺ and Mg²⁺ ions form an insoluble scum with soap","Hard water contains extra dissolved oxygen"],"answer":2,"explanation":"Ca²⁺ and Mg²⁺ ions react with soap to give insoluble calcium and magnesium salts (scum), wasting soap until all these ions are used up.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"कठोर जल में साबुन अच्छा झाग क्यों नहीं देता?","optionsHi":["कठोर जल में साबुन झाग बनने से पहले ही बहुत जल्दी घुल जाता है","कठोर जल अम्लीय होता है और साबुन के अणुओं को नष्ट कर देता है","Ca²⁺ और Mg²⁺ आयन साबुन के साथ अघुलनशील मैल (स्कम) बनाते हैं","कठोर जल में अतिरिक्त घुली हुई ऑक्सीजन होती है"],"explanationHi":"Ca²⁺ और Mg²⁺ आयन साबुन से अभिक्रिया करके कैल्शियम और मैग्नीशियम के अघुलनशील लवण (मैल) बनाते हैं, जब तक ये सभी आयन समाप्त नहीं हो जाते तब तक साबुन व्यर्थ जाता है।"},
  {"id":"sci-chemistry-92","question":"The octane number of petrol is a measure of its:","options":["Calorific value per litre","Volatility (boiling range)","Resistance to knocking","Sulphur content"],"answer":2,"explanation":"A higher octane number means the fuel resists premature ignition (knocking); iso-octane is rated 100 and n-heptane 0. The calorific value is the heat given out on burning.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"पेट्रोल की ऑक्टेन संख्या उसके किस गुण का माप है?","optionsHi":["प्रति लीटर ऊष्मीय मान","वाष्पशीलता (क्वथनांक परास)","नॉकिंग के प्रति प्रतिरोध","सल्फर की मात्रा"],"explanationHi":"उच्च ऑक्टेन संख्या का अर्थ है कि ईंधन समय से पहले प्रज्वलन (नॉकिंग) का प्रतिरोध करता है; आइसो-ऑक्टेन की रेटिंग 100 और n-हेप्टेन की 0 है। ऊष्मीय मान जलने पर निकली ऊष्मा है।"},
  {"id":"sci-chemistry-93","question":"At constant temperature, 2 L of a gas at 1 atm is compressed to 0.5 L. Its new pressure is:","options":["4 atm","2 atm","0.25 atm","1 atm"],"answer":0,"explanation":"By Boyle’s law P₁V₁ = P₂V₂, so 1 × 2 = P₂ × 0.5 and P₂ = 4 atm. Reducing the volume to a quarter raises the pressure four times.","difficulty":"moderate","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"स्थिर तापमान पर 1 atm पर 2 L गैस को संपीडित करके 0.5 L किया जाता है। उसका नया दाब क्या होगा?","optionsHi":["4 atm","2 atm","0.25 atm","1 atm"],"explanationHi":"बॉयल के नियम P₁V₁ = P₂V₂ से 1 × 2 = P₂ × 0.5, इसलिए P₂ = 4 atm। आयतन को एक-चौथाई करने से दाब चार गुना हो जाता है।"},
  {"id":"sci-chemistry-94","question":"A gas occupies 3 L at 27 °C. Keeping the pressure constant, it is heated to 127 °C. Its new volume is:","options":["6 L","3.3 L","4 L","14.1 L"],"answer":2,"explanation":"Charles’s law needs kelvin: 27 °C = 300 K and 127 °C = 400 K, so V₂ = 3 × 400/300 = 4 L. Using Celsius directly (3 × 127/27) gives the trap 14.1 L.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"एक गैस 27 °C पर 3 L आयतन घेरती है। दाब स्थिर रखते हुए उसे 127 °C तक गर्म किया जाता है। उसका नया आयतन क्या होगा?","optionsHi":["6 L","3.3 L","4 L","14.1 L"],"explanationHi":"चार्ल्स के नियम में केल्विन आवश्यक है: 27 °C = 300 K और 127 °C = 400 K, इसलिए V₂ = 3 × 400/300 = 4 L। सेल्सियस को सीधे लेने (3 × 127/27) पर भ्रम का उत्तर 14.1 L आता है।"},
  {"id":"sci-chemistry-95","question":"Natural rubber is heated with sulphur to make it harder and more elastic. This process is called:","options":["Vulcanisation","Galvanisation","Polymerisation","Calcination"],"answer":0,"explanation":"Vulcanisation forms sulphur cross-links between the rubber chains, so the rubber no longer turns sticky in heat or brittle in cold. Galvanisation is coating iron with zinc.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"प्राकृतिक रबर को सल्फर के साथ गर्म करके कठोर और अधिक प्रत्यास्थ बनाया जाता है। इस प्रक्रिया को क्या कहते हैं?","optionsHi":["वल्कनीकरण","यशदलेपन (गैल्वनीकरण)","बहुलकीकरण","निस्तापन (कैल्सिनेशन)"],"explanationHi":"वल्कनीकरण रबर की श्रृंखलाओं के बीच सल्फर के क्रॉस-बंध बनाता है, जिससे रबर गर्मी में चिपचिपी या ठंड में भंगुर नहीं होती। यशदलेपन लोहे पर जस्ते की परत चढ़ाना है।"},
  {"id":"sci-chemistry-97","question":"Gypsum is added to cement during its manufacture in order to:","options":["Make it harder and stronger","Give it a grey colour","Make it waterproof","Slow down its setting"],"answer":3,"explanation":"A few per cent of gypsum (CaSO₄·2H₂O) controls the fast reaction of tricalcium aluminate with water, so the cement does not set too quickly to be worked.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"सीमेंट के निर्माण में उसमें जिप्सम किसलिए मिलाया जाता है?","optionsHi":["उसे अधिक कठोर और मजबूत बनाने के लिए","उसे धूसर रंग देने के लिए","उसे जलरोधी बनाने के लिए","उसके जमने की गति धीमी करने के लिए"],"explanationHi":"कुछ प्रतिशत जिप्सम (CaSO₄·2H₂O) ट्राइकैल्शियम ऐलुमिनेट की जल के साथ तेज अभिक्रिया को नियंत्रित करता है, ताकि सीमेंट इतनी जल्दी न जमे कि उस पर काम न किया जा सके।"},
  {"id":"sci-chemistry-98","question":"Which of the following molecules contains a triple bond?","options":["CO₂","H₂O","N₂","O₂"],"answer":2,"explanation":"In N₂ the two atoms share three pairs of electrons (N≡N), which makes nitrogen very unreactive. O₂ has a double bond and each C=O in CO₂ is a double bond.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"निम्नलिखित में से किस अणु में त्रिबंध होता है?","optionsHi":["CO₂","H₂O","N₂","O₂"],"explanationHi":"N₂ में दोनों परमाणु तीन इलेक्ट्रॉन युग्म साझा करते हैं (N≡N), जो नाइट्रोजन को अत्यंत अक्रिय बनाता है। O₂ में द्विबंध है और CO₂ का प्रत्येक C=O द्विबंध है।"},
  {"id":"sci-chemistry-99","question":"When ethanol is warmed with alkaline potassium permanganate (or acidified potassium dichromate), it is converted into:","options":["Ethanoic acid","Ethene","Ethane","Ethyl ethanoate"],"answer":0,"explanation":"These are oxidising agents, and ethanol is oxidised to ethanoic (acetic) acid. Heating ethanol with concentrated sulphuric acid instead dehydrates it to ethene.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"जब एथेनॉल को क्षारीय पोटैशियम परमैंगनेट (या अम्लीकृत पोटैशियम डाइक्रोमेट) के साथ गर्म किया जाता है, तो वह किसमें परिवर्तित हो जाता है?","optionsHi":["एथेनॉइक अम्ल","एथीन","एथेन","एथिल एथेनोएट"],"explanationHi":"ये ऑक्सीकारक हैं, और एथेनॉल का ऑक्सीकरण एथेनॉइक (एसीटिक) अम्ल में हो जाता है। इसके बजाय एथेनॉल को सांद्र सल्फ्यूरिक अम्ल के साथ गर्म करने पर वह निर्जलित होकर एथीन बन जाता है।"},
  {"id":"sci-chemistry-100","question":"Synthetic detergents work well even in hard water because:","options":["They are strongly acidic and dissolve the scum","They soften the water by precipitating the ions","They are made from vegetable oils rather than animal fats","Their calcium and magnesium salts are soluble in water"],"answer":3,"explanation":"Detergents are sodium salts of sulphonic acids (or similar), whose calcium and magnesium salts stay dissolved, so no scum forms and lather is not lost.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"संश्लेषित अपमार्जक (डिटर्जेंट) कठोर जल में भी अच्छा कार्य करते हैं, क्योंकि:","optionsHi":["वे प्रबल अम्लीय होते हैं और मैल को घोल देते हैं","वे आयनों को अवक्षेपित करके जल को मृदु बना देते हैं","वे पशु वसा के बजाय वनस्पति तेलों से बनते हैं","उनके कैल्शियम और मैग्नीशियम लवण जल में घुलनशील होते हैं"],"explanationHi":"अपमार्जक सल्फोनिक अम्लों (या समान) के सोडियम लवण होते हैं, जिनके कैल्शियम और मैग्नीशियम लवण घुले रहते हैं, इसलिए कोई मैल नहीं बनता और झाग नष्ट नहीं होता।"},
  {"id":"sci-chemistry-101","question":"Ordinary soda-lime glass is made by fusing together:","options":["Sand, lead oxide and potassium carbonate","Limestone, clay and gypsum","Sand, sodium carbonate and limestone","Clay, sand and gypsum"],"answer":2,"explanation":"Silica (sand), soda ash (Na₂CO₃) and limestone (CaCO₃) are melted together. Limestone, clay and gypsum are the raw materials of cement, and sand with lead oxide and potassium carbonate makes lead crystal (flint) glass.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"सामान्य सोडा-चूना काँच किसे एक साथ गलाकर बनाया जाता है?","optionsHi":["रेत, लेड ऑक्साइड और पोटैशियम कार्बोनेट","चूना पत्थर, मिट्टी और जिप्सम","रेत, सोडियम कार्बोनेट और चूना पत्थर","मिट्टी, रेत और जिप्सम"],"explanationHi":"सिलिका (रेत), सोडा ऐश (Na₂CO₃) और चूना पत्थर (CaCO₃) को एक साथ पिघलाया जाता है। चूना पत्थर, मिट्टी और जिप्सम सीमेंट के कच्चे माल हैं, और रेत, लेड ऑक्साइड तथा पोटैशियम कार्बोनेट से लेड क्रिस्टल (फ्लिंट) काँच बनता है।"},
  {"id":"sci-chemistry-102","question":"Galvanised iron sheets are iron coated with a thin layer of:","options":["Nickel","Zinc","Chromium","Tin"],"answer":1,"explanation":"Zinc is more reactive than iron, so even if the coating is scratched, zinc corrodes first and protects the iron (sacrificial protection). Tin plating, used for food cans, protects only while the layer is unbroken.","difficulty":"hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"यशदलेपित (गैल्वनाइज्ड) लोहे की चादरें किस पतली परत से लेपित लोहे की चादरें होती हैं?","optionsHi":["निकल","जस्ता","क्रोमियम","टिन"],"explanationHi":"जस्ता लोहे से अधिक क्रियाशील है, इसलिए परत खरोंची जाने पर भी पहले जस्ता संक्षारित होता है और लोहे की रक्षा करता है (बलिदानी संरक्षण)। खाद्य डिब्बों में प्रयुक्त टिन की परत तभी तक रक्षा करती है जब तक वह अखंड रहे।"},
  {"id":"sci-chemistry-103","question":"How many of these statements about polymers are correct? I. PVC is a polymer of vinyl chloride. II. Bakelite is a thermoplastic. III. Polythene is a thermosetting plastic. IV. Natural rubber is a polymer of isoprene.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"Only I and IV are correct. Bakelite is a thermosetting plastic (it sets permanently and cannot be remoulded), while polythene is a thermoplastic that softens on heating.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"बहुलकों से संबंधित इनमें से कितने कथन सही हैं? I. PVC वाइनिल क्लोराइड का बहुलक है। II. बेकेलाइट एक ताप-सुनम्य (थर्मोप्लास्टिक) है। III. पॉलिथीन एक ताप-दृढ़ (थर्मोसेटिंग) प्लास्टिक है। IV. प्राकृतिक रबर आइसोप्रीन का बहुलक है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"केवल I और IV सही हैं। बेकेलाइट ताप-दृढ़ प्लास्टिक है (वह स्थायी रूप से जम जाता है और दोबारा ढाला नहीं जा सकता), जबकि पॉलिथीन ताप-सुनम्य है जो गर्म करने पर नरम हो जाता है।"},
  {"id":"sci-chemistry-104","question":"Match the mixture with the best method to separate it: 1. Common salt and ammonium chloride 2. Gases of liquefied air 3. Cream from milk 4. Kerosene and water; a. Separating funnel b. Centrifugation c. Fractional distillation d. Sublimation","options":["1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a"],"answer":1,"explanation":"Ammonium chloride sublimes and leaves salt behind, liquefied air is separated by fractional distillation, cream is spun out by centrifugation, and immiscible kerosene and water are separated with a separating funnel.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"मिश्रण का उसे पृथक करने की सर्वश्रेष्ठ विधि से मिलान कीजिए: 1. सामान्य नमक और अमोनियम क्लोराइड 2. द्रवित वायु की गैसें 3. दूध से मलाई 4. मिट्टी का तेल और जल; a. पृथक्करण कीप b. अपकेंद्रण c. प्रभाजी आसवन d. उर्ध्वपातन","optionsHi":["1-d, 2-c, 3-a, 4-b","1-d, 2-c, 3-b, 4-a","1-d, 2-b, 3-c, 4-a","1-c, 2-d, 3-b, 4-a"],"explanationHi":"अमोनियम क्लोराइड उर्ध्वपातित हो जाता है और नमक पीछे रह जाता है, द्रवित वायु को प्रभाजी आसवन से पृथक किया जाता है, मलाई अपकेंद्रण से अलग की जाती है, और अमिश्रणीय मिट्टी का तेल तथा जल पृथक्करण कीप से अलग किए जाते हैं।"},
  {"id":"sci-chemistry-105","question":"Assertion (A): Ethanol mixes with water in all proportions. Reason (R): Ethanol molecules form hydrogen bonds with water molecules.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The –OH group of ethanol forms hydrogen bonds with water, so the two mix completely. Long-chain alcohols are much less soluble because their large hydrocarbon part cannot form such bonds, so R explains A.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"अभिकथन (A): एथेनॉल जल के साथ सभी अनुपातों में मिश्रित हो जाता है। कारण (R): एथेनॉल के अणु जल के अणुओं के साथ हाइड्रोजन बंध बनाते हैं।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"एथेनॉल का –OH समूह जल के साथ हाइड्रोजन बंध बनाता है, इसलिए दोनों पूरी तरह मिल जाते हैं। लंबी श्रृंखला वाले ऐल्कोहॉल बहुत कम घुलनशील होते हैं क्योंकि उनका बड़ा हाइड्रोकार्बन भाग ऐसे बंध नहीं बना सकता, इसलिए R, A की व्याख्या करता है।"},
  {"id":"sci-chemistry-106","question":"A gas occupies 10 L at 27 °C and 1 atm. What volume will it occupy at 127 °C and 2 atm?","options":["4.7 L","26.7 L","20 L","6.67 L"],"answer":3,"explanation":"By the combined gas law V₂ = V₁ × (T₂/T₁) × (P₁/P₂) = 10 × (400/300) × (1/2) = 6.67 L. Heating alone would raise it to 13.3 L, and doubling the pressure halves that.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"एक गैस 27 °C और 1 atm पर 10 L आयतन घेरती है। 127 °C और 2 atm पर वह कितना आयतन घेरेगी?","optionsHi":["4.7 L","26.7 L","20 L","6.67 L"],"explanationHi":"संयुक्त गैस नियम से V₂ = V₁ × (T₂/T₁) × (P₁/P₂) = 10 × (400/300) × (1/2) = 6.67 L। केवल गर्म करने से वह 13.3 L हो जाती, और दाब दोगुना करने से यह आधा हो जाता है।"},
  {"id":"sci-chemistry-107","question":"What volume of 0.1 M NaOH is needed to neutralise 25 mL of 0.2 M H₂SO₄ completely?","options":["100 mL","25 mL","50 mL","200 mL"],"answer":0,"explanation":"Moles of H₂SO₄ = 0.025 × 0.2 = 0.005; being dibasic it gives 0.01 mol H⁺, needing 0.01 mol NaOH. Volume = 0.01 ÷ 0.1 = 0.1 L = 100 mL. Treating the acid as monobasic gives the trap 50 mL.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"0.2 M H₂SO₄ के 25 mL को पूर्णतः उदासीन करने के लिए 0.1 M NaOH का कितना आयतन चाहिए?","optionsHi":["100 mL","25 mL","50 mL","200 mL"],"explanationHi":"H₂SO₄ के मोल = 0.025 × 0.2 = 0.005; द्विक्षारकीय होने से यह 0.01 mol H⁺ देता है, जिसके लिए 0.01 mol NaOH चाहिए। आयतन = 0.01 ÷ 0.1 = 0.1 L = 100 mL। अम्ल को एकक्षारकीय मान लेने पर भ्रम का उत्तर 50 mL आता है।"},
  {"id":"sci-chemistry-108","question":"How many of these statements about fuels are correct? I. CNG consists mainly of methane. II. Ethyl mercaptan is added to LPG so that leaks can be smelt. III. Hydrogen has the highest calorific value per unit mass among common fuels. IV. Anthracite has the highest carbon content among the varieties of coal.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are correct. LPG itself is odourless, so a strong-smelling sulphur compound is added; hydrogen gives about 150 kJ/g, far above petrol or methane; and anthracite (about 90% carbon) ranks above bituminous coal, lignite and peat.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"ईंधनों से संबंधित इनमें से कितने कथन सही हैं? I. CNG मुख्यतः मेथेन से बनी होती है। II. LPG में एथिल मर्कैप्टन इसलिए मिलाया जाता है ताकि रिसाव को सूँघा जा सके। III. सामान्य ईंधनों में हाइड्रोजन का प्रति इकाई द्रव्यमान ऊष्मीय मान सर्वाधिक है। IV. कोयले की किस्मों में ऐन्थ्रासाइट में कार्बन की मात्रा सबसे अधिक होती है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"चारों सही हैं। LPG स्वयं गंधहीन है, इसलिए उसमें तेज गंध वाला सल्फर यौगिक मिलाया जाता है; हाइड्रोजन लगभग 150 kJ/g देती है, जो पेट्रोल या मेथेन से कहीं अधिक है; और ऐन्थ्रासाइट (लगभग 90% कार्बन) बिटुमिनी कोयले, लिग्नाइट और पीट से ऊपर आता है।"},
  {"id":"sci-chemistry-109","question":"Arrange in chronological order: 1. Invention of nylon 2. Discovery of radioactivity by Becquerel 3. Accidental discovery of Teflon 4. Invention of Bakelite","options":["2, 4, 3, 1","2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3"],"answer":1,"explanation":"Becquerel discovered radioactivity in 1896, Baekeland made Bakelite in 1907, Carothers invented nylon in 1935, and Plunkett found Teflon by accident in 1938.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL","questionHi":"कालक्रम के अनुसार व्यवस्थित कीजिए: 1. नायलॉन का आविष्कार 2. बेकरल द्वारा रेडियोधर्मिता की खोज 3. टेफ्लॉन की आकस्मिक खोज 4. बेकेलाइट का आविष्कार","optionsHi":["2, 4, 3, 1","2, 4, 1, 3","4, 2, 1, 3","2, 1, 4, 3"],"explanationHi":"बेकरल ने 1896 में रेडियोधर्मिता खोजी, बेकलैंड ने 1907 में बेकेलाइट बनाया, कैरोथर्स ने 1935 में नायलॉन का आविष्कार किया, और प्लंकेट ने 1938 में संयोगवश टेफ्लॉन खोजा।"},
  {"id":"sci-chemistry-110","question":"Which of the following does NOT show the Tyndall effect?","options":["Milk diluted with water","Common salt solution","Smoke from a chimney","Fog"],"answer":1,"explanation":"A salt solution is a true solution whose ions are too small to scatter light, so a beam passing through it is invisible. Milk, fog and smoke are colloids whose particles scatter light and make the beam visible.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"निम्नलिखित में से कौन टिंडल प्रभाव नहीं दर्शाता?","optionsHi":["जल में तनु किया हुआ दूध","सामान्य नमक का विलयन","चिमनी का धुआँ","कोहरा"],"explanationHi":"नमक का विलयन सच्चा विलयन है जिसके आयन प्रकाश को प्रकीर्णित करने के लिए बहुत छोटे होते हैं, इसलिए उससे गुजरने वाली प्रकाश-किरण दिखाई नहीं देती। दूध, कोहरा और धुआँ कोलॉइड हैं जिनके कण प्रकाश को प्रकीर्णित करके किरण को दृश्य बना देते हैं।"},
  {"id":"sci-chemistry-111","question":"Assertion (A): Iron objects rust faster in coastal areas than in dry inland areas. Reason (R): Salt from sea spray dissolves in moisture and makes it a better conductor, speeding up electrochemical corrosion.","options":["Both A and R are true and R explains A","Both A and R are true but R does not explain A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Rusting is an electrochemical process; dissolved salt increases the conductivity of the water film on the iron, so corrosion goes faster near the sea. R explains A.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"अभिकथन (A): लोहे की वस्तुओं में शुष्क भीतरी क्षेत्रों की तुलना में तटीय क्षेत्रों में अधिक तेजी से जंग लगती है। कारण (R): समुद्री फुहार का नमक नमी में घुलकर उसे बेहतर चालक बना देता है, जिससे विद्युत-रासायनिक संक्षारण तेज हो जाता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"जंग लगना एक विद्युत-रासायनिक प्रक्रिया है; घुला हुआ नमक लोहे पर जल की परत की चालकता बढ़ा देता है, इसलिए समुद्र के पास संक्षारण तेजी से होता है। R, A की व्याख्या करता है।"},
  {"id":"sci-chemistry-112","question":"Match the compound with its use: 1. Silver iodide 2. Silver bromide 3. Potassium nitrate 4. Zinc phosphide; a. Rat poison b. Gunpowder c. Photographic film d. Cloud seeding","options":["1-b, 2-c, 3-d, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a"],"answer":1,"explanation":"Silver iodide crystals seed clouds for artificial rain, light-sensitive silver bromide coats photographic film, potassium nitrate (saltpetre) is the oxidiser in gunpowder, and zinc phosphide is a rodenticide.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"यौगिक का उसके उपयोग से मिलान कीजिए: 1. सिल्वर आयोडाइड 2. सिल्वर ब्रोमाइड 3. पोटैशियम नाइट्रेट 4. जिंक फॉस्फाइड; a. चूहे मारने की दवा b. बारूद c. फोटोग्राफिक फिल्म d. बादलों का बीजन (क्लाउड सीडिंग)","optionsHi":["1-b, 2-c, 3-d, 4-a","1-d, 2-c, 3-b, 4-a","1-d, 2-c, 3-a, 4-b","1-c, 2-d, 3-b, 4-a"],"explanationHi":"सिल्वर आयोडाइड के क्रिस्टल कृत्रिम वर्षा के लिए बादलों में बीजन करते हैं, प्रकाश-संवेदी सिल्वर ब्रोमाइड फोटोग्राफिक फिल्म पर लगाया जाता है, पोटैशियम नाइट्रेट (शोरा) बारूद में ऑक्सीकारक है, और जिंक फॉस्फाइड कृन्तकनाशी है।"},
  {"id":"sci-chemistry-113","question":"Chlorine has two isotopes, Cl-35 and Cl-37, and its average atomic mass is 35.5. The percentage of Cl-37 in natural chlorine is:","options":["50%","25%","75%","35.5%"],"answer":1,"explanation":"Let the fraction of Cl-37 be x: 37x + 35(1 − x) = 35.5, so 2x = 0.5 and x = 0.25, i.e. 25% Cl-37 and 75% Cl-35. 75% is the share of the lighter isotope.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"क्लोरीन के दो समस्थानिक हैं, Cl-35 और Cl-37, और उसका औसत परमाणु द्रव्यमान 35.5 है। प्राकृतिक क्लोरीन में Cl-37 का प्रतिशत कितना है?","optionsHi":["50%","25%","75%","35.5%"],"explanationHi":"माना Cl-37 का अंश x है: 37x + 35(1 − x) = 35.5, इसलिए 2x = 0.5 और x = 0.25, अर्थात 25% Cl-37 और 75% Cl-35। 75% हल्के समस्थानिक का अंश है।"},
  {"id":"sci-chemistry-114","question":"How many of these statements about chemical bonding are correct? I. Sodium chloride is an ionic compound. II. A water molecule is bent, with a bond angle of about 104.5°. III. A methane molecule is tetrahedral. IV. Carbon dioxide is a polar molecule.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. IV is wrong: CO₂ is linear (O=C=O), so the two bond dipoles cancel and the molecule is non-polar, although each C=O bond is polar.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"रासायनिक बंधन से संबंधित इनमें से कितने कथन सही हैं? I. सोडियम क्लोराइड एक आयनिक यौगिक है। II. जल का अणु बंकित (मुड़ा हुआ) होता है, जिसका बंध कोण लगभग 104.5° है। III. मेथेन का अणु चतुष्फलकीय होता है। IV. कार्बन डाइऑक्साइड ध्रुवीय अणु है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। IV गलत है: CO₂ रैखिक (O=C=O) है, इसलिए दोनों बंध द्विध्रुव एक-दूसरे को निरस्त कर देते हैं और अणु अध्रुवीय है, यद्यपि प्रत्येक C=O बंध ध्रुवीय है।"},
  {"id":"sci-chemistry-115","question":"Which of these is a physical change?","options":["Burning of paper","Dissolving sugar in water","Rusting of an iron nail","Cooking an egg until it sets"],"answer":1,"explanation":"Dissolved sugar can be recovered by evaporating the water and no new substance forms, so it is a physical change. Burning, rusting and cooking produce new substances.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"इनमें से कौन-सा भौतिक परिवर्तन है?","optionsHi":["कागज का जलना","चीनी का जल में घुलना","लोहे की कील में जंग लगना","अंडे को पकाकर जमाना"],"explanationHi":"घुली हुई चीनी को जल वाष्पित करके पुनः प्राप्त किया जा सकता है और कोई नया पदार्थ नहीं बनता, इसलिए यह भौतिक परिवर्तन है। जलने, जंग लगने और पकाने से नए पदार्थ बनते हैं।"},
  {"id":"sci-chemistry-116","question":"Which gas is given off when an acid reacts with a metal carbonate such as marble chips?","options":["Carbon dioxide","Hydrogen","Oxygen","Sulphur dioxide"],"answer":0,"explanation":"Acid + carbonate → salt + water + carbon dioxide, which turns lime water milky. Acids with active metals give hydrogen instead, and sulphur dioxide comes from sulphites, not carbonates.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"जब कोई अम्ल संगमरमर के टुकड़ों जैसे धातु कार्बोनेट से अभिक्रिया करता है, तो कौन-सी गैस निकलती है?","optionsHi":["कार्बन डाइऑक्साइड","हाइड्रोजन","ऑक्सीजन","सल्फर डाइऑक्साइड"],"explanationHi":"अम्ल + कार्बोनेट → लवण + जल + कार्बन डाइऑक्साइड, जो चूने के पानी को दूधिया कर देती है। सक्रिय धातुओं से अम्ल हाइड्रोजन देते हैं, और सल्फर डाइऑक्साइड सल्फाइटों से आती है, कार्बोनेटों से नहीं।"},
  {"id":"sci-chemistry-117","question":"Which of the following is an alloy?","options":["Copper","Iron","Steel","Aluminium"],"answer":2,"explanation":"Steel is mainly iron with a small amount of carbon (and often other metals). Copper, iron and aluminium are pure elements.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"निम्नलिखित में से कौन-सी मिश्रधातु है?","optionsHi":["ताँबा","लोहा","इस्पात (स्टील)","ऐलुमिनियम"],"explanationHi":"इस्पात मुख्यतः लोहा है जिसमें थोड़ी मात्रा में कार्बन (और प्रायः अन्य धातुएँ) होती हैं। ताँबा, लोहा और ऐलुमिनियम शुद्ध तत्व हैं।"},
  {"id":"sci-chemistry-118","question":"Sodium hydroxide is commonly known as:","options":["Washing soda","Baking soda","Slaked lime","Caustic soda"],"answer":3,"explanation":"NaOH is caustic soda, used in making soap and paper. Washing soda is Na₂CO₃·10H₂O, baking soda NaHCO₃ and slaked lime Ca(OH)₂.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"सोडियम हाइड्रॉक्साइड को सामान्यतः किस नाम से जाना जाता है?","optionsHi":["धावन सोडा","बेकिंग सोडा","बुझा हुआ चूना","कॉस्टिक सोडा"],"explanationHi":"NaOH कॉस्टिक सोडा है, जो साबुन और कागज बनाने में प्रयुक्त होता है। धावन सोडा Na₂CO₃·10H₂O है, बेकिंग सोडा NaHCO₃ और बुझा चूना Ca(OH)₂ है।"},
  {"id":"sci-chemistry-119","question":"Chemically, rust is mainly:","options":["Hydrated iron(III) oxide","Iron sulphide","Iron carbonate","Anhydrous iron(II) oxide"],"answer":0,"explanation":"Rust is a reddish-brown hydrated ferric oxide, Fe₂O₃·xH₂O, formed when iron reacts with oxygen in the presence of water.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"रासायनिक रूप से जंग मुख्यतः क्या है?","optionsHi":["जलयोजित आयरन(III) ऑक्साइड","आयरन सल्फाइड","आयरन कार्बोनेट","निर्जल आयरन(II) ऑक्साइड"],"explanationHi":"जंग लालिमा लिए भूरा जलयोजित फेरिक ऑक्साइड, Fe₂O₃·xH₂O, है, जो जल की उपस्थिति में लोहे के ऑक्सीजन से अभिक्रिया करने पर बनती है।"},
  {"id":"sci-chemistry-120","question":"Which non-metal has a shiny (lustrous) appearance?","options":["Sulphur","Iodine","Phosphorus","Carbon in the form of charcoal"],"answer":1,"explanation":"Iodine crystals have a metallic lustre although iodine is a non-metal. Graphite (another exception) conducts electricity, but charcoal is dull.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"किस अधातु में चमक (दीप्ति) होती है?","optionsHi":["सल्फर","आयोडीन","फॉस्फोरस","चारकोल के रूप में कार्बन"],"explanationHi":"आयोडीन के क्रिस्टलों में धात्विक चमक होती है, यद्यपि आयोडीन अधातु है। ग्रेफाइट (एक अन्य अपवाद) विद्युत चालन करता है, परंतु चारकोल बेरंग और मटमैला होता है।"},
  {"id":"sci-chemistry-121","question":"Which metal is the best conductor of electricity?","options":["Copper","Gold","Silver","Aluminium"],"answer":2,"explanation":"Silver has the highest electrical conductivity of all metals, followed by copper. Copper is used for wiring because it is far cheaper.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"कौन-सी धातु विद्युत की सर्वश्रेष्ठ चालक है?","optionsHi":["ताँबा","सोना","चाँदी","ऐलुमिनियम"],"explanationHi":"चाँदी की विद्युत चालकता सभी धातुओं में सबसे अधिक है, उसके बाद ताँबे की। ताँबे का उपयोग तारों में इसलिए होता है क्योंकि वह कहीं सस्ता है।"},
  {"id":"sci-chemistry-122","question":"Bronze is an alloy of:","options":["Copper and zinc","Iron and carbon","Lead and tin","Copper and tin"],"answer":3,"explanation":"Bronze is copper with tin, used since the Bronze Age for tools, statues and bells. Copper with zinc is brass; lead with tin is solder.","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"काँसा (ब्रॉन्ज़) किसकी मिश्रधातु है?","optionsHi":["ताँबा और जस्ता","लोहा और कार्बन","सीसा और टिन","ताँबा और टिन"],"explanationHi":"काँसा ताँबे और टिन की मिश्रधातु है, जिसका उपयोग कांस्य युग से औज़ारों, मूर्तियों और घंटों में होता आया है। ताँबा और जस्ता मिलकर पीतल बनाते हैं; सीसा और टिन सोल्डर बनाते हैं।"},
  {"id":"sci-chemistry-123","question":"Electrolysis of brine (concentrated sodium chloride solution) in the chlor-alkali process produces:","options":["Sodium hydroxide, chlorine and hydrogen","Sodium metal, chlorine and oxygen","Hydrochloric acid and sodium metal","Sodium carbonate, chlorine and hydrogen"],"answer":0,"explanation":"Chlorine forms at the anode, hydrogen at the cathode, and sodium hydroxide remains in solution; hence ‘chlor-alkali’. Sodium metal needs electrolysis of molten NaCl.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"क्लोर-क्षार प्रक्रम में ब्राइन (सांद्र सोडियम क्लोराइड विलयन) के विद्युत अपघटन से क्या प्राप्त होता है?","optionsHi":["सोडियम हाइड्रॉक्साइड, क्लोरीन और हाइड्रोजन","सोडियम धातु, क्लोरीन और ऑक्सीजन","हाइड्रोक्लोरिक अम्ल और सोडियम धातु","सोडियम कार्बोनेट, क्लोरीन और हाइड्रोजन"],"explanationHi":"क्लोरीन ऐनोड पर बनती है, हाइड्रोजन कैथोड पर, और सोडियम हाइड्रॉक्साइड विलयन में रह जाता है; इसीलिए ‘क्लोर-क्षार’ नाम है। सोडियम धातु के लिए पिघले NaCl का विद्युत अपघटन करना पड़ता है।"},
  {"id":"sci-chemistry-124","question":"Highly reactive metals such as sodium and magnesium are extracted by:","options":["Heating their oxides strongly with carbon (coke)","Electrolysis of their molten chlorides","Heating their sulphides in air","Dissolving them in water"],"answer":1,"explanation":"These metals hold oxygen more strongly than carbon does, so carbon cannot reduce their oxides; electrolytic reduction of the molten compound is used instead.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"सोडियम और मैग्नीशियम जैसी अत्यधिक क्रियाशील धातुओं का निष्कर्षण किस विधि से किया जाता है?","optionsHi":["उनके ऑक्साइडों को कार्बन (कोक) के साथ प्रबल रूप से गर्म करके","उनके पिघले हुए क्लोराइडों का विद्युत अपघटन करके","उनके सल्फाइडों को वायु में गर्म करके","उन्हें जल में घोलकर"],"explanationHi":"ये धातुएँ ऑक्सीजन को कार्बन की तुलना में अधिक मजबूती से पकड़ती हैं, इसलिए कार्बन उनके ऑक्साइडों का अपचयन नहीं कर सकता; इसके बजाय पिघले यौगिक का विद्युत अपघटनी अपचयन किया जाता है।"},
  {"id":"sci-chemistry-125","question":"An oxide that reacts with both acids and bases to form salt and water is called amphoteric. Which of these is amphoteric?","options":["Sodium oxide","Carbon dioxide","Aluminium oxide","Magnesium oxide"],"answer":2,"explanation":"Al₂O₃ (and ZnO) dissolve in both acids and alkalis. Sodium and magnesium oxides are basic; carbon dioxide is acidic.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"जो ऑक्साइड अम्लों और क्षारों दोनों से अभिक्रिया करके लवण और जल बनाता है, उभयधर्मी कहलाता है। इनमें से कौन-सा उभयधर्मी है?","optionsHi":["सोडियम ऑक्साइड","कार्बन डाइऑक्साइड","ऐलुमिनियम ऑक्साइड","मैग्नीशियम ऑक्साइड"],"explanationHi":"Al₂O₃ (और ZnO) अम्लों और क्षारों दोनों में घुल जाते हैं। सोडियम और मैग्नीशियम के ऑक्साइड क्षारीय हैं; कार्बन डाइऑक्साइड अम्लीय है।"},
  {"id":"sci-chemistry-126","question":"Heating ethanol with excess concentrated sulphuric acid at about 170 °C gives ethene. Here the acid acts as a:","options":["Reducing agent","Oxidising agent","Catalyst for addition","Dehydrating agent"],"answer":3,"explanation":"Concentrated H₂SO₄ removes a molecule of water from ethanol (C₂H₅OH → C₂H₄ + H₂O). Its strong affinity for water also explains why it chars sugar.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एथेनॉल को अधिक मात्रा में सांद्र सल्फ्यूरिक अम्ल के साथ लगभग 170 °C पर गर्म करने से एथीन बनती है। यहाँ अम्ल किस रूप में कार्य करता है?","optionsHi":["अपचायक","ऑक्सीकारक","योगात्मक अभिक्रिया का उत्प्रेरक","निर्जलीकारक"],"explanationHi":"सांद्र H₂SO₄ एथेनॉल से जल का एक अणु निकाल देता है (C₂H₅OH → C₂H₄ + H₂O)। जल के प्रति उसकी प्रबल बंधुता यह भी समझाती है कि वह चीनी को क्यों जला देता है।"},
  {"id":"sci-chemistry-127","question":"In the thermite process used to weld railway tracks, molten iron is produced when:","options":["Aluminium reduces iron(III) oxide, releasing intense heat","Carbon reduces iron oxide in a blast furnace beside the rails","Iron is electrolysed from its molten ore on the spot","Copper displaces iron from iron sulphate in solution"],"answer":0,"explanation":"Fe₂O₃ + 2Al → 2Fe + Al₂O₃ releases so much heat that the iron formed is molten and can fill the gap between rails.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"रेल पटरियों को जोड़ने में प्रयुक्त थर्माइट प्रक्रम में पिघला हुआ लोहा कब बनता है?","optionsHi":["जब ऐलुमिनियम आयरन(III) ऑक्साइड का अपचयन करता है और तीव्र ऊष्मा निकलती है","जब पटरियों के पास वात्या भट्ठी में कार्बन आयरन ऑक्साइड का अपचयन करता है","जब पिघले अयस्क से वहीं लोहे का विद्युत अपघटन किया जाता है","जब ताँबा विलयन में आयरन सल्फेट से लोहे को विस्थापित करता है"],"explanationHi":"Fe₂O₃ + 2Al → 2Fe + Al₂O₃ में इतनी ऊष्मा निकलती है कि बना हुआ लोहा पिघला रहता है और पटरियों के बीच की दरार को भर सकता है।"},
  {"id":"sci-chemistry-128","question":"Diamond is extremely hard because:","options":["It contains strong metallic bonds between its carbon atoms","Each C atom is covalently bonded to four others in a rigid 3-D network","It contains free, mobile electrons that bind the atoms tightly together","Its carbon atoms are arranged in loosely held flat layers"],"answer":1,"explanation":"The strong tetrahedral covalent network has no weak planes. Graphite's layers, held by weak forces, slide over each other, which makes it soft and slippery.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"हीरा अत्यंत कठोर होता है क्योंकि:","optionsHi":["उसके कार्बन परमाणुओं के बीच प्रबल धात्विक बंध होते हैं","प्रत्येक C परमाणु एक दृढ़ 3-D जालक में चार अन्य परमाणुओं से सहसंयोजी रूप से बंधा होता है","उसमें मुक्त, गतिशील इलेक्ट्रॉन होते हैं जो परमाणुओं को कसकर बाँधते हैं","उसके कार्बन परमाणु ढीली पकड़ वाली चपटी परतों में व्यवस्थित होते हैं"],"explanationHi":"प्रबल चतुष्फलकीय सहसंयोजी जालक में कोई कमज़ोर तल नहीं होता। ग्रेफाइट की परतें, जो दुर्बल बलों से जुड़ी होती हैं, एक-दूसरे पर फिसल जाती हैं, जिससे वह मुलायम और चिकना होता है।"},
  {"id":"sci-chemistry-129","question":"n-Butane and isobutane both have the formula C₄H₁₀ but different structures. They are called:","options":["Isotopes","Allotropes","Structural isomers","Geometrical isomers"],"answer":2,"explanation":"Structural isomers have the same molecular formula but different arrangements of atoms (straight versus branched chain). Butanes have no C=C bond, so they cannot show geometrical (cis–trans) isomerism; isotopes and isobars refer to atoms, and allotropes to forms of an element.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"n-ब्यूटेन और आइसोब्यूटेन दोनों का सूत्र C₄H₁₀ है परंतु उनकी संरचनाएँ भिन्न हैं। इन्हें क्या कहते हैं?","optionsHi":["समस्थानिक","अपररूप","संरचनात्मक समावयवी","ज्यामितीय समावयवी"],"explanationHi":"संरचनात्मक समावयवियों का अणुसूत्र समान किंतु परमाणुओं की व्यवस्था भिन्न होती है (सीधी बनाम शाखित श्रृंखला)। ब्यूटेनों में C=C बंध नहीं होता, इसलिए वे ज्यामितीय (सिस–ट्रांस) समावयवता नहीं दर्शा सकते; समस्थानिक और समभारिक परमाणुओं से तथा अपररूप किसी तत्व के रूपों से संबंधित हैं।"},
  {"id":"sci-chemistry-130","question":"What is the percentage of oxygen by mass in water? (H = 1, O = 16)","options":["11.1%","33.3%","66.7%","88.9%"],"answer":3,"explanation":"H₂O has mass 18, of which oxygen is 16: 16/18 × 100 ≈ 88.9%. The 33.3% trap comes from counting atoms (one in three) instead of mass.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"जल में ऑक्सीजन का द्रव्यमान प्रतिशत कितना है? (H = 1, O = 16)","optionsHi":["11.1%","33.3%","66.7%","88.9%"],"explanationHi":"H₂O का द्रव्यमान 18 है, जिसमें ऑक्सीजन 16 है: 16/18 × 100 ≈ 88.9%। 33.3% का भ्रम द्रव्यमान के बजाय परमाणु गिनने (तीन में से एक) से आता है।"},
  {"id":"sci-chemistry-131","question":"How many of these statements about the reactivity of metals are correct? I. Potassium and sodium react vigorously with cold water. II. Gold and platinum do not react with dilute acids. III. Copper displaces silver from silver nitrate solution. IV. Iron displaces zinc from zinc sulphate solution.","options":["Only one","Only three","Only two","All four"],"answer":1,"explanation":"I, II and III are correct. Zinc is more reactive than iron, so iron cannot displace it; zinc's greater reactivity is also why it protects iron in galvanising. IV is wrong.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"धातुओं की क्रियाशीलता से संबंधित इनमें से कितने कथन सही हैं? I. पोटैशियम और सोडियम ठंडे जल से तीव्रता से अभिक्रिया करते हैं। II. सोना और प्लैटिनम तनु अम्लों से अभिक्रिया नहीं करते। III. ताँबा सिल्वर नाइट्रेट विलयन से चाँदी को विस्थापित करता है। IV. लोहा जिंक सल्फेट विलयन से जस्ते को विस्थापित करता है।","optionsHi":["केवल एक","केवल तीन","केवल दो","सभी चार"],"explanationHi":"I, II और III सही हैं। जस्ता लोहे से अधिक क्रियाशील है, इसलिए लोहा उसे विस्थापित नहीं कर सकता; जस्ते की अधिक क्रियाशीलता ही यशदलेपन में लोहे की रक्षा करती है। IV गलत है।"},
  {"id":"sci-chemistry-132","question":"Match the metallurgical step with its description. A. Calcination  B. Roasting  C. Smelting  D. Electrolytic refining; 1. Heating a carbonate ore in little or no air to convert it into an oxide  2. Heating a sulphide ore strongly in excess air  3. Reducing a metal oxide with carbon in a furnace  4. Impure metal as anode and pure metal deposited on the cathode","options":["A-2, B-1, C-3, D-4","A-1, B-2, C-4, D-3","A-1, B-3, C-2, D-4","A-1, B-2, C-3, D-4"],"answer":3,"explanation":"Zinc carbonate is calcined and zinc sulphide roasted, both giving ZnO; smelting with carbon reduces the oxide; copper is purified electrolytically.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"धातुकर्मीय चरण का उसके वर्णन से मिलान कीजिए। A. निस्तापन (कैल्सिनेशन) B. भर्जन (रोस्टिंग) C. प्रगलन (स्मेल्टिंग) D. विद्युत अपघटनी परिष्करण; 1. कार्बोनेट अयस्क को कम या बिना वायु के गर्म करके ऑक्साइड में बदलना 2. सल्फाइड अयस्क को वायु की अधिकता में प्रबल रूप से गर्म करना 3. भट्ठी में धातु ऑक्साइड का कार्बन से अपचयन करना 4. अशुद्ध धातु को ऐनोड और शुद्ध धातु को कैथोड पर जमा करना","optionsHi":["A-2, B-1, C-3, D-4","A-1, B-2, C-4, D-3","A-1, B-3, C-2, D-4","A-1, B-2, C-3, D-4"],"explanationHi":"जिंक कार्बोनेट का निस्तापन और जिंक सल्फाइड का भर्जन किया जाता है, दोनों से ZnO मिलता है; कार्बन से प्रगलन ऑक्साइड का अपचयन करता है; और ताँबे का शोधन विद्युत अपघटन से किया जाता है।"},
  {"id":"sci-chemistry-133","question":"Assertion (A): Graphite conducts electricity, but diamond does not. Reason (R): In graphite each carbon atom is bonded to only three others, leaving one electron per atom free to move.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"The delocalised electrons in graphite's layers carry current; in diamond all four valence electrons are locked in bonds, so it is an insulator.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"अभिकथन (A): ग्रेफाइट विद्युत का चालन करता है, परंतु हीरा नहीं करता। कारण (R): ग्रेफाइट में प्रत्येक कार्बन परमाणु केवल तीन अन्य परमाणुओं से बंधा होता है, जिससे प्रत्येक परमाणु का एक इलेक्ट्रॉन गति करने के लिए मुक्त रहता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A सही है परंतु R गलत है","A गलत है परंतु R सही है"],"explanationHi":"ग्रेफाइट की परतों में विस्थानीकृत इलेक्ट्रॉन धारा का वहन करते हैं; हीरे में चारों संयोजी इलेक्ट्रॉन बंधों में बँधे होते हैं, इसलिए वह विद्युतरोधी है।"},
  {"id":"sci-chemistry-134","question":"How many of these statements about pH in daily life are correct? I. Tooth enamel starts to dissolve when the pH in the mouth falls below about 5.5. II. Rain with a pH below about 5.6 is called acid rain. III. Taking an antacid raises the pH of the stomach contents. IV. A solution of pH 9 is more acidic than one of pH 5.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. A lower pH means a more acidic solution, so pH 5 is acidic and pH 9 is basic; IV is wrong.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"दैनिक जीवन में pH से संबंधित इनमें से कितने कथन सही हैं? I. मुँह में pH लगभग 5.5 से कम होने पर दाँत का इनेमल घुलना शुरू हो जाता है। II. लगभग 5.6 से कम pH वाली वर्षा अम्लीय वर्षा कहलाती है। III. प्रति-अम्ल (एंटैसिड) लेने से आमाशय की सामग्री का pH बढ़ता है। IV. pH 9 वाला विलयन pH 5 वाले विलयन से अधिक अम्लीय होता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं। कम pH का अर्थ अधिक अम्लीय विलयन है, इसलिए pH 5 अम्लीय और pH 9 क्षारीय है; IV गलत है।"},
  {"id":"sci-chemistry-135","question":"Arrange these metals in increasing order of reactivity: 1. Zinc  2. Copper  3. Magnesium  4. Iron","options":["2-4-1-3","2-1-4-3","4-2-1-3","2-4-3-1"],"answer":0,"explanation":"In the activity series, copper < iron < zinc < magnesium. So magnesium displaces zinc, zinc displaces iron, and iron displaces copper from their salt solutions.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"इन धातुओं को क्रियाशीलता के बढ़ते क्रम में व्यवस्थित कीजिए: 1. जिंक 2. ताँबा 3. मैग्नीशियम 4. लोहा","optionsHi":["2-4-1-3","2-1-4-3","4-2-1-3","2-4-3-1"],"explanationHi":"क्रियाशीलता श्रेणी में ताँबा < लोहा < जस्ता < मैग्नीशियम है। इसलिए मैग्नीशियम जस्ते को, जस्ता लोहे को, और लोहा ताँबे को उनके लवण विलयनों से विस्थापित करता है।"},
  {"id":"sci-chemistry-136","question":"Match the functional group with a compound containing it. A. Alcohol (−OH)  B. Aldehyde (−CHO)  C. Ketone (>C=O)  D. Carboxylic acid (−COOH); 1. Ethanoic acid  2. Propanone (acetone)  3. Methanal (formaldehyde)  4. Ethanol","options":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-1, B-3, C-2, D-4","A-4, B-3, C-1, D-2"],"answer":1,"explanation":"Ethanol is an alcohol, formaldehyde the simplest aldehyde, acetone (nail-polish remover) the simplest common ketone, and ethanoic acid gives vinegar its sourness.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"क्रियात्मक समूह का उसे धारण करने वाले यौगिक से मिलान कीजिए। A. ऐल्कोहॉल (−OH) B. ऐल्डिहाइड (−CHO) C. कीटोन (>C=O) D. कार्बोक्सिलिक अम्ल (−COOH); 1. एथेनॉइक अम्ल 2. प्रोपेनोन (ऐसीटोन) 3. मेथेनैल (फॉर्मेल्डिहाइड) 4. एथेनॉल","optionsHi":["A-4, B-2, C-3, D-1","A-4, B-3, C-2, D-1","A-1, B-3, C-2, D-4","A-4, B-3, C-1, D-2"],"explanationHi":"एथेनॉल ऐल्कोहॉल है, फॉर्मेल्डिहाइड सबसे सरल ऐल्डिहाइड, ऐसीटोन (नेल-पॉलिश रिमूवर) सबसे सरल सामान्य कीटोन, और एथेनॉइक अम्ल सिरके को उसकी खटास देता है।"},
  {"id":"sci-chemistry-137","question":"How many of these statements about a homologous series are correct? I. Successive members differ by a −CH₂− unit. II. Their molecular masses differ by 14 u. III. All members show similar chemical properties. IV. All members have identical physical properties.","options":["Only one","Only two","All four","Only three"],"answer":3,"explanation":"I, II and III are correct. Physical properties such as boiling point change gradually as the chain grows, so IV is wrong.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"सजातीय श्रेणी से संबंधित इनमें से कितने कथन सही हैं? I. क्रमागत सदस्यों में −CH₂− इकाई का अंतर होता है। II. उनके आण्विक द्रव्यमानों में 14 u का अंतर होता है। III. सभी सदस्यों के रासायनिक गुण समान होते हैं। IV. सभी सदस्यों के भौतिक गुण एक-से होते हैं।","optionsHi":["केवल एक","केवल दो","सभी चार","केवल तीन"],"explanationHi":"I, II और III सही हैं। श्रृंखला बढ़ने के साथ क्वथनांक जैसे भौतिक गुण धीरे-धीरे बदलते हैं, इसलिए IV गलत है।"},
  {"id":"sci-chemistry-138","question":"Assertion (A): Many esters have a pleasant, fruity smell and are used in perfumes and flavourings. Reason (R): Esters are formed when a carboxylic acid reacts with an alcohol in the presence of an acid catalyst.","options":["Both A and R are true and R is the correct explanation of A","A is true but R is false","Both A and R are true but R is not the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Both statements are true, but the way an ester is made does not explain why it smells fruity; the smell comes from the volatility and structure of the ester molecules.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"अभिकथन (A): अनेक एस्टरों की गंध सुखद, फलों जैसी होती है और वे इत्र तथा स्वादकारकों में प्रयुक्त होते हैं। कारण (R): एस्टर तब बनते हैं जब कार्बोक्सिलिक अम्ल अम्लीय उत्प्रेरक की उपस्थिति में ऐल्कोहॉल से अभिक्रिया करता है।","optionsHi":["A और R दोनों सही हैं और R, A की सही व्याख्या है","A सही है परंतु R गलत है","A और R दोनों सही हैं परंतु R, A की सही व्याख्या नहीं है","A गलत है परंतु R सही है"],"explanationHi":"दोनों कथन सही हैं, परंतु एस्टर बनने की विधि यह नहीं समझाती कि उसमें फलों जैसी गंध क्यों होती है; गंध एस्टर अणुओं की वाष्पशीलता और संरचना से आती है।"},
  {"id":"sci-chemistry-139","question":"What is the percentage of water of crystallisation by mass in blue vitriol, CuSO₄·5H₂O? (Cu = 63.5, S = 32, O = 16, H = 1)","options":["18.0%","36.1%","56.4%","63.9%"],"answer":1,"explanation":"CuSO₄ = 159.5 and 5H₂O = 90, so the formula mass is 249.5; 90/249.5 × 100 ≈ 36.1%. Heating drives off this water, turning blue crystals white.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC · RRB Group D","questionHi":"नीले थोथे, CuSO₄·5H₂O, में क्रिस्टलन जल का द्रव्यमान प्रतिशत कितना है? (Cu = 63.5, S = 32, O = 16, H = 1)","optionsHi":["18.0%","36.1%","56.4%","63.9%"],"explanationHi":"CuSO₄ = 159.5 और 5H₂O = 90, इसलिए सूत्र द्रव्यमान 249.5 है; 90/249.5 × 100 ≈ 36.1%। गर्म करने पर यह जल निकल जाता है और नीले क्रिस्टल सफेद हो जाते हैं।"},
  {"id":"sci-chemistry-140","question":"Water stored in an unglazed earthen pot (matka) stays cooler than the surrounding air in summer. The main reason is that:","options":["Clay is a poor conductor and simply keeps the outside heat away","Water seeping out evaporates from the surface, taking latent heat","Clay reacts with water in an endothermic reaction that absorbs heat","Air trapped in the pores of the clay is always colder than outside"],"answer":1,"explanation":"Evaporation needs latent heat, which is drawn from the pot and the water, so the water cools below air temperature. Poor conduction alone could only slow heating, never cool the water below the surroundings.","difficulty":"hard","source":"RRB NTPC · SSC CGL","questionHi":"गर्मियों में बिना चमकाए (अनग्लेज़्ड) मिट्टी के घड़े (मटके) में रखा जल आसपास की वायु से अधिक ठंडा रहता है। इसका मुख्य कारण है:","optionsHi":["मिट्टी कुचालक है और बाहर की गर्मी को केवल दूर रखती है","रिसकर बाहर आया जल सतह से वाष्पित होकर गुप्त ऊष्मा लेता है","मिट्टी जल से ऊष्माशोषी अभिक्रिया करके ऊष्मा सोख लेती है","मिट्टी के छिद्रों में फँसी वायु सदैव बाहर से ठंडी होती है"],"explanationHi":"वाष्पन के लिए गुप्त ऊष्मा चाहिए, जो घड़े और जल से ली जाती है, इसलिए जल वायु के तापमान से भी ठंडा हो जाता है। केवल कुचालकता गर्म होने की गति ही धीमी कर सकती है, जल को परिवेश से ठंडा कभी नहीं।"},
  {"id":"sci-chemistry-141","question":"Which of the following will increase the rate of evaporation of water from wet clothes? I. Spreading the clothes out II. A rise in the humidity of the air III. A stronger wind IV. A rise in temperature","options":["I and III only","II and IV only","I, II, III and IV","I, III and IV only"],"answer":3,"explanation":"Larger surface area, wind and higher temperature all speed up evaporation. Higher humidity slows it, because the air already holds more water vapour.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"निम्नलिखित में से कौन-सी बातें गीले कपड़ों से जल के वाष्पन की दर बढ़ाएँगी? I. कपड़ों को फैलाकर सुखाना II. वायु की आर्द्रता बढ़ना III. अधिक तेज हवा IV. तापमान बढ़ना","optionsHi":["केवल I और III","केवल II और IV","I, II, III और IV","केवल I, III और IV"],"explanationHi":"अधिक पृष्ठीय क्षेत्रफल, हवा और उच्च तापमान तीनों वाष्पन को तेज करते हैं। उच्च आर्द्रता उसे धीमा करती है, क्योंकि वायु में पहले से अधिक जलवाष्प होती है।"},
  {"id":"sci-chemistry-142","question":"Which of these substances changes directly from solid to vapour on heating, without first melting?","options":["Camphor","Common salt","Sugar","Paraffin wax"],"answer":0,"explanation":"Camphor sublimes, like naphthalene, iodine and ammonium chloride. Salt and wax melt first, and sugar melts and then chars.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"इनमें से कौन-सा पदार्थ गर्म करने पर पहले पिघले बिना सीधे ठोस से वाष्प में बदल जाता है?","optionsHi":["कपूर","सामान्य नमक","चीनी","पैराफिन मोम"],"explanationHi":"कपूर, नैफ्थलीन, आयोडीन और अमोनियम क्लोराइड की तरह, उर्ध्वपातित होता है। नमक और मोम पहले पिघलते हैं, और चीनी पिघलकर फिर जल जाती है।"},
  {"id":"sci-chemistry-143","question":"The smell of hot, freshly cooked food reaches us from some distance, but we have to go close to cold food to smell it. This is because:","options":["Hot food produces new kinds of smell molecules that cold food cannot","Particles diffuse faster when hot, as they have more kinetic energy","Air is denser near hot food, so the smell travels further","Cold food absorbs the smell back from the air around it"],"answer":1,"explanation":"The rate of diffusion increases with temperature: hotter vapour particles move faster and spread through air more quickly.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"गर्म, ताज़ा पके भोजन की गंध हमें कुछ दूरी से आ जाती है, पर ठंडे भोजन की गंध सूँघने के लिए हमें पास जाना पड़ता है। इसका कारण यह है कि:","optionsHi":["गर्म भोजन नए प्रकार के गंध अणु बनाता है जो ठंडा भोजन नहीं बना सकता","गर्म होने पर कण अधिक गतिज ऊर्जा के कारण तेजी से विसरित होते हैं","गर्म भोजन के पास वायु अधिक सघन होती है, इसलिए गंध दूर तक जाती है","ठंडा भोजन आसपास की वायु से गंध को वापस सोख लेता है"],"explanationHi":"विसरण की दर तापमान के साथ बढ़ती है: गर्म वाष्प के कण तेजी से गति करते हैं और वायु में शीघ्र फैल जाते हैं।"},
  {"id":"sci-chemistry-144","question":"Which of the following is an emulsion, that is, a liquid dispersed in another liquid?","options":["Fog","Smoke","Milk","Shaving foam"],"answer":2,"explanation":"Milk is liquid fat dispersed in water. Fog is a liquid in a gas (aerosol), smoke is a solid in a gas, and shaving foam is a gas in a liquid.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"निम्नलिखित में से कौन-सा इमल्शन (पायस) है, अर्थात किसी द्रव में परिक्षिप्त एक द्रव?","optionsHi":["कोहरा","धुआँ","दूध","शेविंग फोम"],"explanationHi":"दूध जल में परिक्षिप्त द्रव वसा है। कोहरा गैस में द्रव है (ऐरोसोल), धुआँ गैस में ठोस है, और शेविंग फोम द्रव में गैस है।"},
  {"id":"sci-chemistry-145","question":"In a dairy, cream is separated from milk by:","options":["Filtration","Centrifugation","Fractional distillation","Sublimation"],"answer":1,"explanation":"Spinning the milk rapidly forces the denser liquid outwards and the lighter fat (cream) collects in the centre. The fat droplets are far too small to be held back by a filter.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"डेयरी में दूध से मलाई किस विधि से अलग की जाती है?","optionsHi":["निस्पंदन (छानना)","अपकेंद्रण","प्रभाजी आसवन","उर्ध्वपातन"],"explanationHi":"दूध को तेजी से घुमाने पर सघन द्रव बाहर की ओर चला जाता है और हल्की वसा (मलाई) बीच में एकत्र हो जाती है। वसा की बूँदें इतनी छोटी होती हैं कि छन्नी उन्हें रोक नहीं सकती।"},
  {"id":"sci-chemistry-146","question":"Pure copper sulphate is obtained from an impure sample by crystallisation rather than by simply evaporating the solution to dryness, because evaporation to dryness:","options":["Leaves soluble impurities in the solid, and heat may decompose the salt","Converts copper sulphate into copper metal and sulphur dioxide","Removes only part of the water of crystallisation, giving bigger crystals","Is always much slower than crystallisation and wastes fuel"],"answer":0,"explanation":"On evaporating to dryness all dissolved impurities stay in the residue and strong heating can drive off water of crystallisation or decompose the salt; in crystallisation the impurities remain in the mother liquor.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"अशुद्ध नमूने से शुद्ध कॉपर सल्फेट विलयन को सीधे सुखाने तक वाष्पित करने के बजाय क्रिस्टलन द्वारा प्राप्त किया जाता है, क्योंकि सुखाने तक वाष्पन:","optionsHi":["घुलनशील अशुद्धियों को ठोस में छोड़ देता है, और ऊष्मा लवण को विघटित कर सकती है","कॉपर सल्फेट को ताँबे की धातु और सल्फर डाइऑक्साइड में बदल देता है","क्रिस्टलन जल का केवल कुछ भाग निकालता है, जिससे बड़े क्रिस्टल बनते हैं","क्रिस्टलन से सदैव बहुत धीमा होता है और ईंधन व्यर्थ करता है"],"explanationHi":"सुखाने तक वाष्पन करने पर सभी घुली अशुद्धियाँ अवशेष में रह जाती हैं और प्रबल ऊष्मा क्रिस्टलन जल को निकाल सकती है या लवण को विघटित कर सकती है; क्रिस्टलन में अशुद्धियाँ मातृ द्रव में रह जाती हैं।"},
  {"id":"sci-chemistry-147","question":"Which of these samples contains the largest number of atoms? (H = 1, He = 4, N = 14, O = 16)","options":["1 g of helium","1 g of nitrogen gas","1 g of oxygen gas","1 g of hydrogen gas"],"answer":3,"explanation":"1 g of H₂ is 0.5 mol of molecules, i.e. 1 mol of atoms. Helium gives 0.25 mol of atoms, N₂ about 0.071 mol and O₂ 0.0625 mol of atoms.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"इन नमूनों में से किसमें परमाणुओं की संख्या सबसे अधिक है? (H = 1, He = 4, N = 14, O = 16)","optionsHi":["1 g हीलियम","1 g नाइट्रोजन गैस","1 g ऑक्सीजन गैस","1 g हाइड्रोजन गैस"],"explanationHi":"1 g H₂ = 0.5 mol अणु, अर्थात 1 mol परमाणु। हीलियम से 0.25 mol परमाणु, N₂ से लगभग 0.071 mol और O₂ से 0.0625 mol परमाणु मिलते हैं।"},
  {"id":"sci-chemistry-148","question":"How many atoms in total are present in one mole of sulphuric acid, H₂SO₄? (Avogadro's number = 6.022 × 10²³)","options":["6.022 × 10²³","4.215 × 10²⁴","3.011 × 10²³","2.409 × 10²⁴"],"answer":1,"explanation":"Each H₂SO₄ molecule has 2 + 1 + 4 = 7 atoms, so one mole contains 7 × 6.022 × 10²³ ≈ 4.215 × 10²⁴ atoms. 6.022 × 10²³ counts molecules, not atoms; 2.409 × 10²⁴ counts only the oxygen atoms.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक मोल सल्फ्यूरिक अम्ल, H₂SO₄, में कुल कितने परमाणु होते हैं? (आवोगाद्रो संख्या = 6.022 × 10²³)","optionsHi":["6.022 × 10²³","4.215 × 10²⁴","3.011 × 10²³","2.409 × 10²⁴"],"explanationHi":"H₂SO₄ के प्रत्येक अणु में 2 + 1 + 4 = 7 परमाणु होते हैं, इसलिए एक मोल में 7 × 6.022 × 10²³ ≈ 4.215 × 10²⁴ परमाणु हैं। 6.022 × 10²³ अणुओं की संख्या है, परमाणुओं की नहीं; 2.409 × 10²⁴ केवल ऑक्सीजन परमाणुओं की गिनती है।"},
  {"id":"sci-chemistry-149","question":"Equal masses of oxygen gas (O₂) and sulphur dioxide (SO₂) are taken. What is the ratio of the total number of atoms in the oxygen sample to that in the sulphur dioxide sample? (O = 16, S = 32)","options":["2 : 1","1 : 2","4 : 3","2 : 3"],"answer":2,"explanation":"For mass m, O₂ gives m/32 × 2 = m/16 mol of atoms, and SO₂ gives m/64 × 3 = 3m/64 mol of atoms; the ratio is (1/16) : (3/64) = 4 : 3. The 2 : 1 trap is the ratio of molecules.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"ऑक्सीजन गैस (O₂) और सल्फर डाइऑक्साइड (SO₂) के समान द्रव्यमान लिए जाते हैं। ऑक्सीजन के नमूने में परमाणुओं की कुल संख्या का सल्फर डाइऑक्साइड के नमूने में परमाणुओं की कुल संख्या से अनुपात क्या है? (O = 16, S = 32)","optionsHi":["2 : 1","1 : 2","4 : 3","2 : 3"],"explanationHi":"द्रव्यमान m के लिए O₂ से m/32 × 2 = m/16 mol परमाणु मिलते हैं, और SO₂ से m/64 × 3 = 3m/64 mol परमाणु; अनुपात (1/16) : (3/64) = 4 : 3। भ्रम का विकल्प 2 : 1 अणुओं का अनुपात है।"},
  {"id":"sci-chemistry-150","question":"An element X has atomic number 13. The formulae of its oxide and its chloride are:","options":["XO and XCl₂","X₃O₂ and XCl₃","X₂O₃ and XCl₂","X₂O₃ and XCl₃"],"answer":3,"explanation":"Configuration 2, 8, 3 gives valency 3 (this is aluminium). With oxygen (valency 2) the formula is X₂O₃, and with chlorine (valency 1) it is XCl₃.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक तत्व X का परमाणु क्रमांक 13 है। उसके ऑक्साइड और क्लोराइड के सूत्र क्या होंगे?","optionsHi":["XO और XCl₂","X₃O₂ और XCl₃","X₂O₃ और XCl₂","X₂O₃ और XCl₃"],"explanationHi":"विन्यास 2, 8, 3 से संयोजकता 3 मिलती है (यह ऐलुमिनियम है)। ऑक्सीजन (संयोजकता 2) के साथ सूत्र X₂O₃ और क्लोरीन (संयोजकता 1) के साथ XCl₃ होता है।"},
  {"id":"sci-chemistry-151","question":"An element has the electronic configuration 2, 8, 2. Its position in the modern periodic table is:","options":["Group 2, Period 3","Group 3, Period 2","Group 2, Period 2","Group 12, Period 3"],"answer":0,"explanation":"Three shells means Period 3, and two valence electrons in an s-block element means Group 2 (this is magnesium).","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक तत्व का इलेक्ट्रॉनिक विन्यास 2, 8, 2 है। आधुनिक आवर्त सारणी में उसकी स्थिति क्या है?","optionsHi":["समूह 2, आवर्त 3","समूह 3, आवर्त 2","समूह 2, आवर्त 2","समूह 12, आवर्त 3"],"explanationHi":"तीन कोश का अर्थ आवर्त 3 है, और s-ब्लॉक तत्व में दो संयोजी इलेक्ट्रॉन का अर्थ समूह 2 है (यह मैग्नीशियम है)।"},
  {"id":"sci-chemistry-152","question":"The neutron, the uncharged particle in the nucleus, was discovered in 1932 by:","options":["J. J. Thomson","Ernest Rutherford","E. Goldstein","James Chadwick"],"answer":3,"explanation":"Chadwick discovered the neutron. Thomson discovered the electron, Goldstein found canal rays (which led to the proton), and Rutherford discovered the nucleus.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"नाभिक में स्थित अनावेशित कण न्यूट्रॉन की खोज 1932 में किसने की?","optionsHi":["जे. जे. थॉमसन","अर्नेस्ट रदरफोर्ड","ई. गोल्डस्टीन","जेम्स चैडविक"],"explanationHi":"चैडविक ने न्यूट्रॉन की खोज की। थॉमसन ने इलेक्ट्रॉन खोजा, गोल्डस्टीन ने केनाल किरणें खोजीं (जिनसे प्रोटॉन की खोज हुई), और रदरफोर्ड ने नाभिक की खोज की।"},
  {"id":"sci-chemistry-153","question":"Isotopes of an element have almost identical chemical properties because they have the same:","options":["Number and arrangement of electrons","Mass number and relative atomic mass","Number of neutrons in each nucleus","Density and melting point"],"answer":0,"explanation":"Chemical behaviour depends on electrons, and isotopes have the same atomic number and so the same electrons. They differ in neutrons and mass number, which affects physical properties like density.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"किसी तत्व के समस्थानिकों के रासायनिक गुण लगभग समान होते हैं क्योंकि उनके समान होते हैं:","optionsHi":["इलेक्ट्रॉनों की संख्या और व्यवस्था","द्रव्यमान संख्या और आपेक्षिक परमाणु द्रव्यमान","प्रत्येक नाभिक में न्यूट्रॉनों की संख्या","घनत्व और गलनांक"],"explanationHi":"रासायनिक व्यवहार इलेक्ट्रॉनों पर निर्भर करता है, और समस्थानिकों का परमाणु क्रमांक समान होता है, अतः इलेक्ट्रॉन भी समान होते हैं। वे न्यूट्रॉनों और द्रव्यमान संख्या में भिन्न होते हैं, जो घनत्व जैसे भौतिक गुणों को प्रभावित करता है।"},
  {"id":"sci-chemistry-154","question":"Match the radioactive isotope with its use: A. Carbon-14 B. Cobalt-60 C. Uranium-235 D. Iodine-131; 1. Fuel in nuclear power reactors 2. Treating goitre and thyroid disorders 3. Finding the age of ancient wood and fossils 4. Radiotherapy for cancer","options":["A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-1, B-4, C-3, D-2"],"answer":1,"explanation":"Carbon-14 is used in radiocarbon dating, cobalt-60 gives gamma rays for cancer treatment, uranium-235 undergoes fission in reactors and iodine-131 is taken up by the thyroid.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"रेडियोधर्मी समस्थानिक का उसके उपयोग से मिलान कीजिए: A. कार्बन-14 B. कोबाल्ट-60 C. यूरेनियम-235 D. आयोडीन-131; 1. नाभिकीय विद्युत रिएक्टरों में ईंधन 2. घेंघा और थायरॉइड विकारों का उपचार 3. प्राचीन लकड़ी और जीवाश्मों की आयु ज्ञात करना 4. कैंसर की विकिरण चिकित्सा","optionsHi":["A-3, B-4, C-2, D-1","A-3, B-4, C-1, D-2","A-4, B-3, C-1, D-2","A-1, B-4, C-3, D-2"],"explanationHi":"कार्बन-14 का उपयोग रेडियोकार्बन काल निर्धारण में होता है, कोबाल्ट-60 कैंसर के उपचार के लिए गामा किरणें देता है, यूरेनियम-235 रिएक्टरों में विखंडित होता है और आयोडीन-131 थायरॉइड द्वारा ग्रहण किया जाता है।"},
  {"id":"sci-chemistry-155","question":"When the equation Fe + H₂O → Fe₃O₄ + H₂ (steam passed over hot iron) is balanced with the smallest whole numbers, the coefficients of Fe, H₂O, Fe₃O₄ and H₂ are:","options":["3, 4, 1, 4","3, 2, 1, 2","3, 4, 1, 2","1, 4, 1, 4"],"answer":0,"explanation":"Three Fe atoms give one Fe₃O₄; its four O atoms need 4 H₂O, whose 8 H atoms form 4 H₂: 3Fe + 4H₂O → Fe₃O₄ + 4H₂.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"समीकरण Fe + H₂O → Fe₃O₄ + H₂ (गर्म लोहे पर भाप प्रवाहित करने पर) को सबसे छोटी पूर्ण संख्याओं से संतुलित करने पर Fe, H₂O, Fe₃O₄ और H₂ के गुणांक क्या होंगे?","optionsHi":["3, 4, 1, 4","3, 2, 1, 2","3, 4, 1, 2","1, 4, 1, 4"],"explanationHi":"तीन Fe परमाणुओं से एक Fe₃O₄ बनता है; उसके चार O परमाणुओं के लिए 4 H₂O चाहिए, जिनके 8 H परमाणु 4 H₂ बनाते हैं: 3Fe + 4H₂O → Fe₃O₄ + 4H₂।"},
  {"id":"sci-chemistry-156","question":"Which of these is a double displacement reaction in which an insoluble precipitate is formed?","options":["Zn + CuSO₄ → ZnSO₄ + Cu","CaCO₃ → CaO + CO₂","Na₂SO₄ + BaCl₂ → BaSO₄ + 2NaCl","Na₂CO₃ + 2HCl → 2NaCl + H₂O + CO₂"],"answer":2,"explanation":"The ions are exchanged and white insoluble barium sulphate precipitates. Na₂CO₃ + HCl is also an exchange reaction but gives a gas, not a precipitate; the others are single displacement and decomposition.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"इनमें से कौन-सी द्विविस्थापन अभिक्रिया है जिसमें अघुलनशील अवक्षेप बनता है?","optionsHi":["Zn + CuSO₄ → ZnSO₄ + Cu","CaCO₃ → CaO + CO₂","Na₂SO₄ + BaCl₂ → BaSO₄ + 2NaCl","Na₂CO₃ + 2HCl → 2NaCl + H₂O + CO₂"],"explanationHi":"आयनों का आदान-प्रदान होता है और सफेद अघुलनशील बेरियम सल्फेट अवक्षेपित होता है। Na₂CO₃ + HCl भी आदान-प्रदान की अभिक्रिया है, परंतु उसमें अवक्षेप नहीं, गैस बनती है; अन्य अभिक्रियाएँ एकल विस्थापन और अपघटन की हैं।"},
  {"id":"sci-chemistry-157","question":"When water is poured onto quicklime, the mixture becomes very hot. This reaction is best described as:","options":["Decomposition and endothermic","Combination and exothermic","Displacement and exothermic","Combination and endothermic"],"answer":1,"explanation":"CaO + H₂O → Ca(OH)₂: two substances combine into one and release a lot of heat, which is why the mixture hisses and gets hot.","difficulty":"hard","source":"RRB Group D · SSC MTS","questionHi":"बिना बुझे चूने पर जल डालने से मिश्रण बहुत गर्म हो जाता है। इस अभिक्रिया का सबसे उपयुक्त वर्णन है:","optionsHi":["अपघटन और ऊष्माशोषी","संयोजन और ऊष्माक्षेपी","विस्थापन और ऊष्माक्षेपी","संयोजन और ऊष्माशोषी"],"explanationHi":"CaO + H₂O → Ca(OH)₂: दो पदार्थ मिलकर एक बनाते हैं और बहुत अधिक ऊष्मा निकलती है, इसीलिए मिश्रण से फुफकार की ध्वनि आती है और वह गर्म हो जाता है।"},
  {"id":"sci-chemistry-158","question":"Two or three days after whitewashing, the walls develop a shiny finish. This is because:","options":["Calcium hydroxide absorbs CO₂ from air, forming calcium carbonate","Calcium hydroxide loses water and turns back into quicklime","Calcium hydroxide reacts with oxygen to form calcium peroxide","Water evaporates and leaves shining crystals of calcium hydroxide"],"answer":0,"explanation":"Slaked lime absorbs CO₂ from the air: Ca(OH)₂ + CO₂ → CaCO₃ + H₂O; the calcium carbonate layer gives the shine.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"दीवारों पर सफेदी (चूना पुताई) कराने के दो-तीन दिन बाद उन पर चमकदार परत आ जाती है। इसका कारण यह है कि:","optionsHi":["कैल्शियम हाइड्रॉक्साइड वायु से CO₂ सोखकर कैल्शियम कार्बोनेट बनाता है","कैल्शियम हाइड्रॉक्साइड जल खोकर पुनः बिना बुझे चूने में बदल जाता है","कैल्शियम हाइड्रॉक्साइड ऑक्सीजन से अभिक्रिया करके कैल्शियम परॉक्साइड बनाता है","जल वाष्पित होकर कैल्शियम हाइड्रॉक्साइड के चमकदार क्रिस्टल छोड़ देता है"],"explanationHi":"बुझा हुआ चूना वायु से CO₂ सोखता है: Ca(OH)₂ + CO₂ → CaCO₃ + H₂O; कैल्शियम कार्बोनेट की परत चमक देती है।"},
  {"id":"sci-chemistry-159","question":"Packets of potato chips are filled with nitrogen gas mainly to:","options":["Absorb moisture from the air and keep the chips crisp","Let nitrogen react with the oil to form a protective layer","Add a mild flavour and aroma to the chips","Keep out oxygen, which would make the fats and oils rancid"],"answer":3,"explanation":"Nitrogen is unreactive and displaces oxygen, preventing the oxidation (rancidity) of fats; it also cushions the chips. It does not react with the oil or absorb water.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"आलू के चिप्स के पैकेटों में नाइट्रोजन गैस मुख्यतः इसलिए भरी जाती है कि:","optionsHi":["वह वायु की नमी सोखकर चिप्स को कुरकुरा रखे","नाइट्रोजन तेल से अभिक्रिया करके सुरक्षात्मक परत बनाए","चिप्स को हल्का स्वाद और सुगंध दे","ऑक्सीजन को बाहर रखे, जो वसा और तेलों को खराब (विकृतगंधी) कर देती है"],"explanationHi":"नाइट्रोजन अक्रिय है और ऑक्सीजन को हटा देती है, जिससे वसा का ऑक्सीकरण (विकृतगंधिता) रुकता है; वह चिप्स को टूटने से भी बचाती है। वह न तेल से अभिक्रिया करती है और न जल सोखती है।"},
  {"id":"sci-chemistry-160","question":"In the reaction CuO + H₂ → Cu + H₂O (on heating), the substance that is oxidised and the substance that acts as the oxidising agent are, respectively:","options":["CuO and H₂","Cu and H₂O","H₂ and CuO","H₂ and Cu"],"answer":2,"explanation":"Hydrogen gains oxygen (is oxidised), while copper oxide loses oxygen (is reduced) and so acts as the oxidising agent; H₂ is the reducing agent.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"अभिक्रिया CuO + H₂ → Cu + H₂O (गर्म करने पर) में ऑक्सीकृत होने वाला पदार्थ और ऑक्सीकारक के रूप में कार्य करने वाला पदार्थ क्रमशः हैं:","optionsHi":["CuO और H₂","Cu और H₂O","H₂ और CuO","H₂ और Cu"],"explanationHi":"हाइड्रोजन ऑक्सीजन ग्रहण करती है (ऑक्सीकृत होती है), जबकि कॉपर ऑक्साइड ऑक्सीजन खोता है (अपचयित होता है) और इसलिए ऑक्सीकारक का कार्य करता है; H₂ अपचायक है।"},
  {"id":"sci-chemistry-161","question":"Silver ornaments and utensils gradually turn black when left exposed to air. The black coating is mainly:","options":["Silver oxide","Silver sulphide","Silver nitrate","Silver carbonate"],"answer":1,"explanation":"Silver reacts with traces of sulphur compounds (such as hydrogen sulphide) in the air to form black silver sulphide; silver hardly reacts with oxygen at room temperature.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"चाँदी के आभूषण और बर्तन वायु में खुले रखने पर धीरे-धीरे काले पड़ जाते हैं। यह काली परत मुख्यतः क्या है?","optionsHi":["सिल्वर ऑक्साइड","सिल्वर सल्फाइड","सिल्वर नाइट्रेट","सिल्वर कार्बोनेट"],"explanationHi":"चाँदी वायु में उपस्थित सल्फर यौगिकों (जैसे हाइड्रोजन सल्फाइड) की सूक्ष्म मात्रा से अभिक्रिया करके काला सिल्वर सल्फाइड बनाती है; कमरे के तापमान पर चाँदी ऑक्सीजन से लगभग अभिक्रिया नहीं करती।"},
  {"id":"sci-chemistry-162","question":"A curry (turmeric) stain on a white shirt turns reddish-brown when the shirt is washed with soap, and turns yellow again after rinsing with plenty of water. This shows that:","options":["Soap is acidic, and turmeric is an indicator that turns red in acids","Soap is basic, and turmeric is an indicator that turns red in bases","Soap bleaches the turmeric and turns it into a new red dye","Water reacts chemically with turmeric to make it yellow again"],"answer":1,"explanation":"Turmeric is a natural indicator: yellow in neutral or acidic medium and reddish-brown in basic medium. Soap solution is basic; rinsing removes the soap and the colour returns.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"सफेद कमीज़ पर लगा हल्दी (करी) का दाग साबुन से धोने पर लालिमा लिए भूरा हो जाता है, और बहुत जल से खँगालने पर फिर पीला हो जाता है। इससे पता चलता है कि:","optionsHi":["साबुन अम्लीय है, और हल्दी ऐसा सूचक है जो अम्लों में लाल हो जाता है","साबुन क्षारीय है, और हल्दी ऐसा सूचक है जो क्षारों में लाल हो जाता है","साबुन हल्दी को विरंजित कर एक नया लाल रंजक बना देता है","जल हल्दी से रासायनिक अभिक्रिया करके उसे पुनः पीला बना देता है"],"explanationHi":"हल्दी एक प्राकृतिक सूचक है: उदासीन या अम्लीय माध्यम में पीली और क्षारीय माध्यम में लालिमा लिए भूरी। साबुन का विलयन क्षारीय होता है; खँगालने से साबुन हट जाता है और रंग लौट आता है।"},
  {"id":"sci-chemistry-163","question":"An ant bite causes pain and a burning sensation. Rubbing it with a paste of baking soda gives relief because:","options":["Basic baking soda neutralises the formic acid from the ant","Baking soda neutralises the acetic acid injected by the ant","Baking soda, a strong alkali, dissolves the ant's venom","Baking soda, a mild acid, neutralises the alkaline venom"],"answer":0,"explanation":"Ant stings contain methanoic (formic) acid, not acetic acid; sodium hydrogencarbonate is a mild (weak) base that neutralises it.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"चींटी के काटने से पीड़ा और जलन होती है। उस पर बेकिंग सोडे का लेप लगाने से राहत मिलती है क्योंकि:","optionsHi":["क्षारीय बेकिंग सोडा चींटी के फॉर्मिक अम्ल को उदासीन कर देता है","बेकिंग सोडा चींटी द्वारा डाले गए ऐसीटिक अम्ल को उदासीन कर देता है","बेकिंग सोडा, एक प्रबल क्षार, चींटी के विष को घोल देता है","बेकिंग सोडा, एक मृदु अम्ल, क्षारीय विष को उदासीन कर देता है"],"explanationHi":"चींटी के डंक में मेथेनॉइक (फॉर्मिक) अम्ल होता है, ऐसीटिक अम्ल नहीं; सोडियम हाइड्रोजनकार्बोनेट एक मृदु (दुर्बल) क्षार है जो उसे उदासीन कर देता है।"},
  {"id":"sci-chemistry-164","question":"While diluting concentrated sulphuric acid, we must add the acid slowly to water with stirring, never water to the acid, because:","options":["Water does not mix with the acid at all if it is added the other way round","The reaction then becomes endothermic and the mixture freezes","Adding water to the acid releases large amounts of poisonous hydrogen gas","Mixing is highly exothermic; a little water on much acid boils and splashes"],"answer":3,"explanation":"Dissolving the acid releases a great deal of heat; when water is added to the acid, the small amount of water boils at once and throws out acid. Adding acid to a large volume of water spreads the heat.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"सांद्र सल्फ्यूरिक अम्ल को तनु करते समय हमें अम्ल को जल में धीरे-धीरे हिलाते हुए मिलाना चाहिए, जल को अम्ल में कभी नहीं, क्योंकि:","optionsHi":["उलटे क्रम में डालने पर जल अम्ल के साथ बिल्कुल नहीं मिलता","तब अभिक्रिया ऊष्माशोषी हो जाती है और मिश्रण जम जाता है","अम्ल में जल डालने से बहुत अधिक मात्रा में विषैली हाइड्रोजन गैस निकलती है","मिश्रण बहुत अधिक ऊष्माक्षेपी है; अधिक अम्ल पर थोड़ा जल उबलकर छलक जाता है"],"explanationHi":"अम्ल के घुलने पर बहुत अधिक ऊष्मा निकलती है; अम्ल में जल डालने पर थोड़ा-सा जल तुरंत उबल जाता है और अम्ल को उछाल देता है। जल की बड़ी मात्रा में अम्ल डालने से ऊष्मा फैल जाती है।"},
  {"id":"sci-chemistry-165","question":"Dry hydrogen chloride gas does not change the colour of dry blue litmus paper, but it turns moist blue litmus red. The reason is that:","options":["Dry HCl gas behaves as a base until it touches water","Litmus paper works only when it is wet, whatever the substance","HCl forms H⁺ (H₃O⁺) ions only when dissolved in water","HCl gas reacts with the dye only in the presence of light"],"answer":2,"explanation":"Acidic behaviour comes from H⁺ ions, which HCl forms only on dissolving in water. In the dry state it stays as covalent molecules, so it cannot show acidic properties.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"शुष्क हाइड्रोजन क्लोराइड गैस शुष्क नीले लिटमस पत्र का रंग नहीं बदलती, परंतु नम नीले लिटमस को लाल कर देती है। इसका कारण यह है कि:","optionsHi":["शुष्क HCl गैस जल के संपर्क में आने तक क्षार की तरह व्यवहार करती है","लिटमस पत्र केवल गीला होने पर ही कार्य करता है, चाहे कोई भी पदार्थ हो","HCl केवल जल में घुलने पर H⁺ (H₃O⁺) आयन बनाता है","HCl गैस केवल प्रकाश की उपस्थिति में रंजक से अभिक्रिया करती है"],"explanationHi":"अम्लीय व्यवहार H⁺ आयनों से आता है, जिन्हें HCl केवल जल में घुलने पर बनाता है। शुष्क अवस्था में वह सहसंयोजी अणुओं के रूप में रहता है, इसलिए अम्लीय गुण नहीं दर्शा सकता।"},
  {"id":"sci-chemistry-166","question":"A large mass of natural gas can be filled into a small steel cylinder as CNG, but the same cannot be done with water. The main reason is that:","options":["Gas particles are much smaller than the molecules of water","Gas particles are far apart, so pressure can push them closer","Gas particles lose part of their mass when they are compressed","Gas particles have very strong forces of attraction between them"],"answer":1,"explanation":"In a gas the particles are far apart, so pressure can push them much closer; in a liquid they are already almost touching, so it is nearly incompressible.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"प्राकृतिक गैस की बड़ी मात्रा को CNG के रूप में एक छोटे इस्पात सिलिंडर में भरा जा सकता है, परंतु जल के साथ ऐसा नहीं किया जा सकता। इसका मुख्य कारण है:","optionsHi":["गैस के कण जल के अणुओं से बहुत छोटे होते हैं","गैस के कण एक-दूसरे से बहुत दूर होते हैं, इसलिए दाब उन्हें पास ला सकता है","संपीडित करने पर गैस के कण अपने द्रव्यमान का कुछ भाग खो देते हैं","गैस के कणों के बीच अत्यंत प्रबल आकर्षण बल होते हैं"],"explanationHi":"गैस में कण दूर-दूर होते हैं, इसलिए दाब उन्हें बहुत पास ला सकता है; द्रव में वे पहले से लगभग सटे होते हैं, इसलिए द्रव लगभग असंपीड्य होता है।"},
  {"id":"sci-chemistry-167","question":"Which of these pairs has the same number of electrons?","options":["A sodium atom and a neon atom","A chloride ion and a neon atom","A potassium ion and a sodium ion","A sodium ion and a neon atom"],"answer":3,"explanation":"Na⁺ has 11 − 1 = 10 electrons, the same as neon. A sodium atom has 11, and Cl⁻ and K⁺ each have 18 electrons.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"इनमें से किस युग्म में इलेक्ट्रॉनों की संख्या समान है?","optionsHi":["सोडियम परमाणु और नियॉन परमाणु","क्लोराइड आयन और नियॉन परमाणु","पोटैशियम आयन और सोडियम आयन","सोडियम आयन और नियॉन परमाणु"],"explanationHi":"Na⁺ में 11 − 1 = 10 इलेक्ट्रॉन होते हैं, जो नियॉन के बराबर हैं। सोडियम परमाणु में 11 होते हैं, और Cl⁻ तथा K⁺ में प्रत्येक के 18 इलेक्ट्रॉन होते हैं।"},
  {"id":"sci-chemistry-168","question":"Hydrochloric acid and acetic acid solutions of the same molar concentration are compared. The hydrochloric acid has a much lower pH because:","options":["It ionises almost fully in water, giving far more H⁺ ions","Its molecules contain more hydrogen atoms than acetic acid","It is a gas, so it dissolves in water faster","Acetic acid is really a base that neutralises itself"],"answer":0,"explanation":"HCl is a strong acid that ionises fully; acetic acid is weak and ionises only slightly. The number of H atoms in the formula is irrelevant: CH₃COOH has four H atoms but only one can ionise.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"समान मोलर सांद्रता वाले हाइड्रोक्लोरिक अम्ल और एसीटिक अम्ल के विलयनों की तुलना की जाती है। हाइड्रोक्लोरिक अम्ल का pH बहुत कम होता है क्योंकि:","optionsHi":["वह जल में लगभग पूर्णतः आयनित होता है और कहीं अधिक H⁺ आयन देता है","उसके अणुओं में एसीटिक अम्ल से अधिक हाइड्रोजन परमाणु होते हैं","वह गैस है, इसलिए जल में अधिक तेजी से घुलता है","एसीटिक अम्ल वास्तव में एक क्षार है जो स्वयं को उदासीन कर लेता है"],"explanationHi":"HCl प्रबल अम्ल है जो पूर्णतः आयनित होता है; एसीटिक अम्ल दुर्बल है और केवल थोड़ा आयनित होता है। सूत्र में H परमाणुओं की संख्या अप्रासंगिक है: CH₃COOH में चार H परमाणु हैं पर केवल एक ही आयनित हो सकता है।"},
  {"id":"sci-chemistry-169","question":"10 mL of a hydrochloric acid solution of pH 2 is diluted with water to 1 litre. The pH of the diluted solution is about:","options":["2, since dilution does not change pH","3","4","0"],"answer":2,"explanation":"Diluting 100 times reduces [H⁺] from 10⁻² M to 10⁻⁴ M, so the pH rises to 4. Each tenfold dilution of a strong acid raises the pH by one unit.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"pH 2 वाले हाइड्रोक्लोरिक अम्ल विलयन के 10 mL को जल मिलाकर 1 लीटर तक तनु किया जाता है। तनु विलयन का pH लगभग कितना होगा?","optionsHi":["2, क्योंकि तनुकरण से pH नहीं बदलता","3","4","0"],"explanationHi":"100 गुना तनु करने पर [H⁺] 10⁻² M से घटकर 10⁻⁴ M हो जाता है, इसलिए pH बढ़कर 4 हो जाता है। प्रबल अम्ल को प्रत्येक दस गुना तनु करने पर pH एक इकाई बढ़ता है।"},
  {"id":"sci-chemistry-170","question":"An aqueous solution of which salt will turn red litmus blue?","options":["Ammonium chloride","Sodium chloride","Copper sulphate","Sodium carbonate"],"answer":3,"explanation":"Sodium carbonate is the salt of a strong base (NaOH) and a weak acid (H₂CO₃), so its solution is basic. NaCl is neutral; ammonium chloride and copper sulphate solutions are acidic.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"किस लवण का जलीय विलयन लाल लिटमस को नीला कर देगा?","optionsHi":["अमोनियम क्लोराइड","सोडियम क्लोराइड","कॉपर सल्फेट","सोडियम कार्बोनेट"],"explanationHi":"सोडियम कार्बोनेट प्रबल क्षार (NaOH) और दुर्बल अम्ल (H₂CO₃) का लवण है, इसलिए उसका विलयन क्षारीय होता है। NaCl उदासीन है; अमोनियम क्लोराइड और कॉपर सल्फेट के विलयन अम्लीय होते हैं।"},
  {"id":"sci-chemistry-171","question":"Plaster of Paris must be stored in a moisture-proof container because:","options":["It reacts with moisture and sets into hard gypsum","It absorbs moisture and slowly turns into quicklime","It catches fire when it comes in contact with moist air","Moisture slowly turns it into washing soda crystals"],"answer":0,"explanation":"CaSO₄·½H₂O combines with water to form gypsum, CaSO₄·2H₂O, which is hard; that is why it is used for plasters for fractured bones but spoils in humid storage.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"प्लास्टर ऑफ पेरिस को नमी-रोधी पात्र में रखना चाहिए क्योंकि:","optionsHi":["वह नमी से अभिक्रिया करके कठोर जिप्सम बनकर जम जाता है","वह नमी सोखकर धीरे-धीरे बिना बुझे चूने में बदल जाता है","नम वायु के संपर्क में आने पर वह आग पकड़ लेता है","नमी उसे धीरे-धीरे धावन सोडा के क्रिस्टलों में बदल देती है"],"explanationHi":"CaSO₄·½H₂O जल से संयोग करके जिप्सम, CaSO₄·2H₂O, बनाता है, जो कठोर होता है; इसीलिए यह टूटी हड्डियों के प्लास्टर में काम आता है, पर नम भंडारण में खराब हो जाता है।"},
  {"id":"sci-chemistry-172","question":"Bleaching powder is added to water in overhead tanks and wells mainly to:","options":["Remove the hardness of water","Kill germs by releasing chlorine","Remove the colour and smell of iron salts","Make the water slightly alkaline for drinking"],"answer":1,"explanation":"Bleaching powder releases chlorine, a strong oxidising agent that kills disease-causing microbes; it is a disinfectant, not a water softener.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"ऊपरी टंकियों और कुओं के जल में विरंजक चूर्ण मुख्यतः किसलिए मिलाया जाता है?","optionsHi":["जल की कठोरता दूर करने के लिए","क्लोरीन मुक्त करके रोगाणुओं को मारने के लिए","आयरन लवणों का रंग और गंध हटाने के लिए","पीने के लिए जल को थोड़ा क्षारीय बनाने के लिए"],"explanationHi":"विरंजक चूर्ण क्लोरीन मुक्त करता है, जो प्रबल ऑक्सीकारक है और रोगकारक सूक्ष्मजीवों को मारता है; वह कीटाणुनाशक है, जल को मृदु बनाने वाला नहीं।"},
  {"id":"sci-chemistry-173","question":"Baking powder contains a mild edible acid such as tartaric acid along with baking soda. The acid is added so that:","options":["The bread becomes harder and stays fresh for many more days","It sweetens the cake and gives it a golden colour","It reacts with the soda to give CO₂, leaving no bitter carbonate","It stops carbon dioxide from being released until the cake cools"],"answer":2,"explanation":"Heating baking soda alone gives CO₂ but leaves sodium carbonate, which tastes bitter. With the acid, the CO₂ is released and the bitter carbonate is not left behind.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"बेकिंग पाउडर में बेकिंग सोडे के साथ टार्टरिक अम्ल जैसा मृदु खाद्य अम्ल होता है। अम्ल इसलिए मिलाया जाता है कि:","optionsHi":["ब्रेड कठोर हो जाए और कई दिनों तक ताज़ी रहे","वह केक को मीठा बनाए और उसे सुनहरा रंग दे","वह सोडे से अभिक्रिया करके CO₂ दे और कड़वा कार्बोनेट न बचे","वह केक के ठंडा होने तक कार्बन डाइऑक्साइड को निकलने से रोके"],"explanationHi":"अकेले बेकिंग सोडा गर्म करने पर CO₂ देता है पर सोडियम कार्बोनेट छोड़ता है, जो कड़वा लगता है। अम्ल के साथ CO₂ मुक्त हो जाती है और कड़वा कार्बोनेट पीछे नहीं रहता।"},
  {"id":"sci-chemistry-174","question":"Which of these metals does NOT release hydrogen gas when added to dilute hydrochloric acid?","options":["Zinc","Iron","Copper","Magnesium"],"answer":2,"explanation":"Copper is below hydrogen in the reactivity series, so it cannot displace hydrogen from dilute acids. Zn, Fe and Mg are above hydrogen.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"इनमें से कौन-सी धातु तनु हाइड्रोक्लोरिक अम्ल में डालने पर हाइड्रोजन गैस मुक्त नहीं करती?","optionsHi":["जिंक","लोहा","ताँबा","मैग्नीशियम"],"explanationHi":"ताँबा क्रियाशीलता श्रेणी में हाइड्रोजन से नीचे है, इसलिए वह तनु अम्लों से हाइड्रोजन को विस्थापित नहीं कर सकता। Zn, Fe और Mg हाइड्रोजन से ऊपर हैं।"},
  {"id":"sci-chemistry-175","question":"A clean iron nail is dipped in blue copper sulphate solution for about 20 minutes. What is observed?","options":["A brown coat forms on the nail and the solution turns pale green","A silvery coating forms on the nail and the solution stays blue","The nail dissolves completely and the solution turns colourless","Nothing happens, because iron is less reactive than copper is"],"answer":0,"explanation":"Iron displaces copper: Fe + CuSO₄ → FeSO₄ + Cu. Reddish-brown copper deposits on the nail and pale green iron sulphate replaces the blue copper sulphate.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक साफ लोहे की कील को नीले कॉपर सल्फेट विलयन में लगभग 20 मिनट डुबोया जाता है। क्या देखा जाएगा?","optionsHi":["कील पर भूरी परत जम जाती है और विलयन हल्का हरा हो जाता है","कील पर चमकीली चाँदी जैसी परत बन जाती है और विलयन नीला ही रहता है","कील पूरी तरह घुल जाती है और विलयन रंगहीन हो जाता है","कुछ नहीं होता, क्योंकि लोहा ताँबे से कम क्रियाशील है"],"explanationHi":"लोहा ताँबे को विस्थापित करता है: Fe + CuSO₄ → FeSO₄ + Cu। कील पर लालिमा लिए भूरा ताँबा जम जाता है और हल्का हरा आयरन सल्फेट नीले कॉपर सल्फेट का स्थान ले लेता है।"},
  {"id":"sci-chemistry-176","question":"Which of these reactions will actually take place? I. Copper strip + silver nitrate solution II. Silver strip + copper sulphate solution III. Iron strip + zinc sulphate solution IV. Zinc strip + iron sulphate solution","options":["I and III only","II and IV only","I and IV only","III and IV only"],"answer":2,"explanation":"A metal displaces only a less reactive metal from its salt. Reactivity: Zn > Fe > Cu > Ag, so Cu displaces Ag and Zn displaces Fe, but Ag cannot displace Cu and Fe cannot displace Zn.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"इनमें से कौन-सी अभिक्रियाएँ वास्तव में होंगी? I. ताँबे की पट्टी + सिल्वर नाइट्रेट विलयन II. चाँदी की पट्टी + कॉपर सल्फेट विलयन III. लोहे की पट्टी + जिंक सल्फेट विलयन IV. जस्ते की पट्टी + आयरन सल्फेट विलयन","optionsHi":["केवल I और III","केवल II और IV","केवल I और IV","केवल III और IV"],"explanationHi":"कोई धातु केवल कम क्रियाशील धातु को उसके लवण से विस्थापित करती है। क्रियाशीलता: Zn > Fe > Cu > Ag, इसलिए Cu, Ag को और Zn, Fe को विस्थापित करता है, परंतु Ag, Cu को और Fe, Zn को विस्थापित नहीं कर सकता।"},
  {"id":"sci-chemistry-177","question":"Gold, which does not dissolve in any single common acid, dissolves in aqua regia. Aqua regia is a freshly prepared mixture of:","options":["Concentrated nitric acid and concentrated sulphuric acid in the ratio 3 : 1","Concentrated hydrochloric acid and concentrated sulphuric acid in the ratio 1 : 3","Concentrated hydrochloric acid and concentrated nitric acid in the ratio 1 : 3","Concentrated hydrochloric acid and concentrated nitric acid in the ratio 3 : 1"],"answer":3,"explanation":"Aqua regia (‘royal water’) is 3 parts concentrated HCl to 1 part concentrated HNO₃. The reversed 1 : 3 ratio is a common trap.","difficulty":"hard","source":"RRB NTPC · SSC CGL","questionHi":"सोना, जो किसी एक सामान्य अम्ल में नहीं घुलता, अम्लराज (एक्वा रेजिया) में घुल जाता है। अम्लराज किसका ताज़ा बनाया गया मिश्रण है?","optionsHi":["सांद्र नाइट्रिक अम्ल और सांद्र सल्फ्यूरिक अम्ल का 3 : 1 अनुपात","सांद्र हाइड्रोक्लोरिक अम्ल और सांद्र सल्फ्यूरिक अम्ल का 1 : 3 अनुपात","सांद्र हाइड्रोक्लोरिक अम्ल और सांद्र नाइट्रिक अम्ल का 1 : 3 अनुपात","सांद्र हाइड्रोक्लोरिक अम्ल और सांद्र नाइट्रिक अम्ल का 3 : 1 अनुपात"],"explanationHi":"अम्लराज (‘रॉयल वाटर’) में सांद्र HCl के 3 भाग और सांद्र HNO₃ का 1 भाग होता है। उलटा 1 : 3 अनुपात सामान्य भ्रम है।"},
  {"id":"sci-chemistry-178","question":"Solid sodium chloride does not conduct electricity, but molten sodium chloride does. This is because:","options":["Solid NaCl has no ions at all; ions form only when it melts","Its ions are fixed in the solid but free to move in the melt","Molten NaCl contains free electrons that flow as in a metal","Heat itself carries the electric current through the melt"],"answer":1,"explanation":"Ionic solids already contain ions, but they are locked in the crystal; on melting or dissolving the ions become mobile and can carry current.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"ठोस सोडियम क्लोराइड विद्युत का चालन नहीं करता, परंतु पिघला हुआ सोडियम क्लोराइड करता है। इसका कारण यह है कि:","optionsHi":["ठोस NaCl में आयन बिल्कुल नहीं होते; आयन केवल पिघलने पर बनते हैं","उसके आयन ठोस में स्थिर होते हैं पर पिघले हुए रूप में गति करने के लिए मुक्त होते हैं","पिघले NaCl में मुक्त इलेक्ट्रॉन होते हैं जो धातु की तरह प्रवाहित होते हैं","ऊष्मा स्वयं पिघले पदार्थ में विद्युत धारा का वहन करती है"],"explanationHi":"आयनिक ठोसों में आयन पहले से होते हैं, पर वे क्रिस्टल में जकड़े रहते हैं; पिघलने या घुलने पर आयन गतिशील हो जाते हैं और धारा का वहन कर सकते हैं।"},
  {"id":"sci-chemistry-179","question":"Which metal would melt if a piece of it were held in the palm of your hand?","options":["Gallium","Sodium","Aluminium","Lead"],"answer":0,"explanation":"Gallium melts at about 30 °C, below body temperature. Sodium melts near 98 °C, lead at about 327 °C and aluminium at about 660 °C.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"यदि किसी धातु का टुकड़ा हथेली पर रखा जाए तो कौन-सी धातु पिघल जाएगी?","optionsHi":["गैलियम","सोडियम","ऐलुमिनियम","सीसा"],"explanationHi":"गैलियम लगभग 30 °C पर पिघलता है, जो शरीर के तापमान से कम है। सोडियम लगभग 98 °C पर, सीसा लगभग 327 °C पर और ऐलुमिनियम लगभग 660 °C पर पिघलता है।"},
  {"id":"sci-chemistry-180","question":"White phosphorus is stored under water, whereas sodium is stored under kerosene. The reason for storing phosphorus under water is that:","options":["Phosphorus reacts violently with kerosene and explodes","Phosphorus dissolves in kerosene but not in water","Phosphorus catches fire on its own in air at about 30 °C","Phosphorus needs water around it to remain a solid"],"answer":2,"explanation":"White phosphorus ignites spontaneously in air at about 30 °C, so it is kept away from air under water, with which it does not react. Sodium reacts with water, so it is kept under kerosene instead.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"श्वेत फॉस्फोरस को जल के नीचे रखा जाता है, जबकि सोडियम को मिट्टी के तेल में। फॉस्फोरस को जल के नीचे रखने का कारण यह है कि:","optionsHi":["फॉस्फोरस मिट्टी के तेल से प्रचंड अभिक्रिया करके विस्फोट कर देता है","फॉस्फोरस मिट्टी के तेल में घुलता है पर जल में नहीं","फॉस्फोरस लगभग 30 °C पर वायु में अपने आप आग पकड़ लेता है","ठोस बने रहने के लिए फॉस्फोरस को अपने चारों ओर जल की आवश्यकता होती है"],"explanationHi":"श्वेत फॉस्फोरस लगभग 30 °C पर वायु में स्वतः जल उठता है, इसलिए उसे जल के नीचे वायु से दूर रखा जाता है, जिससे वह अभिक्रिया नहीं करता। सोडियम जल से अभिक्रिया करता है, इसलिए उसे मिट्टी के तेल में रखा जाता है।"},
  {"id":"sci-chemistry-181","question":"Metals of medium reactivity, such as zinc, are usually extracted from their oxides by:","options":["Electrolysis of the molten ore using graphite electrodes","Heating the ore alone in air until it decomposes","Heating the oxide with a reducing agent such as coke","Displacement from its salt solution with copper"],"answer":2,"explanation":"ZnO + C → Zn + CO. Electrolysis is needed for very reactive metals like Na and Al, heating alone works only for metals low in the series like mercury, and copper cannot displace zinc.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"जिंक जैसी मध्यम क्रियाशीलता वाली धातुओं का निष्कर्षण सामान्यतः उनके ऑक्साइडों से किस विधि द्वारा किया जाता है?","optionsHi":["ग्रेफाइट इलेक्ट्रोडों से पिघले अयस्क का विद्युत अपघटन","अयस्क को केवल वायु में उसके विघटित होने तक गर्म करना","ऑक्साइड को कोक जैसे अपचायक के साथ गर्म करना","ताँबे द्वारा उसके लवण विलयन से विस्थापन"],"explanationHi":"ZnO + C → Zn + CO। Na और Al जैसी अति क्रियाशील धातुओं के लिए विद्युत अपघटन चाहिए, केवल गर्म करना श्रेणी में नीचे की धातुओं, जैसे पारे, के लिए ही काम करता है, और ताँबा जस्ते को विस्थापित नहीं कर सकता।"},
  {"id":"sci-chemistry-182","question":"Mercury can be obtained from its ore cinnabar (HgS) simply by heating it in air, while sodium cannot be obtained by heating its compounds. The reason is that mercury:","options":["Has a very low melting point and so simply boils off the ore","Is low in reactivity, so its compounds decompose easily on heating","Is a liquid that separates from the ore by gravity alone","Forms an alloy with sulphur that melts and runs off easily"],"answer":1,"explanation":"Cinnabar is roasted to HgO, which on further heating decomposes into mercury. Highly reactive metals form very stable compounds that need electrolysis.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"पारा अपने अयस्क सिनेबार (HgS) को वायु में केवल गर्म करने से प्राप्त हो जाता है, जबकि सोडियम को उसके यौगिकों को गर्म करके प्राप्त नहीं किया जा सकता। इसका कारण यह है कि पारा:","optionsHi":["का गलनांक बहुत कम है, इसलिए वह अयस्क से उबलकर निकल जाता है","कम क्रियाशील है, इसलिए उसके यौगिक गर्म करने पर आसानी से विघटित हो जाते हैं","द्रव है जो केवल गुरुत्व से अयस्क से अलग हो जाता है","सल्फर के साथ ऐसी मिश्रधातु बनाता है जो पिघलकर आसानी से बह जाती है"],"explanationHi":"सिनेबार को भर्जित करने पर HgO बनता है, जो और गर्म करने पर विघटित होकर पारा देता है। अति क्रियाशील धातुओं के यौगिक बहुत स्थायी होते हैं, जिनके लिए विद्युत अपघटन चाहिए।"},
  {"id":"sci-chemistry-183","question":"Solder, used for joining electrical wires, is an alloy chosen for its low melting point. It is made of:","options":["Copper and zinc","Copper and tin","Iron and carbon","Lead and tin"],"answer":3,"explanation":"Solder (lead and tin) melts at a lower temperature than either pure metal, so it can be melted to join wires without harming them. Copper–zinc is brass and copper–tin is bronze.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"बिजली के तारों को जोड़ने में प्रयुक्त सोल्डर कम गलनांक के लिए चुनी गई मिश्रधातु है। यह किससे बनता है?","optionsHi":["ताँबा और जस्ता","ताँबा और टिन","लोहा और कार्बन","सीसा और टिन"],"explanationHi":"सोल्डर (सीसा और टिन) किसी भी शुद्ध धातु से कम तापमान पर पिघलता है, इसलिए उसे तारों को बिना हानि पहुँचाए जोड़ने के लिए पिघलाया जा सकता है। ताँबा–जस्ता पीतल है और ताँबा–टिन काँसा है।"},
  {"id":"sci-chemistry-184","question":"Stainless steel resists rusting because iron in it is alloyed with:","options":["Chromium and nickel","Copper and zinc","Tin and lead","Aluminium and magnesium"],"answer":0,"explanation":"Chromium forms a thin protective oxide layer on stainless steel, and nickel adds to its resistance to corrosion.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"स्टेनलेस स्टील में जंग नहीं लगती क्योंकि उसमें लोहे को किसके साथ मिश्रित किया जाता है?","optionsHi":["क्रोमियम और निकल","ताँबा और जस्ता","टिन और सीसा","ऐलुमिनियम और मैग्नीशियम"],"explanationHi":"क्रोमियम स्टेनलेस स्टील पर ऑक्साइड की पतली सुरक्षात्मक परत बनाता है, और निकल उसकी संक्षारण-प्रतिरोधकता को और बढ़ाता है।"},
  {"id":"sci-chemistry-185","question":"Carbon forms millions of compounds, far more than any other element. The two properties mainly responsible are:","options":["High electronegativity and strong metallic character","Catenation (forming long chains and rings) and a valency of four","The ability to form ionic bonds and to lose four electrons easily","Its presence in all living things and its high melting point"],"answer":1,"explanation":"Carbon bonds strongly to itself, forming chains, branches and rings, and its tetravalency lets it bond to many other atoms. Carbon forms covalent, not ionic, compounds.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"कार्बन किसी भी अन्य तत्व से कहीं अधिक, लाखों यौगिक बनाता है। इसके लिए मुख्यतः उत्तरदायी दो गुण हैं:","optionsHi":["उच्च विद्युत ऋणात्मकता और प्रबल धात्विक गुण","श्रृंखलन (लंबी श्रृंखलाएँ और वलय बनाना) और चार की संयोजकता","आयनिक बंध बनाने की क्षमता और चार इलेक्ट्रॉन आसानी से त्यागना","सभी जीवित वस्तुओं में उसकी उपस्थिति और उच्च गलनांक"],"explanationHi":"कार्बन स्वयं से प्रबलता से जुड़कर श्रृंखलाएँ, शाखाएँ और वलय बनाता है, और उसकी चतुःसंयोजकता उसे अनेक अन्य परमाणुओं से जुड़ने देती है। कार्बन सहसंयोजी यौगिक बनाता है, आयनिक नहीं।"},
  {"id":"sci-chemistry-186","question":"How many covalent bonds are present in a molecule of propane, C₃H₈?","options":["8","11","10","20"],"answer":2,"explanation":"Propane has 2 C–C bonds and 8 C–H bonds, a total of 10; in general an alkane CₙH₂ₙ₊₂ has 3n + 1 bonds. 8 counts only the C–H bonds, 11 wrongly gives three carbons three C–C links, and 20 is the number of bonding electrons, not bonds.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"प्रोपेन, C₃H₈, के एक अणु में कितने सहसंयोजी बंध होते हैं?","optionsHi":["8","11","10","20"],"explanationHi":"प्रोपेन में 2 C–C बंध और 8 C–H बंध होते हैं, कुल 10; सामान्यतः ऐल्केन CₙH₂ₙ₊₂ में 3n + 1 बंध होते हैं। 8 केवल C–H बंधों की गिनती है, 11 तीन कार्बनों में तीन C–C कड़ियाँ मान लेने की गलती है, और 20 बंधकारी इलेक्ट्रॉनों की संख्या है, बंधों की नहीं।"},
  {"id":"sci-chemistry-187","question":"Which of these hydrocarbons is unsaturated?","options":["C₂H₆","C₃H₈","C₄H₁₀","C₂H₄"],"answer":3,"explanation":"C₂H₄ (ethene) fits CₙH₂ₙ and has a carbon–carbon double bond. The others fit CₙH₂ₙ₊₂ and are saturated alkanes.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"इनमें से कौन-सा हाइड्रोकार्बन असंतृप्त है?","optionsHi":["C₂H₆","C₃H₈","C₄H₁₀","C₂H₄"],"explanationHi":"C₂H₄ (एथीन) CₙH₂ₙ सूत्र के अनुरूप है और उसमें कार्बन–कार्बन द्विबंध होता है। अन्य CₙH₂ₙ₊₂ के अनुरूप हैं और संतृप्त ऐल्केन हैं।"},
  {"id":"sci-chemistry-188","question":"The flame of a household gas stove turns yellow and the bottoms of cooking vessels get blackened. This shows that:","options":["The fuel is burning incompletely for lack of air","The gas has become richer in hydrogen, which burns yellow","The burner is supplying too much oxygen to the flame","The fuel is burning completely and giving out more heat"],"answer":0,"explanation":"With too little air, the fuel burns incompletely and unburnt carbon forms soot and a yellow, luminous flame; cleaning the air holes restores the blue flame.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"घरेलू गैस चूल्हे की लौ पीली हो जाती है और खाना पकाने के बर्तनों की तली काली पड़ जाती है। इससे पता चलता है कि:","optionsHi":["वायु की कमी से ईंधन अपूर्ण रूप से जल रहा है","गैस में हाइड्रोजन अधिक हो गई है, जो पीली लौ से जलती है","बर्नर लौ को बहुत अधिक ऑक्सीजन दे रहा है","ईंधन पूर्णतः जल रहा है और अधिक ऊष्मा दे रहा है"],"explanationHi":"वायु बहुत कम होने पर ईंधन अपूर्ण रूप से जलता है और बिना जला कार्बन कालिख तथा पीली, दीप्तिमान लौ बनाता है; वायु के छिद्र साफ करने से नीली लौ लौट आती है।"},
  {"id":"sci-chemistry-189","question":"Vegetable oils are converted into vanaspati ghee by adding hydrogen to them in the presence of a catalyst. The catalyst commonly used is:","options":["Iron","Platinum","Vanadium pentoxide","Nickel"],"answer":3,"explanation":"Hydrogenation of unsaturated oils uses finely divided nickel. Iron catalyses the Haber process and vanadium pentoxide the contact process for sulphuric acid.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"वनस्पति तेलों में उत्प्रेरक की उपस्थिति में हाइड्रोजन मिलाकर उन्हें वनस्पति घी में बदला जाता है। सामान्यतः प्रयुक्त उत्प्रेरक कौन-सा है?","optionsHi":["लोहा","प्लैटिनम","वैनेडियम पेंटाऑक्साइड","निकल"],"explanationHi":"असंतृप्त तेलों के हाइड्रोजनीकरण में महीन चूर्ण के रूप में निकल प्रयुक्त होता है। लोहा हैबर प्रक्रम का और वैनेडियम पेंटाऑक्साइड सल्फ्यूरिक अम्ल के संपर्क प्रक्रम का उत्प्रेरक है।"},
  {"id":"sci-chemistry-190","question":"Pure ethanoic acid is called glacial acetic acid because:","options":["It is found naturally in glaciers and polar ice","It is used to preserve fish and meat packed in ice","It melts at about 17 °C, so it freezes in winter","It is made by fermenting sugar solutions kept ice-cold"],"answer":2,"explanation":"The melting point of pure ethanoic acid is about 290 K, so in cold climates it solidifies into ice-like crystals.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"शुद्ध एथेनॉइक अम्ल को ग्लेशियल ऐसीटिक अम्ल क्यों कहते हैं?","optionsHi":["यह प्राकृतिक रूप से हिमनदों और ध्रुवीय बर्फ में पाया जाता है","इसका उपयोग बर्फ में पैक की गई मछली और माँस को सुरक्षित रखने में होता है","यह लगभग 17 °C पर पिघलता है, इसलिए सर्दियों में जम जाता है","यह बर्फ जैसे ठंडे रखे शर्करा विलयनों के किण्वन से बनता है"],"explanationHi":"शुद्ध एथेनॉइक अम्ल का गलनांक लगभग 290 K है, इसलिए ठंडे मौसम में वह बर्फ जैसे क्रिस्टलों के रूप में जम जाता है।"},
  {"id":"sci-chemistry-191","question":"A small piece of sodium is dropped into ethanol. What happens?","options":["Hydrogen gas is evolved and sodium ethoxide is formed","Carbon dioxide is evolved and sodium ethanoate is formed","Oxygen gas is evolved and sodium hydroxide is formed","No reaction takes place, as ethanol is not an acid"],"answer":0,"explanation":"2Na + 2C₂H₅OH → 2C₂H₅ONa + H₂. Ethanol, like water, reacts with sodium to give hydrogen even though it is neutral to litmus.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"सोडियम का एक छोटा टुकड़ा एथेनॉल में डाला जाता है। क्या होता है?","optionsHi":["हाइड्रोजन गैस निकलती है और सोडियम एथॉक्साइड बनता है","कार्बन डाइऑक्साइड निकलती है और सोडियम एथेनोएट बनता है","ऑक्सीजन गैस निकलती है और सोडियम हाइड्रॉक्साइड बनता है","कोई अभिक्रिया नहीं होती, क्योंकि एथेनॉल अम्ल नहीं है"],"explanationHi":"2Na + 2C₂H₅OH → 2C₂H₅ONa + H₂। एथेनॉल, जल की तरह, लिटमस के प्रति उदासीन होने पर भी सोडियम से अभिक्रिया करके हाइड्रोजन देता है।"},
  {"id":"sci-chemistry-192","question":"Which test can tell a sample of ethanol apart from a sample of ethanoic acid?","options":["Adding a small piece of sodium to each","Adding sodium hydrogencarbonate to each","Mixing each with water","Adding a few drops of phenolphthalein to each"],"answer":1,"explanation":"Only ethanoic acid gives brisk effervescence of CO₂ with NaHCO₃. Both liquids give hydrogen with sodium, both mix with water, and phenolphthalein stays colourless in both.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"कौन-सा परीक्षण एथेनॉल के नमूने को एथेनॉइक अम्ल के नमूने से अलग पहचान सकता है?","optionsHi":["प्रत्येक में सोडियम का एक छोटा टुकड़ा डालना","प्रत्येक में सोडियम हाइड्रोजनकार्बोनेट डालना","प्रत्येक को जल में मिलाना","प्रत्येक में फिनॉल्फ्थेलिन की कुछ बूँदें डालना"],"explanationHi":"केवल एथेनॉइक अम्ल NaHCO₃ के साथ CO₂ की तीव्र बुदबुदाहट देता है। दोनों द्रव सोडियम के साथ हाइड्रोजन देते हैं, दोनों जल में मिल जाते हैं, और फिनॉल्फ्थेलिन दोनों में रंगहीन रहता है।"},
  {"id":"sci-chemistry-193","question":"Drinking spurious liquor containing methanol can cause blindness or death because:","options":["Methanol is converted to ethanol in the body, causing extreme drunken intoxication","Methanol freezes the fluid inside the eyeball and makes it opaque","Methanol directly dissolves the lens of the eye on contact","Methanol is oxidised in the liver to methanal, which damages the optic nerve"],"answer":3,"explanation":"The liver oxidises methanol to methanal, which reacts rapidly with cell components and coagulates protoplasm; the optic nerve is especially affected.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"मेथेनॉल वाली नकली शराब पीने से अंधापन या मृत्यु हो सकती है क्योंकि:","optionsHi":["शरीर में मेथेनॉल एथेनॉल में बदल जाता है, जिससे अत्यधिक नशा होता है","मेथेनॉल नेत्र गोलक के भीतर के द्रव को जमा देता है और उसे अपारदर्शी बना देता है","मेथेनॉल संपर्क में आते ही आँख के लेंस को सीधे घोल देता है","यकृत में मेथेनॉल का ऑक्सीकरण मेथेनैल में हो जाता है, जो दृक् तंत्रिका को क्षति पहुँचाता है"],"explanationHi":"यकृत मेथेनॉल को मेथेनैल में ऑक्सीकृत करता है, जो कोशिका घटकों से तेजी से अभिक्रिया करता है और जीवद्रव्य को स्कंदित कर देता है; दृक् तंत्रिका विशेष रूप से प्रभावित होती है।"},
  {"id":"sci-chemistry-194","question":"An antacid taken for acidity in the stomach commonly contains:","options":["Calcium oxide (quicklime)","Sodium chloride","Magnesium hydroxide","Ammonium chloride"],"answer":2,"explanation":"Milk of magnesia, Mg(OH)₂, is a mild base that neutralises excess stomach acid. Quicklime is too caustic, NaCl is neutral and ammonium chloride is acidic.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"आमाशय में अम्लता के लिए लिए जाने वाले प्रति-अम्ल (एंटैसिड) में सामान्यतः क्या होता है?","optionsHi":["कैल्शियम ऑक्साइड (बिना बुझा चूना)","सोडियम क्लोराइड","मैग्नीशियम हाइड्रॉक्साइड","अमोनियम क्लोराइड"],"explanationHi":"मिल्क ऑफ मैग्नीशिया, Mg(OH)₂, एक मृदु क्षार है जो आमाशय के अतिरिक्त अम्ल को उदासीन कर देता है। बिना बुझा चूना अत्यधिक दाहक है, NaCl उदासीन है और अमोनियम क्लोराइड अम्लीय है।"},
  {"id":"sci-chemistry-195","question":"Mendeleev left gaps in his periodic table and predicted the properties of an undiscovered element he called eka-aluminium. When it was discovered, it was named:","options":["Germanium","Scandium","Gallium","Indium"],"answer":2,"explanation":"Gallium, found in 1875, matched the predicted eka-aluminium closely; germanium matched his eka-silicon and scandium his eka-boron.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"मेंडेलीव ने अपनी आवर्त सारणी में रिक्त स्थान छोड़े और एक अनखोजे तत्व के गुणों की भविष्यवाणी की, जिसे उन्होंने एका-ऐलुमिनियम कहा। जब वह खोजा गया, तो उसका नाम रखा गया:","optionsHi":["जर्मेनियम","स्कैंडियम","गैलियम","इंडियम"],"explanationHi":"1875 में खोजा गया गैलियम भविष्यवाणी किए गए एका-ऐलुमिनियम से निकटता से मेल खाता था; जर्मेनियम उनके एका-सिलिकॉन से और स्कैंडियम एका-बोरॉन से मेल खाता था।"},
  {"id":"sci-chemistry-196","question":"Among the third-period elements sodium, magnesium, aluminium and silicon, which shows the most metallic character?","options":["Silicon","Aluminium","Magnesium","Sodium"],"answer":3,"explanation":"Metallic character (the tendency to lose electrons) decreases from left to right across a period, so sodium is the most metallic and silicon is a metalloid.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"तीसरे आवर्त के तत्वों सोडियम, मैग्नीशियम, ऐलुमिनियम और सिलिकॉन में से किसमें धात्विक गुण सबसे अधिक है?","optionsHi":["सिलिकॉन","ऐलुमिनियम","मैग्नीशियम","सोडियम"],"explanationHi":"धात्विक गुण (इलेक्ट्रॉन त्यागने की प्रवृत्ति) आवर्त में बाएँ से दाएँ घटता है, इसलिए सोडियम सबसे अधिक धात्विक है और सिलिकॉन उपधातु है।"},
  {"id":"sci-chemistry-197","question":"The two main raw materials used to make Portland cement are:","options":["Limestone and clay","Sand and soda ash","Gypsum and sand","Bauxite, coke and cryolite"],"answer":0,"explanation":"Limestone and clay are heated strongly to form clinker, which is ground with a little gypsum. Sand and soda ash (with limestone) are raw materials for glass.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"पोर्टलैंड सीमेंट बनाने में प्रयुक्त दो मुख्य कच्चे माल कौन-से हैं?","optionsHi":["चूना पत्थर और मिट्टी","रेत और सोडा ऐश","जिप्सम और रेत","बॉक्साइट, कोक और क्रायोलाइट"],"explanationHi":"चूना पत्थर और मिट्टी को प्रबल रूप से गर्म करके क्लिंकर बनाया जाता है, जिसे थोड़े जिप्सम के साथ पीसा जाता है। रेत और सोडा ऐश (चूना पत्थर के साथ) काँच के कच्चे माल हैं।"},
  {"id":"sci-chemistry-198","question":"A burning pan of cooking oil should never be put out by pouring water on it because:","options":["Water reacts chemically with the hot oil to form an explosive mixture of gases","Water sinks below the oil, flashes into steam and scatters burning oil","Water increases the oxygen supply reaching the fire","Water itself catches fire when it touches very hot oil"],"answer":1,"explanation":"The water sinks below the oil, flashes into steam and spatters the burning oil. Covering the pan with a lid or a damp cloth cuts off the air instead.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"खाना पकाने के तेल की जलती हुई कड़ाही की आग को कभी जल डालकर नहीं बुझाना चाहिए क्योंकि:","optionsHi":["जल गर्म तेल से रासायनिक अभिक्रिया करके गैसों का विस्फोटक मिश्रण बनाता है","जल तेल के नीचे बैठकर तुरंत भाप बन जाता है और जलता हुआ तेल बिखेर देता है","जल आग तक पहुँचने वाली ऑक्सीजन की आपूर्ति बढ़ा देता है","बहुत गर्म तेल के संपर्क में आने पर जल स्वयं आग पकड़ लेता है"],"explanationHi":"जल तेल के नीचे बैठ जाता है, तुरंत भाप बन जाता है और जलता हुआ तेल छिटका देता है। इसके बजाय कड़ाही को ढक्कन या गीले कपड़े से ढकने से वायु कट जाती है।"},
  {"id":"sci-chemistry-199","question":"Carbon dioxide is effective in putting out fires, especially those of electrical equipment and oil, because it:","options":["Reacts chemically with the burning fuel to form a compound that cannot burn","Is lighter than air and pushes the flames upward and away","Is heavier than air, does not support burning and is non-conducting","Absorbs heat by decomposing into carbon and oxygen in the flame"],"answer":2,"explanation":"Being denser than air, CO₂ settles over the burning material and keeps oxygen away; it leaves no residue and does not conduct electricity.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"कार्बन डाइऑक्साइड आग बुझाने में, विशेषकर विद्युत उपकरणों और तेल की आग में, प्रभावी है क्योंकि वह:","optionsHi":["जलते ईंधन से रासायनिक अभिक्रिया करके ऐसा यौगिक बनाती है जो जल नहीं सकता","वायु से हल्की है और लपटों को ऊपर तथा दूर धकेल देती है","वायु से भारी है, दहन में सहायक नहीं है और विद्युत की कुचालक है","लौ में कार्बन और ऑक्सीजन में विघटित होकर ऊष्मा सोख लेती है"],"explanationHi":"वायु से सघन होने के कारण CO₂ जलते पदार्थ पर जम जाती है और ऑक्सीजन को दूर रखती है; वह कोई अवशेष नहीं छोड़ती और विद्युत चालन नहीं करती।"},
  {"id":"sci-chemistry-200","question":"The yellowing and pitting of the marble of the Taj Mahal (‘marble cancer’) is caused mainly by:","options":["Acid rain formed from SO₂ and nitrogen oxides","Ozone formed in the lower atmosphere by sunlight","Carbon monoxide from vehicles on nearby roads","Excess oxygen given out by the trees in the nearby gardens"],"answer":0,"explanation":"SO₂ and NO₂ dissolve in rain to form sulphuric and nitric acids, which react with the calcium carbonate of marble and corrode it.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"ताजमहल के संगमरमर का पीला पड़ना और उस पर गड्ढे बनना (‘मार्बल कैंसर’) मुख्यतः किसके कारण होता है?","optionsHi":["SO₂ और नाइट्रोजन ऑक्साइडों से बनी अम्लीय वर्षा","सूर्य के प्रकाश द्वारा निचले वायुमंडल में बनी ओज़ोन","पास की सड़कों पर वाहनों से निकली कार्बन मोनोऑक्साइड","पास के बगीचों के वृक्षों द्वारा छोड़ी गई अतिरिक्त ऑक्सीजन"],"explanationHi":"SO₂ और NO₂ वर्षा में घुलकर सल्फ्यूरिक और नाइट्रिक अम्ल बनाती हैं, जो संगमरमर के कैल्शियम कार्बोनेट से अभिक्रिया करके उसे संक्षारित करते हैं।"},
  {"id":"sci-chemistry-201","question":"People in some regions who drink groundwater for years develop mottled, brownish teeth and stiff, deformed bones. The most likely cause is excess of which substance in the water?","options":["Iodine","Calcium","Chloride","Fluoride"],"answer":3,"explanation":"A little fluoride protects teeth, but excess causes dental and skeletal fluorosis. Excess calcium makes water hard but does not cause these symptoms.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"कुछ क्षेत्रों में वर्षों तक भूजल पीने वाले लोगों के दाँतों पर भूरे धब्बे पड़ जाते हैं और अस्थियाँ कठोर तथा विकृत हो जाती हैं। जल में किस पदार्थ की अधिकता इसका सबसे संभावित कारण है?","optionsHi":["आयोडीन","कैल्शियम","क्लोराइड","फ्लोराइड"],"explanationHi":"थोड़ा फ्लोराइड दाँतों की रक्षा करता है, परंतु अधिकता से दंत और कंकालीय फ्लोरोसिस होता है। अधिक कैल्शियम जल को कठोर बनाता है परंतु ये लक्षण उत्पन्न नहीं करता।"},
  {"id":"sci-chemistry-202","question":"Match the disease with the pollutant mainly responsible: A. Minamata disease B. Itai-itai disease C. Blue baby syndrome D. Blackfoot disease; 1. Nitrate in drinking water 2. Mercury 3. Arsenic 4. Cadmium","options":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3"],"answer":0,"explanation":"Minamata (Japan) was caused by mercury in fish, Itai-itai by cadmium, blue baby syndrome by nitrates that reduce the blood's oxygen-carrying capacity, and blackfoot disease by arsenic in well water.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"रोग का मुख्यतः उत्तरदायी प्रदूषक से मिलान कीजिए: A. मिनामाटा रोग B. इटाई-इटाई रोग C. ब्लू बेबी सिंड्रोम D. ब्लैकफुट रोग; 1. पेयजल में नाइट्रेट 2. पारा 3. आर्सेनिक 4. कैडमियम","optionsHi":["A-2, B-4, C-1, D-3","A-4, B-2, C-1, D-3","A-2, B-4, C-3, D-1","A-2, B-1, C-4, D-3"],"explanationHi":"मिनामाटा (जापान) मछली में उपस्थित पारे से, इटाई-इटाई कैडमियम से, ब्लू बेबी सिंड्रोम नाइट्रेटों से (जो रक्त की ऑक्सीजन वहन क्षमता घटा देते हैं) और ब्लैकफुट रोग कुओं के जल में आर्सेनिक से हुआ।"},
  {"id":"sci-chemistry-203","question":"The gas that leaked from a pesticide factory in the Bhopal gas tragedy of December 1984 was:","options":["Phosgene (carbonyl chloride)","Methyl isocyanate","Chlorine","Hydrogen cyanide"],"answer":1,"explanation":"About 40 tonnes of methyl isocyanate (MIC), used in making a carbamate pesticide, escaped from the Union Carbide plant. Phosgene was used to make MIC but was not the gas that leaked.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"दिसंबर 1984 की भोपाल गैस त्रासदी में कीटनाशक कारखाने से कौन-सी गैस रिसी थी?","optionsHi":["फॉस्जीन (कार्बोनिल क्लोराइड)","मेथिल आइसोसायनेट","क्लोरीन","हाइड्रोजन सायनाइड"],"explanationHi":"यूनियन कार्बाइड संयंत्र से कार्बामेट कीटनाशक बनाने में प्रयुक्त लगभग 40 टन मेथिल आइसोसायनेट (MIC) रिसी। फॉस्जीन का उपयोग MIC बनाने में होता था, परंतु रिसने वाली गैस वह नहीं थी।"},
  {"id":"sci-chemistry-204","question":"Rayon is often called artificial silk. Which statement about it is correct?","options":["It is a fully synthetic fibre made only from petroleum products","It is made by silkworms fed on special chemicals","It is a type of nylon","It is made by chemically treating cellulose from wood pulp"],"answer":3,"explanation":"Rayon is a man-made fibre regenerated from natural cellulose, so it is semi-synthetic. Nylon is fully synthetic from petrochemicals.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"रेयॉन को प्रायः कृत्रिम रेशम कहा जाता है। इसके बारे में कौन-सा कथन सही है?","optionsHi":["यह पूर्णतः संश्लेषित रेशा है जो केवल पेट्रोलियम उत्पादों से बना है","यह रेशम के कीड़ों द्वारा बनाया जाता है जिन्हें विशेष रसायन खिलाए जाते हैं","यह नायलॉन का एक प्रकार है","यह लकड़ी की लुगदी से प्राप्त सेलुलोज के रासायनिक उपचार से बनता है"],"explanationHi":"रेयॉन प्राकृतिक सेलुलोज से पुनर्जनित मानव-निर्मित रेशा है, इसलिए यह अर्ध-संश्लेषित है। नायलॉन पेट्रोरसायनों से बना पूर्णतः संश्लेषित रेशा है।"},
  {"id":"sci-chemistry-205","question":"Which of these materials is biodegradable?","options":["A polythene carry bag","A PVC pipe","A jute sack","A nylon rope"],"answer":2,"explanation":"Jute is a natural plant fibre (cellulose) that microbes can decompose. Polythene, PVC and nylon are synthetic polymers that persist for very long.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"इनमें से कौन-सा पदार्थ जैवनिम्नीकरणीय है?","optionsHi":["पॉलिथीन की थैली","PVC का पाइप","जूट का बोरा","नायलॉन की रस्सी"],"explanationHi":"जूट प्राकृतिक पादप रेशा (सेलुलोज) है जिसे सूक्ष्मजीव अपघटित कर सकते हैं। पॉलिथीन, PVC और नायलॉन संश्लेषित बहुलक हैं जो बहुत लंबे समय तक बने रहते हैं।"},
  {"id":"sci-chemistry-206","question":"Aspirin, chemically acetylsalicylic acid, is mainly used as:","options":["An antibiotic to kill bacteria","A painkiller and fever-reducer","An antacid to neutralise stomach acid","A disinfectant for wounds"],"answer":1,"explanation":"Aspirin is an analgesic and antipyretic; it also reduces blood clotting. It has no antibacterial action and, being an acid, can irritate the stomach rather than relieve acidity.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"ऐस्पिरिन, रासायनिक रूप से ऐसीटिलसैलिसिलिक अम्ल, का मुख्य उपयोग किस रूप में होता है?","optionsHi":["जीवाणुओं को मारने वाले प्रतिजैविक के रूप में","दर्दनाशक और ज्वरनाशक के रूप में","आमाशय के अम्ल को उदासीन करने वाले प्रति-अम्ल के रूप में","घावों के कीटाणुनाशक के रूप में"],"explanationHi":"ऐस्पिरिन पीड़ाहारी और ज्वरनाशक है; यह रक्त के थक्का जमने को भी कम करती है। इसमें जीवाणुरोधी क्रिया नहीं होती, और अम्ल होने के कारण यह अम्लता दूर करने के बजाय आमाशय में जलन उत्पन्न कर सकती है।"},
  {"id":"sci-chemistry-207","question":"Which of these compounds is commonly added to sauces, jams and soft drinks as a preservative?","options":["Sodium benzoate","Calcium oxide","Sodium hydroxide","Sodium hydrogencarbonate"],"answer":0,"explanation":"Sodium benzoate stops the growth of moulds and bacteria in acidic foods. Calcium oxide and sodium hydroxide are caustic, and baking soda is a raising agent.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"इनमें से कौन-सा यौगिक सामान्यतः सॉस, जैम और शीतल पेयों में परिरक्षक के रूप में मिलाया जाता है?","optionsHi":["सोडियम बेंज़ोएट","कैल्शियम ऑक्साइड","सोडियम हाइड्रॉक्साइड","सोडियम हाइड्रोजनकार्बोनेट"],"explanationHi":"सोडियम बेंज़ोएट अम्लीय खाद्य पदार्थों में फफूँद और जीवाणुओं की वृद्धि रोकता है। कैल्शियम ऑक्साइड और सोडियम हाइड्रॉक्साइड दाहक हैं, और बेकिंग सोडा खमीर उठाने वाला पदार्थ है।"},
  {"id":"sci-chemistry-208","question":"Which of these fuels has the highest calorific value (heat released per kilogram)?","options":["LPG","Petrol","Methane (CNG)","Hydrogen"],"answer":3,"explanation":"Hydrogen gives about 150 kJ/g, roughly three times as much as LPG, CNG or petrol (about 45–55 kJ/g). Storing it safely is the main problem.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"इन ईंधनों में से किसका ऊष्मीय मान (प्रति किलोग्राम निकलने वाली ऊष्मा) सबसे अधिक है?","optionsHi":["LPG","पेट्रोल","मेथेन (CNG)","हाइड्रोजन"],"explanationHi":"हाइड्रोजन लगभग 150 kJ/g देती है, जो LPG, CNG या पेट्रोल (लगभग 45–55 kJ/g) से लगभग तीन गुना है। उसका सुरक्षित भंडारण ही मुख्य समस्या है।"},
  {"id":"sci-chemistry-209","question":"Which variety of coal has the highest percentage of carbon and the highest heating value?","options":["Peat","Anthracite","Lignite","Bituminous coal"],"answer":1,"explanation":"Carbon content rises in the order peat < lignite < bituminous < anthracite, as the plant matter is buried longer and deeper.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"कोयले की किस किस्म में कार्बन का प्रतिशत और तापन मान सबसे अधिक होता है?","optionsHi":["पीट","ऐन्थ्रासाइट","लिग्नाइट","बिटुमिनी कोयला"],"explanationHi":"पादप पदार्थ के अधिक समय तक और अधिक गहराई में दबे रहने से कार्बन की मात्रा पीट < लिग्नाइट < बिटुमिनी < ऐन्थ्रासाइट के क्रम में बढ़ती है।"},
  {"id":"sci-chemistry-210","question":"In the fractional distillation of crude petroleum, which fraction is collected at the top of the column, at the lowest temperature?","options":["Bitumen","Diesel","Petroleum gas","Lubricating oil"],"answer":2,"explanation":"The column is hottest at the bottom; fractions with the lowest boiling points, such as petroleum gas, rise to the top, while bitumen stays at the bottom.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"कच्चे पेट्रोलियम के प्रभाजी आसवन में स्तंभ के शीर्ष पर, सबसे कम तापमान पर, कौन-सा प्रभाज एकत्र होता है?","optionsHi":["बिटुमेन","डीज़ल","पेट्रोलियम गैस","स्नेहक तेल"],"explanationHi":"स्तंभ का तल सबसे गर्म होता है; सबसे कम क्वथनांक वाले प्रभाज, जैसे पेट्रोलियम गैस, ऊपर उठ जाते हैं, जबकि बिटुमेन तल में रहता है।"},
  {"id":"sci-chemistry-211","question":"Coke, used as the reducing agent in the extraction of iron, is obtained by:","options":["Heating coal strongly in the absence of air","Burning coal in excess air","Fractional distillation of petroleum residue","Heating wood in a limited supply of air"],"answer":0,"explanation":"Destructive distillation of coal drives off coal gas and coal tar and leaves coke, almost pure carbon. Heating wood in limited air gives charcoal.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"लोहे के निष्कर्षण में अपचायक के रूप में प्रयुक्त कोक कैसे प्राप्त होता है?","optionsHi":["कोयले को वायु की अनुपस्थिति में प्रबल रूप से गर्म करके","कोयले को वायु की अधिकता में जलाकर","पेट्रोलियम अवशेष के प्रभाजी आसवन से","लकड़ी को सीमित वायु में गर्म करके"],"explanationHi":"कोयले का भंजक आसवन कोल गैस और कोलतार को निकाल देता है तथा लगभग शुद्ध कार्बन कोक छोड़ता है। सीमित वायु में लकड़ी गर्म करने से चारकोल मिलता है।"},
  {"id":"sci-chemistry-212","question":"A radioactive sample of mass 16 g has a half-life of 5 days. How much of it remains undecayed after 20 days?","options":["4 g","8 g","0 g","1 g"],"answer":3,"explanation":"20 days is 4 half-lives: 16 → 8 → 4 → 2 → 1 g. It never reaches zero by halving; 4 g would be the answer after only 2 half-lives.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"16 g द्रव्यमान वाले एक रेडियोधर्मी नमूने की अर्धायु 5 दिन है। 20 दिन बाद नमूने का कितना द्रव्यमान अविघटित बचेगा?","optionsHi":["4 g","8 g","0 g","1 g"],"explanationHi":"20 दिन 4 अर्धायु के बराबर हैं: 16 → 8 → 4 → 2 → 1 g। आधा करते जाने पर वह कभी शून्य नहीं होता; केवल 2 अर्धायु के बाद उत्तर 4 g होता।"},
  {"id":"sci-chemistry-213","question":"Ordinary filament bulbs are filled with argon rather than air because argon:","options":["Glows brightly and adds to the light given out","Is inert, so the hot filament is not oxidised","Conducts electricity and lowers the resistance","Absorbs the ultraviolet rays from the filament"],"answer":1,"explanation":"In air the white-hot tungsten filament would burn (oxidise) quickly; an inert gas like argon prevents this and slows the evaporation of the filament.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"साधारण तंतु वाले बल्बों में वायु के बजाय आर्गन भरी जाती है क्योंकि आर्गन:","optionsHi":["तेज चमकती है और निकलने वाले प्रकाश को बढ़ाती है","अक्रिय है, इसलिए गर्म तंतु का ऑक्सीकरण नहीं होता","विद्युत का चालन करती है और प्रतिरोध घटाती है","तंतु से निकलने वाली पराबैंगनी किरणों को सोख लेती है"],"explanationHi":"वायु में श्वेत-तप्त टंगस्टन तंतु शीघ्र जल (ऑक्सीकृत हो) जाता; आर्गन जैसी अक्रिय गैस इसे रोकती है और तंतु के वाष्पन को धीमा करती है।"},
  {"id":"sci-chemistry-214","question":"Ice floats on water because:","options":["Ice contains trapped air bubbles that make it light enough to float","Ice molecules are smaller than the molecules of liquid water","Hydrogen bonds hold molecules in an open lattice of lower density","Ice has a higher mass than the same volume of liquid water"],"answer":2,"explanation":"In ice each molecule is hydrogen-bonded in a fixed open lattice, so ice occupies more volume than the same mass of liquid water; even bubble-free ice floats.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"बर्फ जल पर तैरती है क्योंकि:","optionsHi":["बर्फ में फँसे वायु के बुलबुले उसे तैरने योग्य हल्का बना देते हैं","बर्फ के अणु द्रव जल के अणुओं से छोटे होते हैं","हाइड्रोजन बंध अणुओं को कम घनत्व वाले खुले जालक में थामे रखते हैं","बर्फ का द्रव्यमान उसी आयतन के द्रव जल से अधिक होता है"],"explanationHi":"बर्फ में प्रत्येक अणु हाइड्रोजन बंध द्वारा एक स्थिर खुले जालक में जुड़ा होता है, इसलिए बर्फ उतने ही द्रव्यमान के द्रव जल से अधिक आयतन घेरती है; बुलबुला-रहित बर्फ भी तैरती है।"},
  {"id":"sci-chemistry-215","question":"In many nuclear reactors in India, heavy water (D₂O) is used as:","options":["The fuel that undergoes fission","A moderator that slows down fast neutrons","A shield that absorbs gamma rays","A source of extra neutrons to start the chain reaction"],"answer":1,"explanation":"Fission works best with slow neutrons, and the deuterium in heavy water slows them down while absorbing very few. Uranium is the fuel.","difficulty":"hard","source":"SSC CGL · State PSC","questionHi":"भारत के अनेक नाभिकीय रिएक्टरों में भारी जल (D₂O) का उपयोग किस रूप में होता है?","optionsHi":["विखंडित होने वाले ईंधन के रूप में","तीव्र न्यूट्रॉनों को धीमा करने वाले मंदक के रूप में","गामा किरणों को अवशोषित करने वाली ढाल के रूप में","शृंखला अभिक्रिया शुरू करने के लिए अतिरिक्त न्यूट्रॉनों के स्रोत के रूप में"],"explanationHi":"विखंडन धीमे न्यूट्रॉनों से सबसे अच्छा होता है, और भारी जल का ड्यूटीरियम उन्हें धीमा करता है जबकि बहुत कम अवशोषित करता है। यूरेनियम ईंधन है।"},
  {"id":"sci-chemistry-216","question":"Carbon dioxide is bubbled through lime water. The lime water first turns milky, but if bubbling continues for a long time it becomes clear again. This is because:","options":["CaCO₃ reacts with more CO₂ and water to form soluble Ca(HCO₃)₂","The calcium carbonate decomposes back into calcium oxide","The extra carbon dioxide evaporates the water from the solution","The milkiness was due to air bubbles that later escape"],"answer":0,"explanation":"Ca(OH)₂ + CO₂ → CaCO₃↓ (milky); then CaCO₃ + H₂O + CO₂ → Ca(HCO₃)₂, which dissolves. The same reaction causes temporary hardness of water.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"चूने के पानी में कार्बन डाइऑक्साइड प्रवाहित की जाती है। चूने का पानी पहले दूधिया हो जाता है, परंतु यदि बुदबुदाना देर तक जारी रहे तो वह फिर साफ हो जाता है। इसका कारण यह है कि:","optionsHi":["CaCO₃ और अधिक CO₂ तथा जल से अभिक्रिया करके घुलनशील Ca(HCO₃)₂ बनाता है","कैल्शियम कार्बोनेट पुनः कैल्शियम ऑक्साइड में विघटित हो जाता है","अतिरिक्त कार्बन डाइऑक्साइड विलयन के जल को वाष्पित कर देती है","दूधियापन वायु के बुलबुलों के कारण था जो बाद में निकल जाते हैं"],"explanationHi":"Ca(OH)₂ + CO₂ → CaCO₃↓ (दूधिया); फिर CaCO₃ + H₂O + CO₂ → Ca(HCO₃)₂, जो घुल जाता है। यही अभिक्रिया जल की अस्थायी कठोरता का कारण भी है।"},
  {"id":"sci-chemistry-217","question":"What is the molar mass of aluminium sulphate, Al₂(SO₄)₃? (Al = 27, S = 32, O = 16)","options":["315 g/mol","150 g/mol","294 g/mol","342 g/mol"],"answer":3,"explanation":"2 × 27 + 3 × (32 + 4 × 16) = 54 + 288 = 342 g/mol. 315 uses only one Al atom, 150 treats it as Al₂SO₄, and 294 takes S as 16.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"ऐलुमिनियम सल्फेट, Al₂(SO₄)₃, का मोलर द्रव्यमान कितना है? (Al = 27, S = 32, O = 16)","optionsHi":["315 g/mol","150 g/mol","294 g/mol","342 g/mol"],"explanationHi":"2 × 27 + 3 × (32 + 4 × 16) = 54 + 288 = 342 g/mol। 315 केवल एक Al परमाणु लेने से आता है, 150 इसे Al₂SO₄ मान लेने से, और 294 S को 16 मान लेने से।"},
  {"id":"sci-chemistry-218","question":"3 g of carbon combines completely with 8 g of oxygen to form carbon dioxide. By the law of constant proportions, how much oxygen will combine completely with 9 g of carbon to form carbon dioxide?","options":["16 g","24 g","27 g","8 g"],"answer":1,"explanation":"Carbon and oxygen always combine in the fixed mass ratio 3 : 8 in CO₂, so 9 g of carbon needs 9 × 8/3 = 24 g of oxygen.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"3 g कार्बन 8 g ऑक्सीजन से पूर्णतः संयोग करके कार्बन डाइऑक्साइड बनाता है। स्थिर अनुपात के नियम के अनुसार 9 g कार्बन के साथ कार्बन डाइऑक्साइड बनाने के लिए कितनी ऑक्सीजन पूर्णतः संयोग करेगी?","optionsHi":["16 g","24 g","27 g","8 g"],"explanationHi":"CO₂ में कार्बन और ऑक्सीजन सदैव 3 : 8 के निश्चित द्रव्यमान अनुपात में संयोग करते हैं, इसलिए 9 g कार्बन को 9 × 8/3 = 24 g ऑक्सीजन चाहिए।"},
  {"id":"sci-chemistry-219","question":"10 g of hydrogen and 64 g of oxygen are made to react to form water. What mass of water is formed? (H = 1, O = 16)","options":["74 g","90 g","72 g","64 g"],"answer":2,"explanation":"64 g O₂ is 2 mol and needs 4 mol (8 g) of H₂, so oxygen is limiting; 4 mol of water = 72 g, and 2 g of hydrogen is left over. 74 g wrongly assumes everything reacts.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"10 g हाइड्रोजन और 64 g ऑक्सीजन को अभिक्रिया करके जल बनाने दिया जाता है। बने जल का द्रव्यमान कितना है? (H = 1, O = 16)","optionsHi":["74 g","90 g","72 g","64 g"],"explanationHi":"64 g O₂ = 2 mol को 4 mol (8 g) H₂ चाहिए, इसलिए ऑक्सीजन सीमांत अभिकर्मक है; 4 mol जल = 72 g बनता है, और 2 g हाइड्रोजन बच जाती है। 74 g यह मान लेने की भूल है कि सब कुछ अभिक्रिया कर लेता है।"},
  {"id":"sci-chemistry-220","question":"At STP, 11.2 litres of a gas has a mass of 22 g. The gas could be: (C = 12, N = 14, O = 16, H = 1)","options":["Carbon dioxide","Oxygen","Nitrogen dioxide","Ammonia"],"answer":0,"explanation":"11.2 L at STP is 0.5 mol, so the molar mass is 22/0.5 = 44 g/mol, which matches CO₂. Nitrogen dioxide (46) is close but not equal, and oxygen (32) and ammonia (17) are far off.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"STP पर किसी गैस के 11.2 लीटर का द्रव्यमान 22 g है। वह गैस हो सकती है: (C = 12, N = 14, O = 16, H = 1)","optionsHi":["कार्बन डाइऑक्साइड","ऑक्सीजन","नाइट्रोजन डाइऑक्साइड","अमोनिया"],"explanationHi":"STP पर 11.2 L = 0.5 mol है, इसलिए मोलर द्रव्यमान 22/0.5 = 44 g/mol है, जो CO₂ से मेल खाता है। नाइट्रोजन डाइऑक्साइड (46) निकट है पर बराबर नहीं, और ऑक्सीजन (32) तथा अमोनिया (17) बहुत दूर हैं।"},
  {"id":"sci-chemistry-221","question":"Which of the following processes is exothermic?","options":["Photosynthesis","Respiration","Electrolysis of water","Decomposition of calcium carbonate on heating"],"answer":1,"explanation":"Respiration oxidises glucose and releases energy. Photosynthesis absorbs light energy, and electrolysis and thermal decomposition need a supply of energy.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"निम्नलिखित में से कौन-सी प्रक्रिया ऊष्माक्षेपी है?","optionsHi":["प्रकाश संश्लेषण","श्वसन","जल का विद्युत अपघटन","गर्म करने पर कैल्शियम कार्बोनेट का अपघटन"],"explanationHi":"श्वसन ग्लूकोज का ऑक्सीकरण करता है और ऊर्जा मुक्त करता है। प्रकाश संश्लेषण प्रकाश ऊर्जा अवशोषित करता है, और विद्युत अपघटन तथा तापीय अपघटन में ऊर्जा की आपूर्ति चाहिए।"},
  {"id":"sci-chemistry-222","question":"Cobalt oxide is added to molten glass to give it which colour?","options":["Ruby red","Bottle green","Deep blue","Brown"],"answer":2,"explanation":"Cobalt compounds give glass a deep blue colour. Green glass usually comes from iron or chromium oxides and red from gold or copper compounds.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"पिघले काँच में कोबाल्ट ऑक्साइड मिलाने से उसे कौन-सा रंग मिलता है?","optionsHi":["माणिक्य लाल","बोतल जैसा हरा","गहरा नीला","भूरा"],"explanationHi":"कोबाल्ट यौगिक काँच को गहरा नीला रंग देते हैं। हरा काँच प्रायः आयरन या क्रोमियम ऑक्साइडों से और लाल सोने या ताँबे के यौगिकों से बनता है।"},
  {"id":"sci-chemistry-223","question":"Assertion (A): Copper vessels left in moist air for a long time develop a green coating. Reason (R): Copper slowly reacts with moist carbon dioxide in the air to form basic copper carbonate.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The green layer is basic copper carbonate, CuCO₃·Cu(OH)₂, formed from moist CO₂ and oxygen; it is the corrosion of copper, just as rust is the corrosion of iron.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"अभिकथन (A): नम वायु में लंबे समय तक रखे ताँबे के बर्तनों पर हरी परत जम जाती है। कारण (R): ताँबा वायु की नम कार्बन डाइऑक्साइड से धीरे-धीरे अभिक्रिया करके क्षारकीय कॉपर कार्बोनेट बनाता है।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"हरी परत क्षारकीय कॉपर कार्बोनेट, CuCO₃·Cu(OH)₂, है, जो नम CO₂ और ऑक्सीजन से बनती है; यह ताँबे का संक्षारण है, जैसे जंग लोहे का संक्षारण है।"},
  {"id":"sci-chemistry-224","question":"Assertion (A): Ionic compounds generally dissolve readily in kerosene and petrol. Reason (R): Ionic compounds are made up of positive and negative ions.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"Ionic compounds are made of ions (R is true), but they are generally soluble in water and insoluble in non-polar solvents like kerosene and petrol, so A is false.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"अभिकथन (A): आयनिक यौगिक सामान्यतः मिट्टी के तेल और पेट्रोल में आसानी से घुल जाते हैं। कारण (R): आयनिक यौगिक धनायनों और ऋणायनों से बने होते हैं।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"आयनिक यौगिक आयनों से बने होते हैं (R सही है), परंतु वे सामान्यतः जल में घुलनशील और मिट्टी के तेल तथा पेट्रोल जैसे अध्रुवीय विलायकों में अघुलनशील होते हैं, इसलिए A गलत है।"},
  {"id":"sci-chemistry-225","question":"Assertion (A): A galvanised iron bucket does not rust even when its zinc coating gets scratched. Reason (R): Zinc is more reactive than iron, so it corrodes in preference to the exposed iron.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Zinc acts as a sacrificial metal: being more reactive, it is oxidised first, protecting the iron even where the iron is exposed. Paint or tin coatings do not protect once broken.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"अभिकथन (A): यशदलेपित लोहे की बाल्टी में जस्ते की परत खरोंच जाने पर भी जंग नहीं लगती। कारण (R): जस्ता लोहे से अधिक क्रियाशील है, इसलिए खुले लोहे की तुलना में वही पहले संक्षारित होता है।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"जस्ता बलिदानी धातु का कार्य करता है: अधिक क्रियाशील होने से वह पहले ऑक्सीकृत होता है और खुले लोहे की भी रक्षा करता है। पेंट या टिन की परतें टूटने के बाद रक्षा नहीं करतीं।"},
  {"id":"sci-chemistry-226","question":"Assertion (A): An aqueous solution of glucose conducts electricity just as dilute hydrochloric acid does. Reason (R): Both glucose and hydrochloric acid contain hydrogen.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":3,"explanation":"R is true, but A is false: HCl ionises in water and its solution conducts, while glucose does not ionise at all, so its solution does not conduct. Containing hydrogen does not make a compound produce ions.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"अभिकथन (A): ग्लूकोज का जलीय विलयन तनु हाइड्रोक्लोरिक अम्ल की तरह ही विद्युत का चालन करता है। कारण (R): ग्लूकोज और हाइड्रोक्लोरिक अम्ल दोनों में हाइड्रोजन होती है।","optionsHi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों सही हैं, परंतु R, A की सही व्याख्या नहीं है","A सही है, परंतु R गलत है","A गलत है, परंतु R सही है"],"explanationHi":"R सही है, परंतु A गलत है: HCl जल में आयनित होता है और उसका विलयन चालन करता है, जबकि ग्लूकोज बिल्कुल आयनित नहीं होता, इसलिए उसका विलयन चालन नहीं करता। हाइड्रोजन होने से कोई यौगिक आयन नहीं बनाता।"},
  {"id":"sci-chemistry-227","question":"How many of these statements are correct? I. Evaporation takes place only at the surface, while boiling takes place throughout the liquid. II. Evaporation can occur at any temperature below the boiling point. III. Water boils at a lower temperature on a high mountain than at sea level. IV. Dissolving common salt in water lowers its boiling point.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct; lower air pressure at altitude lowers the boiling point. A dissolved solute such as salt raises the boiling point, so IV is wrong.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. वाष्पन केवल सतह पर होता है, जबकि उबलना पूरे द्रव में होता है। II. वाष्पन क्वथनांक से नीचे किसी भी तापमान पर हो सकता है। III. ऊँचे पर्वत पर जल समुद्र तल की तुलना में कम तापमान पर उबलता है। IV. जल में सामान्य नमक घोलने से उसका क्वथनांक घटता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और III सही हैं; ऊँचाई पर कम वायुदाब क्वथनांक को घटा देता है। नमक जैसा घुला हुआ विलेय क्वथनांक बढ़ाता है, इसलिए IV गलत है।"},
  {"id":"sci-chemistry-228","question":"How many of these statements are correct? I. All bases are alkalis. II. All alkalis are bases. III. Acids turn blue litmus red. IV. Metal oxides are generally basic in nature.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Alkalis are only those bases that dissolve in water, so every alkali is a base but not every base (e.g. Cu(OH)₂) is an alkali. Statements II, III and IV are correct.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"इनमें से कितने कथन सही हैं? I. सभी क्षारक, क्षार (ऐल्कली) होते हैं। II. सभी क्षार, क्षारक होते हैं। III. अम्ल नीले लिटमस को लाल कर देते हैं। IV. धातु ऑक्साइड सामान्यतः प्रकृति से क्षारकीय होते हैं।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"क्षार केवल वे क्षारक हैं जो जल में घुलते हैं, इसलिए प्रत्येक क्षार क्षारक है पर प्रत्येक क्षारक (जैसे Cu(OH)₂) क्षार नहीं है। कथन II, III और IV सही हैं।"},
  {"id":"sci-chemistry-229","question":"Most non-metal oxides are acidic. Which of these non-metal oxides is neutral?","options":["Carbon dioxide","Carbon monoxide","Sulphur dioxide","Phosphorus pentoxide"],"answer":1,"explanation":"CO, like N₂O and H₂O, is a neutral oxide. CO₂, SO₂ and P₂O₅ dissolve in water to form acids.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"अधिकांश अधातु ऑक्साइड अम्लीय होते हैं। इनमें से कौन-सा अधातु ऑक्साइड उदासीन है?","optionsHi":["कार्बन डाइऑक्साइड","कार्बन मोनोऑक्साइड","सल्फर डाइऑक्साइड","फॉस्फोरस पेंटाऑक्साइड"],"explanationHi":"CO, N₂O और H₂O की तरह, एक उदासीन ऑक्साइड है। CO₂, SO₂ और P₂O₅ जल में घुलकर अम्ल बनाते हैं।"},
  {"id":"sci-chemistry-230","question":"When magnesium chloride (MgCl₂) is formed from its elements, each magnesium atom:","options":["Gains two electrons, one from each chlorine atom","Shares one pair of electrons with each chlorine atom","Loses one electron to each of two chlorine atoms","Loses two electrons to a single chlorine atom"],"answer":2,"explanation":"Mg (2, 8, 2) gives one electron to each of two Cl atoms, forming Mg²⁺ and two Cl⁻ ions. A chlorine atom needs only one electron to complete its octet, so it cannot take two.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"अपने तत्वों से मैग्नीशियम क्लोराइड (MgCl₂) बनने पर प्रत्येक मैग्नीशियम परमाणु:","optionsHi":["दो इलेक्ट्रॉन ग्रहण करता है, प्रत्येक क्लोरीन परमाणु से एक","प्रत्येक क्लोरीन परमाणु के साथ इलेक्ट्रॉनों का एक युग्म साझा करता है","दो क्लोरीन परमाणुओं में से प्रत्येक को एक इलेक्ट्रॉन त्यागता है","एक ही क्लोरीन परमाणु को दो इलेक्ट्रॉन त्यागता है"],"explanationHi":"Mg (2, 8, 2) दो Cl परमाणुओं में से प्रत्येक को एक इलेक्ट्रॉन देता है, जिससे Mg²⁺ और दो Cl⁻ आयन बनते हैं। क्लोरीन परमाणु को अष्टक पूरा करने के लिए केवल एक इलेक्ट्रॉन चाहिए, इसलिए वह दो नहीं ले सकता।"},
  {"id":"sci-chemistry-231","question":"To electroplate a steel spoon with silver, the correct arrangement is:","options":["Spoon as the anode, silver plate as the cathode, copper sulphate solution as electrolyte","Spoon as the cathode, silver plate as the anode, a silver salt solution as electrolyte","Spoon as the cathode, carbon rod as the anode, sodium chloride solution as electrolyte","Spoon and silver plate both as cathodes, dilute sulphuric acid as electrolyte"],"answer":1,"explanation":"Metal ions are deposited at the cathode, so the object to be plated is the cathode; the silver anode dissolves to replace the Ag⁺ ions removed from the silver salt electrolyte.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"इस्पात की चम्मच पर चाँदी का विद्युत लेपन करने के लिए सही व्यवस्था है:","optionsHi":["चम्मच ऐनोड, चाँदी की प्लेट कैथोड, कॉपर सल्फेट विलयन विद्युत अपघट्य","चम्मच कैथोड, चाँदी की प्लेट ऐनोड, चाँदी के लवण का विलयन विद्युत अपघट्य","चम्मच कैथोड, कार्बन की छड़ ऐनोड, सोडियम क्लोराइड विलयन विद्युत अपघट्य","चम्मच और चाँदी की प्लेट दोनों कैथोड, तनु सल्फ्यूरिक अम्ल विद्युत अपघट्य"],"explanationHi":"धातु आयन कैथोड पर जमा होते हैं, इसलिए जिस वस्तु पर लेपन करना है वह कैथोड होती है; चाँदी का ऐनोड घुलकर चाँदी के लवण वाले विद्युत अपघट्य से निकले Ag⁺ आयनों की पूर्ति करता है।"},
  {"id":"sci-chemistry-232","question":"In the electrolysis of water, a few drops of dilute sulphuric acid are added to the water. This is done because:","options":["Pure water conducts poorly; the acid supplies ions so current flows","The acid supplies the hydrogen gas that collects at the cathode","The acid prevents oxygen from forming at the anode during electrolysis","The acid lowers the boiling point so the water does not overheat"],"answer":0,"explanation":"Pure water has very few ions; adding acid makes it conduct, while the gases collected still come from water in a 2 : 1 volume ratio of hydrogen to oxygen.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"जल के विद्युत अपघटन में जल में तनु सल्फ्यूरिक अम्ल की कुछ बूँदें मिलाई जाती हैं। ऐसा इसलिए किया जाता है कि:","optionsHi":["शुद्ध जल कम चालन करता है; अम्ल आयन देता है ताकि धारा प्रवाहित हो सके","अम्ल वह हाइड्रोजन गैस देता है जो कैथोड पर एकत्र होती है","अम्ल विद्युत अपघटन के दौरान ऐनोड पर ऑक्सीजन बनने से रोकता है","अम्ल क्वथनांक घटा देता है ताकि जल अत्यधिक गर्म न हो"],"explanationHi":"शुद्ध जल में आयन बहुत कम होते हैं; अम्ल मिलाने से वह चालन करने लगता है, जबकि एकत्र होने वाली गैसें अब भी जल से ही बनती हैं, हाइड्रोजन और ऑक्सीजन के 2 : 1 आयतन अनुपात में।"},
  {"id":"sci-chemistry-233","question":"Which statement best describes what happens when a candle burns?","options":["Only a physical change occurs, since the wax simply melts","Only a chemical change occurs, since the wax simply burns","Both: wax melts and vaporises, and the wax vapour burns","Neither, since the total mass of wax and products stays the same"],"answer":2,"explanation":"Wax melts and vaporises (physical changes, reversible), and the vapour burns to form CO₂ and water with heat and light (a chemical change). Mass is conserved overall, but the wax itself is used up.","difficulty":"hard","source":"RRB Group D · SSC CHSL","questionHi":"मोमबत्ती के जलने पर क्या होता है, इसका सबसे अच्छा वर्णन कौन-सा कथन करता है?","optionsHi":["केवल भौतिक परिवर्तन होता है, क्योंकि मोम केवल पिघलता है","केवल रासायनिक परिवर्तन होता है, क्योंकि मोम केवल जलता है","दोनों: मोम पिघलता और वाष्पित होता है, और मोम की वाष्प जलती है","कोई नहीं, क्योंकि मोम और उत्पादों का कुल द्रव्यमान समान रहता है"],"explanationHi":"मोम पिघलता और वाष्पित होता है (भौतिक परिवर्तन, उत्क्रमणीय), और वाष्प जलकर ऊष्मा और प्रकाश के साथ CO₂ और जल बनाती है (रासायनिक परिवर्तन)। कुल द्रव्यमान संरक्षित रहता है, परंतु मोम स्वयं समाप्त हो जाता है।"},
  {"id":"sci-chemistry-234","question":"The IUPAC name of the compound CH₃CH₂CHO is:","options":["Propanone","Propanol","Ethanal","Propanal"],"answer":3,"explanation":"Three carbon atoms (prop-) with an aldehyde group (–CHO, suffix -al) give propanal. Propanone is the three-carbon ketone CH₃COCH₃, and ethanal has only two carbons.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"यौगिक CH₃CH₂CHO का IUPAC नाम क्या है?","optionsHi":["प्रोपेनोन","प्रोपेनॉल","एथेनैल","प्रोपेनैल"],"explanationHi":"तीन कार्बन परमाणु (प्रोप-) और ऐल्डिहाइड समूह (–CHO, प्रत्यय -ऐल) से प्रोपेनैल बनता है। प्रोपेनोन तीन कार्बन वाला कीटोन CH₃COCH₃ है, और एथेनैल में केवल दो कार्बन होते हैं।"},
  {"id":"sci-chemistry-235","question":"Orange-brown bromine water loses its colour when shaken with which of these gases?","options":["Ethene","Methane","Ethane","Carbon dioxide"],"answer":0,"explanation":"Ethene has a C=C double bond and undergoes an addition reaction with bromine, which decolourises it; saturated alkanes like methane and ethane do not react this way in the dark.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"नारंगी-भूरा ब्रोमीन जल इनमें से किस गैस के साथ हिलाने पर अपना रंग खो देता है?","optionsHi":["एथीन","मेथेन","एथेन","कार्बन डाइऑक्साइड"],"explanationHi":"एथीन में C=C द्विबंध होता है और वह ब्रोमीन से योगात्मक अभिक्रिया करती है, जिससे वह रंगहीन हो जाता है; मेथेन और एथेन जैसे संतृप्त ऐल्केन अँधेरे में इस प्रकार अभिक्रिया नहीं करते।"},
  {"id":"sci-chemistry-236","question":"In sunlight, methane reacts with chlorine to give chloromethane (CH₃Cl) and hydrogen chloride. This is an example of:","options":["An addition reaction","A substitution reaction","A combustion reaction","A polymerisation reaction"],"answer":1,"explanation":"A hydrogen atom of methane is replaced by a chlorine atom, which is substitution. Saturated hydrocarbons cannot undergo addition since they have no double bond.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"सूर्य के प्रकाश में मेथेन क्लोरीन से अभिक्रिया करके क्लोरोमेथेन (CH₃Cl) और हाइड्रोजन क्लोराइड बनाती है। यह किसका उदाहरण है?","optionsHi":["योगात्मक अभिक्रिया","प्रतिस्थापन अभिक्रिया","दहन अभिक्रिया","बहुलकीकरण अभिक्रिया"],"explanationHi":"मेथेन का एक हाइड्रोजन परमाणु क्लोरीन परमाणु से प्रतिस्थापित हो जाता है, जो प्रतिस्थापन है। संतृप्त हाइड्रोकार्बनों में द्विबंध नहीं होता, इसलिए वे योग अभिक्रिया नहीं कर सकते।"},
  {"id":"sci-chemistry-237","question":"How many electrons are shared between the two atoms in an oxygen molecule, O₂?","options":["2","6","8","4"],"answer":3,"explanation":"Each oxygen atom (6 valence electrons) needs two more, so the atoms share two pairs, i.e. 4 electrons, forming a double bond. Six electrons are shared in the triple bond of N₂.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"ऑक्सीजन अणु, O₂, में दोनों परमाणुओं के बीच कितने इलेक्ट्रॉन साझा होते हैं?","optionsHi":["2","6","8","4"],"explanationHi":"प्रत्येक ऑक्सीजन परमाणु (6 संयोजी इलेक्ट्रॉन) को दो और चाहिए, इसलिए परमाणु दो युग्म, अर्थात 4 इलेक्ट्रॉन, साझा करते हैं और द्विबंध बनता है। N₂ के त्रिबंध में छह इलेक्ट्रॉन साझा होते हैं।"},
  {"id":"sci-chemistry-238","question":"The element with atomic number 16 has a valency of:","options":["6","2","4","8"],"answer":1,"explanation":"Sulphur is 2, 8, 6; it needs two more electrons to complete its octet, so its valency is 8 − 6 = 2. The trap 6 is the number of valence electrons.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"परमाणु क्रमांक 16 वाले तत्व की संयोजकता क्या है?","optionsHi":["6","2","4","8"],"explanationHi":"सल्फर 2, 8, 6 है; अष्टक पूरा करने के लिए उसे दो और इलेक्ट्रॉन चाहिए, इसलिए उसकी संयोजकता 8 − 6 = 2 है। भ्रम का उत्तर 6 संयोजी इलेक्ट्रॉनों की संख्या है।"},
  {"id":"sci-chemistry-239","question":"Which pair of atomic numbers represents two elements in the same period of the periodic table?","options":["3 and 11","9 and 17","11 and 17","12 and 20"],"answer":2,"explanation":"Elements 11 (Na) and 17 (Cl) both have three shells, so both are in Period 3. The pairs 3 and 11, 9 and 17, and 12 and 20 are in the same groups, not the same periods.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"परमाणु क्रमांकों का कौन-सा युग्म आवर्त सारणी के एक ही आवर्त के दो तत्वों को दर्शाता है?","optionsHi":["3 और 11","9 और 17","11 और 17","12 और 20"],"explanationHi":"तत्व 11 (Na) और 17 (Cl) दोनों में तीन कोश हैं, इसलिए दोनों आवर्त 3 में हैं। युग्म 3 और 11, 9 और 17, तथा 12 और 20 एक ही समूह में हैं, एक ही आवर्त में नहीं।"},
  {"id":"sci-chemistry-240","question":"Newlands' law of octaves was found to apply well only to the lighter elements, up to:","options":["Calcium","Sodium","Iron","Uranium"],"answer":0,"explanation":"Newlands' pattern (every eighth element similar) worked only up to calcium; beyond that, elements with very different properties fell into the same column.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"न्यूलैंड्स का अष्टक नियम केवल हल्के तत्वों पर ही ठीक से लागू पाया गया, कहाँ तक?","optionsHi":["कैल्शियम तक","सोडियम तक","लोहे तक","यूरेनियम तक"],"explanationHi":"न्यूलैंड्स का प्रतिरूप (प्रत्येक आठवाँ तत्व समान) केवल कैल्शियम तक ही कार्य करता था; उसके बाद बहुत भिन्न गुणों वाले तत्व एक ही स्तंभ में आ गए।"},
  {"id":"sci-chemistry-241","question":"When a bottle of soda water is opened, bubbles rush out. The main reason is that:","options":["Air rushing into the bottle displaces dissolved CO₂ from water","Escaping gas cools the soda, and colder water holds less CO₂","Oxygen from the air reacts with carbonic acid to free its CO₂","Pressure above the liquid falls, so less CO₂ stays dissolved"],"answer":3,"explanation":"CO₂ is dissolved under high pressure, and the solubility of a gas falls when the pressure above it drops, so the excess escapes as bubbles. Colder water actually holds more CO₂, and air neither displaces nor reacts with it.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"सोडा वाटर की बोतल खोलने पर बुलबुले तेजी से निकलते हैं। इसका मुख्य कारण है:","optionsHi":["बोतल में दौड़कर घुसने वाली वायु जल से घुली CO₂ को विस्थापित कर देती है","निकलती गैस सोडे को ठंडा कर देती है, और ठंडा जल कम CO₂ रखता है","वायु की ऑक्सीजन कार्बोनिक अम्ल से अभिक्रिया करके उसकी CO₂ मुक्त कर देती है","द्रव के ऊपर का दाब घट जाता है, इसलिए कम CO₂ घुली रह पाती है"],"explanationHi":"CO₂ उच्च दाब पर घुली होती है, और ऊपर का दाब घटने पर गैस की विलेयता घट जाती है, इसलिए अधिक CO₂ बुलबुलों के रूप में निकल जाती है। ठंडा जल वास्तव में अधिक CO₂ रखता है, और वायु न उसे विस्थापित करती है न उससे अभिक्रिया।"},
  {"id":"sci-chemistry-242","question":"Fish in a pond often come to the surface gasping on very hot summer afternoons. From the chemistry of solutions, the reason is that:","options":["Dissolved oxygen reacts with the hot water and is used up","Gases are less soluble in warmer water, so it holds less oxygen","Hot water dissolves more carbon dioxide, which drives out the nitrogen","Sunlight splits the dissolved oxygen into separate atoms"],"answer":1,"explanation":"Unlike most solids, gases become less soluble in water as the temperature rises, so warm water contains less dissolved oxygen.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"तालाब की मछलियाँ गर्मी की बहुत तपती दोपहर में प्रायः हाँफती हुई सतह पर आ जाती हैं। विलयनों के रसायन की दृष्टि से इसका कारण है:","optionsHi":["घुली हुई ऑक्सीजन गर्म जल से अभिक्रिया करके समाप्त हो जाती है","गैसें गर्म जल में कम घुलनशील होती हैं, इसलिए उसमें कम ऑक्सीजन होती है","गर्म जल अधिक कार्बन डाइऑक्साइड घोलता है, जो नाइट्रोजन को बाहर निकाल देती है","सूर्य का प्रकाश घुली ऑक्सीजन को अलग-अलग परमाणुओं में तोड़ देता है"],"explanationHi":"अधिकांश ठोसों के विपरीत, तापमान बढ़ने पर गैसें जल में कम घुलनशील हो जाती हैं, इसलिए गर्म जल में घुली ऑक्सीजन कम होती है।"},
  {"id":"sci-chemistry-243","question":"The solubility of a salt is 110 g per 100 g of water at 60 °C and 32 g per 100 g of water at 20 °C. If 210 g of its saturated solution at 60 °C is cooled to 20 °C, what mass of salt crystallises out?","options":["78 g","110 g","32 g","142 g"],"answer":0,"explanation":"210 g of saturated solution = 100 g water + 110 g salt. At 20 °C that water can hold only 32 g, so 110 − 32 = 78 g crystallises.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"किसी लवण की विलेयता 60 °C पर 100 g जल में 110 g और 20 °C पर 100 g जल में 32 g है। 60 °C पर उसके 210 g संतृप्त विलयन को 20 °C तक ठंडा करने पर कितना लवण क्रिस्टलित होकर निकलेगा?","optionsHi":["78 g","110 g","32 g","142 g"],"explanationHi":"210 g संतृप्त विलयन = 100 g जल + 110 g लवण। 20 °C पर वह जल केवल 32 g रख सकता है, इसलिए 110 − 32 = 78 g क्रिस्टलित हो जाता है।"},
  {"id":"sci-chemistry-244","question":"20 g of common salt is dissolved in 80 g of water. The concentration of the solution, by mass percentage, is:","options":["25%","16%","20%","80%"],"answer":2,"explanation":"Mass percentage = mass of solute / mass of solution × 100 = 20/(20 + 80) × 100 = 20%. The trap 25% divides by the mass of the solvent instead of the solution.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"20 g सामान्य नमक को 80 g जल में घोला जाता है। विलयन की सांद्रता द्रव्यमान प्रतिशत में कितनी है?","optionsHi":["25%","16%","20%","80%"],"explanationHi":"द्रव्यमान प्रतिशत = विलेय का द्रव्यमान / विलयन का द्रव्यमान × 100 = 20/(20 + 80) × 100 = 20%। भ्रम का उत्तर 25% विलयन के बजाय विलायक के द्रव्यमान से भाग देने पर आता है।"},
  {"id":"sci-chemistry-245","question":"A colourless solution turns phenolphthalein pink. What colour will it give with methyl orange?","options":["Red","Pink","Colourless","Yellow"],"answer":3,"explanation":"A pink colour with phenolphthalein shows the solution is basic; methyl orange is yellow in basic solution and red in acidic solution.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"एक रंगहीन विलयन फिनॉल्फ्थेलिन को गुलाबी कर देता है। मेथिल ऑरेंज के साथ वह कौन-सा रंग देगा?","optionsHi":["लाल","गुलाबी","रंगहीन","पीला"],"explanationHi":"फिनॉल्फ्थेलिन के साथ गुलाबी रंग दर्शाता है कि विलयन क्षारीय है; मेथिल ऑरेंज क्षारीय विलयन में पीला और अम्लीय विलयन में लाल होता है।"},
  {"id":"sci-chemistry-246","question":"When calcium is put into water, it reacts and soon starts floating. The reason is that:","options":["Calcium is a light metal, less dense than water","The calcium hydroxide formed is lighter than water","Hydrogen bubbles cling to the metal and lift it","The heat of the reaction turns the calcium into vapour"],"answer":2,"explanation":"Calcium is actually denser than water; the hydrogen bubbles formed on its surface make it float. The reaction is less vigorous than that of sodium, so the hydrogen does not catch fire.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"जब कैल्शियम को जल में डाला जाता है, तो वह अभिक्रिया करता है और शीघ्र ही तैरने लगता है। इसका कारण है:","optionsHi":["कैल्शियम हल्की धातु है, जल से कम घनत्व वाली","बना हुआ कैल्शियम हाइड्रॉक्साइड जल से हल्का होता है","हाइड्रोजन के बुलबुले धातु से चिपककर उसे ऊपर उठा देते हैं","अभिक्रिया की ऊष्मा कैल्शियम को वाष्प में बदल देती है"],"explanationHi":"कैल्शियम वास्तव में जल से सघन है; उसकी सतह पर बने हाइड्रोजन के बुलबुले उसे तैरा देते हैं। अभिक्रिया सोडियम की अपेक्षा कम तीव्र होती है, इसलिए हाइड्रोजन आग नहीं पकड़ती।"},
  {"id":"sci-chemistry-247","question":"Gold used in jewellery is usually mixed with a little copper or silver because pure gold is:","options":["Too soft to keep its shape and design","Too reactive and tarnishes quickly","Too brittle and cracks when hammered","Too poor a conductor of heat and electricity"],"answer":0,"explanation":"Pure (24-carat) gold is very soft and malleable; alloying with copper or silver makes it harder. Gold is unreactive and not brittle.","difficulty":"moderate","source":"RRB Group D · SSC MTS","questionHi":"आभूषणों में प्रयुक्त सोने में सामान्यतः थोड़ा ताँबा या चाँदी मिलाई जाती है क्योंकि शुद्ध सोना:","optionsHi":["इतना मुलायम होता है कि अपना आकार और डिज़ाइन बनाए नहीं रख सकता","बहुत क्रियाशील है और शीघ्र धूमिल हो जाता है","बहुत भंगुर है और हथौड़े से पीटने पर चटक जाता है","ऊष्मा और विद्युत का बहुत कमज़ोर चालक है"],"explanationHi":"शुद्ध (24 कैरेट) सोना बहुत मुलायम और आघातवर्ध्य होता है; ताँबे या चाँदी के साथ मिश्रधातु बनाने से वह कठोर हो जाता है। सोना अक्रिय है और भंगुर नहीं है।"},
  {"id":"sci-chemistry-248","question":"When lead nitrate crystals are heated in a dry test tube, brown fumes are seen. These fumes are of:","options":["Oxygen","Nitrogen dioxide","Bromine vapour","Nitric oxide (NO)"],"answer":1,"explanation":"2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂. Nitrogen dioxide is the brown gas; oxygen and nitric oxide are colourless, and lead oxide is a yellowish solid left behind. Bromine vapour is also brown but contains an element not present in lead nitrate.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"लेड नाइट्रेट के क्रिस्टलों को शुष्क परखनली में गर्म करने पर भूरे धुएँ दिखाई देते हैं। ये धुएँ किसके हैं?","optionsHi":["ऑक्सीजन","नाइट्रोजन डाइऑक्साइड","ब्रोमीन वाष्प","नाइट्रिक ऑक्साइड (NO)"],"explanationHi":"2Pb(NO₃)₂ → 2PbO + 4NO₂ + O₂। नाइट्रोजन डाइऑक्साइड भूरी गैस है; ऑक्सीजन और नाइट्रिक ऑक्साइड रंगहीन हैं, और लेड ऑक्साइड पीलापन लिए ठोस बच जाता है। ब्रोमीन वाष्प भी भूरी होती है, परंतु उसका तत्व लेड नाइट्रेट में नहीं है।"},
  {"id":"sci-chemistry-249","question":"When green ferrous sulphate crystals are heated strongly, they leave a reddish-brown solid and give off gases with the smell of burning sulphur. The gases are:","options":["Hydrogen sulphide and water vapour","Sulphur dioxide and oxygen","Sulphur dioxide and sulphur trioxide","Sulphur trioxide and hydrogen sulphide"],"answer":2,"explanation":"After losing its water of crystallisation, 2FeSO₄ → Fe₂O₃ + SO₂ + SO₃. The reddish-brown solid is ferric oxide.","difficulty":"very-hard","source":"SSC CGL · State PSC","questionHi":"हरे फेरस सल्फेट के क्रिस्टलों को प्रबल रूप से गर्म करने पर लालिमा लिए भूरा ठोस बचता है और जलते सल्फर जैसी गंध वाली गैसें निकलती हैं। ये गैसें हैं:","optionsHi":["हाइड्रोजन सल्फाइड और जलवाष्प","सल्फर डाइऑक्साइड और ऑक्सीजन","सल्फर डाइऑक्साइड और सल्फर ट्राइऑक्साइड","सल्फर ट्राइऑक्साइड और हाइड्रोजन सल्फाइड"],"explanationHi":"क्रिस्टलन जल खोने के बाद 2FeSO₄ → Fe₂O₃ + SO₂ + SO₃। लालिमा लिए भूरा ठोस फेरिक ऑक्साइड है।"},
  {"id":"sci-chemistry-250","question":"Blue copper sulphate crystals turn white on strong heating and become blue again when a few drops of water are added. The best explanation is that:","options":["The heating decomposes copper sulphate into copper and sulphur","They lose water of crystallisation on heating and regain it later","Heating oxidises the copper, and the added water reduces it again","The blue colour is due to trapped air, which escapes on heating"],"answer":1,"explanation":"CuSO₄·5H₂O loses its five water molecules to become white anhydrous CuSO₄; adding water restores the hydrated blue form. This is why anhydrous copper sulphate is used to test for water.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"नीले कॉपर सल्फेट के क्रिस्टल प्रबल रूप से गर्म करने पर सफेद हो जाते हैं और कुछ बूँदें जल मिलाने पर फिर नीले हो जाते हैं। इसकी सबसे अच्छी व्याख्या है कि:","optionsHi":["गर्म करने से कॉपर सल्फेट ताँबे और सल्फर में विघटित हो जाता है","गर्म करने पर वे क्रिस्टलन जल खो देते हैं और बाद में उसे पुनः प्राप्त कर लेते हैं","गर्म करने से ताँबे का ऑक्सीकरण होता है, और मिलाया गया जल उसे फिर अपचयित कर देता है","नीला रंग फँसी हुई वायु के कारण है, जो गर्म करने पर निकल जाती है"],"explanationHi":"CuSO₄·5H₂O अपने पाँच जल अणु खोकर सफेद निर्जल CuSO₄ बन जाता है; जल मिलाने पर जलयोजित नीला रूप लौट आता है। इसीलिए निर्जल कॉपर सल्फेट का उपयोग जल की जाँच में होता है।"},
  {"id":"sci-chemistry-251","question":"Which statement about ozone is correct?","options":["Stratospheric ozone absorbs UV, but ground-level ozone is a pollutant","Ozone is a molecule made of two oxygen atoms joined by a double bond","The ozone layer lies in the troposphere, close to the Earth's surface","Ozone depletion is caused mainly by rising carbon dioxide levels"],"answer":0,"explanation":"O₃ high up shields life from UV rays, but at ground level it is a toxic component of smog. It has three oxygen atoms, lies in the stratosphere, and is depleted mainly by CFCs.","difficulty":"hard","source":"RRB NTPC · SSC CHSL","questionHi":"ओज़ोन के बारे में कौन-सा कथन सही है?","optionsHi":["समताप मंडलीय ओज़ोन UV को अवशोषित करती है, परंतु भूतल की ओज़ोन प्रदूषक है","ओज़ोन दो ऑक्सीजन परमाणुओं के द्विबंध से जुड़ने से बना अणु है","ओज़ोन परत क्षोभ मंडल में, पृथ्वी की सतह के निकट स्थित है","ओज़ोन क्षरण मुख्यतः कार्बन डाइऑक्साइड के बढ़ते स्तर के कारण होता है"],"explanationHi":"ऊँचाई पर O₃ जीवन को UV किरणों से बचाती है, परंतु भूतल पर वह धूम-कोहरे (स्मॉग) का विषैला घटक है। उसमें तीन ऑक्सीजन परमाणु होते हैं, वह समताप मंडल में स्थित है, और उसका क्षरण मुख्यतः CFC से होता है।"},
  {"id":"sci-chemistry-252","question":"What is the approximate mass of a single molecule of water in grams? (H = 1, O = 16, Avogadro's number = 6.022 × 10²³)","options":["2.99 × 10⁻²² g","1.66 × 10⁻²⁴ g","2.99 × 10⁻²³ g","3.34 × 10²² g"],"answer":2,"explanation":"One mole of water (18 g) contains 6.022 × 10²³ molecules, so one molecule has mass 18 ÷ 6.022 × 10²³ ≈ 2.99 × 10⁻²³ g. The value 1.66 × 10⁻²⁴ g is the mass of 1 atomic mass unit.","difficulty":"hard","questionHi":"जल के एक अणु का लगभग द्रव्यमान ग्राम में कितना होता है? (H = 1, O = 16, आवोगाद्रो संख्या = 6.022 × 10²³)","optionsHi":["2.99 × 10⁻²² g","1.66 × 10⁻²⁴ g","2.99 × 10⁻²³ g","3.34 × 10²² g"],"explanationHi":"एक मोल जल (18 g) में 6.022 × 10²³ अणु होते हैं, इसलिए एक अणु का द्रव्यमान 18 ÷ 6.022 × 10²³ ≈ 2.99 × 10⁻²³ g है। 1.66 × 10⁻²⁴ g एक परमाणु द्रव्यमान इकाई का द्रव्यमान है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-253","question":"How many electrons are present in 9 g of water? (H = 1, O = 16, Avogadro's number = 6.022 × 10²³)","options":["3.01 × 10²⁴","3.01 × 10²³","6.02 × 10²⁴","6.02 × 10²³"],"answer":0,"explanation":"9 g of water is 0.5 mol, so it has 0.5 × 6.022 × 10²³ molecules. Each molecule has 10 electrons (2 from H and 8 from O), giving 5 × 6.022 × 10²³ = 3.01 × 10²⁴ electrons.","difficulty":"very-hard","questionHi":"9 g जल में कितने इलेक्ट्रॉन होते हैं? (H = 1, O = 16, आवोगाद्रो संख्या = 6.022 × 10²³)","optionsHi":["3.01 × 10²⁴","3.01 × 10²³","6.02 × 10²⁴","6.02 × 10²³"],"explanationHi":"9 g जल 0.5 मोल है, इसलिए उसमें 0.5 × 6.022 × 10²³ अणु होते हैं। प्रत्येक अणु में 10 इलेक्ट्रॉन होते हैं (H के 2 और O के 8), अतः कुल 5 × 6.022 × 10²³ = 3.01 × 10²⁴ इलेक्ट्रॉन हुए।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-254","question":"Under the same conditions of temperature and pressure, the rates of diffusion of hydrogen and oxygen gases are in the ratio (H = 1, O = 16):","options":["2 : 1","16 : 1","8 : 1","4 : 1"],"answer":3,"explanation":"By Graham's law, rate is inversely proportional to the square root of molar mass: rate(H₂) : rate(O₂) = √(32 ÷ 2) = √16 = 4 : 1. The 16 : 1 answer forgets the square root.","difficulty":"hard","questionHi":"ताप और दाब की समान परिस्थितियों में हाइड्रोजन और ऑक्सीजन गैसों की विसरण दरों का अनुपात है (H = 1, O = 16):","optionsHi":["2 : 1","16 : 1","8 : 1","4 : 1"],"explanationHi":"ग्राहम के नियम के अनुसार विसरण दर मोलर द्रव्यमान के वर्गमूल के व्युत्क्रमानुपाती होती है: दर(H₂) : दर(O₂) = √(32 ÷ 2) = √16 = 4 : 1। 16 : 1 का उत्तर वर्गमूल लेना भूल जाने से आता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-255","question":"A gas mixture contains 4 g of hydrogen and 32 g of oxygen at a total pressure of 3 atm. What is the partial pressure of oxygen? (H = 1, O = 16)","options":["2 atm","1 atm","1.5 atm","2.67 atm"],"answer":1,"explanation":"4 g of H₂ is 2 mol and 32 g of O₂ is 1 mol, so the mole fraction of oxygen is 1/3 and its partial pressure is 3 × 1/3 = 1 atm. Using mass fractions instead of mole fractions gives the trap value 2.67 atm.","difficulty":"very-hard","questionHi":"एक गैस मिश्रण में 4 g हाइड्रोजन और 32 g ऑक्सीजन है तथा कुल दाब 3 atm है। ऑक्सीजन का आंशिक दाब कितना है? (H = 1, O = 16)","optionsHi":["2 atm","1 atm","1.5 atm","2.67 atm"],"explanationHi":"4 g H₂ = 2 मोल और 32 g O₂ = 1 मोल, इसलिए ऑक्सीजन का मोल अंश 1/3 है और उसका आंशिक दाब 3 × 1/3 = 1 atm है। मोल अंश के स्थान पर द्रव्यमान अंश लेने पर भ्रामक मान 2.67 atm आता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-256","question":"2.4 g of magnesium ribbon is added to 100 mL of 1 M hydrochloric acid. What volume of hydrogen is released at STP? (Mg = 24; 1 mol of gas occupies 22.4 L at STP)","options":["2.24 L","0.56 L","1.12 L","4.48 L"],"answer":2,"explanation":"Mg + 2HCl → MgCl₂ + H₂. Mg is 0.1 mol and needs 0.2 mol HCl, but only 0.1 mol HCl is present, so HCl is the limiting reagent and gives 0.05 mol H₂ = 1.12 L. The value 2.24 L assumes all the magnesium reacts.","difficulty":"very-hard","questionHi":"2.4 g मैग्नीशियम फीते को 100 mL 1 M हाइड्रोक्लोरिक अम्ल में डाला जाता है। STP पर कितने आयतन की हाइड्रोजन निकलेगी? (Mg = 24; STP पर 1 मोल गैस का आयतन 22.4 L)","optionsHi":["2.24 L","0.56 L","1.12 L","4.48 L"],"explanationHi":"Mg + 2HCl → MgCl₂ + H₂। Mg 0.1 मोल है और उसे 0.2 मोल HCl चाहिए, पर केवल 0.1 मोल HCl है, अतः HCl सीमांत अभिकर्मक है और 0.05 मोल H₂ = 1.12 L देता है। 2.24 L का मान यह मानने पर आता है कि सारा मैग्नीशियम अभिक्रिया कर लेता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-257","question":"A hydrocarbon contains 85.7% carbon and 14.3% hydrogen by mass and has a vapour density of 28. Its molecular formula is: (C = 12, H = 1)","options":["C₂H₄","C₃H₆","C₅H₁₀","C₄H₈"],"answer":3,"explanation":"The mole ratio C : H = 85.7/12 : 14.3/1 = 7.14 : 14.3 = 1 : 2, so the empirical formula is CH₂ (mass 14). Molar mass = 2 × vapour density = 56, so n = 56 ÷ 14 = 4 and the formula is C₄H₈.","difficulty":"very-hard","questionHi":"एक हाइड्रोकार्बन में द्रव्यमान से 85.7% कार्बन और 14.3% हाइड्रोजन है तथा उसका वाष्प घनत्व 28 है। उसका आणविक सूत्र है: (C = 12, H = 1)","optionsHi":["C₂H₄","C₃H₆","C₅H₁₀","C₄H₈"],"explanationHi":"मोल अनुपात C : H = 85.7/12 : 14.3/1 = 7.14 : 14.3 = 1 : 2, अतः मूलानुपाती सूत्र CH₂ है (द्रव्यमान 14)। मोलर द्रव्यमान = 2 × वाष्प घनत्व = 56, इसलिए n = 56 ÷ 14 = 4 और सूत्र C₄H₈ है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-258","question":"Butane burns in oxygen: C₄H₁₀ + O₂ → CO₂ + H₂O. When the equation is balanced with the smallest whole-number coefficients, what is the sum of all the coefficients?","options":["66","33","27","35"],"answer":1,"explanation":"2C₄H₁₀ + 13O₂ → 8CO₂ + 10H₂O, because 8 C atoms and 20 H atoms need 16 + 10 = 26 O atoms, i.e. 13 O₂. The sum is 2 + 13 + 8 + 10 = 33, and 66 comes from not reducing to the smallest whole numbers.","difficulty":"very-hard","questionHi":"ब्यूटेन ऑक्सीजन में जलती है: C₄H₁₀ + O₂ → CO₂ + H₂O। समीकरण को सबसे छोटे पूर्ण संख्या गुणांकों से संतुलित करने पर सभी गुणांकों का योग कितना होगा?","optionsHi":["66","33","27","35"],"explanationHi":"2C₄H₁₀ + 13O₂ → 8CO₂ + 10H₂O, क्योंकि 8 C परमाणुओं और 20 H परमाणुओं के लिए 16 + 10 = 26 O परमाणु अर्थात 13 O₂ चाहिए। योग 2 + 13 + 8 + 10 = 33 है, और 66 सबसे छोटी पूर्ण संख्याओं तक न घटाने पर आता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-259","question":"Carbon forms two oxides, CO and CO₂. The masses of oxygen that combine with a fixed mass of carbon in the two oxides are in the simple ratio 1 : 2. This illustrates the law of:","options":["multiple proportions","conservation of mass","constant (definite) proportions","Gay-Lussac's law of combining volumes"],"answer":0,"explanation":"In CO, 12 g of carbon combines with 16 g of oxygen and in CO₂ with 32 g, a ratio of 1 : 2. When two elements form more than one compound, the masses of one that combine with a fixed mass of the other are in small whole-number ratio: the law of multiple proportions.","difficulty":"moderate","questionHi":"कार्बन के दो ऑक्साइड CO और CO₂ बनते हैं। दोनों ऑक्साइडों में कार्बन के निश्चित द्रव्यमान से संयोग करने वाली ऑक्सीजन के द्रव्यमान सरल अनुपात 1 : 2 में हैं। यह किस नियम को दर्शाता है?","optionsHi":["गुणित अनुपात का नियम","द्रव्यमान संरक्षण का नियम","स्थिर (निश्चित) अनुपात का नियम","गे-लुसाक का संयोजी आयतन का नियम"],"explanationHi":"CO में 12 g कार्बन 16 g ऑक्सीजन से और CO₂ में 32 g से संयोग करता है, अनुपात 1 : 2। जब दो तत्व एक से अधिक यौगिक बनाते हैं, तो एक तत्व के निश्चित द्रव्यमान से जुड़ने वाले दूसरे तत्व के द्रव्यमान छोटी पूर्ण संख्याओं के अनुपात में होते हैं: यही गुणित अनुपात का नियम है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-260","question":"Which pair of nuclides are isotones (same number of neutrons)?","options":["¹²C and ¹³C","¹⁴C and ¹⁴N","¹³C and ¹⁴N","¹⁶O and ¹⁷O"],"answer":2,"explanation":"¹³C (Z = 6) has 13 − 6 = 7 neutrons and ¹⁴N (Z = 7) has 14 − 7 = 7 neutrons, so they are isotones. ¹²C/¹³C and ¹⁶O/¹⁷O are isotopes (same Z), and ¹⁴C/¹⁴N are isobars (same mass number).","difficulty":"hard","questionHi":"न्यूक्लाइडों का कौन-सा युग्म समस्थानिक न्यूट्रॉनी (आइसोटोन) है (न्यूट्रॉनों की संख्या समान)?","optionsHi":["¹²C और ¹³C","¹⁴C और ¹⁴N","¹³C और ¹⁴N","¹⁶O और ¹⁷O"],"explanationHi":"¹³C (Z = 6) में 13 − 6 = 7 न्यूट्रॉन और ¹⁴N (Z = 7) में 14 − 7 = 7 न्यूट्रॉन होते हैं, इसलिए ये आइसोटोन हैं। ¹²C/¹³C और ¹⁶O/¹⁷O समस्थानिक (समान Z) हैं तथा ¹⁴C/¹⁴N समभारिक (समान द्रव्यमान संख्या) हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-261","question":"An atom of ²³⁸U (atomic number 92) emits one α-particle and then two β-particles. The nucleus finally formed is:","options":["²³⁴Th (Z = 90)","²³⁰Th (Z = 90)","²³⁴Pa (Z = 91)","²³⁴U (Z = 92)"],"answer":3,"explanation":"Alpha emission lowers mass number by 4 and Z by 2, giving ²³⁴Th (Z = 90). Each beta emission raises Z by 1 without changing mass number, so after two β we get ²³⁴U (Z = 92), an isotope of the parent.","difficulty":"very-hard","questionHi":"²³⁸U (परमाणु क्रमांक 92) का एक परमाणु पहले एक α-कण और फिर दो β-कण उत्सर्जित करता है। अंत में बनने वाला नाभिक है:","optionsHi":["²³⁴Th (Z = 90)","²³⁰Th (Z = 90)","²³⁴Pa (Z = 91)","²³⁴U (Z = 92)"],"explanationHi":"α उत्सर्जन से द्रव्यमान संख्या 4 और Z 2 घटता है, जिससे ²³⁴Th (Z = 90) बनता है। प्रत्येक β उत्सर्जन से द्रव्यमान संख्या बदले बिना Z में 1 की वृद्धि होती है, इसलिए दो β के बाद ²³⁴U (Z = 92) मिलता है, जो मूल तत्व का समस्थानिक है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-262","question":"In Rutherford's gold-foil experiment, a very small number of α-particles rebounded almost straight back. This showed that:","options":["electrons move in fixed circular orbits around the nucleus","the positive charge and most of the mass of an atom lie in a very small, dense nucleus","most of the volume of an atom is occupied by electrons","gold atoms are much lighter than the α-particles"],"answer":1,"explanation":"Only a tiny, heavy, positively charged centre could turn back fast α-particles, which is why very few rebounded. The fact that most particles passed straight through showed that most of the atom is empty space.","difficulty":"moderate","questionHi":"रदरफ़ोर्ड के स्वर्ण पन्नी प्रयोग में बहुत थोड़े α-कण लगभग सीधे वापस लौट आए। इससे सिद्ध हुआ कि:","optionsHi":["इलेक्ट्रॉन नाभिक के चारों ओर निश्चित वृत्ताकार कक्षाओं में घूमते हैं","परमाणु का धनावेश और अधिकांश द्रव्यमान एक बहुत छोटे, घने नाभिक में होता है","परमाणु के अधिकांश आयतन पर इलेक्ट्रॉनों का अधिकार होता है","सोने के परमाणु α-कणों से बहुत हल्के होते हैं"],"explanationHi":"केवल एक छोटा, भारी, धनावेशित केंद्र ही तेज़ α-कणों को पीछे लौटा सकता था, इसीलिए बहुत कम कण लौटे। अधिकांश कणों का सीधे निकल जाना दर्शाता है कि परमाणु का अधिकांश भाग रिक्त है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-263","question":"Which of these elements is a metalloid?","options":["Silicon","Aluminium","Phosphorus","Magnesium"],"answer":0,"explanation":"Silicon has properties between those of metals and non-metals: it is lustrous like a metal yet brittle and a semiconductor. Aluminium and magnesium are metals and phosphorus is a non-metal.","difficulty":"moderate","questionHi":"इनमें से कौन-सा तत्व उपधातु (मेटैलॉइड) है?","optionsHi":["सिलिकन","ऐलुमिनियम","फ़ॉस्फ़ोरस","मैग्नीशियम"],"explanationHi":"सिलिकन के गुण धातुओं और अधातुओं के बीच के हैं: वह धातु की तरह चमकीला है, पर भंगुर और अर्धचालक है। ऐलुमिनियम और मैग्नीशियम धातुएँ हैं तथा फ़ॉस्फ़ोरस अधातु है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-264","question":"Chlorine gas is bubbled through a colourless solution of potassium bromide. What is observed?","options":["No change, because bromide is more reactive than chlorine","A violet colour appears because of iodine","The solution turns orange-brown because of bromine","A white precipitate of potassium chloride settles"],"answer":2,"explanation":"Chlorine is more reactive than bromine, so it displaces bromine from the bromide: Cl₂ + 2KBr → 2KCl + Br₂. The liberated bromine colours the solution orange-brown, and KCl stays dissolved.","difficulty":"hard","questionHi":"पोटैशियम ब्रोमाइड के रंगहीन विलयन में क्लोरीन गैस प्रवाहित की जाती है। क्या देखा जाएगा?","optionsHi":["कोई परिवर्तन नहीं, क्योंकि ब्रोमाइड क्लोरीन से अधिक क्रियाशील है","आयोडीन के कारण बैंगनी रंग आ जाता है","ब्रोमीन के कारण विलयन नारंगी-भूरा हो जाता है","पोटैशियम क्लोराइड का श्वेत अवक्षेप बैठ जाता है"],"explanationHi":"क्लोरीन ब्रोमीन से अधिक क्रियाशील है, इसलिए वह ब्रोमाइड से ब्रोमीन को विस्थापित कर देती है: Cl₂ + 2KBr → 2KCl + Br₂। मुक्त ब्रोमीन विलयन को नारंगी-भूरा कर देती है और KCl घुला रहता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-265","question":"Deep-sea divers breathe a mixture of oxygen and helium instead of ordinary air mainly because helium:","options":["is heavier than nitrogen, so it helps the diver to sink","reacts with nitrogen in the blood and removes it","supplies more oxygen to the lungs than air does","is much less soluble in blood than nitrogen at high pressure"],"answer":3,"explanation":"At great depth the high pressure dissolves a lot of nitrogen in the blood, which forms painful bubbles on quick ascent (the bends). Helium is far less soluble and is also non-toxic, so it avoids this.","difficulty":"hard","questionHi":"गहरे समुद्र के गोताखोर साधारण वायु के स्थान पर ऑक्सीजन और हीलियम का मिश्रण साँस में लेते हैं, मुख्यतः क्योंकि हीलियम:","optionsHi":["नाइट्रोजन से भारी है, इसलिए गोताखोर को डूबने में सहायता करती है","रक्त की नाइट्रोजन से अभिक्रिया करके उसे हटा देती है","वायु की तुलना में फेफड़ों को अधिक ऑक्सीजन देती है","उच्च दाब पर रक्त में नाइट्रोजन की तुलना में बहुत कम घुलनशील है"],"explanationHi":"अधिक गहराई पर उच्च दाब से रक्त में बहुत नाइट्रोजन घुल जाती है, जो तेज़ी से ऊपर आने पर पीड़ादायक बुलबुले बनाती है (डिकम्प्रेशन बीमारी)। हीलियम बहुत कम घुलनशील और अविषाक्त है, इसलिए यह समस्या नहीं होती।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-266","question":"Which gas is the third most abundant in dry air by volume, after nitrogen and oxygen?","options":["Carbon dioxide","Argon","Neon","Helium"],"answer":1,"explanation":"Dry air is about 78% nitrogen, 21% oxygen and 0.93% argon. Carbon dioxide is only about 0.04%, and neon and helium are present in minute traces.","difficulty":"hard","questionHi":"नाइट्रोजन और ऑक्सीजन के बाद शुष्क वायु में आयतन के अनुसार तीसरी सबसे प्रचुर गैस कौन-सी है?","optionsHi":["कार्बन डाइऑक्साइड","ऑर्गन","नियॉन","हीलियम"],"explanationHi":"शुष्क वायु में लगभग 78% नाइट्रोजन, 21% ऑक्सीजन और 0.93% ऑर्गन होती है। कार्बन डाइऑक्साइड केवल लगभग 0.04% है, और नियॉन तथा हीलियम अत्यल्प मात्रा में हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-267","question":"A filter paper dipped in acidified potassium dichromate solution turns from orange to green when held in a gas. The gas is:","options":["Sulphur dioxide","Carbon dioxide","Ammonia","Chlorine"],"answer":0,"explanation":"Sulphur dioxide is a reducing agent and reduces the orange dichromate ions (Cr₂O₇²⁻) to green chromium(III) ions. CO₂, NH₃ and Cl₂ do not reduce dichromate in this way.","difficulty":"hard","questionHi":"अम्लीकृत पोटैशियम डाइक्रोमेट विलयन में भिगोया गया छन्ना कागज़ किसी गैस में रखने पर नारंगी से हरा हो जाता है। वह गैस है:","optionsHi":["सल्फ़र डाइऑक्साइड","कार्बन डाइऑक्साइड","अमोनिया","क्लोरीन"],"explanationHi":"सल्फ़र डाइऑक्साइड अपचायक है और नारंगी डाइक्रोमेट आयनों (Cr₂O₇²⁻) को हरे क्रोमियम(III) आयनों में अपचयित कर देती है। CO₂, NH₃ और Cl₂ डाइक्रोमेट को इस प्रकार अपचयित नहीं करतीं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-268","question":"When a glass rod dipped in concentrated hydrochloric acid is held near another dipped in concentrated ammonia solution, dense white fumes form. These fumes are of:","options":["ammonium nitrate","sodium chloride","ammonium chloride","ammonium hydroxide vapour"],"answer":2,"explanation":"Ammonia gas and hydrogen chloride gas escaping from the two solutions combine in the air: NH₃ + HCl → NH₄Cl. The tiny solid particles of ammonium chloride look like white smoke.","difficulty":"moderate","questionHi":"जब सांद्र हाइड्रोक्लोरिक अम्ल में डूबी काँच की छड़ को सांद्र अमोनिया विलयन में डूबी दूसरी छड़ के पास लाया जाता है, तो सघन श्वेत धूम बनता है। यह धूम किसका है?","optionsHi":["अमोनियम नाइट्रेट","सोडियम क्लोराइड","अमोनियम क्लोराइड","अमोनियम हाइड्रॉक्साइड वाष्प"],"explanationHi":"दोनों विलयनों से निकलने वाली अमोनिया और हाइड्रोजन क्लोराइड गैसें वायु में मिल जाती हैं: NH₃ + HCl → NH₄Cl। अमोनियम क्लोराइड के सूक्ष्म ठोस कण श्वेत धुएँ जैसे दिखते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-269","question":"Equal volumes of a strong acid solution of pH 2 and a strong acid solution of pH 4 are mixed. The pH of the mixture is closest to:","options":["3.0","2.3","2.7","3.3"],"answer":1,"explanation":"[H⁺] of the mixture = (10⁻² + 10⁻⁴) ÷ 2 ≈ 5.05 × 10⁻³ M, so pH = −log(5.05 × 10⁻³) ≈ 2.3. Averaging the pH values to get 3.0 is the trap, because pH is a logarithmic scale.","difficulty":"very-hard","questionHi":"pH 2 वाले प्रबल अम्ल विलयन और pH 4 वाले प्रबल अम्ल विलयन के समान आयतन मिलाए जाते हैं। मिश्रण का pH लगभग कितना होगा?","optionsHi":["3.0","2.3","2.7","3.3"],"explanationHi":"मिश्रण का [H⁺] = (10⁻² + 10⁻⁴) ÷ 2 ≈ 5.05 × 10⁻³ M, अतः pH = −log(5.05 × 10⁻³) ≈ 2.3। pH मानों का औसत लेकर 3.0 निकालना जाल है, क्योंकि pH लघुगणकीय पैमाना है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-270","question":"The hydrogen-ion concentration of a solution of pH 2 is how many times that of a solution of pH 5?","options":["3","30","100","1000"],"answer":3,"explanation":"pH is a negative logarithm to base 10, so each unit of pH changes [H⁺] ten-fold. A difference of 3 pH units means 10³ = 1000 times.","difficulty":"hard","questionHi":"pH 2 वाले विलयन की हाइड्रोजन आयन सांद्रता pH 5 वाले विलयन की कितने गुनी होती है?","optionsHi":["3","30","100","1000"],"explanationHi":"pH आधार 10 पर ऋणात्मक लघुगणक है, इसलिए pH की प्रत्येक इकाई पर [H⁺] दस गुना बदल जाता है। 3 pH इकाइयों के अंतर का अर्थ है 10³ = 1000 गुना।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-271","question":"A solution turns methyl orange yellow but leaves phenolphthalein colourless. Its pH is most likely about:","options":["6","2","10","13"],"answer":0,"explanation":"Methyl orange is red below about pH 3.1 and yellow above 4.4, while phenolphthalein stays colourless below about pH 8.3. Both observations together place the pH between roughly 4.4 and 8.3, so 6 is the only possible choice.","difficulty":"very-hard","questionHi":"एक विलयन मेथिल ऑरेंज को पीला कर देता है, पर फ़ीनॉलफ़्थेलीन को रंगहीन रहने देता है। उसका pH लगभग कितना होने की संभावना है?","optionsHi":["6","2","10","13"],"explanationHi":"मेथिल ऑरेंज लगभग pH 3.1 से नीचे लाल और 4.4 से ऊपर पीला होता है, जबकि फ़ीनॉलफ़्थेलीन लगभग pH 8.3 से नीचे रंगहीन रहता है। दोनों प्रेक्षण मिलकर pH को लगभग 4.4 और 8.3 के बीच रखते हैं, इसलिए 6 ही संभव विकल्प है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-272","question":"Rain water in unpolluted air is naturally slightly acidic, with a pH of about 5.6. The acid responsible is formed by the dissolving of:","options":["sulphur dioxide","nitrogen dioxide","carbon dioxide","ozone"],"answer":2,"explanation":"Atmospheric CO₂ dissolves in rain to form weak carbonic acid, H₂CO₃, which brings the pH down to about 5.6. Rain is called acid rain only when its pH falls below this, because of SO₂ and NOₓ from pollution.","difficulty":"hard","questionHi":"प्रदूषणरहित वायु में वर्षा जल स्वाभाविक रूप से थोड़ा अम्लीय होता है, जिसका pH लगभग 5.6 होता है। इसके लिए उत्तरदायी अम्ल किसके घुलने से बनता है?","optionsHi":["सल्फ़र डाइऑक्साइड","नाइट्रोजन डाइऑक्साइड","कार्बन डाइऑक्साइड","ओज़ोन"],"explanationHi":"वायुमंडलीय CO₂ वर्षा में घुलकर दुर्बल कार्बोनिक अम्ल H₂CO₃ बनाती है, जो pH को लगभग 5.6 तक ले आता है। वर्षा को अम्लीय वर्षा तभी कहते हैं जब प्रदूषण से SO₂ और NOₓ के कारण उसका pH इससे भी नीचे चला जाए।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-273","question":"Permanent hardness of water, which is NOT removed by boiling, can be removed by:","options":["boiling it for a longer time","adding washing soda (sodium carbonate)","passing it through a sand filter","adding bleaching powder"],"answer":1,"explanation":"Permanent hardness is due to chlorides and sulphates of calcium and magnesium. Washing soda precipitates Ca²⁺ and Mg²⁺ as insoluble carbonates, and ion-exchange resins also remove them. Boiling removes only temporary (bicarbonate) hardness.","difficulty":"hard","questionHi":"जल की स्थायी कठोरता, जो उबालने से दूर नहीं होती, किससे दूर की जा सकती है?","optionsHi":["उसे अधिक समय तक उबालकर","धावन सोडा (सोडियम कार्बोनेट) मिलाकर","उसे रेत के फ़िल्टर से गुज़ारकर","विरंजक चूर्ण मिलाकर"],"explanationHi":"स्थायी कठोरता कैल्सियम और मैग्नीशियम के क्लोराइडों और सल्फ़ेटों के कारण होती है। धावन सोडा Ca²⁺ और Mg²⁺ को अघुलनशील कार्बोनेटों के रूप में अवक्षेपित कर देता है, और आयन-विनिमय रेज़िन भी इन्हें हटाते हैं। उबालने से केवल अस्थायी (बाइकार्बोनेट) कठोरता दूर होती है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-274","question":"Pellets of sodium hydroxide left in an open dish become wet and slowly turn into a solution. This behaviour is called:","options":["efflorescence","sublimation","crystallisation","deliquescence"],"answer":3,"explanation":"A deliquescent substance absorbs so much water vapour from the air that it dissolves in it. Efflorescence is the opposite, the loss of water of crystallisation, as in washing soda crystals turning to powder.","difficulty":"moderate","questionHi":"खुली तश्तरी में छोड़ी गई सोडियम हाइड्रॉक्साइड की गोलियाँ गीली होकर धीरे-धीरे विलयन में बदल जाती हैं। इस गुण को क्या कहते हैं?","optionsHi":["प्रस्फुटन (एफ्लोरेसेंस)","ऊर्ध्वपातन","क्रिस्टलन","प्रगलन (डेलीक्वेसेंस)"],"explanationHi":"प्रगलनशील पदार्थ वायु से इतनी जलवाष्प सोख लेता है कि उसी में घुल जाता है। प्रस्फुटन इसके विपरीत है, जिसमें क्रिस्टलन जल निकल जाता है, जैसे धावन सोडा के क्रिस्टल चूर्ण बन जाते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-275","question":"What volume of oxygen at STP is obtained by the complete decomposition of 34 g of hydrogen peroxide? 2H₂O₂ → 2H₂O + O₂ (H = 1, O = 16; 1 mol of gas = 22.4 L at STP)","options":["11.2 L","22.4 L","5.6 L","33.6 L"],"answer":0,"explanation":"34 g of H₂O₂ is 1 mol (molar mass 34). Two moles give one mole of O₂, so 1 mol gives 0.5 mol O₂ = 0.5 × 22.4 = 11.2 L.","difficulty":"very-hard","questionHi":"34 g हाइड्रोजन परॉक्साइड के पूर्ण अपघटन से STP पर कितने आयतन की ऑक्सीजन मिलेगी? 2H₂O₂ → 2H₂O + O₂ (H = 1, O = 16; STP पर 1 मोल गैस = 22.4 L)","optionsHi":["11.2 L","22.4 L","5.6 L","33.6 L"],"explanationHi":"34 g H₂O₂ = 1 मोल (मोलर द्रव्यमान 34)। दो मोल से एक मोल O₂ मिलती है, इसलिए 1 मोल से 0.5 मोल O₂ = 0.5 × 22.4 = 11.2 L मिलती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-276","question":"Heating 12.25 g of potassium chlorate gives potassium chloride and oxygen: 2KClO₃ → 2KCl + 3O₂. What volume of oxygen is released at STP? (K = 39, Cl = 35.5, O = 16; 1 mol of gas = 22.4 L at STP)","options":["2.24 L","4.48 L","3.36 L","6.72 L"],"answer":2,"explanation":"The molar mass of KClO₃ is 122.5 g, so 12.25 g is 0.1 mol. Two moles give three moles of O₂, so 0.1 mol gives 0.15 mol O₂ = 0.15 × 22.4 = 3.36 L.","difficulty":"hard","questionHi":"12.25 g पोटैशियम क्लोरेट को गर्म करने पर पोटैशियम क्लोराइड और ऑक्सीजन मिलती है: 2KClO₃ → 2KCl + 3O₂। STP पर कितने आयतन की ऑक्सीजन निकलेगी? (K = 39, Cl = 35.5, O = 16; STP पर 1 मोल गैस = 22.4 L)","optionsHi":["2.24 L","4.48 L","3.36 L","6.72 L"],"explanationHi":"KClO₃ का मोलर द्रव्यमान 122.5 g है, इसलिए 12.25 g = 0.1 मोल। दो मोल से तीन मोल O₂ मिलती है, अतः 0.1 मोल से 0.15 मोल O₂ = 0.15 × 22.4 = 3.36 L मिलती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-277","question":"In the electrolytic extraction of aluminium, alumina (Al₂O₃) is dissolved in molten cryolite mainly to:","options":["lower the melting point and raise the conductivity of the melt","remove the silica impurity present in the bauxite ore itself","reduce the alumina chemically to aluminium metal at the cathode","keep the carbon lining of the tank from being oxidised by air"],"answer":0,"explanation":"Pure alumina melts at over 2000 °C and conducts poorly. Dissolving it in molten cryolite (Na₃AlF₆) lets electrolysis run near 950 °C, saving energy.","difficulty":"hard","questionHi":"ऐलुमिनियम के विद्युत अपघटनी निष्कर्षण में ऐलुमिना (Al₂O₃) को पिघले क्रायोलाइट में मुख्यतः किसलिए घोला जाता है?","optionsHi":["गलनांक घटाने और गलित मिश्रण की चालकता बढ़ाने के लिए","स्वयं बॉक्साइट अयस्क में उपस्थित सिलिका अशुद्धि हटाने के लिए","ऐलुमिना को कैथोड पर रासायनिक रूप से ऐलुमिनियम धातु में अपचयित करने के लिए","टंकी के कार्बन अस्तर को वायु से ऑक्सीकृत होने से बचाने के लिए"],"explanationHi":"शुद्ध ऐलुमिना 2000 °C से अधिक पर पिघलता है और कम चालक है। उसे पिघले क्रायोलाइट (Na₃AlF₆) में घोलने से विद्युत अपघटन लगभग 950 °C पर हो जाता है, जिससे ऊर्जा की बचत होती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-278","question":"In the electrolytic extraction of aluminium, the carbon anodes have to be replaced from time to time because:","options":["they dissolve slowly in the molten aluminium collecting at the bottom","molten cryolite slowly dissolves them during the long electrolysis","they get coated with an insulating layer of alumina after some hours","oxygen released at the anode burns them away as carbon dioxide"],"answer":3,"explanation":"Oxygen is liberated at the anode, and at about 950 °C it oxidises the graphite to CO and CO₂, so the anodes are consumed. The cathode is the carbon lining of the tank on which aluminium collects.","difficulty":"very-hard","questionHi":"ऐलुमिनियम के विद्युत अपघटनी निष्कर्षण में कार्बन ऐनोडों को समय-समय पर बदलना पड़ता है, क्योंकि:","optionsHi":["वे तली में एकत्र गलित ऐलुमिनियम में धीरे-धीरे घुल जाते हैं","लंबे विद्युत अपघटन के दौरान पिघला क्रायोलाइट उन्हें धीरे-धीरे घोल देता है","कुछ घंटों बाद उन पर ऐलुमिना की विद्युतरोधी परत चढ़ जाती है","ऐनोड पर मुक्त ऑक्सीजन उन्हें कार्बन डाइऑक्साइड के रूप में जला देती है"],"explanationHi":"ऐनोड पर ऑक्सीजन मुक्त होती है और लगभग 950 °C पर वह ग्रेफ़ाइट को CO और CO₂ में ऑक्सीकृत कर देती है, इसलिए ऐनोड खर्च होते जाते हैं। कैथोड टंकी का कार्बन अस्तर है जिस पर ऐलुमिनियम एकत्र होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-279","question":"In the blast furnace for iron, limestone is added to remove the silica (SiO₂) of the ore. The product that forms and floats on the molten iron is:","options":["calcium oxide (quicklime)","calcium silicate (slag)","calcium carbide","iron silicate"],"answer":1,"explanation":"Limestone decomposes to CaO, which combines with acidic silica: CaO + SiO₂ → CaSiO₃. This molten calcium silicate (slag) is lighter than iron, floats on it and is tapped off separately.","difficulty":"very-hard","questionHi":"लोहे की धमन भट्ठी में अयस्क की सिलिका (SiO₂) हटाने के लिए चूना पत्थर डाला जाता है। बनने वाला जो उत्पाद गलित लोहे पर तैरता है, वह है:","optionsHi":["कैल्सियम ऑक्साइड (अनबुझा चूना)","कैल्सियम सिलिकेट (धातुमल)","कैल्सियम कार्बाइड","आयरन सिलिकेट"],"explanationHi":"चूना पत्थर अपघटित होकर CaO देता है, जो अम्लीय सिलिका से संयोग करता है: CaO + SiO₂ → CaSiO₃। यह गलित कैल्सियम सिलिकेट (धातुमल) लोहे से हल्का होता है, उस पर तैरता है और अलग से निकाल लिया जाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-280","question":"German silver, used for utensils and ornaments, is an alloy of:","options":["silver, copper and zinc","silver, nickel and tin","copper, zinc and nickel","copper, tin and silver"],"answer":2,"explanation":"German silver (nickel silver) has no silver at all; it is about 60% copper with zinc and nickel, and only looks like silver.","difficulty":"hard","questionHi":"बर्तनों और आभूषणों में प्रयुक्त जर्मन सिल्वर किन धातुओं की मिश्रधातु है?","optionsHi":["चाँदी, ताँबा और जस्ता","चाँदी, निकल और टिन","ताँबा, जस्ता और निकल","ताँबा, टिन और चाँदी"],"explanationHi":"जर्मन सिल्वर (निकल सिल्वर) में चाँदी बिल्कुल नहीं होती; इसमें लगभग 60% ताँबा तथा जस्ता और निकल होते हैं और वह केवल चाँदी जैसी दिखती है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-281","question":"Which of these alloys is light and strong, and so is used in the bodies of aircraft?","options":["Duralumin","Brass","Solder","Bell metal"],"answer":0,"explanation":"Duralumin is aluminium with small amounts of copper, magnesium and manganese; it is as strong as mild steel but far lighter. Brass, solder and bell metal are heavy copper- or lead-based alloys.","difficulty":"moderate","questionHi":"इनमें से कौन-सी मिश्रधातु हल्की और मज़बूत होने के कारण वायुयानों की बनावट में प्रयुक्त होती है?","optionsHi":["ड्यूरैलुमिन","पीतल","सोल्डर","घंटा धातु"],"explanationHi":"ड्यूरैलुमिन में ऐलुमिनियम के साथ थोड़ा ताँबा, मैग्नीशियम और मैंगनीज़ होता है; यह मृदु इस्पात जितना मज़बूत पर कहीं हल्का होता है। पीतल, सोल्डर और घंटा धातु भारी ताँबा या सीसा आधारित मिश्रधातुएँ हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-282","question":"Which of these iron materials contains the highest percentage of carbon?","options":["Wrought iron","Mild steel","Cast iron","Stainless steel"],"answer":2,"explanation":"Cast iron has about 2-4.5% carbon, which makes it hard but brittle. Steels have about 0.1-1.5% carbon and wrought iron less than 0.2%.","difficulty":"hard","questionHi":"लोहे की इन सामग्रियों में से किसमें कार्बन का प्रतिशत सबसे अधिक होता है?","optionsHi":["पिटवाँ लोहा","मृदु इस्पात","ढलवाँ लोहा","स्टेनलेस स्टील"],"explanationHi":"ढलवाँ लोहे में लगभग 2-4.5% कार्बन होता है, जो उसे कठोर पर भंगुर बनाता है। इस्पात में लगभग 0.1-1.5% और पिटवाँ लोहे में 0.2% से कम कार्बन होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-283","question":"Iron does not dissolve in cold concentrated nitric acid even though it lies above hydrogen in the reactivity series. The reason is that:","options":["nitric acid is too weak an acid to react with any metal when it is concentrated","a thin protective layer of oxide forms on the iron surface (passivity)","the gas formed in the reaction coats the iron and stops the reaction completely","concentrated nitric acid is almost free of hydrogen ions, so it cannot attack metals"],"answer":1,"explanation":"Concentrated nitric acid is a strong oxidising agent that quickly coats iron with a thin, unreactive oxide film, and this passive layer stops further reaction. This is why iron containers can carry the concentrated acid.","difficulty":"very-hard","questionHi":"हाइड्रोजन से ऊपर क्रियाशीलता श्रेणी में होने पर भी लोहा ठंडे सांद्र नाइट्रिक अम्ल में नहीं घुलता। इसका कारण है:","optionsHi":["सांद्र होने पर नाइट्रिक अम्ल इतना दुर्बल अम्ल हो जाता है कि वह किसी धातु से अभिक्रिया नहीं करता","लोहे की सतह पर ऑक्साइड की पतली सुरक्षात्मक परत बन जाती है (निष्क्रियता)","अभिक्रिया में बनी गैस लोहे को ढककर अभिक्रिया पूरी तरह रोक देती है","सांद्र नाइट्रिक अम्ल में हाइड्रोजन आयन लगभग नहीं होते, इसलिए वह धातुओं पर क्रिया नहीं कर सकता"],"explanationHi":"सांद्र नाइट्रिक अम्ल प्रबल ऑक्सीकारक है जो लोहे पर शीघ्र ही ऑक्साइड की पतली, अक्रिय परत चढ़ा देता है और यह निष्क्रिय परत आगे की अभिक्रिया रोक देती है। इसीलिए लोहे के पात्रों में सांद्र अम्ल ढोया जा सकता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-284","question":"Which metal reacts with steam but does not react with cold water?","options":["Sodium","Calcium","Copper","Iron"],"answer":3,"explanation":"Iron reacts with steam to form Fe₃O₄ and hydrogen, but it does not react with cold water. Sodium and calcium react with cold water, and copper reacts with neither cold water nor steam.","difficulty":"hard","questionHi":"कौन-सी धातु भाप से अभिक्रिया करती है पर ठंडे जल से नहीं?","optionsHi":["सोडियम","कैल्सियम","ताँबा","लोहा"],"explanationHi":"लोहा भाप से अभिक्रिया करके Fe₃O₄ और हाइड्रोजन बनाता है, पर ठंडे जल से अभिक्रिया नहीं करता। सोडियम और कैल्सियम ठंडे जल से अभिक्रिया करते हैं तथा ताँबा न ठंडे जल से, न भाप से।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-285","question":"How many of these statements are correct? I. Zinc oxide is amphoteric. II. Aluminium reacts with both dilute hydrochloric acid and sodium hydroxide solution, releasing hydrogen. III. Copper displaces zinc from zinc sulphate solution. IV. Iron treated with concentrated nitric acid becomes passive and stops reacting.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and IV are correct. Copper is less reactive than zinc, so it cannot displace zinc from its salt solution; the reverse reaction occurs.","difficulty":"very-hard","questionHi":"इनमें से कितने कथन सही हैं? I. जिंक ऑक्साइड उभयधर्मी है। II. ऐलुमिनियम तनु हाइड्रोक्लोरिक अम्ल और सोडियम हाइड्रॉक्साइड विलयन दोनों से अभिक्रिया करके हाइड्रोजन मुक्त करता है। III. ताँबा जिंक सल्फ़ेट विलयन से जस्ते को विस्थापित कर देता है। IV. सांद्र नाइट्रिक अम्ल से उपचारित लोहा निष्क्रिय हो जाता है और अभिक्रिया करना बंद कर देता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चार"],"explanationHi":"I, II और IV सही हैं। ताँबा जस्ते से कम क्रियाशील है, इसलिए वह उसके लवण विलयन से जस्ते को विस्थापित नहीं कर सकता; उलटी अभिक्रिया होती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-286","question":"What is the oxidation number of chromium in potassium dichromate, K₂Cr₂O₇?","options":["+3","+7","+12","+6"],"answer":3,"explanation":"The charges must add to zero: 2(+1) + 2x + 7(−2) = 0, so 2x = 12 and x = +6. The value +12 is the total for two chromium atoms, not one.","difficulty":"hard","questionHi":"पोटैशियम डाइक्रोमेट, K₂Cr₂O₇ में क्रोमियम की ऑक्सीकरण संख्या कितनी है?","optionsHi":["+3","+7","+12","+6"],"explanationHi":"आवेशों का योग शून्य होना चाहिए: 2(+1) + 2x + 7(−2) = 0, अतः 2x = 12 और x = +6। +12 दो क्रोमियम परमाणुओं का कुल मान है, एक का नहीं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-287","question":"When silver bromide is exposed to sunlight it turns grey: 2AgBr → 2Ag + Br₂. This is an example of:","options":["thermal decomposition","photolytic decomposition","electrolytic decomposition","double displacement"],"answer":1,"explanation":"Here light energy breaks the compound down into silver and bromine, so it is a photolytic (photochemical) decomposition. This is the basis of black-and-white photography.","difficulty":"moderate","questionHi":"सिल्वर ब्रोमाइड को धूप में रखने पर वह भूरा-स्लेटी हो जाता है: 2AgBr → 2Ag + Br₂। यह किसका उदाहरण है?","optionsHi":["ऊष्मीय अपघटन","प्रकाश अपघटन","विद्युत अपघटन","द्विविस्थापन"],"explanationHi":"यहाँ प्रकाश ऊर्जा यौगिक को चाँदी और ब्रोमीन में तोड़ देती है, इसलिए यह प्रकाश (प्रकाश-रासायनिक) अपघटन है। श्वेत-श्याम फ़ोटोग्राफ़ी इसी पर आधारित है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-288","question":"A yellow precipitate forms when potassium iodide solution is added to lead nitrate solution. The precipitate is:","options":["lead iodide (PbI₂)","lead chloride (PbCl₂)","potassium nitrate (KNO₃)","lead oxide (PbO)"],"answer":0,"explanation":"Pb(NO₃)₂ + 2KI → PbI₂ + 2KNO₃. Lead iodide is insoluble and bright yellow, while potassium nitrate stays dissolved. Lead chloride would be white.","difficulty":"hard","questionHi":"पोटैशियम आयोडाइड विलयन को लेड नाइट्रेट विलयन में मिलाने पर पीला अवक्षेप बनता है। यह अवक्षेप है:","optionsHi":["लेड आयोडाइड (PbI₂)","लेड क्लोराइड (PbCl₂)","पोटैशियम नाइट्रेट (KNO₃)","लेड ऑक्साइड (PbO)"],"explanationHi":"Pb(NO₃)₂ + 2KI → PbI₂ + 2KNO₃। लेड आयोडाइड अघुलनशील और चमकीला पीला होता है, जबकि पोटैशियम नाइट्रेट घुला रहता है। लेड क्लोराइड श्वेत होता।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-289","question":"A salt solution gives a pale yellow precipitate with silver nitrate solution, which dissolves only partly in dilute ammonia. The anion present is:","options":["chloride","iodide","bromide","nitrate"],"answer":2,"explanation":"Silver bromide is pale yellow and only sparingly soluble in dilute ammonia. Silver chloride is white and dissolves readily, silver iodide is a deeper yellow and insoluble, and nitrates give no precipitate.","difficulty":"hard","questionHi":"एक लवण विलयन सिल्वर नाइट्रेट विलयन के साथ हल्का पीला अवक्षेप देता है, जो तनु अमोनिया में केवल आंशिक रूप से घुलता है। उपस्थित ऋणायन है:","optionsHi":["क्लोराइड","आयोडाइड","ब्रोमाइड","नाइट्रेट"],"explanationHi":"सिल्वर ब्रोमाइड हल्का पीला होता है और तनु अमोनिया में अल्प घुलनशील है। सिल्वर क्लोराइड श्वेत है और आसानी से घुल जाता है, सिल्वर आयोडाइड गहरा पीला और अघुलनशील है, तथा नाइट्रेट कोई अवक्षेप नहीं देते।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-290","question":"The bright green colour in fireworks is produced by the salts of:","options":["strontium","calcium","sodium","barium"],"answer":3,"explanation":"Barium compounds give an apple-green flame. Strontium gives crimson red, calcium brick red and sodium golden yellow.","difficulty":"hard","questionHi":"आतिशबाज़ी में चमकीला हरा रंग किसके लवणों से उत्पन्न होता है?","optionsHi":["स्ट्रॉन्शियम","कैल्सियम","सोडियम","बेरियम"],"explanationHi":"बेरियम यौगिक सेब जैसी हरी ज्वाला देते हैं। स्ट्रॉन्शियम गहरी लाल, कैल्सियम ईंट जैसी लाल और सोडियम सुनहरी पीली ज्वाला देता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-291","question":"On adding sodium hydroxide solution to a salt solution, a dirty-green precipitate forms which turns reddish-brown on standing in air. The cation present is:","options":["Fe²⁺","Cu²⁺","Ni²⁺","Zn²⁺"],"answer":0,"explanation":"Fe²⁺ gives dirty-green Fe(OH)₂, which is oxidised by air to reddish-brown Fe(OH)₃. Cu²⁺ gives a blue precipitate, Zn²⁺ a white one, and nickel hydroxide is green but does not change colour.","difficulty":"very-hard","questionHi":"किसी लवण विलयन में सोडियम हाइड्रॉक्साइड विलयन मिलाने पर गंदा हरा अवक्षेप बनता है, जो वायु में रखने पर लाल-भूरा हो जाता है। उपस्थित धनायन है:","optionsHi":["Fe²⁺","Cu²⁺","Ni²⁺","Zn²⁺"],"explanationHi":"Fe²⁺ गंदा हरा Fe(OH)₂ देता है, जो वायु में ऑक्सीकृत होकर लाल-भूरा Fe(OH)₃ बन जाता है। Cu²⁺ नीला अवक्षेप, Zn²⁺ श्वेत अवक्षेप देता है, और निकल हाइड्रॉक्साइड हरा होता है पर रंग नहीं बदलता।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-292","question":"A tin-plated iron can and a galvanised (zinc-coated) iron bucket both get scratched through the coating and are exposed to moist air. Which statement is correct?","options":["Both rust at the same rate, because bare iron is exposed to moist air in each case","The can's iron rusts faster as tin is less reactive, but zinc keeps protecting the bucket's iron","The bucket's iron rusts faster because zinc is less reactive than iron, so zinc cannot help","Neither rusts, because both tin and zinc form protective oxide layers over the scratch"],"answer":1,"explanation":"Where the coating is broken, the more reactive metal corrodes first. Zinc is more reactive than iron, so it corrodes instead and still protects the iron; tin is less reactive, so iron becomes the corroding metal and rusts even faster than bare iron.","difficulty":"very-hard","questionHi":"एक टिन-लेपित लोहे के डिब्बे और एक जस्तित (जस्ते की परत वाली) लोहे की बाल्टी, दोनों की परत खरोंच से कट जाती है और वे नम वायु में रहते हैं। कौन-सा कथन सही है?","optionsHi":["दोनों समान गति से जंग खाते हैं, क्योंकि दोनों में खुला लोहा नम वायु के संपर्क में है","डिब्बे का लोहा तेज़ी से जंग खाता है क्योंकि टिन कम क्रियाशील है, पर जस्ता बाल्टी के लोहे की रक्षा करता रहता है","बाल्टी का लोहा तेज़ी से जंग खाता है क्योंकि जस्ता लोहे से कम क्रियाशील है, इसलिए जस्ता सहायक नहीं होता","दोनों में जंग नहीं लगता, क्योंकि टिन और जस्ता दोनों खरोंच पर सुरक्षात्मक ऑक्साइड परतें बना देते हैं"],"explanationHi":"जहाँ परत टूटी हो वहाँ अधिक क्रियाशील धातु पहले संक्षारित होती है। जस्ता लोहे से अधिक क्रियाशील है, इसलिए वही संक्षारित होकर लोहे की रक्षा करता रहता है; टिन कम क्रियाशील है, इसलिए लोहा संक्षारित होने वाली धातु बन जाता है और खुले लोहे से भी तेज़ जंग खाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-293","question":"During discharge of a lead storage battery (car battery), the density of the sulphuric acid electrolyte:","options":["increases, because the lead sulphate formed dissolves in the acid","stays constant, because only the plates and not the acid react","decreases, because sulphuric acid is used up and water forms","increases, because water is consumed at both of the plates"],"answer":2,"explanation":"On discharge both plates change to PbSO₄: Pb + PbO₂ + 2H₂SO₄ → 2PbSO₄ + 2H₂O. Acid is consumed and water formed, so the electrolyte becomes less dense; the density is used as a measure of the state of charge.","difficulty":"very-hard","questionHi":"सीसा संचायक बैटरी (कार की बैटरी) के विसर्जन के समय सल्फ़्यूरिक अम्ल इलेक्ट्रोलाइट का घनत्व:","optionsHi":["बढ़ता है, क्योंकि बना लेड सल्फ़ेट अम्ल में घुल जाता है","स्थिर रहता है, क्योंकि केवल प्लेटें अभिक्रिया करती हैं, अम्ल नहीं","घटता है, क्योंकि सल्फ़्यूरिक अम्ल खर्च होता है और जल बनता है","बढ़ता है, क्योंकि दोनों प्लेटों पर जल खर्च होता है"],"explanationHi":"विसर्जन पर दोनों प्लेटें PbSO₄ में बदल जाती हैं: Pb + PbO₂ + 2H₂SO₄ → 2PbSO₄ + 2H₂O। अम्ल खर्च होता है और जल बनता है, इसलिए इलेक्ट्रोलाइट कम सघन हो जाता है; घनत्व आवेश की स्थिति का माप होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-294","question":"In a dry (Leclanché) cell, the zinc container acts as the:","options":["negative electrode (anode), because zinc is oxidised","positive electrode (cathode), because zinc is reduced","electrolyte, because zinc ions carry the current","oxidising agent that takes electrons from the carbon rod"],"answer":0,"explanation":"Zinc loses electrons (Zn → Zn²⁺ + 2e⁻), so the zinc casing is the negative terminal (anode). The central carbon rod is the positive terminal, and the electrolyte is a paste of NH₄Cl and ZnCl₂.","difficulty":"hard","questionHi":"शुष्क सेल (लेक्लांशे सेल) में जस्ते का पात्र क्या कार्य करता है?","optionsHi":["ऋण इलेक्ट्रोड (ऐनोड), क्योंकि जस्ता ऑक्सीकृत होता है","धन इलेक्ट्रोड (कैथोड), क्योंकि जस्ता अपचयित होता है","इलेक्ट्रोलाइट, क्योंकि जस्ते के आयन धारा ले जाते हैं","ऑक्सीकारक जो कार्बन छड़ से इलेक्ट्रॉन लेता है"],"explanationHi":"जस्ता इलेक्ट्रॉन खोता है (Zn → Zn²⁺ + 2e⁻), इसलिए जस्ते का आवरण ऋण टर्मिनल (ऐनोड) है। मध्य की कार्बन छड़ धन टर्मिनल है और इलेक्ट्रोलाइट NH₄Cl तथा ZnCl₂ की लेई है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-295","question":"Copper sulphate solution is electrolysed using copper electrodes. As the electrolysis continues, the blue colour of the solution:","options":["fades gradually because Cu²⁺ ions are removed from the solution","deepens gradually because more Cu²⁺ ions pass into the solution","turns green because copper oxide is formed on the electrodes","stays almost unchanged, as Cu dissolves at the anode as fast as it deposits"],"answer":3,"explanation":"At the cathode Cu²⁺ + 2e⁻ → Cu, and at the copper anode Cu → Cu²⁺ + 2e⁻ at the same rate, so the Cu²⁺ concentration stays the same. With inert platinum electrodes the blue colour would fade instead.","difficulty":"very-hard","questionHi":"कॉपर सल्फ़ेट विलयन का विद्युत अपघटन ताँबे के इलेक्ट्रोडों से किया जाता है। विद्युत अपघटन चलते रहने पर विलयन का नीला रंग:","optionsHi":["विलयन से Cu²⁺ आयन हटते जाने के कारण धीरे-धीरे फीका पड़ता है","विलयन में और Cu²⁺ आयन जाने के कारण धीरे-धीरे गहरा होता है","इलेक्ट्रोडों पर कॉपर ऑक्साइड बनने के कारण हरा हो जाता है","लगभग वैसा ही रहता है, क्योंकि ऐनोड पर Cu उतनी ही तेज़ी से घुलता है जितनी तेज़ी से जमता है"],"explanationHi":"कैथोड पर Cu²⁺ + 2e⁻ → Cu और ताँबे के ऐनोड पर Cu → Cu²⁺ + 2e⁻ समान दर से होता है, इसलिए Cu²⁺ की सांद्रता वही रहती है। अक्रिय प्लैटिनम इलेक्ट्रोड होने पर नीला रंग फीका पड़ता।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-296","question":"Which of these ores is a sulphide ore?","options":["Bauxite","Haematite","Zinc blende","Calamine"],"answer":2,"explanation":"Zinc blende is zinc sulphide (ZnS). Bauxite (Al₂O₃·2H₂O) and haematite (Fe₂O₃) are oxide ores, and calamine (ZnCO₃) is a carbonate.","difficulty":"moderate","questionHi":"इनमें से कौन-सा अयस्क सल्फ़ाइड अयस्क है?","optionsHi":["बॉक्साइट","हेमेटाइट","ज़िंक ब्लेंड","कैलामाइन"],"explanationHi":"ज़िंक ब्लेंड जिंक सल्फ़ाइड (ZnS) है। बॉक्साइट (Al₂O₃·2H₂O) और हेमेटाइट (Fe₂O₃) ऑक्साइड अयस्क हैं तथा कैलामाइन (ZnCO₃) कार्बोनेट है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-297","question":"Which metal reacts with both dilute hydrochloric acid and sodium hydroxide solution, releasing hydrogen gas?","options":["Iron","Aluminium","Copper","Silver"],"answer":1,"explanation":"Aluminium is amphoteric in behaviour: 2Al + 6HCl → 2AlCl₃ + 3H₂ and 2Al + 2NaOH + 2H₂O → 2NaAlO₂ + 3H₂. Iron reacts only with the acid, and copper and silver with neither.","difficulty":"hard","questionHi":"कौन-सी धातु तनु हाइड्रोक्लोरिक अम्ल और सोडियम हाइड्रॉक्साइड विलयन दोनों से अभिक्रिया करके हाइड्रोजन गैस मुक्त करती है?","optionsHi":["लोहा","ऐलुमिनियम","ताँबा","चाँदी"],"explanationHi":"ऐलुमिनियम उभयधर्मी व्यवहार दिखाता है: 2Al + 6HCl → 2AlCl₃ + 3H₂ तथा 2Al + 2NaOH + 2H₂O → 2NaAlO₂ + 3H₂। लोहा केवल अम्ल से अभिक्रिया करता है, और ताँबा तथा चाँदी किसी से नहीं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-298","question":"Which of these non-metals exists as a liquid at room temperature?","options":["Iodine","Chlorine","Phosphorus","Bromine"],"answer":3,"explanation":"Bromine is the only non-metal that is a liquid at room temperature (a dark red-brown, volatile liquid). Iodine and phosphorus are solids and chlorine is a gas, while the only liquid metal is mercury.","difficulty":"moderate","questionHi":"इनमें से कौन-सी अधातु कमरे के ताप पर द्रव अवस्था में पाई जाती है?","optionsHi":["आयोडीन","क्लोरीन","फ़ॉस्फ़ोरस","ब्रोमीन"],"explanationHi":"ब्रोमीन ही एकमात्र अधातु है जो कमरे के ताप पर द्रव है (गहरे लाल-भूरे रंग का वाष्पशील द्रव)। आयोडीन और फ़ॉस्फ़ोरस ठोस हैं तथा क्लोरीन गैस है, जबकि एकमात्र द्रव धातु पारा है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-299","question":"In a safety match, the red phosphorus is present:","options":["on the match head along with the oxidiser and sulphur","on the stick, just below the head of the match","on the striking strip at the side of the box","mixed with the wax coating that covers the stick"],"answer":2,"explanation":"The head of a safety match holds an oxidiser (potassium chlorate) with antimony sulphide, while the red phosphorus is in the striking strip of the box. Friction produces a little white phosphorus, which ignites the head.","difficulty":"hard","questionHi":"सुरक्षा माचिस में लाल फ़ॉस्फ़ोरस कहाँ होता है?","optionsHi":["तीली के सिरे पर ऑक्सीकारक और सल्फ़र के साथ","तीली पर माचिस के सिरे के ठीक नीचे","डिब्बे की बगल की घर्षण पट्टी पर","तीली को ढकने वाली मोम की परत में मिला हुआ"],"explanationHi":"सुरक्षा माचिस के सिरे में ऑक्सीकारक (पोटैशियम क्लोरेट) और ऐंटिमनी सल्फ़ाइड होता है, जबकि लाल फ़ॉस्फ़ोरस डिब्बे की घर्षण पट्टी में होता है। घर्षण से थोड़ा श्वेत फ़ॉस्फ़ोरस बनता है, जो सिरे को जला देता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-300","question":"An alloy in which one of the metals is mercury is called:","options":["amalgam","solder","brass","bronze"],"answer":0,"explanation":"Mercury forms alloys called amalgams with many metals; dental amalgam contains silver and tin with mercury. Solder is lead-tin, brass is copper-zinc and bronze is copper-tin.","difficulty":"moderate","questionHi":"जिस मिश्रधातु में एक धातु पारा होती है, उसे क्या कहते हैं?","optionsHi":["अमलगम","सोल्डर","पीतल","काँसा"],"explanationHi":"पारा अनेक धातुओं के साथ अमलगम कहलाने वाली मिश्रधातुएँ बनाता है; दंत अमलगम में पारे के साथ चाँदी और टिन होते हैं। सोल्डर सीसा-टिन, पीतल ताँबा-जस्ता और काँसा ताँबा-टिन की मिश्रधातु है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-301","question":"In the electrolysis of molten sodium chloride, what is obtained at the cathode and at the anode?","options":["Chlorine at the cathode and sodium at the anode","Sodium at the cathode and chlorine at the anode","Hydrogen at the cathode and chlorine at the anode","Sodium at the cathode and oxygen at the anode"],"answer":1,"explanation":"In the molten salt only Na⁺ and Cl⁻ ions are present: Na⁺ gains an electron at the cathode to form sodium metal, and Cl⁻ loses one at the anode to give chlorine gas. Hydrogen and oxygen appear only when water is present, as in brine.","difficulty":"hard","questionHi":"गलित सोडियम क्लोराइड के विद्युत अपघटन में कैथोड और ऐनोड पर क्या प्राप्त होता है?","optionsHi":["कैथोड पर क्लोरीन और ऐनोड पर सोडियम","कैथोड पर सोडियम और ऐनोड पर क्लोरीन","कैथोड पर हाइड्रोजन और ऐनोड पर क्लोरीन","कैथोड पर सोडियम और ऐनोड पर ऑक्सीजन"],"explanationHi":"गलित लवण में केवल Na⁺ और Cl⁻ आयन होते हैं: Na⁺ कैथोड पर इलेक्ट्रॉन पाकर सोडियम धातु बनाता है और Cl⁻ ऐनोड पर इलेक्ट्रॉन खोकर क्लोरीन गैस देता है। हाइड्रोजन और ऑक्सीजन तभी आती हैं जब जल उपस्थित हो, जैसे नमकीन जल (ब्राइन) में।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-302","question":"How many structural isomers does pentane, C₅H₁₂, have (counting pentane itself)?","options":["2","3","4","5"],"answer":1,"explanation":"The three isomers are n-pentane, isopentane (2-methylbutane) and neopentane (2,2-dimethylpropane). Butane has two isomers and hexane has five.","difficulty":"hard","questionHi":"पेन्टेन, C₅H₁₂ के कितने संरचनात्मक समावयव होते हैं (पेन्टेन को भी गिनते हुए)?","optionsHi":["2","3","4","5"],"explanationHi":"तीन समावयव हैं: n-पेन्टेन, आइसोपेन्टेन (2-मेथिलब्यूटेन) और निओपेन्टेन (2,2-डाइमेथिलप्रोपेन)। ब्यूटेन के दो और हेक्सेन के पाँच समावयव होते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-303","question":"How many shared electron pairs (counting each pair of a double bond separately) are there in one molecule of ethene, C₂H₄?","options":["4","5","6","7"],"answer":2,"explanation":"Ethene has one C=C double bond (2 shared pairs) and four C–H single bonds (4 pairs), giving 2 + 4 = 6 shared pairs. Ethyne would have 3 + 2 = 5.","difficulty":"hard","questionHi":"एथीन, C₂H₄ के एक अणु में कितने साझे इलेक्ट्रॉन युग्म होते हैं (द्विबंध के प्रत्येक युग्म को अलग गिनते हुए)?","optionsHi":["4","5","6","7"],"explanationHi":"एथीन में एक C=C द्विबंध (2 साझे युग्म) और चार C–H एकल बंध (4 युग्म) होते हैं, अतः 2 + 4 = 6 साझे युग्म हुए। एथाइन में 3 + 2 = 5 होते।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-304","question":"An alkyne molecule contains five carbon atoms. How many hydrogen atoms does it have?","options":["8","10","12","6"],"answer":0,"explanation":"Alkynes follow the general formula CₙH₂ₙ₋₂, so for n = 5 the formula is C₅H₈. C₅H₁₀ would be an alkene and C₅H₁₂ an alkane.","difficulty":"hard","questionHi":"एक ऐल्काइन अणु में पाँच कार्बन परमाणु हैं। उसमें कितने हाइड्रोजन परमाणु होंगे?","optionsHi":["8","10","12","6"],"explanationHi":"ऐल्काइनों का सामान्य सूत्र CₙH₂ₙ₋₂ होता है, इसलिए n = 5 के लिए सूत्र C₅H₈ है। C₅H₁₀ ऐल्कीन और C₅H₁₂ ऐल्केन होता।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-305","question":"Ethanol (CH₃CH₂OH) and dimethyl ether (CH₃OCH₃) are best described as:","options":["homologues","chain isomers","functional isomers","position isomers"],"answer":2,"explanation":"Both have the molecular formula C₂H₆O but different functional groups (alcohol and ether), so they are functional isomers. Homologues differ by a CH₂ unit.","difficulty":"hard","questionHi":"एथेनॉल (CH₃CH₂OH) और डाइमेथिल ईथर (CH₃OCH₃) को सबसे उपयुक्त रूप से क्या कहा जाएगा?","optionsHi":["सजातीय (होमोलॉग)","शृंखला समावयव","क्रियात्मक समूह समावयव","स्थिति समावयव"],"explanationHi":"दोनों का आणविक सूत्र C₂H₆O है पर क्रियात्मक समूह अलग (ऐल्कोहॉल और ईथर) हैं, इसलिए ये क्रियात्मक समूह समावयव हैं। सजातीय यौगिक एक CH₂ इकाई से भिन्न होते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-306","question":"In making ethyl ethanoate from ethanol and ethanoic acid, a few drops of concentrated sulphuric acid are added. Its role is as a:","options":["reducing agent that removes oxygen from ethanol","reactant that becomes part of the ester formed","base that neutralises the ethanoic acid used","catalyst that also absorbs the water formed"],"answer":3,"explanation":"Esterification is a reversible reaction, and concentrated H₂SO₄ speeds it up as a catalyst and also takes up the water produced, which pushes the equilibrium towards the ester.","difficulty":"hard","questionHi":"एथेनॉल और एथेनॉइक अम्ल से एथिल एथेनोएट बनाने में सांद्र सल्फ़्यूरिक अम्ल की कुछ बूँदें डाली जाती हैं। इसकी भूमिका है:","optionsHi":["अपचायक जो एथेनॉल से ऑक्सीजन हटाता है","अभिकारक जो बने एस्टर का भाग बन जाता है","क्षार जो प्रयुक्त एथेनॉइक अम्ल को उदासीन करता है","उत्प्रेरक जो बने जल को भी सोख लेता है"],"explanationHi":"एस्टरीकरण उत्क्रमणीय अभिक्रिया है, और सांद्र H₂SO₄ उत्प्रेरक के रूप में उसे तेज़ करता है तथा बने जल को सोख लेता है, जिससे साम्य एस्टर की ओर बढ़ जाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-307","question":"Which plastic cannot be softened and remoulded once it has set, and is used for electrical switches and plugs?","options":["Polythene","PVC","Bakelite","Nylon"],"answer":2,"explanation":"Bakelite is a thermosetting plastic: its cross-linked structure sets permanently on heating and it does not conduct electricity. Polythene, PVC and nylon are thermoplastics that soften on heating.","difficulty":"moderate","questionHi":"कौन-सा प्लास्टिक एक बार जम जाने पर नरम करके दोबारा ढाला नहीं जा सकता और विद्युत स्विचों तथा प्लगों में प्रयुक्त होता है?","optionsHi":["पॉलिथीन","PVC","बेकेलाइट","नायलॉन"],"explanationHi":"बेकेलाइट ऊष्मासह (थर्मोसेटिंग) प्लास्टिक है: उसकी जालीनुमा संरचना गर्म करने पर स्थायी रूप से जम जाती है और वह विद्युत का चालन नहीं करता। पॉलिथीन, PVC और नायलॉन ऊष्मानम्य (थर्मोप्लास्टिक) हैं जो गर्म करने पर नरम होते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-308","question":"The links joining the units of nylon are of the same type as the links joining amino acids in proteins. They are:","options":["ester linkages (–COO–)","amide linkages (–CONH–)","ether linkages (–O–)","glycosidic linkages"],"answer":1,"explanation":"Nylon is a polyamide, with –CONH– links between its units, just like the peptide bonds of proteins. Terylene is a polyester, with ester links.","difficulty":"hard","questionHi":"नायलॉन की इकाइयों को जोड़ने वाले बंधन उसी प्रकार के हैं जैसे प्रोटीनों में अमीनो अम्लों को जोड़ने वाले बंधन। ये हैं:","optionsHi":["एस्टर बंधन (–COO–)","ऐमाइड बंधन (–CONH–)","ईथर बंधन (–O–)","ग्लाइकोसिडिक बंधन"],"explanationHi":"नायलॉन पॉलीऐमाइड है, जिसकी इकाइयों के बीच प्रोटीनों के पेप्टाइड बंधों जैसे –CONH– बंधन होते हैं। टेरिलीन पॉलिएस्टर है, जिसमें एस्टर बंधन होते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-309","question":"In the cleansing action of soap, the long hydrocarbon tail of the soap molecule:","options":["reacts chemically with the grease and turns it into a salt","is attracted to water and forms the outer surface of the micelle","dissolves in water and carries the dirt along with it","is attracted to oil or grease and forms the inside of the micelle"],"answer":3,"explanation":"The hydrocarbon tail is hydrophobic, so it dissolves in the oily dirt and forms the core of a micelle, while the ionic heads face the water outside. The micelle then carries the dirt away on rinsing.","difficulty":"very-hard","questionHi":"साबुन की सफ़ाई क्रिया में साबुन अणु की लंबी हाइड्रोकार्बन पूँछ:","optionsHi":["ग्रीज़ से रासायनिक अभिक्रिया करके उसे लवण में बदल देती है","जल की ओर आकर्षित होती है और मिसेल की बाहरी सतह बनाती है","जल में घुलकर मैल को अपने साथ ले जाती है","तेल या ग्रीज़ की ओर आकर्षित होती है और मिसेल का भीतरी भाग बनाती है"],"explanationHi":"हाइड्रोकार्बन पूँछ जलविरोधी होती है, इसलिए वह तैलीय मैल में घुलकर मिसेल का क्रोड बनाती है, जबकि आयनिक सिर बाहर जल की ओर रहते हैं। धोने पर मिसेल मैल को बहा ले जाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-310","question":"A strong-smelling compound, ethanethiol, is added to LPG in cylinders so that:","options":["a leak of the gas can be detected by its smell","the gas burns with a bluer and hotter flame","the gas does not freeze in cold weather","the gas becomes lighter than the surrounding air"],"answer":0,"explanation":"LPG itself is almost odourless, so a leak would go unnoticed. The foul-smelling ethanethiol (ethyl mercaptan) gives a warning at very low concentration.","difficulty":"moderate","questionHi":"सिलेंडरों में LPG के साथ तीव्र गंध वाला यौगिक एथेनथायॉल मिलाया जाता है, ताकि:","optionsHi":["गैस के रिसाव का पता उसकी गंध से लग सके","गैस अधिक नीली और गर्म लौ के साथ जले","ठंडे मौसम में गैस जमे नहीं","गैस आसपास की वायु से हल्की हो जाए"],"explanationHi":"LPG स्वयं लगभग गंधहीन होती है, इसलिए रिसाव का पता नहीं चलता। दुर्गंधयुक्त एथेनथायॉल (एथिल मरकैप्टन) बहुत कम सांद्रता पर भी चेतावनी दे देता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-311","question":"Which zone of a candle flame is the hottest?","options":["The innermost dark zone near the wick","The middle bright yellow zone","The outermost thin blue zone","All the zones are equally hot"],"answer":2,"explanation":"The outermost zone gets plenty of oxygen, so combustion there is complete and the temperature is highest. The innermost zone holds unburnt wax vapour and is the coolest, and the middle zone is luminous because of glowing carbon particles.","difficulty":"hard","questionHi":"मोमबत्ती की लौ का कौन-सा क्षेत्र सबसे अधिक गर्म होता है?","optionsHi":["बाती के पास का सबसे भीतरी काला क्षेत्र","बीच का चमकीला पीला क्षेत्र","सबसे बाहरी पतला नीला क्षेत्र","सभी क्षेत्र समान रूप से गर्म होते हैं"],"explanationHi":"सबसे बाहरी क्षेत्र को पर्याप्त ऑक्सीजन मिलती है, इसलिए वहाँ दहन पूर्ण होता है और ताप सबसे अधिक होता है। सबसे भीतरी क्षेत्र में न जला मोम वाष्प होता है और वह सबसे ठंडा है, तथा बीच का क्षेत्र दहकते कार्बन कणों के कारण चमकीला होता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-312","question":"Water puts out a burning piece of wood mainly because it:","options":["cuts off the fuel by dissolving the wood","cools the wood below its ignition temperature","removes oxygen by reacting chemically with it","forms a layer of carbon dioxide over the wood"],"answer":1,"explanation":"Burning needs fuel, oxygen and a temperature above the ignition temperature. Water absorbs a lot of heat as it warms and turns into steam, bringing the wood below its ignition temperature.","difficulty":"hard","questionHi":"जलती हुई लकड़ी को पानी मुख्यतः इसलिए बुझा देता है क्योंकि वह:","optionsHi":["लकड़ी को घोलकर ईंधन को हटा देता है","लकड़ी को उसके ज्वलन ताप से नीचे ठंडा कर देता है","ऑक्सीजन से रासायनिक अभिक्रिया करके उसे हटा देता है","लकड़ी पर कार्बन डाइऑक्साइड की परत बना देता है"],"explanationHi":"दहन के लिए ईंधन, ऑक्सीजन और ज्वलन ताप से ऊपर का ताप चाहिए। गर्म होने और भाप बनने में पानी बहुत ऊष्मा सोखता है, जिससे लकड़ी का ताप ज्वलन ताप से नीचे आ जाता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-313","question":"A fuel has a calorific value of 55,000 kJ/kg. How much heat is released when 250 g of it burns completely?","options":["220,000 kJ","137,500 kJ","1,375 kJ","13,750 kJ"],"answer":3,"explanation":"250 g = 0.25 kg, so the heat released = 55,000 × 0.25 = 13,750 kJ. Forgetting to convert grams to kilograms gives the wrong values in the other options.","difficulty":"moderate","questionHi":"एक ईंधन का ऊष्मीय मान 55,000 kJ/kg है। उसके 250 g के पूर्ण दहन पर कितनी ऊष्मा निकलेगी?","optionsHi":["220,000 kJ","137,500 kJ","1,375 kJ","13,750 kJ"],"explanationHi":"250 g = 0.25 kg, इसलिए निकली ऊष्मा = 55,000 × 0.25 = 13,750 kJ। ग्राम को किलोग्राम में बदलना भूल जाने पर अन्य विकल्पों के मान आते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-314","question":"Water gas, a useful industrial fuel made by passing steam over red-hot coke, is a mixture of:","options":["carbon monoxide and hydrogen","carbon dioxide and hydrogen","methane and hydrogen","carbon monoxide and carbon dioxide"],"answer":0,"explanation":"C + H₂O → CO + H₂ at high temperature. Both gases burn, so the mixture is a fuel; it is also used as a source of hydrogen.","difficulty":"hard","questionHi":"लाल तप्त कोक पर भाप प्रवाहित करके बनाई जाने वाली उपयोगी औद्योगिक ईंधन गैस, वाटर गैस, किसका मिश्रण है?","optionsHi":["कार्बन मोनोक्साइड और हाइड्रोजन","कार्बन डाइऑक्साइड और हाइड्रोजन","मेथेन और हाइड्रोजन","कार्बन मोनोक्साइड और कार्बन डाइऑक्साइड"],"explanationHi":"उच्च ताप पर C + H₂O → CO + H₂। दोनों गैसें जलती हैं, इसलिए यह मिश्रण ईंधन है; इसे हाइड्रोजन के स्रोत के रूप में भी प्रयोग किया जाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-315","question":"Which of these is NOT obtained by the destructive distillation of coal?","options":["Coke","Coal tar","Coal gas","Petroleum jelly"],"answer":3,"explanation":"Heating coal strongly in the absence of air gives coke, coal tar, coal gas and ammoniacal liquor. Petroleum jelly (Vaseline) is a product of petroleum refining.","difficulty":"moderate","questionHi":"इनमें से कौन-सा कोयले के भंजक आसवन से प्राप्त नहीं होता?","optionsHi":["कोक","कोल टार","कोल गैस","पेट्रोलियम जेली"],"explanationHi":"वायु की अनुपस्थिति में कोयले को तेज़ गर्म करने पर कोक, कोल टार, कोल गैस और अमोनिया युक्त द्रव मिलते हैं। पेट्रोलियम जेली (वैसलीन) पेट्रोलियम शोधन का उत्पाद है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-316","question":"Industrial ethanol is made unfit for drinking by adding small amounts of methanol and a bitter dye. Such ethanol is called:","options":["absolute alcohol","rectified spirit","denatured alcohol","power alcohol"],"answer":2,"explanation":"Denatured alcohol (methylated spirit) is made poisonous or foul-tasting so that cheap industrial ethanol is not misused as a drink. Rectified spirit is about 95% ethanol and absolute alcohol is 100% ethanol.","difficulty":"hard","questionHi":"औद्योगिक एथेनॉल में थोड़ा मेथेनॉल और कड़वा रंजक मिलाकर उसे पीने के अयोग्य बना दिया जाता है। ऐसे एथेनॉल को क्या कहते हैं?","optionsHi":["परिशुद्ध ऐल्कोहॉल (ऐब्सोल्यूट)","रेक्टिफ़ाइड स्पिरिट","विकृत ऐल्कोहॉल","पावर ऐल्कोहॉल"],"explanationHi":"विकृत ऐल्कोहॉल (मेथिलेटेड स्पिरिट) को विषैला या बेस्वाद बना दिया जाता है ताकि सस्ते औद्योगिक एथेनॉल का पेय के रूप में दुरुपयोग न हो। रेक्टिफ़ाइड स्पिरिट लगभग 95% एथेनॉल और परिशुद्ध ऐल्कोहॉल 100% एथेनॉल होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-317","question":"The enzyme of yeast that converts glucose into ethanol and carbon dioxide is:","options":["invertase","zymase","maltase","diastase"],"answer":1,"explanation":"Zymase, a complex of yeast enzymes, converts glucose to ethanol and CO₂: C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂. Invertase splits sucrose into glucose and fructose.","difficulty":"hard","questionHi":"यीस्ट का वह एंज़ाइम जो ग्लूकोस को एथेनॉल और कार्बन डाइऑक्साइड में बदलता है, है:","optionsHi":["इन्वर्टेज़","ज़ाइमेज़","माल्टेज़","डायस्टेज़"],"explanationHi":"ज़ाइमेज़, यीस्ट के एंज़ाइमों का संकुल, ग्लूकोस को एथेनॉल और CO₂ में बदलता है: C₆H₁₂O₆ → 2C₂H₅OH + 2CO₂। इन्वर्टेज़ सुक्रोस को ग्लूकोस और फ्रक्टोस में तोड़ता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-318","question":"What is the percentage of nitrogen by mass in ammonium nitrate, NH₄NO₃? (N = 14, H = 1, O = 16)","options":["35%","28%","17.5%","46.7%"],"answer":0,"explanation":"Molar mass of NH₄NO₃ = 14 + 4 + 14 + 48 = 80 g. It has two nitrogen atoms, so N% = 28 ÷ 80 × 100 = 35%. The value 46.7% is the nitrogen content of urea.","difficulty":"very-hard","questionHi":"अमोनियम नाइट्रेट, NH₄NO₃ में नाइट्रोजन का द्रव्यमान प्रतिशत कितना है? (N = 14, H = 1, O = 16)","optionsHi":["35%","28%","17.5%","46.7%"],"explanationHi":"NH₄NO₃ का मोलर द्रव्यमान = 14 + 4 + 14 + 48 = 80 g। इसमें दो नाइट्रोजन परमाणु हैं, इसलिए N% = 28 ÷ 80 × 100 = 35%। 46.7% यूरिया की नाइट्रोजन मात्रा है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-319","question":"Photochemical smog is formed when sunlight acts on:","options":["sulphur dioxide and water vapour from coal smoke","carbon dioxide and nitrogen present in clean air","chlorofluorocarbons and oxygen in the stratosphere","nitrogen oxides and hydrocarbons from vehicles"],"answer":3,"explanation":"Sunlight drives reactions between nitrogen oxides and unburnt hydrocarbons in vehicle exhaust, producing ozone and PAN, which irritate the eyes and lungs. Smog from coal smoke, sulphur dioxide and fog is the older, classical type.","difficulty":"hard","questionHi":"प्रकाश-रासायनिक धूम-कोहरा (फ़ोटोकेमिकल स्मॉग) तब बनता है जब सूर्य का प्रकाश किन पर क्रिया करता है?","optionsHi":["कोयले के धुएँ से निकले सल्फ़र डाइऑक्साइड और जलवाष्प","स्वच्छ वायु में उपस्थित कार्बन डाइऑक्साइड और नाइट्रोजन","समतापमंडल में क्लोरोफ्लोरोकार्बन और ऑक्सीजन","वाहनों से निकले नाइट्रोजन ऑक्साइड और हाइड्रोकार्बन"],"explanationHi":"सूर्य का प्रकाश वाहनों के निकास में नाइट्रोजन ऑक्साइडों और अदग्ध हाइड्रोकार्बनों के बीच अभिक्रियाएँ कराता है, जिनसे ओज़ोन और PAN बनते हैं जो आँखों और फेफड़ों में जलन करते हैं। कोयले के धुएँ, सल्फ़र डाइऑक्साइड और कोहरे वाला स्मॉग पुराना, परंपरागत प्रकार है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-320","question":"Which of these substances is used as an antiseptic on a wound (applied to living tissue), and not as a disinfectant for floors and drains?","options":["Bleaching powder","Formalin","Tincture of iodine","Phenyl"],"answer":2,"explanation":"Tincture of iodine is mild enough to be applied on skin and wounds to kill germs, so it is an antiseptic. Bleaching powder, formalin and phenyl are too harsh for living tissue and are used as disinfectants on inanimate things.","difficulty":"hard","questionHi":"इनमें से किस पदार्थ का उपयोग घाव पर (जीवित ऊतक पर) प्रतिरोधी (ऐंटीसेप्टिक) के रूप में होता है, फ़र्श और नालियों के विसंक्रामक के रूप में नहीं?","optionsHi":["विरंजक चूर्ण","फ़ॉर्मेलिन","टिंचर आयोडीन","फिनाइल"],"explanationHi":"टिंचर आयोडीन इतना मृदु होता है कि उसे त्वचा और घावों पर कीटाणु मारने के लिए लगाया जा सकता है, इसलिए वह ऐंटीसेप्टिक है। विरंजक चूर्ण, फ़ॉर्मेलिन और फिनाइल जीवित ऊतक के लिए बहुत तीव्र हैं और निर्जीव वस्तुओं पर विसंक्रामक के रूप में प्रयुक्त होते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-321","question":"Saccharin is used as an artificial sweetener, even by diabetics, because it:","options":["lowers the blood sugar level directly","is not metabolised by the body and gives no calories","is a form of glucose that does not raise blood sugar","is completely destroyed when it is cooked"],"answer":1,"explanation":"Saccharin is several hundred times sweeter than sugar but is not broken down for energy in the body, so it adds no calories and does not raise blood glucose. It is not a form of glucose.","difficulty":"hard","questionHi":"सैकरीन का उपयोग कृत्रिम मीठे के रूप में, मधुमेह रोगियों द्वारा भी, इसलिए होता है क्योंकि वह:","optionsHi":["रक्त शर्करा के स्तर को सीधे घटाता है","शरीर में उपापचित नहीं होता और कैलोरी नहीं देता","ग्लूकोस का ऐसा रूप है जो रक्त शर्करा नहीं बढ़ाता","पकाने पर पूरी तरह नष्ट हो जाता है"],"explanationHi":"सैकरीन चीनी से कई सौ गुना मीठा होता है, पर शरीर में ऊर्जा के लिए नहीं टूटता, इसलिए कैलोरी नहीं जोड़ता और रक्त ग्लूकोस नहीं बढ़ाता। वह ग्लूकोस का रूप नहीं है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-322","question":"Laboratory glassware that can be heated strongly without cracking is made of borosilicate (Pyrex) glass because this glass has:","options":["a very high density compared with ordinary glass","a high melting point, which is its only special property","a very high refractive index compared with ordinary glass","a very low coefficient of thermal expansion"],"answer":3,"explanation":"Borosilicate glass expands very little on heating, so it does not develop the stresses that crack ordinary soda-lime glass when the temperature changes quickly.","difficulty":"moderate","questionHi":"प्रयोगशाला के जो काँच के बर्तन तेज़ गर्म करने पर भी नहीं चटकते, वे बोरोसिलिकेट (पायरेक्स) काँच के बने होते हैं, क्योंकि इस काँच में होता है:","optionsHi":["साधारण काँच की तुलना में बहुत अधिक घनत्व","ऊँचा गलनांक, जो उसकी एकमात्र विशेषता है","साधारण काँच की तुलना में बहुत अधिक अपवर्तनांक","बहुत कम ऊष्मीय प्रसार गुणांक"],"explanationHi":"बोरोसिलिकेट काँच गर्म करने पर बहुत कम फैलता है, इसलिए ताप के तेज़ी से बदलने पर उसमें वे तनाव नहीं बनते जो साधारण सोडा-चूना काँच को चटका देते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-323","question":"The black 'lead' in a pencil is actually:","options":["graphite mixed with clay","lead mixed with graphite","charcoal pressed with wax","lead sulphide"],"answer":0,"explanation":"Pencil 'lead' is graphite mixed with clay; more clay makes it harder (H grades) and less clay makes it softer and darker (B grades). It contains no lead metal.","difficulty":"moderate","questionHi":"पेंसिल का काला 'लेड' वास्तव में क्या होता है?","optionsHi":["मिट्टी मिला हुआ ग्रेफ़ाइट","ग्रेफ़ाइट मिला हुआ सीसा","मोम के साथ दबाया गया चारकोल","लेड सल्फ़ाइड"],"explanationHi":"पेंसिल का 'लेड' मिट्टी मिला ग्रेफ़ाइट है; अधिक मिट्टी उसे कठोर (H श्रेणी) और कम मिट्टी नरम तथा गहरा (B श्रेणी) बनाती है। उसमें सीसा धातु नहीं होती।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-324","question":"What mass of carbon dioxide is produced by the complete combustion of 30 g of ethane, C₂H₆? 2C₂H₆ + 7O₂ → 4CO₂ + 6H₂O (C = 12, H = 1, O = 16)","options":["44 g","132 g","88 g","30 g"],"answer":2,"explanation":"30 g of ethane is 1 mol (molar mass 30). Two moles of ethane give four moles of CO₂, so 1 mol gives 2 mol CO₂ = 2 × 44 = 88 g.","difficulty":"hard","questionHi":"30 g एथेन, C₂H₆ के पूर्ण दहन से कितने द्रव्यमान की कार्बन डाइऑक्साइड बनेगी? 2C₂H₆ + 7O₂ → 4CO₂ + 6H₂O (C = 12, H = 1, O = 16)","optionsHi":["44 g","132 g","88 g","30 g"],"explanationHi":"30 g एथेन = 1 मोल (मोलर द्रव्यमान 30)। दो मोल एथेन से चार मोल CO₂ मिलती है, इसलिए 1 मोल से 2 मोल CO₂ = 2 × 44 = 88 g मिलती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-325","question":"Which gas mixture is burnt to give a very hot flame for welding and cutting metals?","options":["Acetylene and oxygen","Methane and nitrogen","Ethane and carbon dioxide","Hydrogen and nitrogen"],"answer":0,"explanation":"Burning ethyne (acetylene) in pure oxygen gives the oxy-acetylene flame, which reaches about 3000 °C and is used to weld and cut metals. Nitrogen and carbon dioxide do not support combustion.","difficulty":"moderate","questionHi":"धातुओं की वेल्डिंग और कटाई के लिए बहुत गर्म लौ देने हेतु कौन-सा गैस मिश्रण जलाया जाता है?","optionsHi":["ऐसीटिलीन और ऑक्सीजन","मेथेन और नाइट्रोजन","एथेन और कार्बन डाइऑक्साइड","हाइड्रोजन और नाइट्रोजन"],"explanationHi":"एथाइन (ऐसीटिलीन) को शुद्ध ऑक्सीजन में जलाने पर ऑक्सी-ऐसीटिलीन लौ मिलती है, जो लगभग 3000 °C तक पहुँचती है और धातुओं की वेल्डिंग तथा कटाई में काम आती है। नाइट्रोजन और कार्बन डाइऑक्साइड दहन में सहायक नहीं होतीं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-326","question":"A leak of LPG tends to collect near the floor, whereas a leak of CNG rises and disperses. This is because:","options":["LPG is much hotter than CNG when it escapes from its cylinder","LPG vapour is heavier than air, but methane is lighter","LPG is a liquid at room temperature while CNG is a solid","LPG dissolves quickly in the water vapour of the room air"],"answer":1,"explanation":"LPG is mainly propane and butane (molar masses 44 and 58), heavier than air (about 29), so it settles at floor level. CNG is mainly methane (16), lighter than air, so it rises.","difficulty":"hard","questionHi":"LPG का रिसाव फ़र्श के पास जमा होता है, जबकि CNG का रिसाव ऊपर उठकर फैल जाता है। इसका कारण है:","optionsHi":["सिलेंडर से निकलते समय LPG, CNG से बहुत अधिक गर्म होती है","LPG वाष्प वायु से भारी है, पर मेथेन हल्की है","LPG कमरे के ताप पर द्रव और CNG ठोस होती है","LPG कमरे की वायु की जलवाष्प में तेज़ी से घुल जाती है"],"explanationHi":"LPG मुख्यतः प्रोपेन और ब्यूटेन है (मोलर द्रव्यमान 44 और 58), जो वायु (लगभग 29) से भारी हैं, इसलिए फ़र्श पर बैठ जाती है। CNG मुख्यतः मेथेन (16) है, जो वायु से हल्की है, इसलिए ऊपर उठती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-327","question":"Which of these molecules is non-polar even though it contains polar bonds?","options":["H₂O","NH₃","CO₂","HCl"],"answer":2,"explanation":"CO₂ is linear, so the two polar C=O bond dipoles point in opposite directions and cancel. Water and ammonia are bent and pyramidal, so their dipoles add up, and HCl is a polar diatomic molecule.","difficulty":"hard","questionHi":"इनमें से कौन-सा अणु ध्रुवीय बंध होने पर भी अध्रुवीय है?","optionsHi":["H₂O","NH₃","CO₂","HCl"],"explanationHi":"CO₂ रैखिक है, इसलिए दोनों ध्रुवीय C=O बंधों के द्विध्रुव विपरीत दिशाओं में होकर एक-दूसरे को निरस्त कर देते हैं। जल और अमोनिया क्रमशः बंकिम और पिरामिडाकार हैं, इसलिए उनके द्विध्रुव जुड़ते हैं, और HCl ध्रुवीय द्विपरमाणुक अणु है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-328","question":"Water boils at 100 °C, while hydrogen sulphide (H₂S), which has a larger molar mass, is a gas at room temperature. The main reason is that:","options":["water molecules are held together by hydrogen bonds","H₂S molecules are completely non-polar in nature","sulphur is more electronegative than oxygen in water","H₂S molecules are bonded by strong ionic forces"],"answer":0,"explanation":"Oxygen is small and highly electronegative, so water molecules form strong hydrogen bonds with one another, and much more energy is needed to separate them. H₂S shows only weak attractions between molecules.","difficulty":"hard","questionHi":"जल 100 °C पर उबलता है, जबकि हाइड्रोजन सल्फ़ाइड (H₂S), जिसका मोलर द्रव्यमान अधिक है, कमरे के ताप पर गैस है। इसका मुख्य कारण है:","optionsHi":["जल के अणु हाइड्रोजन बंधों से जुड़े रहते हैं","H₂S के अणु पूर्णतः अध्रुवीय होते हैं","जल में ऑक्सीजन की अपेक्षा सल्फ़र अधिक विद्युतऋणात्मक है","H₂S के अणु प्रबल आयनिक बलों से बँधे होते हैं"],"explanationHi":"ऑक्सीजन छोटी और अत्यधिक विद्युतऋणात्मक है, इसलिए जल के अणु आपस में प्रबल हाइड्रोजन बंध बनाते हैं और उन्हें अलग करने में बहुत अधिक ऊर्जा लगती है। H₂S में अणुओं के बीच केवल दुर्बल आकर्षण होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-329","question":"The number of lone pairs of electrons on the central atom of a water molecule and of an ammonia molecule respectively is:","options":["1 and 2","2 and 1","2 and 2","1 and 1"],"answer":1,"explanation":"Oxygen has 6 valence electrons: 2 are used in two O–H bonds, leaving 2 lone pairs. Nitrogen has 5: 3 are used in three N–H bonds, leaving 1 lone pair.","difficulty":"very-hard","questionHi":"जल अणु और अमोनिया अणु के केंद्रीय परमाणु पर एकाकी इलेक्ट्रॉन युग्मों की संख्या क्रमशः है:","optionsHi":["1 और 2","2 और 1","2 और 2","1 और 1"],"explanationHi":"ऑक्सीजन के 6 संयोजी इलेक्ट्रॉनों में से 2 दो O–H बंधों में लगते हैं, जिससे 2 एकाकी युग्म बचते हैं। नाइट्रोजन के 5 में से 3 तीन N–H बंधों में लगते हैं, जिससे 1 एकाकी युग्म बचता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-330","question":"Metals can be hammered into thin sheets without breaking mainly because:","options":["the metal atoms are held together only by weak van der Waals forces between layers","the ions are locked in fixed positions by strong directional covalent bonds","the free electrons absorb the force of the hammer and convert it into heat","layers of metal ions slide over one another while the electron sea holds them together"],"answer":3,"explanation":"In a metal, positive ions sit in a sea of mobile electrons; the bonding is non-directional, so layers can slip past each other without breaking the metallic bond. Ionic crystals shatter because sliding brings like charges together.","difficulty":"hard","questionHi":"धातुओं को पीटकर पतली चादरों में बदला जा सकता है और वे टूटती नहीं, मुख्यतः क्योंकि:","optionsHi":["धातु के परमाणु परतों के बीच केवल दुर्बल वान डर वाल्स बलों से जुड़े होते हैं","आयन प्रबल दिशात्मक सहसंयोजी बंधों द्वारा निश्चित स्थानों पर जकड़े होते हैं","मुक्त इलेक्ट्रॉन हथौड़े के बल को सोखकर उसे ऊष्मा में बदल देते हैं","धातु आयनों की परतें एक-दूसरे पर फिसलती हैं जबकि इलेक्ट्रॉन सागर उन्हें जोड़े रखता है"],"explanationHi":"धातु में धनायन गतिशील इलेक्ट्रॉनों के सागर में स्थित होते हैं; बंधन अदिशात्मक है, इसलिए परतें धात्विक बंध टूटे बिना एक-दूसरे पर फिसल सकती हैं। आयनिक क्रिस्टल टूट जाते हैं क्योंकि फिसलने से समान आवेश पास आ जाते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-331","question":"Which statement about the sizes of atoms and their ions is correct?","options":["Na⁺ is smaller than the Na atom, and Cl⁻ is larger than the Cl atom","Na⁺ is larger than the Na atom, and Cl⁻ is smaller than the Cl atom","Both Na⁺ and Cl⁻ are smaller than their parent atoms","Both Na⁺ and Cl⁻ are larger than their parent atoms"],"answer":0,"explanation":"Sodium loses its outer shell when it forms Na⁺, so it shrinks. Chlorine gains an electron to form Cl⁻, and the extra electron repulsion makes the ion larger than the atom.","difficulty":"hard","questionHi":"परमाणुओं और उनके आयनों के आकार के बारे में कौन-सा कथन सही है?","optionsHi":["Na⁺ का आकार Na परमाणु से छोटा और Cl⁻ का आकार Cl परमाणु से बड़ा होता है","Na⁺ का आकार Na परमाणु से बड़ा और Cl⁻ का आकार Cl परमाणु से छोटा होता है","Na⁺ और Cl⁻ दोनों अपने मूल परमाणुओं से छोटे होते हैं","Na⁺ और Cl⁻ दोनों अपने मूल परमाणुओं से बड़े होते हैं"],"explanationHi":"Na⁺ बनने पर सोडियम अपना बाह्य कोश खो देता है, इसलिए सिकुड़ जाता है। क्लोरीन इलेक्ट्रॉन ग्रहण करके Cl⁻ बनता है और अतिरिक्त इलेक्ट्रॉन-प्रतिकर्षण आयन को परमाणु से बड़ा बना देता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-332","question":"A mixture contains iron filings, sawdust, common salt and sand. Which order of steps separates all four components?","options":["Evaporate the mixture to dryness, then use a magnet, then add water and filter the rest","Add water and filter, then use a magnet on the residue, then evaporate the filtrate to dryness","Use a magnet, add water and skim off the sawdust, filter off the sand, evaporate the filtrate","Add water, evaporate it all, then use a magnet and filter paper on what is left behind"],"answer":2,"explanation":"The magnet first removes the iron. Water then dissolves the salt and the sawdust floats and can be skimmed off; filtration removes the sand and evaporating the filtrate gives the salt.","difficulty":"very-hard","questionHi":"एक मिश्रण में लोहे का चूर्ण, बुरादा, साधारण नमक और रेत हैं। किस क्रम के चरण चारों घटकों को पृथक कर देते हैं?","optionsHi":["मिश्रण को सुखाने तक वाष्पित करें, फिर चुंबक प्रयोग करें, फिर पानी डालकर शेष को छानें","पानी डालकर छानें, फिर अवशेष पर चुंबक प्रयोग करें, फिर निस्यंद को सुखाने तक वाष्पित करें","चुंबक प्रयोग करें, पानी डालकर बुरादा निकाल लें, रेत को छानकर अलग करें, निस्यंद को वाष्पित करें","पानी डालें, उसे पूरा वाष्पित करें, फिर शेष बचे पदार्थ पर चुंबक और छन्ना कागज़ प्रयोग करें"],"explanationHi":"चुंबक सबसे पहले लोहा हटा लेता है। फिर पानी नमक को घोल देता है, बुरादा तैरता है और उसे निकाला जा सकता है; छानने से रेत अलग होती है और निस्यंद को वाष्पित करने से नमक मिलता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-333","question":"Water boils at a lower temperature on a high mountain than at sea level because there:","options":["the water contains more dissolved air","the atmospheric pressure is lower","the sunlight is more intense","the air is colder than the water"],"answer":1,"explanation":"A liquid boils when its vapour pressure equals the surrounding pressure. At high altitude the atmospheric pressure is lower, so this happens at a temperature below 100 °C, which is why food cooks slowly there.","difficulty":"moderate","questionHi":"ऊँचे पर्वत पर जल समुद्र तल की तुलना में कम ताप पर उबलता है, क्योंकि वहाँ:","optionsHi":["जल में अधिक घुली वायु होती है","वायुमंडलीय दाब कम होता है","सूर्य का प्रकाश अधिक तीव्र होता है","वायु जल से अधिक ठंडी होती है"],"explanationHi":"कोई द्रव तब उबलता है जब उसका वाष्प दाब आसपास के दाब के बराबर हो जाता है। अधिक ऊँचाई पर वायुमंडलीय दाब कम होता है, इसलिए ऐसा 100 °C से कम ताप पर हो जाता है, इसीलिए वहाँ भोजन देर से पकता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-334","question":"Steam at 100 °C causes a more severe burn than boiling water at 100 °C because steam:","options":["is much hotter than boiling water at the same pressure","carries more dissolved air with it into the skin","has a higher specific heat than liquid water does","releases latent heat as it condenses on the skin"],"answer":3,"explanation":"Both are at 100 °C, but when steam condenses on the skin it gives out its latent heat of vaporisation (about 2260 J per gram) in addition to the heat from cooling, so much more energy reaches the skin.","difficulty":"very-hard","questionHi":"100 °C की भाप 100 °C के खौलते जल की तुलना में अधिक गंभीर जलन करती है, क्योंकि भाप:","optionsHi":["उसी दाब पर खौलते जल से कहीं अधिक गर्म होती है","अपने साथ त्वचा में अधिक घुली वायु ले जाती है","द्रव जल से अधिक विशिष्ट ऊष्मा रखती है","त्वचा पर संघनित होते समय गुप्त ऊष्मा छोड़ती है"],"explanationHi":"दोनों 100 °C पर हैं, पर त्वचा पर संघनित होते समय भाप ठंडा होने की ऊष्मा के अतिरिक्त अपनी वाष्पन गुप्त ऊष्मा (लगभग 2260 J प्रति ग्राम) भी देती है, इसलिए त्वचा तक कहीं अधिक ऊर्जा पहुँचती है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-335","question":"What is the ratio of the absolute (Kelvin) temperatures corresponding to 127 °C and 27 °C?","options":["127 : 27","4 : 3","3 : 4","100 : 27"],"answer":1,"explanation":"127 °C = 400 K and 27 °C = 300 K, so the ratio is 400 : 300 = 4 : 3. The ratio of Celsius readings, 127 : 27, has no physical meaning in gas-law problems.","difficulty":"very-hard","questionHi":"127 °C और 27 °C के संगत परम (केल्विन) तापों का अनुपात क्या है?","optionsHi":["127 : 27","4 : 3","3 : 4","100 : 27"],"explanationHi":"127 °C = 400 K और 27 °C = 300 K, इसलिए अनुपात 400 : 300 = 4 : 3 है। सेल्सियस पाठ्यांकों का अनुपात 127 : 27 गैस नियमों की गणनाओं में कोई भौतिक अर्थ नहीं रखता।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-336","question":"Equal volumes of neon and hydrogen gas at the same temperature and pressure contain the same number of:","options":["atoms","protons","molecules","grams of matter"],"answer":2,"explanation":"By Avogadro's law, equal volumes of gases under the same conditions have equal numbers of molecules. Neon is monatomic and hydrogen is diatomic, so the numbers of atoms, protons (10 per Ne, 2 per H₂) and masses differ.","difficulty":"hard","questionHi":"ताप और दाब समान होने पर नियॉन और हाइड्रोजन गैस के समान आयतनों में किसकी संख्या समान होती है?","optionsHi":["परमाणुओं की","प्रोटॉनों की","अणुओं की","पदार्थ के ग्रामों की"],"explanationHi":"आवोगाद्रो के नियम के अनुसार समान परिस्थितियों में गैसों के समान आयतनों में अणुओं की संख्या समान होती है। नियॉन एकपरमाणुक और हाइड्रोजन द्विपरमाणुक है, इसलिए परमाणुओं, प्रोटॉनों (Ne में 10, H₂ में 2) और द्रव्यमान की संख्याएँ भिन्न होती हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-337","question":"Which of these samples contains the same number of molecules as 16 g of oxygen gas? (H = 1, C = 12, O = 16)","options":["1 g of hydrogen gas","2 g of hydrogen gas","16 g of methane","44 g of carbon dioxide"],"answer":0,"explanation":"16 g of O₂ is 16 ÷ 32 = 0.5 mol. Only 1 g of H₂ (1 ÷ 2 = 0.5 mol) matches; 2 g of H₂, 16 g of CH₄ and 44 g of CO₂ are each 1 mol.","difficulty":"hard","questionHi":"इनमें से किस नमूने में अणुओं की संख्या 16 g ऑक्सीजन गैस के अणुओं के बराबर है? (H = 1, C = 12, O = 16)","optionsHi":["1 g हाइड्रोजन गैस","2 g हाइड्रोजन गैस","16 g मेथेन","44 g कार्बन डाइऑक्साइड"],"explanationHi":"16 g O₂ = 16 ÷ 32 = 0.5 मोल। केवल 1 g H₂ (1 ÷ 2 = 0.5 मोल) बराबर है; 2 g H₂, 16 g CH₄ और 44 g CO₂ प्रत्येक 1 मोल हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-338","question":"200 mL of 0.5 M hydrochloric acid is mixed with 300 mL of 1 M hydrochloric acid. What is the molarity of the final solution?","options":["0.75 M","0.4 M","1.5 M","0.8 M"],"answer":3,"explanation":"Total moles = 0.2 × 0.5 + 0.3 × 1 = 0.1 + 0.3 = 0.4 mol in 0.5 L, so the molarity is 0.4 ÷ 0.5 = 0.8 M. The simple average of the two molarities, 0.75 M, ignores the unequal volumes.","difficulty":"very-hard","questionHi":"200 mL 0.5 M हाइड्रोक्लोरिक अम्ल को 300 mL 1 M हाइड्रोक्लोरिक अम्ल में मिलाया जाता है। अंतिम विलयन की मोलरता क्या है?","optionsHi":["0.75 M","0.4 M","1.5 M","0.8 M"],"explanationHi":"कुल मोल = 0.2 × 0.5 + 0.3 × 1 = 0.1 + 0.3 = 0.4 मोल, जो 0.5 L में हैं, इसलिए मोलरता 0.4 ÷ 0.5 = 0.8 M है। दोनों मोलरताओं का सरल औसत 0.75 M असमान आयतनों की उपेक्षा करता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-339","question":"Which of these is NOT changed when a catalyst is added to a reaction?","options":["The activation energy","The rate of the reaction","The heat of reaction (enthalpy change)","The path (mechanism) of the reaction"],"answer":2,"explanation":"A catalyst offers a new path with a lower activation energy and so speeds up the reaction, but the energies of the reactants and products stay the same. The enthalpy change and the final equilibrium position are therefore unchanged.","difficulty":"very-hard","questionHi":"किसी अभिक्रिया में उत्प्रेरक मिलाने पर इनमें से किसमें परिवर्तन नहीं होता?","optionsHi":["सक्रियण ऊर्जा","अभिक्रिया की दर","अभिक्रिया की ऊष्मा (एन्थैल्पी परिवर्तन)","अभिक्रिया का पथ (क्रियाविधि)"],"explanationHi":"उत्प्रेरक कम सक्रियण ऊर्जा वाला नया पथ देता है और इस प्रकार अभिक्रिया को तेज़ करता है, पर अभिकारकों और उत्पादों की ऊर्जाएँ वही रहती हैं। इसलिए एन्थैल्पी परिवर्तन और अंतिम साम्य की स्थिति नहीं बदलती।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-340","question":"When ammonium nitrate dissolves in water, the solution becomes cold. This shows that its dissolution is:","options":["exothermic, because heat is released into the water","endothermic, because heat is absorbed from the surroundings","a chemical change in which a cold gas is formed","a physical change in which no energy is exchanged"],"answer":1,"explanation":"The solution cools because dissolving ammonium nitrate absorbs heat from the water and the surroundings, which is an endothermic process. Instant cold packs use this effect.","difficulty":"moderate","questionHi":"अमोनियम नाइट्रेट के जल में घुलने पर विलयन ठंडा हो जाता है। इससे पता चलता है कि उसका घुलना है:","optionsHi":["ऊष्माक्षेपी, क्योंकि जल में ऊष्मा निकलती है","ऊष्माशोषी, क्योंकि परिवेश से ऊष्मा अवशोषित होती है","रासायनिक परिवर्तन, जिसमें ठंडी गैस बनती है","भौतिक परिवर्तन, जिसमें ऊर्जा का कोई आदान-प्रदान नहीं होता"],"explanationHi":"विलयन इसलिए ठंडा होता है कि अमोनियम नाइट्रेट घुलते समय जल और परिवेश से ऊष्मा सोखता है, जो ऊष्माशोषी प्रक्रम है। तात्कालिक ठंडे पैक इसी प्रभाव का उपयोग करते हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-341","question":"During a thunderstorm, some atmospheric nitrogen is changed into compounds that plants can use because:","options":["rain simply washes free nitrogen gas out of the air and carries it into the soil","lightning splits water into hydrogen, which combines with nitrogen to make ammonia","the vibrations of thunder break the N₂ molecules directly into ready plant food","lightning gives the energy for N₂ and O₂ to form oxides that dissolve in rain as nitrates"],"answer":3,"explanation":"The high temperature of a lightning flash makes N₂ combine with O₂: N₂ + O₂ → 2NO, which oxidises to NO₂ and dissolves in rain as nitric acid. This reaches the soil as nitrates, a natural form of nitrogen fixation.","difficulty":"hard","questionHi":"तड़ित-झंझा के समय वायुमंडल की कुछ नाइट्रोजन उन यौगिकों में बदल जाती है जिन्हें पौधे उपयोग कर सकते हैं, क्योंकि:","optionsHi":["वर्षा केवल वायु से मुक्त नाइट्रोजन गैस को धोकर मिट्टी में पहुँचा देती है","बिजली जल को हाइड्रोजन में तोड़ देती है, जो नाइट्रोजन से मिलकर अमोनिया बनाती है","गर्जन के कंपन N₂ अणुओं को सीधे तैयार पादप भोजन में तोड़ देते हैं","बिजली N₂ और O₂ को ऑक्साइड बनाने की ऊर्जा देती है, जो वर्षा में नाइट्रेट के रूप में घुल जाते हैं"],"explanationHi":"बिजली की चमक का उच्च ताप N₂ को O₂ से मिला देता है: N₂ + O₂ → 2NO, जो ऑक्सीकृत होकर NO₂ बनता है और वर्षा में नाइट्रिक अम्ल के रूप में घुल जाता है। यह मिट्टी में नाइट्रेट के रूप में पहुँचता है, जो नाइट्रोजन स्थिरीकरण का प्राकृतिक रूप है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-342","question":"Which statement correctly compares bleaching by chlorine and by sulphur dioxide?","options":["Chlorine bleaches permanently by oxidation; SO₂ bleaches by reduction and the colour may return","Both bleach by oxidation, and in both cases the bleaching is permanent","Chlorine bleaches by reduction and SO₂ bleaches by oxidation, so both effects are permanent","Both bleach by reduction, and in both cases the colour returns in air"],"answer":0,"explanation":"Moist chlorine forms hypochlorous acid, which oxidises the coloured substance permanently. Sulphur dioxide reduces the dye to a colourless form, and the original colour slowly returns when the article is exposed to air, so newspapers bleached with SO₂ turn yellow again.","difficulty":"very-hard","questionHi":"क्लोरीन और सल्फ़र डाइऑक्साइड द्वारा विरंजन की तुलना कौन-सा कथन सही करता है?","optionsHi":["क्लोरीन ऑक्सीकरण द्वारा स्थायी विरंजन करती है; SO₂ अपचयन द्वारा विरंजन करती है और रंग लौट सकता है","दोनों ऑक्सीकरण द्वारा विरंजित करती हैं, और दोनों में विरंजन स्थायी होता है","क्लोरीन अपचयन द्वारा और SO₂ ऑक्सीकरण द्वारा विरंजित करती है, इसलिए दोनों के प्रभाव स्थायी होते हैं","दोनों अपचयन द्वारा विरंजित करती हैं, और दोनों में रंग वायु में लौट आता है"],"explanationHi":"नम क्लोरीन हाइपोक्लोरस अम्ल बनाती है, जो रंगीन पदार्थ को स्थायी रूप से ऑक्सीकृत कर देता है। सल्फ़र डाइऑक्साइड रंजक को रंगहीन रूप में अपचयित करती है, और वस्तु को वायु में रखने पर मूल रंग धीरे-धीरे लौट आता है, इसीलिए SO₂ से विरंजित अख़बार फिर पीले पड़ जाते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-343","question":"A gas with the smell of rotten eggs turns filter paper dipped in lead acetate solution black. The gas is:","options":["sulphur dioxide","ammonia","hydrogen sulphide","nitrogen dioxide"],"answer":2,"explanation":"Hydrogen sulphide reacts with lead acetate to form black lead sulphide: (CH₃COO)₂Pb + H₂S → PbS + 2CH₃COOH. Sulphur dioxide smells of burning sulphur and ammonia is pungent.","difficulty":"moderate","questionHi":"सड़े अंडे जैसी गंध वाली एक गैस लेड ऐसीटेट विलयन में भिगोए छन्ना कागज़ को काला कर देती है। वह गैस है:","optionsHi":["सल्फ़र डाइऑक्साइड","अमोनिया","हाइड्रोजन सल्फ़ाइड","नाइट्रोजन डाइऑक्साइड"],"explanationHi":"हाइड्रोजन सल्फ़ाइड लेड ऐसीटेट से अभिक्रिया करके काला लेड सल्फ़ाइड बनाती है: (CH₃COO)₂Pb + H₂S → PbS + 2CH₃COOH। सल्फ़र डाइऑक्साइड की गंध जलते सल्फ़र जैसी और अमोनिया की तीखी होती है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-344","question":"Which of these is an acid salt, that is, one that still has a replaceable hydrogen atom?","options":["NaCl","NaHSO₄","Na₂CO₃","CH₃COONa"],"answer":1,"explanation":"Sodium hydrogen sulphate is formed by only partial neutralisation of H₂SO₄ and still contains an ionisable H, so its solution is acidic. NaCl, Na₂CO₃ and CH₃COONa have no replaceable hydrogen.","difficulty":"hard","questionHi":"इनमें से कौन-सा अम्लीय लवण है, अर्थात जिसमें अब भी प्रतिस्थापनीय हाइड्रोजन परमाणु है?","optionsHi":["NaCl","NaHSO₄","Na₂CO₃","CH₃COONa"],"explanationHi":"सोडियम हाइड्रोजन सल्फ़ेट H₂SO₄ के केवल आंशिक उदासीनीकरण से बनता है और उसमें अब भी आयनित हो सकने वाला H होता है, इसलिए उसका विलयन अम्लीय होता है। NaCl, Na₂CO₃ और CH₃COONa में प्रतिस्थापनीय हाइड्रोजन नहीं होता।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-345","question":"Which of these is a double salt?","options":["Copper sulphate pentahydrate, CuSO₄·5H₂O","Sodium chloride, NaCl","Potassium ferrocyanide, K₄[Fe(CN)₆]","Mohr's salt, FeSO₄·(NH₄)₂SO₄·6H₂O"],"answer":3,"explanation":"A double salt is formed by crystallising two simple salts together and it breaks into the ions of both in water; Mohr's salt gives Fe²⁺, NH₄⁺ and SO₄²⁻. K₄[Fe(CN)₆] is a complex salt whose complex ion stays intact in water.","difficulty":"hard","questionHi":"इनमें से कौन-सा द्विक लवण है?","optionsHi":["कॉपर सल्फ़ेट पेन्टाहाइड्रेट, CuSO₄·5H₂O","सोडियम क्लोराइड, NaCl","पोटैशियम फ़ेरोसायनाइड, K₄[Fe(CN)₆]","मोहर लवण, FeSO₄·(NH₄)₂SO₄·6H₂O"],"explanationHi":"द्विक लवण दो सरल लवणों के साथ क्रिस्टलित होने से बनता है और जल में दोनों के आयनों में टूट जाता है; मोहर लवण Fe²⁺, NH₄⁺ और SO₄²⁻ देता है। K₄[Fe(CN)₆] संकुल लवण है, जिसका संकुल आयन जल में अखंड रहता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-346","question":"Alum is added to muddy water to clear it because it:","options":["makes the suspended clay particles clump together and settle","dissolves the suspended clay particles completely in the water","kills all the harmful bacteria present in the muddy water","makes the water neutral by removing any acid present in it"],"answer":0,"explanation":"Alum (potash alum) provides Al³⁺ ions that neutralise the charge on tiny suspended particles, so they coagulate into larger clumps that settle down. It does not disinfect the water or dissolve clay.","difficulty":"hard","questionHi":"गँदले पानी को साफ़ करने के लिए उसमें फिटकरी डाली जाती है, क्योंकि वह:","optionsHi":["निलंबित मिट्टी के कणों को आपस में जोड़कर तली में बैठा देती है","निलंबित मिट्टी के कणों को पानी में पूरी तरह घोल देती है","गँदले पानी में उपस्थित सभी हानिकारक जीवाणुओं को मार देती है","पानी में उपस्थित किसी भी अम्ल को हटाकर उसे उदासीन बना देती है"],"explanationHi":"फिटकरी (पोटाश ऐलम) Al³⁺ आयन देती है जो सूक्ष्म निलंबित कणों के आवेश को उदासीन कर देते हैं, जिससे वे बड़े गुच्छों में जमकर नीचे बैठ जाते हैं। वह पानी को रोगाणुमुक्त नहीं करती और न मिट्टी को घोलती है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-347","question":"Phosphoric acid (H₃PO₄) is neutralised by sodium hydroxide. How many different sodium salts can it form?","options":["1","2","3","4"],"answer":2,"explanation":"It is a tribasic acid, so its three hydrogens can be replaced step by step, giving NaH₂PO₄, Na₂HPO₄ and Na₃PO₄. Of these only the last is a normal salt; the first two are acid salts.","difficulty":"very-hard","questionHi":"फ़ॉस्फ़ोरिक अम्ल (H₃PO₄) को सोडियम हाइड्रॉक्साइड से उदासीन किया जाता है। वह कितने भिन्न सोडियम लवण बना सकता है?","optionsHi":["1","2","3","4"],"explanationHi":"यह त्रिक्षारकीय अम्ल है, इसलिए इसके तीनों हाइड्रोजन क्रमशः प्रतिस्थापित हो सकते हैं, जिससे NaH₂PO₄, Na₂HPO₄ और Na₃PO₄ बनते हैं। इनमें केवल अंतिम सामान्य लवण है; पहले दो अम्लीय लवण हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-348","question":"Which element was detected in the spectrum of the Sun before it was found on the Earth?","options":["Neon","Helium","Argon","Krypton"],"answer":1,"explanation":"Helium was identified from a yellow line in the solar spectrum during the 1868 eclipse, and its name comes from the Greek helios, the Sun. It was isolated on Earth only in 1895.","difficulty":"moderate","questionHi":"किस तत्व की पहचान पृथ्वी पर मिलने से पहले सूर्य के स्पेक्ट्रम में हुई थी?","optionsHi":["नियॉन","हीलियम","ऑर्गन","क्रिप्टॉन"],"explanationHi":"हीलियम की पहचान 1868 के सूर्यग्रहण के दौरान सौर स्पेक्ट्रम की एक पीली रेखा से हुई थी, और उसका नाम यूनानी शब्द हीलियोस (सूर्य) से आया है। पृथ्वी पर उसे 1895 में ही पृथक किया गया।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-349","question":"Arrange α-rays, β-rays and γ-rays in increasing order of their penetrating power.","options":["γ < β < α","β < α < γ","α < γ < β","α < β < γ"],"answer":3,"explanation":"Alpha particles are heavy and stopped by paper or skin, beta particles by a few millimetres of aluminium, while gamma rays are electromagnetic waves that need thick lead or concrete. So the order is α < β < γ.","difficulty":"moderate","questionHi":"α-किरणों, β-किरणों और γ-किरणों को उनकी भेदन क्षमता के बढ़ते क्रम में व्यवस्थित कीजिए।","optionsHi":["γ < β < α","β < α < γ","α < γ < β","α < β < γ"],"explanationHi":"ऐल्फ़ा कण भारी होते हैं और काग़ज़ या त्वचा से रुक जाते हैं, बीटा कण कुछ मिलीमीटर ऐलुमिनियम से रुकते हैं, जबकि गामा किरणें विद्युत-चुंबकीय तरंगें हैं जिन्हें रोकने के लिए मोटा सीसा या कंक्रीट चाहिए। अतः क्रम α < β < γ है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-350","question":"A vegetable oil decolourises bromine water, whereas a fat that is solid at room temperature does so only slightly. This shows that the oil is:","options":["a saturated compound with only single bonds","a compound that reacts by substitution with bromine water","unsaturated, because bromine adds on to its C=C double bonds","a mineral oil that simply dissolves the bromine"],"answer":2,"explanation":"Bromine adds across C=C double bonds and loses its orange colour. Oils contain many unsaturated fatty acids, whereas solid fats are mostly saturated and react very little.","difficulty":"hard","questionHi":"एक वनस्पति तेल ब्रोमीन जल को रंगहीन कर देता है, जबकि कमरे के ताप पर ठोस वसा ऐसा केवल थोड़ा ही करती है। इससे पता चलता है कि तेल है:","optionsHi":["केवल एकल बंधों वाला संतृप्त यौगिक","ऐसा यौगिक जो ब्रोमीन जल से प्रतिस्थापन द्वारा अभिक्रिया करता है","असंतृप्त, क्योंकि ब्रोमीन उसके C=C द्विबंधों पर जुड़ जाती है","खनिज तेल जो ब्रोमीन को केवल घोल लेता है"],"explanationHi":"ब्रोमीन C=C द्विबंधों पर जुड़ जाती है और अपना नारंगी रंग खो देती है। तेलों में अनेक असंतृप्त वसीय अम्ल होते हैं, जबकि ठोस वसाएँ अधिकतर संतृप्त होती हैं और बहुत कम अभिक्रिया करती हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-351","question":"A sodium salt contaminated with a little potassium gives a bright yellow flame that hides the lilac colour of potassium. The yellow light can be filtered out by viewing the flame through:","options":["blue cobalt glass","red cellophane paper","green filter glass","a clear glass slide"],"answer":0,"explanation":"Blue cobalt glass absorbs the strong yellow light of sodium and lets the violet-lilac light of potassium pass, so potassium can be detected even in the presence of sodium.","difficulty":"hard","questionHi":"थोड़े पोटैशियम से अशुद्ध एक सोडियम लवण चमकीली पीली ज्वाला देता है जो पोटैशियम के बैंगनी-लाल रंग को ढक लेती है। पीले प्रकाश को ज्वाला को किसके द्वारा देखकर हटाया जा सकता है?","optionsHi":["नीले कोबाल्ट काँच से","लाल सेलोफ़ेन काग़ज़ से","हरे फ़िल्टर काँच से","पारदर्शी काँच की पट्टी से"],"explanationHi":"नीला कोबाल्ट काँच सोडियम के तीव्र पीले प्रकाश को सोख लेता है और पोटैशियम का बैंगनी-लाल प्रकाश निकलने देता है, इसलिए सोडियम की उपस्थिति में भी पोटैशियम का पता चल जाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-352","question":"In the Solvay process for making sodium carbonate, the sparingly soluble compound that separates first from the ammoniated brine when carbon dioxide is passed through it is:","options":["sodium hydrogencarbonate (NaHCO₃)","sodium carbonate (Na₂CO₃)","ammonium chloride (NH₄Cl)","calcium carbonate (CaCO₃)"],"answer":0,"explanation":"NaCl + NH₃ + CO₂ + H₂O → NaHCO₃ + NH₄Cl. Sodium hydrogencarbonate is the least soluble of the products in the cold brine, so it crystallises; heating it later gives sodium carbonate.","difficulty":"very-hard","questionHi":"सोडियम कार्बोनेट बनाने की सॉल्वे विधि में अमोनिकृत नमकीन जल में कार्बन डाइऑक्साइड प्रवाहित करने पर सबसे पहले कौन-सा अल्प घुलनशील यौगिक पृथक होता है?","optionsHi":["सोडियम हाइड्रोजनकार्बोनेट (NaHCO₃)","सोडियम कार्बोनेट (Na₂CO₃)","अमोनियम क्लोराइड (NH₄Cl)","कैल्सियम कार्बोनेट (CaCO₃)"],"explanationHi":"NaCl + NH₃ + CO₂ + H₂O → NaHCO₃ + NH₄Cl। ठंडे नमकीन जल में उत्पादों में सोडियम हाइड्रोजनकार्बोनेट सबसे कम घुलनशील है, इसलिए वही क्रिस्टलित होता है; बाद में उसे गर्म करने पर सोडियम कार्बोनेट मिलता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-353","question":"Equal masses of marble powder and marble chips are each allowed to react completely with excess dilute hydrochloric acid. Which statement is correct?","options":["The powder gives more carbon dioxide in total because it reacts completely","Both give the same total volume of CO₂, but the powder gives it faster","The chips give more carbon dioxide because they react for a longer time","Both give the same amount of carbon dioxide and at exactly the same speed"],"answer":1,"explanation":"The amount of gas depends only on the amount of CaCO₃, which is the same in both. Powder has a much larger surface area exposed to the acid, so it reacts faster, but the final volume is equal.","difficulty":"very-hard","questionHi":"संगमरमर के चूर्ण और संगमरमर के टुकड़ों के समान द्रव्यमानों को अलग-अलग आधिक्य तनु हाइड्रोक्लोरिक अम्ल से पूर्ण अभिक्रिया करने दिया जाता है। कौन-सा कथन सही है?","optionsHi":["चूर्ण कुल मिलाकर अधिक कार्बन डाइऑक्साइड देता है क्योंकि वह पूरी तरह अभिक्रिया करता है","दोनों CO₂ का कुल आयतन समान देते हैं, पर चूर्ण उसे अधिक तेज़ी से देता है","टुकड़े अधिक कार्बन डाइऑक्साइड देते हैं क्योंकि वे अधिक समय तक अभिक्रिया करते हैं","दोनों समान मात्रा में और ठीक समान गति से कार्बन डाइऑक्साइड देते हैं"],"explanationHi":"गैस की मात्रा केवल CaCO₃ की मात्रा पर निर्भर करती है, जो दोनों में समान है। चूर्ण का अम्ल के संपर्क में आने वाला पृष्ठीय क्षेत्रफल बहुत अधिक होता है, इसलिए वह तेज़ी से अभिक्रिया करता है, पर अंतिम आयतन बराबर रहता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-354","question":"Match the colloid with its type: 1. Fog 2. Whipped cream 3. Jelly 4. Paint (solid particles in a liquid); a. Gel b. Aerosol c. Foam d. Sol.","options":["1-c, 2-b, 3-a, 4-d","1-b, 2-c, 3-d, 4-a","1-b, 2-c, 3-a, 4-d","1-a, 2-c, 3-b, 4-d"],"answer":2,"explanation":"Fog is liquid droplets in a gas (aerosol), whipped cream is a gas in a liquid (foam), jelly is a liquid in a solid (gel) and paint is solid particles in a liquid (sol).","difficulty":"very-hard","questionHi":"कोलॉइड का उसके प्रकार से मिलान कीजिए: 1. कोहरा 2. फेंटी हुई क्रीम 3. जेली 4. पेंट (द्रव में ठोस कण); a. जेल b. ऐरोसॉल c. झाग d. सॉल।","optionsHi":["1-c, 2-b, 3-a, 4-d","1-b, 2-c, 3-d, 4-a","1-b, 2-c, 3-a, 4-d","1-a, 2-c, 3-b, 4-d"],"explanationHi":"कोहरा गैस में द्रव बूँदें (ऐरोसॉल), फेंटी क्रीम द्रव में गैस (झाग), जेली ठोस में द्रव (जेल) और पेंट द्रव में ठोस कण (सॉल) है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-355","question":"The continuous zig-zag motion of colloidal particles seen under a microscope (Brownian motion) is caused by:","options":["convection currents set up in the liquid by uneven heating of the slide","attraction of the particles towards the glass slide below them","repulsion between like charges present on the colloidal particles","bombardment of the particles by the moving molecules of the medium"],"answer":3,"explanation":"The molecules of the dispersion medium are in constant random motion and strike the colloidal particles unevenly from different sides, making them move in a zig-zag path. This motion also helps to keep the colloid from settling.","difficulty":"hard","questionHi":"सूक्ष्मदर्शी में दिखने वाली कोलॉइडी कणों की सतत टेढ़ी-मेढ़ी गति (ब्राउनी गति) का कारण है:","optionsHi":["स्लाइड के असमान गर्म होने से द्रव में उत्पन्न संवहन धाराएँ","कणों का नीचे की काँच की पट्टी की ओर आकर्षित होना","कोलॉइडी कणों पर उपस्थित समान आवेशों के बीच प्रतिकर्षण","माध्यम के गतिशील अणुओं द्वारा कणों पर टक्कर"],"explanationHi":"परिक्षेपण माध्यम के अणु निरंतर यादृच्छिक गति में रहते हैं और कोलॉइडी कणों पर अलग-अलग ओर से असमान टक्कर मारते हैं, जिससे कण टेढ़े-मेढ़े पथ पर चलते हैं। यह गति कोलॉइड को बैठने से रोकने में भी सहायक है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-356","question":"A supersaturated solution of sodium acetate suddenly crystallises when a tiny crystal of the salt is dropped into it. The liquid left after the crystallisation is:","options":["saturated at that temperature","unsaturated, because the solute has left it","still supersaturated, as before","pure water"],"answer":0,"explanation":"The extra dissolved salt crystallises out until the solution holds exactly the maximum amount the solvent can dissolve at that temperature, so the remaining liquid is saturated. It cannot be unsaturated or still supersaturated.","difficulty":"very-hard","questionHi":"सोडियम ऐसीटेट के अतिसंतृप्त विलयन में लवण का एक नन्हा क्रिस्टल डालने पर वह अचानक क्रिस्टलित हो जाता है। क्रिस्टलन के बाद बचा द्रव है:","optionsHi":["उस ताप पर संतृप्त","असंतृप्त, क्योंकि विलेय उसमें से निकल गया","पहले की तरह अतिसंतृप्त","शुद्ध जल"],"explanationHi":"आधिक्य में घुला लवण तब तक क्रिस्टलित होता है जब तक विलयन में उस ताप पर विलायक द्वारा घोली जा सकने वाली अधिकतम मात्रा ही शेष रहे, इसलिए बचा द्रव संतृप्त होता है। वह न असंतृप्त हो सकता है, न अब भी अतिसंतृप्त।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-357","question":"Drinking water contains 0.5 ppm of fluoride (1 ppm = 1 mg per litre). How many milligrams of fluoride are present in a 20-litre bucket of this water?","options":["1 mg","10 mg","100 mg","0.025 mg"],"answer":1,"explanation":"0.5 ppm means 0.5 mg per litre, so 20 litres contain 0.5 × 20 = 10 mg of fluoride. Dividing instead of multiplying gives 0.025 mg.","difficulty":"hard","questionHi":"पेयजल में फ़्लोराइड की मात्रा 0.5 ppm है (1 ppm = 1 mg प्रति लीटर)। इस जल की 20 लीटर की बाल्टी में कितने मिलीग्राम फ़्लोराइड होगा?","optionsHi":["1 mg","10 mg","100 mg","0.025 mg"],"explanationHi":"0.5 ppm का अर्थ है 0.5 mg प्रति लीटर, इसलिए 20 लीटर में 0.5 × 20 = 10 mg फ़्लोराइड है। गुणा के स्थान पर भाग देने पर 0.025 mg आता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-358","question":"If 1 g of matter were completely converted into energy, how much energy would be released? (c = 3 × 10⁸ m/s)","options":["9 × 10¹⁶ J","9 × 10¹⁰ J","9 × 10¹³ J","3 × 10¹¹ J"],"answer":2,"explanation":"By E = mc² with m = 1 g = 10⁻³ kg: E = 10⁻³ × (3 × 10⁸)² = 9 × 10¹³ J. Using 1 g without converting to kilograms gives the trap value 9 × 10¹⁶ J.","difficulty":"very-hard","questionHi":"यदि 1 g द्रव्य पूर्णतः ऊर्जा में परिवर्तित हो जाए, तो कितनी ऊर्जा मुक्त होगी? (c = 3 × 10⁸ m/s)","optionsHi":["9 × 10¹⁶ J","9 × 10¹⁰ J","9 × 10¹³ J","3 × 10¹¹ J"],"explanationHi":"E = mc² से, m = 1 g = 10⁻³ kg लेने पर: E = 10⁻³ × (3 × 10⁸)² = 9 × 10¹³ J। 1 g को किलोग्राम में बदले बिना लेने पर भ्रामक मान 9 × 10¹⁶ J आता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-359","question":"Which period of the modern periodic table contains 18 elements and includes the first row of d-block (transition) elements?","options":["Second period","Sixth period","Third period","Fourth period"],"answer":3,"explanation":"The fourth period has 18 elements, from potassium to krypton, including the ten transition elements scandium to zinc. The second and third periods have 8 each and the sixth has 32.","difficulty":"moderate","questionHi":"आधुनिक आवर्त सारणी के किस आवर्त में 18 तत्व हैं और d-ब्लॉक (संक्रमण) तत्वों की पहली पंक्ति शामिल है?","optionsHi":["दूसरा आवर्त","छठा आवर्त","तीसरा आवर्त","चौथा आवर्त"],"explanationHi":"चौथे आवर्त में पोटैशियम से क्रिप्टॉन तक 18 तत्व हैं, जिनमें स्कैन्डियम से जिंक तक के दस संक्रमण तत्व शामिल हैं। दूसरे और तीसरे आवर्त में 8-8 तथा छठे में 32 तत्व हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-360","question":"Which of these ions is colourless in aqueous solution?","options":["Zn²⁺","Cu²⁺","Fe³⁺","Ni²⁺"],"answer":0,"explanation":"Zn²⁺ has a completely filled 3d subshell (d¹⁰), so it has no d-d transitions and is colourless. Cu²⁺ is blue, Fe³⁺ yellow-brown and Ni²⁺ green.","difficulty":"hard","questionHi":"इनमें से कौन-सा आयन जलीय विलयन में रंगहीन होता है?","optionsHi":["Zn²⁺","Cu²⁺","Fe³⁺","Ni²⁺"],"explanationHi":"Zn²⁺ का 3d उपकोश पूर्णतः भरा है (d¹⁰), इसलिए उसमें d-d संक्रमण नहीं होते और वह रंगहीन होता है। Cu²⁺ नीला, Fe³⁺ पीला-भूरा और Ni²⁺ हरा होता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-361","question":"Cracking of dodecane (C₁₂H₂₆) gives octane (C₈H₁₈) and one other hydrocarbon. The other product is:","options":["C₄H₁₀","C₄H₈","C₃H₆","C₄H₆"],"answer":1,"explanation":"Atoms must balance: C₁₂H₂₆ → C₈H₁₈ + C₄H₈, since 12 − 8 = 4 carbon atoms and 26 − 18 = 8 hydrogen atoms remain. C₄H₈ is butene, an unsaturated hydrocarbon, which is typical of cracking.","difficulty":"very-hard","questionHi":"डोडेकेन (C₁₂H₂₆) के भंजन से ऑक्टेन (C₈H₁₈) और एक अन्य हाइड्रोकार्बन मिलता है। वह अन्य उत्पाद है:","optionsHi":["C₄H₁₀","C₄H₈","C₃H₆","C₄H₆"],"explanationHi":"परमाणु संतुलित होने चाहिए: C₁₂H₂₆ → C₈H₁₈ + C₄H₈, क्योंकि 12 − 8 = 4 कार्बन और 26 − 18 = 8 हाइड्रोजन परमाणु बचते हैं। C₄H₈ ब्यूटीन है, जो असंतृप्त हाइड्रोकार्बन है, और भंजन में यही सामान्य है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-362","question":"Detergents with branched hydrocarbon chains cause persistent foam in rivers and lakes because they are:","options":["heavier than water and settle on the bed","converted into insoluble scum by the calcium of the water","not easily broken down by bacteria because of the branched chains","converted into soap by the minerals of the water"],"answer":2,"explanation":"Bacteria cannot readily break down branched-chain detergents, so they are non-biodegradable and build up as foam and pollute the water. Straight-chain detergents are biodegradable.","difficulty":"hard","questionHi":"शाखित हाइड्रोकार्बन शृंखला वाले अपमार्जक नदियों और झीलों में स्थायी झाग पैदा करते हैं, क्योंकि वे:","optionsHi":["जल से भारी होते हैं और तली में बैठ जाते हैं","जल के कैल्सियम से अघुलनशील झाग (स्कम) में बदल जाते हैं","शाखित शृंखलाओं के कारण जीवाणुओं द्वारा सरलता से नहीं टूटते","जल के खनिजों से साबुन में बदल जाते हैं"],"explanationHi":"जीवाणु शाखित शृंखला वाले अपमार्जकों को आसानी से नहीं तोड़ पाते, इसलिए वे अजैवनिम्नीकरणीय होते हैं, झाग के रूप में जमा होते हैं और जल को प्रदूषित करते हैं। सीधी शृंखला वाले अपमार्जक जैवनिम्नीकरणीय होते हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-363","question":"Activated charcoal is used in gas masks and water filters because it:","options":["reacts chemically with every poisonous gas that is present","dissolves the impurities and then holds them in its pores","kills the germs by releasing carbon dioxide into the water","adsorbs gases and dissolved impurities on its large surface"],"answer":3,"explanation":"Activated charcoal is highly porous, so its enormous surface area adsorbs gas molecules and dissolved colouring or odour-causing impurities onto the surface. Adsorption is a surface effect, unlike absorption.","difficulty":"moderate","questionHi":"सक्रियित चारकोल का उपयोग गैस मुखौटों और जल फ़िल्टरों में इसलिए होता है क्योंकि वह:","optionsHi":["उपस्थित प्रत्येक विषैली गैस से रासायनिक अभिक्रिया करता है","अशुद्धियों को घोलकर फिर अपने रंध्रों में रोक लेता है","जल में कार्बन डाइऑक्साइड छोड़कर रोगाणुओं को मारता है","अपनी बड़ी सतह पर गैसों और घुली अशुद्धियों का अधिशोषण करता है"],"explanationHi":"सक्रियित चारकोल अत्यंत सरंध्र होता है, इसलिए उसकी विशाल सतह गैस अणुओं और घुली रंगीन या गंधकारी अशुद्धियों को अपनी सतह पर अधिशोषित कर लेती है। अधिशोषण सतही प्रभाव है, अवशोषण से भिन्न।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-364","question":"Graphite is used as a dry lubricant because:","options":["its layers are weakly bonded and slide over one another","it is a very good conductor of both heat and electricity","it is softer than every metal and wears away smoothly","its tiny molecules are perfectly smooth and round like beads"],"answer":0,"explanation":"In graphite the carbon atoms form flat layers held to one another only by weak van der Waals forces, so the layers slide easily. Its ability to conduct heat or electricity is not the reason for lubrication.","difficulty":"moderate","questionHi":"ग्रेफ़ाइट का उपयोग शुष्क स्नेहक के रूप में इसलिए होता है क्योंकि:","optionsHi":["उसकी परतें दुर्बल रूप से बँधी होती हैं और एक-दूसरे पर फिसलती हैं","वह ऊष्मा और विद्युत दोनों का बहुत अच्छा चालक है","वह हर धातु से नरम है और चिकनाई से घिस जाता है","उसके छोटे अणु मोतियों की तरह पूर्णतः चिकने और गोल होते हैं"],"explanationHi":"ग्रेफ़ाइट में कार्बन परमाणु चपटी परतें बनाते हैं जो एक-दूसरे से केवल दुर्बल वान डर वाल्स बलों से जुड़ी होती हैं, इसलिए परतें आसानी से फिसल जाती हैं। उसकी ऊष्मा या विद्युत चालकता स्नेहन का कारण नहीं है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-365","question":"A fertiliser bag labelled NPK 12:32:16 contains 12% nitrogen (N), 32% P₂O₅ and 16% K₂O by mass. How many kilograms of nitrogen are present in a 50 kg bag?","options":["12 kg","6 kg","8 kg","16 kg"],"answer":1,"explanation":"Nitrogen is 12% of 50 kg, which is 0.12 × 50 = 6 kg. The value 8 kg is 16% of the bag (the K₂O content).","difficulty":"hard","questionHi":"NPK 12:32:16 लिखी उर्वरक की बोरी में द्रव्यमान से 12% नाइट्रोजन (N), 32% P₂O₅ और 16% K₂O है। 50 kg की बोरी में कितने किलोग्राम नाइट्रोजन है?","optionsHi":["12 kg","6 kg","8 kg","16 kg"],"explanationHi":"नाइट्रोजन 50 kg का 12% है, अर्थात 0.12 × 50 = 6 kg। 8 kg बोरी का 16% (K₂O की मात्रा) है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-366","question":"How many grams of sodium are present in 117 g of sodium chloride? (Na = 23, Cl = 35.5)","options":["23 g","58.5 g","46 g","117 g"],"answer":2,"explanation":"Molar mass of NaCl = 58.5 g, so 117 g is 2 mol. Each mole of NaCl has 23 g of sodium, so 2 mol contain 2 × 23 = 46 g.","difficulty":"hard","questionHi":"117 g सोडियम क्लोराइड में कितने ग्राम सोडियम है? (Na = 23, Cl = 35.5)","optionsHi":["23 g","58.5 g","46 g","117 g"],"explanationHi":"NaCl का मोलर द्रव्यमान 58.5 g है, इसलिए 117 g = 2 मोल। NaCl के प्रत्येक मोल में 23 g सोडियम होता है, अतः 2 मोल में 2 × 23 = 46 g है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-367","question":"A pressure cooker cooks food faster than an open pan because:","options":["the steam inside is at the same temperature but much more of it is made","the lid stops dust and air from entering the food","the walls of the cooker are better conductors of heat","the raised pressure inside raises the boiling point of water above 100 °C"],"answer":3,"explanation":"The steam trapped inside raises the pressure to about twice the atmospheric pressure, so water boils at about 120 °C. Food cooks faster at this higher temperature.","difficulty":"moderate","questionHi":"प्रेशर कुकर में भोजन खुले बर्तन की तुलना में जल्दी पकता है, क्योंकि:","optionsHi":["भीतर की भाप उसी ताप पर रहती है पर बहुत अधिक बनती है","ढक्कन धूल और वायु को भोजन में जाने से रोकता है","कुकर की दीवारें ऊष्मा की अच्छी चालक हैं","भीतर बढ़ा हुआ दाब जल का क्वथनांक 100 °C से ऊपर कर देता है"],"explanationHi":"भीतर रुकी भाप दाब को वायुमंडलीय दाब के लगभग दोगुने तक बढ़ा देती है, इसलिए जल लगभग 120 °C पर उबलता है। इस अधिक ताप पर भोजन जल्दी पकता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-368","question":"The correct formula of calcium phosphate is:","options":["Ca₃(PO₄)₂","Ca₂(PO₄)₃","CaPO₄","Ca₃PO₄"],"answer":0,"explanation":"Calcium ion is Ca²⁺ and phosphate ion is PO₄³⁻. Criss-crossing the charges gives Ca₃(PO₄)₂, with total charge 3 × (+2) + 2 × (−3) = 0.","difficulty":"hard","questionHi":"कैल्सियम फ़ॉस्फ़ेट का सही सूत्र है:","optionsHi":["Ca₃(PO₄)₂","Ca₂(PO₄)₃","CaPO₄","Ca₃PO₄"],"explanationHi":"कैल्सियम आयन Ca²⁺ और फ़ॉस्फ़ेट आयन PO₄³⁻ है। आवेशों को आड़ा-तिरछा (क्रिस-क्रॉस) करने पर Ca₃(PO₄)₂ मिलता है, जिसका कुल आवेश 3 × (+2) + 2 × (−3) = 0 है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-369","question":"When magnesium burns in air it forms magnesium oxide and also a small amount of a nitride. The formula of magnesium nitride is:","options":["MgN","Mg₃N₂","Mg₂N₃","Mg₂N"],"answer":1,"explanation":"Magnesium forms Mg²⁺ and nitrogen forms N³⁻, so criss-crossing the charges gives Mg₃N₂: 3 × (+2) + 2 × (−3) = 0. Magnesium is one of the few metals that burns in nitrogen.","difficulty":"hard","questionHi":"मैग्नीशियम वायु में जलने पर मैग्नीशियम ऑक्साइड और थोड़ी मात्रा में नाइट्राइड भी बनाता है। मैग्नीशियम नाइट्राइड का सूत्र है:","optionsHi":["MgN","Mg₃N₂","Mg₂N₃","Mg₂N"],"explanationHi":"मैग्नीशियम Mg²⁺ और नाइट्रोजन N³⁻ बनाती है, इसलिए आवेशों को क्रिस-क्रॉस करने पर Mg₃N₂ मिलता है: 3 × (+2) + 2 × (−3) = 0। मैग्नीशियम उन थोड़ी-सी धातुओं में है जो नाइट्रोजन में जलती हैं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-370","question":"The IUPAC name of acetone, CH₃COCH₃, is:","options":["propanal","propanol","propanone","propanoic acid"],"answer":2,"explanation":"Acetone has a carbonyl group (C=O) between two carbon atoms, so it is a ketone and takes the suffix -one: propanone. Propanal is an aldehyde and propanoic acid a carboxylic acid.","difficulty":"moderate","questionHi":"ऐसीटोन, CH₃COCH₃ का IUPAC नाम है:","optionsHi":["प्रोपेनल","प्रोपेनॉल","प्रोपेनोन","प्रोपेनोइक अम्ल"],"explanationHi":"ऐसीटोन में दो कार्बन परमाणुओं के बीच कार्बोनिल समूह (C=O) है, इसलिए वह कीटोन है और उसमें अनुलग्न -ओन लगता है: प्रोपेनोन। प्रोपेनल ऐल्डिहाइड और प्रोपेनोइक अम्ल कार्बोक्सिलिक अम्ल है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-371","question":"Sterling silver contains 92.5% silver by mass. How many grams of pure silver are there in an 80 g sterling silver article?","options":["72.5 g","80 g","7.4 g","74 g"],"answer":3,"explanation":"Silver = 92.5% of 80 g = 0.925 × 80 = 74 g. The remaining 6 g is mostly copper, added to make the soft silver harder.","difficulty":"hard","questionHi":"स्टर्लिंग चाँदी में द्रव्यमान से 92.5% चाँदी होती है। 80 g की स्टर्लिंग चाँदी की वस्तु में कितने ग्राम शुद्ध चाँदी है?","optionsHi":["72.5 g","80 g","7.4 g","74 g"],"explanationHi":"चाँदी = 80 g का 92.5% = 0.925 × 80 = 74 g। शेष 6 g मुख्यतः ताँबा है, जो नरम चाँदी को कठोर बनाने के लिए मिलाया जाता है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-372","question":"How much water must be added to 100 mL of a 10% (v/v) solution to dilute it to 4% (v/v)?","options":["150 mL","250 mL","100 mL","60 mL"],"answer":0,"explanation":"The volume of solute stays at 10 mL, so the final volume = 10 ÷ 0.04 = 250 mL. The water to be added is 250 − 100 = 150 mL; 250 mL is the final volume, not the water added.","difficulty":"very-hard","questionHi":"100 mL के 10% (आ./आ.) विलयन को 4% (आ./आ.) तक तनु करने के लिए कितना जल मिलाना होगा?","optionsHi":["150 mL","250 mL","100 mL","60 mL"],"explanationHi":"विलेय का आयतन 10 mL ही रहता है, इसलिए अंतिम आयतन = 10 ÷ 0.04 = 250 mL। मिलाया जाने वाला जल 250 − 100 = 150 mL है; 250 mL अंतिम आयतन है, मिलाया गया जल नहीं।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-373","question":"Which of these gases is collected by the downward displacement of air, because it is lighter than air?","options":["Chlorine","Ammonia","Carbon dioxide","Sulphur dioxide"],"answer":1,"explanation":"Ammonia (molar mass 17) is lighter than air (about 29), so it rises and is collected in an upside-down jar. Chlorine (71), carbon dioxide (44) and sulphur dioxide (64) are heavier than air and are collected by upward displacement.","difficulty":"moderate","questionHi":"इनमें से कौन-सी गैस वायु के नीचे की ओर विस्थापन द्वारा एकत्र की जाती है, क्योंकि वह वायु से हल्की है?","optionsHi":["क्लोरीन","अमोनिया","कार्बन डाइऑक्साइड","सल्फ़र डाइऑक्साइड"],"explanationHi":"अमोनिया (मोलर द्रव्यमान 17) वायु (लगभग 29) से हल्की है, इसलिए वह ऊपर उठती है और उलटे जार में एकत्र की जाती है। क्लोरीन (71), कार्बन डाइऑक्साइड (44) और सल्फ़र डाइऑक्साइड (64) वायु से भारी हैं और ऊपर की ओर विस्थापन से एकत्र की जाती हैं।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-374","question":"Which substance can be used to dry ammonia gas?","options":["Concentrated sulphuric acid","Phosphorus pentoxide","Quicklime (calcium oxide)","Anhydrous calcium chloride"],"answer":2,"explanation":"Ammonia is basic, so it reacts with the acidic drying agents conc. H₂SO₄ and P₄O₁₀. It also combines with anhydrous CaCl₂ to form CaCl₂·8NH₃. Quicklime does not react with ammonia and is the standard drying agent.","difficulty":"very-hard","questionHi":"अमोनिया गैस को सुखाने के लिए किस पदार्थ का उपयोग किया जा सकता है?","optionsHi":["सांद्र सल्फ़्यूरिक अम्ल","फ़ॉस्फ़ोरस पेन्टाऑक्साइड","अनबुझा चूना (कैल्सियम ऑक्साइड)","निर्जल कैल्सियम क्लोराइड"],"explanationHi":"अमोनिया क्षारीय है, इसलिए वह अम्लीय शुष्कक सांद्र H₂SO₄ और P₄O₁₀ से अभिक्रिया करती है। वह निर्जल CaCl₂ से भी संयोग करके CaCl₂·8NH₃ बनाती है। कैल्सियम ऑक्साइड अमोनिया से अभिक्रिया नहीं करता और वही मानक शुष्कक है।","source":"SSC CGL · RRB NTPC"},
  {"id":"sci-chemistry-375","question":"When concentrated sulphuric acid is poured on sugar, the sugar turns black and swells up. This is because the acid acts as:","options":["an oxidising agent that adds oxygen to the sugar molecules","a catalyst that makes the sugar decompose on its own","a base that neutralises the acidic sugar solution","a dehydrating agent that removes the elements of water"],"answer":3,"explanation":"Sugar is C₁₂H₂₂O₁₁ and the acid pulls out hydrogen and oxygen in the ratio of water, leaving black carbon. The heat released drives off steam and CO₂, which makes the carbon swell into a porous mass.","difficulty":"moderate","questionHi":"सांद्र सल्फ़्यूरिक अम्ल को चीनी पर डालने पर चीनी काली पड़ जाती है और फूल जाती है। इसका कारण है कि अम्ल कार्य करता है:","optionsHi":["ऑक्सीकारक, जो चीनी के अणुओं में ऑक्सीजन जोड़ता है","उत्प्रेरक, जो चीनी को स्वयं अपघटित कराता है","क्षार, जो अम्लीय चीनी विलयन को उदासीन करता है","निर्जलीकारक, जो जल के तत्व निकाल लेता है"],"explanationHi":"चीनी C₁₂H₂₂O₁₁ है और अम्ल उसमें से जल के अनुपात में हाइड्रोजन और ऑक्सीजन खींच लेता है, जिससे काला कार्बन बचता है। निकली ऊष्मा भाप और CO₂ उड़ा देती है, जिससे कार्बन फूलकर सरंध्र पुंज बन जाता है।","source":"SSC CGL · RRB Group D"},
  {"id":"sci-chemistry-376","question":"Which postulate of Dalton's atomic theory is NOT correct in the light of later discoveries?","options":["Atoms are neither created nor destroyed in a chemical reaction","Atoms of different elements combine in simple whole-number ratios to form compounds","Atoms are indivisible and all atoms of a given element are exactly alike","Atoms of different elements have different masses and properties"],"answer":2,"explanation":"Atoms are made of electrons, protons and neutrons, so they are divisible, and isotopes show that atoms of the same element can differ in mass. The other postulates still hold for chemical reactions.","difficulty":"hard","questionHi":"डाल्टन के परमाणु सिद्धांत की कौन-सी अभिधारणा बाद की खोजों के प्रकाश में सही नहीं है?","optionsHi":["रासायनिक अभिक्रिया में परमाणु न बनाए जाते हैं, न नष्ट किए जाते हैं","भिन्न तत्वों के परमाणु सरल पूर्ण संख्या अनुपातों में संयोग करके यौगिक बनाते हैं","परमाणु अविभाज्य हैं और किसी तत्व के सभी परमाणु बिल्कुल एक जैसे होते हैं","भिन्न तत्वों के परमाणुओं के द्रव्यमान और गुण भिन्न होते हैं"],"explanationHi":"परमाणु इलेक्ट्रॉनों, प्रोटॉनों और न्यूट्रॉनों से बने हैं, इसलिए वे विभाज्य हैं, और समस्थानिक दिखाते हैं कि एक ही तत्व के परमाणुओं के द्रव्यमान भिन्न हो सकते हैं। शेष अभिधारणाएँ रासायनिक अभिक्रियाओं के लिए अब भी सही हैं।","source":"SSC CGL · RRB NTPC"},
];

